/// Read-only discovery, scoped to the node identity the renderer is showing.
async fn read_starter_current(state: &NodeState, node_id: &str) -> Result<bitsov_app::starter::Status, String> {
    require_starter_build()?;
    read_starter_current_enabled(state, node_id).await
        .map_err(|_| "Could not read starter balance status.".into())
}

// Private enabled paths let boundary tests exercise both modes without mutating
// process environment. IPC always enters through the build-gated wrappers.
fn require_starter_build() -> Result<(), String> {
    if option_env!("VITE_STARTER_BALANCE") == Some("1") { Ok(()) }
    else { Err("Starter balance is disabled in this build.".into()) }
}

async fn read_starter_current_enabled(state: &NodeState, node_id: &str) -> Result<bitsov_app::starter::Status, String> {
    let _change = state.remote_change.lock().await;
    read_starter_on_connection(state, node_id).await
}

// Caller holds remote_change across discovery, auth refresh, dispatch and reply.
async fn read_starter_on_connection(state: &NodeState, node_id: &str) -> Result<bitsov_app::starter::Status, String> {
    let overview = read_node_overview(state).await?;
    if overview.node_id != node_id || overview.network.as_deref() != Some("signet")
        || !overview.capabilities.iter().any(|c| c == "starter_channel_request_v1") {
        return Err("Starter balance is unavailable for this node.".into());
    }
    get_json(state, bitsov_app::starter::PATH).await
}

/// Receive scope only. Never enter the spend/owner-approval flow or accept amounts.
async fn do_starter_request(
    state: &NodeState, node_id: &str, request_id: &str,
) -> Result<bitsov_app::starter::Status, String> {
    require_starter_build()?;
    do_starter_request_enabled(state, node_id, request_id).await
        .map_err(|_| "Could not confirm the starter balance request.".into())
}

async fn do_starter_request_enabled(
    state: &NodeState, node_id: &str, request_id: &str,
) -> Result<bitsov_app::starter::Status, String> {
    let _change = state.remote_change.lock().await;
    let id = control::room_id(request_id).map_err(|_| "Invalid starter request UUID.".to_string())?;
    if id.as_bytes()[14] != b'4' || !matches!(id.as_bytes()[19], b'8' | b'9' | b'a' | b'b') {
        return Err("Invalid starter request UUID.".into());
    }
    if !matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(s) if s.scopes.iter().any(|v| v == "receive")) {
        return Err("A paired receive session is required.".into());
    }
    let generation = *state.remote_connect_generation.borrow();
    let discovery = read_starter_on_connection(state, node_id).await?;
    if !discovery.hub_configured {
        return Err("No starter hub is configured.".into());
    }
    if *state.remote_connect_generation.borrow() != generation
        || state.node_id.lock().unwrap().as_deref() != Some(node_id) {
        return Err("The connected node changed.".into());
    }
    let (status, body) = call_api(state, reqwest::Method::POST, bitsov_app::starter::PATH,
        Some(serde_json::json!({"request_id": id}))).await?;
    // Another paired device may already have started the node's one request.
    // Adopt the node's current root; never invent a replacement UUID here.
    if status == reqwest::StatusCode::CONFLICT
        && serde_json::from_str::<serde_json::Value>(&body).ok()
            .is_some_and(|v| v["code"] == "starter_already_requested") {
        return read_starter_on_connection(state, node_id).await;
    }
    decode(bitsov_app::starter::PATH, status, &body)
}

#[tauri::command(rename_all = "snake_case")]
async fn starter_current(
    window: WebviewWindow<impl tauri::Runtime>, state: State<'_, NodeState>, node_id: String,
) -> Result<bitsov_app::starter::Status, String> {
    reject_sealed_window(&window)?;
    drop(window);
    read_starter_current(state.inner(), &node_id).await
}

#[tauri::command(rename_all = "snake_case")]
async fn starter_request(
    window: WebviewWindow<impl tauri::Runtime>, state: State<'_, NodeState>, node_id: String, request_id: String,
) -> Result<bitsov_app::starter::Status, String> {
    reject_sealed_window(&window)?;
    drop(window);
    do_starter_request(state.inner(), &node_id, &request_id).await
}

// ---- control center actions (slice B) -----------------------------------------
//
// Every spending or node-changing call checks the owner's spend window FIRST,
// before any request, and goes through `call_api` like the reads. The node still
// decides: a 403 means this token cannot do it, whatever the window says.
// Receiving (an invoice) needs no approval. See `bitsov_app::act`.

/// Parse a 2xx body into an action shape.
fn decode_act<T: serde::de::DeserializeOwned>(path: &str, body: &str) -> Result<T, ActionError> {
    serde_json::from_str(body).map_err(|e| ActionError::node(format!("{path} decode failed: {e}")))
}

/// An admin POST (invites), never a money request. Always needs the spend window.
async fn gated_post(
    state: &NodeState,
    path: &str,
    body: serde_json::Value,
) -> Result<String, ActionError> {
    gated_post_auth(state, Auth::Window(approval_generation(state)?), path, body).await
}

/// Admin POST under the same budget / window authority as a paid send (file upload).
async fn gated_post_auth(
    state: &NodeState,
    auth: Auth,
    path: &str,
    body: serde_json::Value,
) -> Result<String, ActionError> {
    check_auth(state, auth)?;
    let (status, text) = call_api(state, reqwest::Method::POST, path, Some(body)).await?;
    if act::is_scope_refusal(status.as_u16()) {
        return Err(ActionError::new(
                "owner_only",
                "Your box allows this only from its owner, not from a paired app. Ask the person who set it up.",
            ));
    }
    if !status.is_success() {
        return Err(ActionError::node(api_error(path, status, &text)));
    }
    Ok(text)
}

fn approval_generation(state: &NodeState) -> Result<u64, ActionError> {
    let mut gate = state.spend.lock().unwrap();
    gate.check(now_ms())?;
    Ok(gate.generation())
}

/// The app's own files: `NodeState::app_dir` in external mode, else next to the
/// supervised node's config.
fn app_files_dir(state: &NodeState) -> Option<PathBuf> {
    if let Some(dir) = state.app_dir.lock().unwrap().clone() {
        return Some(dir);
    }
    state.config.lock().unwrap().as_deref()?.parent().map(Path::to_path_buf)
}

/// Snapshot error context before preflight can fail. This read grants no authority
/// and changes no refusal: the locked journal remains the spending fence.
fn pending_operation_id(state: &NodeState) -> Result<Option<String>, ActionError> {
    let Some(dir) = app_files_dir(state) else { return Ok(None) };
    Ok(spend_journal::read_pending(&dir.join("app-spend"))?.and_then(|p| p.operation_id))
}

fn spend_journal(state: &NodeState) -> Result<Journal, ActionError> {
    let dir = app_files_dir(state)
        .ok_or_else(|| spend_journal::unknown("The app data directory is not ready."))?;
    Journal::open(&dir.join("app-spend"))
}

/// Requires the money lock. Preflight readers must not normalize a snapshot
/// belonging to another money action that is awaiting its node response.
fn locked_spend_journal(state: &NodeState) -> Result<Journal, ActionError> {
    let journal = spend_journal(state)?;
    if let Some(mut pending) = journal.pending()? {
        if let Some(id) = pending.operation_id.clone() {
            let record = journal.operation_record(&id)?;
            let may_be_call = record.as_ref().is_none_or(|r| r.kind == "legacy" || r.kind.starts_with("call_"));
            let proven_unsent = pending.non_dispatch_proven && pending.resumable
                && pending.accounting_msat.is_none() && pending.paid.is_none()
                && pending.undelivered.is_none() && pending.evidence_reservation_msat.is_none()
                && record.as_ref().is_some_and(|r| r.state == spend_journal::OperationState::Unpaid);
            if may_be_call && !proven_unsent {
                // Pre-A2 grace releases retained their operation id. They have
                // no durable proof that the original call cannot still pay.
                // Confirmed abandonment clears that id and never enters here.
                if pending.resumable || record.as_ref().is_some_and(|r| r.state == spend_journal::OperationState::Unpaid) {
                    pending.resumable = false;
                    journal.save(&pending)?;
                    journal.record_outcome(&pending, spend_journal::OperationState::Unknown, None)?;
                }
                if !pending.budgeted && pending.accounting_msat.is_none() {
                    if state.node_id.lock().unwrap().as_deref() != Some(&pending.node_id) {
                        return Err(spend_journal::unknown("The pending call belongs to another node identity."));
                    }
                    let peer = pending.peer.as_deref().ok_or_else(|| spend_journal::unknown("The pending call has no accounting target."))?;
                    // Restore only the existing liability, never permission to
                    // dispatch. Idempotent across a crash before the slot save.
                    with_book(state, true, |book| {
                        if !book.ledger.iter().any(|entry| entry.id == pending.charge_id()) {
                            book.reserve(pending.charge_id(), peer, false, pending.max_msat, now_ms());
                        }
                        Ok(())
                    })?;
                    pending.budgeted = true;
                    journal.save(&pending)?;
                }
            }
        }
    }
    Ok(journal)
}

fn ceiling(price: u64, max_msat: u64) -> Result<(), ActionError> {
    if max_msat == 0 || price > max_msat {
        return Err(ActionError::new("price_changed", format!("The current price is {price} msat, above the confirmed ceiling of {max_msat} msat. Nothing was dispatched; refresh the quote.")));
    }
    Ok(())
}

fn no_pending_spend(state: &NodeState) -> Result<(), ActionError> {
    // A resumable record holds no payment; the next send may replace it.
    if let Some(p) = spend_journal(state)?.pending()?.filter(|p| !p.resumable) {
        return act::with_op(Active(p.operation_id.as_deref()), Err(spend_journal::unknown("Check the pending result before starting another action.")));
    }
    Ok(())
}

// ---- budgets (B2) ---------------------------------------------------------------
//
// Budget numbers and the 24-hour ledger live next to the spend journal. The
// owner's approval does not: it is `NodeState::autopay`, memory only.

/// Which approval a money request runs under, with the generation it was checked at.
#[derive(Clone, Copy, Debug)]
enum Auth {
    Window(u64),
    Budget(u64),
    /// A live call's own payment after the owner's approval ran out, on a
    /// node that keeps the call (`call_continuity_v1`): its next minute,
    /// drawn on the hold pinned at admission ([`do_call_block`]), or its
    /// hangup or reconnect request ([`held_call_plan`]). Carries the call's
    /// `spend_stops` from when it began; any explicit stop since ends it.
    CallHold(u64),
}

/// A cooldown is a proven pre-dispatch refusal, before journal or reservation I/O.
/// A dial in flight is not one: the request waits behind it, and if it fails the
/// proxy answers that nothing was forwarded (`remote_retry_wait`).
fn refuse_if_connection_waiting(state: &NodeState) -> Result<(), ActionError> {
    if state.remote_retry.cooling_down() {
        return Err(ActionError::new("not_ready", "Waiting for the connection. Your node will retry automatically."));
    }
    Ok(())
}

/// For a repeat of a request the node may already hold: an admission resume or a
/// direct-payment replay. Neither can read a proxy refusal as proven unpaid, so
/// each also waits out a dial's anti-burst stamp rather than meet that refusal.
fn refuse_if_connection_busy(state: &NodeState) -> Result<(), ActionError> {
    if state.remote_retry.remaining().is_some() {
        return Err(ActionError::new("not_ready", "Waiting for the connection. Your node will retry automatically."));
    }
    Ok(())
}

fn check_auth(state: &NodeState, auth: Auth) -> Result<(), ActionError> {
    match auth {
        Auth::Window(g) => state.spend.lock().unwrap().check_generation(g, now_ms()),
        Auth::Budget(g) => state.autopay.lock().unwrap().check_generation(g, now_ms()),
        Auth::CallHold(stops) if spend_stops(state) == stops => Ok(()),
        Auth::CallHold(_) => Err(ActionError::new("spend_locked", "Sending spends from your node. Approve spending first.")),
    }
}

fn spend_stops(state: &NodeState) -> u64 {
    state.spend_stops.load(Ordering::SeqCst)
}

/// An explicit stop of spending (see `NodeState::spend_stops`).
fn stop_spending(state: &NodeState) {
    state.spend_stops.fetch_add(1, Ordering::SeqCst);
}

/// The node refused this app's token: nothing may spend, held call minutes included.
fn refuse_spend(state: &NodeState) -> ActionError {
    stop_spending(state);
    state.autopay.lock().unwrap().lock();
    *state.node_grant.lock().unwrap() = None;
    state.spend.lock().unwrap().refused()
}

/// A message send's line in the budget ledger.
struct Charge {
    target: String,
    room: bool,
    /// The owner's first-contact confirmation, with the budget they chose.
    confirm: Option<u64>,
    /// This node may pay admission separately from a message cap.
    readmission_possible: bool,
    /// This call issued a bounded one-time contact confirmation.
    confirmed: bool,
    /// The node keeps durable message operations (`message_operations_v1`):
    /// a 1:1 compose carries a journaled `operation_id`.
    operation: bool,
    /// Envelope identity support from this send's status; None asks afresh.
    envelope_ids: Option<bool>,
    /// `final_failure_node` of this send's status; None for a send with no operation.
    failure_final_on: Option<String>,
    /// A node-routed paid offer or a paid answer: the grant read under the
    /// money lock must also outlast this node's call limit (`call_window_fits`).
    call_window: bool,
}

fn budget_dir(state: &NodeState) -> Result<(PathBuf, String), ActionError> {
    let dir = app_files_dir(state)
        .ok_or_else(|| ActionError::new("app_not_ready", "The app data directory is not ready."))?
        .join("app-spend");
    let node_id = state.node_id.lock().unwrap().clone().ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
    Ok((dir, node_id))
}

/// Read the book, let `edit` change it, and write it back only if asked.
fn with_book<T>(state: &NodeState, write: bool, edit: impl FnOnce(&mut Book) -> Result<T, ActionError>) -> Result<T, ActionError> {
    let _io = state.budget_io.lock().unwrap();
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = (|| {
    let (dir, node_id) = budget_dir(state)?;
    let mut book = budget::load(&dir, &node_id)?;
    let out = edit(&mut book)?;
    if write {
        let pending = spend_journal::read_pending(&dir)?;
        let keep: Vec<&str> = pending.iter().flat_map(|p| {
            [Some(p.request_hash.as_str()), Some(p.charge_id()), p.rollback_charge_id.as_deref()]
                .into_iter().flatten()
        }).collect();
        book.prune_retaining(now_ms(), &keep);
        budget::save(&dir, &book)?;
    }
    Ok(out)
    })();
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

fn refuse_if_paused(state: &NodeState) -> Result<(), ActionError> {
    if budget_paused(state)? {
        return Err(ActionError::new("budget_paused", "Payments are paused. Resume them to send."));
    }
    Ok(())
}

/// Pause-all, where a book exists. Before sign-in there is nothing to pause.
fn budget_paused(state: &NodeState) -> Result<bool, ActionError> {
    if budget_dir(state).is_err() { return Ok(false); }
    with_book(state, false, |b| Ok(b.paused))
}

/// Decide, before any request, whether and under which approval a message pays.
fn plan_message(state: &NodeState, target: &str, room: bool, max_msat: u64, first_contact_msat: Option<u64>) -> Result<(Auth, budget::Plan), ActionError> {
    let now = now_ms();
    let window = approval_generation(state);
    let (ceiling, generation) = {
        let mut autopay = state.autopay.lock().unwrap();
        (autopay.ceiling(now), autopay.generation())
    };
    let plan = with_book(state, false, |book| budget::plan(book, budget::Ask {
        target,
        room,
        max_msat,
        first_contact_msat,
        autopay: ceiling,
        window: window.as_ref().map(|_| ()).map_err(Clone::clone),
        now_ms: now,
    }))?;
    let auth = match plan.route {
        budget::Route::Budget => Auth::Budget(generation),
        budget::Route::Window => Auth::Window(window?),
    };
    Ok((auth, plan))
}

/// The manual window supplies authority, never an exemption from the daily book.
fn plan_manual_charge(state: &NodeState, target: &str, max_msat: u64) -> Result<Charge, ActionError> {
    with_book(state, false, |book| budget::plan(book, budget::Ask {
        target, room: false, max_msat, first_contact_msat: None,
        autopay: None, window: Ok(()), now_ms: now_ms(),
    }))?;
    Ok(Charge {
        target: target.into(), room: false, confirm: None,
        readmission_possible: false, confirmed: false, operation: false, envelope_ids: None, failure_final_on: None,
        call_window: false,
    })
}

/// Re-plan against the book on disk and reserve the ceiling, under the journal lock.
fn reserve(state: &NodeState, auth: Auth, charge: &Charge, id: &str, max_msat: u64) -> Result<(), ActionError> {
    let now = now_ms();
    let ceiling = match auth {
        Auth::Budget(_) => state.autopay.lock().unwrap().ceiling(now),
        Auth::Window(_) | Auth::CallHold(_) => None,
    };
    with_book(state, true, |book| {
        // Reserve each charge once. An unsettled row under this id is this same
        // charge from an attempt whose reservation landed but was reported
        // failed: re-plan without it and hold it once. A settled row with this
        // id is an earlier identical send and stays.
        if let Some(i) = book.ledger.iter().rposition(|e| e.id == id && !e.settled) {
            book.ledger.remove(i);
        }
        let plan = budget::plan(book, budget::Ask {
            target: &charge.target,
            room: charge.room,
            max_msat,
            first_contact_msat: charge.confirm,
            autopay: ceiling,
            window: Ok(()),
            now_ms: now,
        })?;
        let expected = if matches!(auth, Auth::Budget(_)) { budget::Route::Budget } else { budget::Route::Window };
        if plan.route != expected {
            return Err(ActionError::new("budget_needed", "Your budget approval changed while sending. Nothing was sent; approve it again."));
        }
        if let Some(limit) = plan.confirm {
            book.set_limit(&charge.target, charge.room, limit)?;
        }
        book.reserve(id, &charge.target, charge.room, max_msat, now);
        Ok(())
    })
}

/// Release an attempt's own reservation, and only that: the last book row with
/// its charge id, and only while it is still held. An earlier identical send
/// has the same charge id; its settled row is never released, at any amount,
/// zero included. Nothing to do when the last such row is settled or gone, so
/// a replayed cleanup releases nothing more.
fn release_own_reservation(state: &NodeState, id: &str) -> Result<(), ActionError> {
    let own = with_book(state, false, |book| Ok(book.ledger.iter().rev()
        .find(|e| e.id == id).is_some_and(|e| !e.settled)))?;
    if own { close_charge(state, id, None, None)?; }
    Ok(())
}

/// Settle or release durably; callers must retain the journal on I/O failure.
fn close_charge(state: &NodeState, id: &str, paid: Option<u64>, target: Option<&Target>) -> Result<(), ActionError> {
    let (dir, _) = budget_dir(state)?;
    let evidence = spend_journal::read_pending(&dir)?
        .filter(|p| p.charge_id() == id && p.accounting_msat == paid)
        .and_then(|p| p.paid);
    with_book(state, true, |book| {
        match paid {
            Some(msat) => {
                let entry = book.ledger.iter().rev().find(|entry| entry.id == id)
                    .ok_or_else(|| spend_journal::unknown("The saved payment has no matching budget reservation. Inspect the local budget book."))?;
                if msat > 0 && matches!(entry.target.as_str(), budget::INVOICE_PAYMENTS | budget::KEYSEND_PAYMENTS) {
                    let Some(Target::Payment { hash }) = target else {
                        return Err(spend_journal::unknown("The payment has no canonical identity. The reservation stays held."));
                    };
                    if hash.len() != 64 || !hash.bytes().all(|c| c.is_ascii_hexdigit()) {
                        return Err(spend_journal::unknown("The payment identity is invalid. The reservation stays held."));
                    }
                    book.settle_payment(id, hash, msat, now_ms());
                } else {
                    book.settle(id, msat, now_ms());
                }
            }
            None => book.release(id),
        }
        if paid.is_some() {
            if let Some(entry) = book.ledger.iter_mut().rev().find(|e| e.id == id) {
                // A duplicate canonical payment settles this attempt at zero.
                entry.paid = if entry.msat == 0 && paid.is_some_and(|amount| amount > 0) { Some(budget::Paid { msat: 0, fee_unknown: false }) } else { evidence };
            }
        }
        Ok(())
    }).map_err(spend_journal::unknown)
}

/// A delivery-only retry can reveal the fee of its original payment. Update that
/// row, never charge the retry again. Only refine an exact principal match.
fn refine_retry_fee(state: &NodeState, pending: &spend_journal::Pending, reply: &act::SendReply) -> Result<bool, ActionError> {
    let (Some(original), Some(fee), Some(previous)) =
        (pending.rollback_charge_id.as_deref(), reply.fee_paid_msat, pending.undelivered.as_ref()) else { return Ok(false) };
    if reply.payment_hash.is_none() || reply.payment_hash != previous.payment_hash { return Ok(false); }
    let principal = reply.amount_msat.checked_add(reply.readmission_msat.unwrap_or(0))
        .ok_or_else(|| spend_journal::unknown("The reported principal overflows."))?;
    let total = principal.checked_add(fee)
        .ok_or_else(|| spend_journal::unknown("The reported paid total overflows."))?;
    with_book(state, true, |book| {
        // Repeated delivery-only attempts have zero rows. The journal also
        // retains the original request row until this operation is finished.
        let original = if book.ledger.iter().rev().find(|e| e.id == original).is_some_and(|e| e.msat == 0) {
            pending.request_hash.as_str()
        } else { original };
        let Some(entry) = book.ledger.iter_mut().rev().find(|e| e.id == original) else { return Ok(false) };
        if !entry.paid.is_some_and(|p| p.fee_unknown && p.msat == principal) { return Ok(false); }
        // Leave the original bound intact until the caller durably fences a
        // contradiction. A crash here must not turn the excess into a new cap.
        if total > entry.msat { return Ok(true); }
        entry.msat = total;
        entry.paid = Some(budget::Paid { msat: total, fee_unknown: false });
        Ok(false)
    })
}

/// A successful POST retains its context through the caller's receipt decoding.
#[derive(Debug)]
struct MoneyReply {
    text: String,
    operation_id: Option<String>,
}

impl MoneyReply {
    fn decode<T: serde::de::DeserializeOwned>(&self, path: &str) -> Result<T, ActionError> {
        act::with_op(Active(self.operation_id.as_deref()), decode_act(path, &self.text))
    }
}

/// No automatic HTTP retry on a money path. Journal before dispatch, and retain
/// ambiguity on every transport/5xx/decode failure, even across app restarts.
async fn money_post(state: &NodeState, auth: Auth, path: &str, body: serde_json::Value, max_msat: u64, charge: Option<Charge>) -> Result<MoneyReply, ActionError> {
    money_post_with(state, auth, path, body, max_msat, charge, None).await
}

/// `retry` names the paid, undelivered record a delivery retry reuses. It
/// passes the fence only if the journal holds exactly that record, not in
/// flight. The retry never removes it: the same record is rewritten in place
/// (atomically) as in flight before dispatch, and any refusal before dispatch
/// writes the prior record back. A crash at any point leaves a record.
///
/// A 1:1 compose on a `message_operations_v1` node carries an `operation_id`
/// saved in the journal before the POST. A retry of the same send, or a resend
/// of a message the node holds no payment for, reuses it: the node pays at most
/// once per id and answers 409 if the text changed.
///
/// Holds `NodeState::money` throughout: a reconcile waits for this POST.
async fn money_post_with(state: &NodeState, auth: Auth, path: &str, mut body: serde_json::Value, max_msat: u64, charge: Option<Charge>, retry: Option<&spend_journal::Undelivered>) -> Result<MoneyReply, ActionError> {
    let mut existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let _money = state.money.lock().await;
    if cfg!(test) { pause_points::at(&state.api_base, "after_lock").await; }
    // A failed refresh cannot erase an ID already observed before the wait.
    existing_operation = pending_operation_id(state).unwrap_or_else(|_| existing_operation.clone());
    refuse_if_connection_waiting(state)?;
    let journal = locked_spend_journal(state)?;
    let prior = journal.pending()?;
    existing_operation = prior.as_ref().and_then(|p| p.operation_id.clone());
    ensure_fresh_token(state).await;
    if cfg!(test) { pause_points::at(&state.api_base, "after_token").await; }
    let token = state.ordinary_token().map_err(|e| ActionError::new("app_not_ready", &e))?
        .ok_or_else(|| ActionError::new("app_not_ready", "Not authenticated."))?;
    let node_id = state.node_id.lock().unwrap().clone().ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
    if body["host_expected_node_id"].as_str().is_some_and(|expected| expected != node_id) {
        return act::with_op(Active(body["host_admission_op"].as_str()), Err(ActionError::new(
            "call_identity_changed", "This call belongs to another node identity. Nothing was paid.")));
    }
    // A minute is issued only while its call's consent is still admitted and
    // confirmed, checked again under the money lock: End (or a refusal) that
    // came while this minute waited here issues nothing.
    if path == "/messages/compose" && body["kind"].as_u64() == Some(u64::from(act::KIND_CALL_BLOCK)) {
        if let Some(refused) = block_consent_refusal(state, &node_id, &body) { return Err(refused); }
        if cfg!(test) { pause_points::at(&state.api_base, "between_block_checks").await; }
        if minute_past_journaled_hold(state, &journal, &node_id, &body, max_msat)? {
            return Err(ActionError::new(MINUTE_PAST_HOLD, MINUTE_PAST_HOLD_WORDS));
        }
    }
    // Call admission guards precede the generic pending fence, under the same
    // money lock as dispatch. Concurrent calls wait for the first receipt.
    if path == "/messages/compose" && body["is_room"].as_bool() != Some(true) {
        let kind = body["kind"].as_u64().unwrap_or(0);
        if matches!(kind, 400 | 403) {
            let peer = body["recipient"].as_str().unwrap_or_default();
            let calls = journal.call_operations(&node_id, Some(peer))?;
            let payload = body["plaintext"].as_str().and_then(|s| serde_json::from_str::<serde_json::Value>(s).ok());
            let call_id = payload.as_ref().and_then(|v| v["call_id"].as_str());
            let blocked = if kind == 400 {
                calls.iter().find(|r| spend_journal::admission_open(r, &calls))
                    .map(|r| (r, "call_admission_open", if payload.as_ref().and_then(|v| v["sdp"].as_str())
                        .is_some_and(|sdp| sdp.lines().any(|line| line.starts_with("a=x-bitsov-restart-of:"))) {
                            "Your last call is still closing. End it, then call again."
                        } else { "End the existing call before starting another admission. Nothing was paid." }))
            } else {
                let offer = calls.iter().filter(|r| r.call_id.as_deref() == call_id
                    && matches!(r.kind.as_str(), "call_offer" | "call_recovery"))
                    .max_by_key(|r| (r.created_ms, &r.op_id));
                let expected = body["host_admission_op"].as_str();
                // Preflight may have waited on quotes while the peer ended the
                // call or another admission reused its wire id. Recheck here.
                if body["host_call_snapshot"].as_bool() == Some(true)
                    && offer.map(|r| r.op_id.as_str()) != expected {
                    return act::with_op(Active(expected), Err(ActionError::new(
                        "call_not_live", "This admission has ended. Nothing was dispatched.")));
                }
                let hangup = calls.iter().find(|r| spend_journal::hangup_blocks(r)
                    && match offer {
                        Some(offer) => spend_journal::hangup_for(r, offer),
                        None => r.call_id.as_deref() == call_id && r.parent_op.is_none(),
                    });
                if let Some(hangup) = hangup {
                    Some((hangup, "hangup_in_flight", "This call already has a hangup operation. Nothing was dispatched again."))
                } else {
                    offer.filter(|r| !spend_journal::admission_open(r, &calls))
                        .map(|r| (r, "call_not_live", "This admission has ended. Nothing was dispatched."))
                }
            };
            if let Some((record, code, message)) = blocked {
                return act::with_op(Active(Some(&record.op_id)), Err(ActionError::new(code, message)));
            }
        }
    }
    match (&prior, retry) {
        (None, None) => {}
        // Holds no payment: this action replaces it, or resumes it below.
        (Some(p), None) if p.resumable && p.node_id == node_id => {}
        (Some(p), Some(u)) if u.retry && !u.in_flight && !p.over_budget && p.node_id == node_id && p.undelivered.as_ref() == Some(u) => {}
        _ => return Err(spend_journal::unknown("Check the pending result before sending again.")),
    }
    // Pause all binds every money request, whatever window or approval is open.
    refuse_if_paused(state)?;
    check_auth(state, auth)?;
    // A fresh non-paying quote distinguishes #99 from older nodes which use
    // the same capability name but may pay admission beyond the message cap.
    // Probe once per run/identity; an unavailable quote keeps the older bound.
    if !has_all_in_caps(state) && charge.as_ref().is_some_and(|c| c.readmission_possible) {
        let peer = if body["is_room"].as_bool() == Some(true) {
            read_room_members(state, body["recipient"].as_str().unwrap_or_default()).await.ok()
                .and_then(|members| members.into_iter().find(|id| id != &node_id))
        } else { body["recipient"].as_str().map(str::to_string) };
        // The charge's readmission flag came from this send's fresh status.
        if let Some(peer) = peer { let _ = read_first_contact_quote_with_cap(state, &peer, true).await; }
    }
    let all_in_caps = has_all_in_caps(state);
    // M6: a call block draws from the call's reservation, which the node made
    // under the grant when the offer went out. The grant's remaining budget
    // already excludes that hold, so it is not checked again here; the node
    // still refuses a block outside the reservation or the grant.
    let call_kind = if path == "/messages/compose" { body["kind"].as_u64() } else { None };
    let call_block = call_kind == Some(u64::from(act::KIND_CALL_BLOCK));
    // As the node: only an offer (and a block, from its hold) has call
    // authority, capped by the call per-payment limit. Answer, ICE and hangup
    // are bounded like messages, by the 6-sat message cap. An explicit
    // payment (invoice or keysend) is bounded by the signed per-payment
    // limit; messages, files and rooms keep the message cap.
    let cap = if call_kind == Some(u64::from(act::KIND_CALL_OFFER)) { grant::PaymentCap::CallCeiling }
        else if is_direct_payment(path) { grant::PaymentCap::Payment }
        else { grant::PaymentCap::Grant };
    let node_grant = if call_block { None } else {
        check_node_grant_with_envelope_ids(state, path, &body, max_msat,
            charge.as_ref().and_then(|c| c.envelope_ids), cap).await?
    };
    // A node-routed paid offer or a paid answer must fit inside the grant read
    // here, under the money lock, before anything is reserved or sent: a grant
    // replaced by a short one after the earlier checks still refuses it.
    if charge.as_ref().is_some_and(|c| c.call_window) {
        if let Some(g) = &node_grant { call_window_fits(state, g.expires_at_ms())?; }
    }
    let reserve_msat = match (&charge, &node_grant) {
        // A zero cap: the node pays nothing, re-admission included.
        _ if max_msat == 0 => 0,
        (Some(c), Some(g)) if !all_in_caps && (c.readmission_possible || g.recipient_left(&c.target).is_some()) => {
            let limit = if c.room {
                g.remaining_msat
            } else if let Some(left) = g.recipient_left(&c.target) {
                left.min(g.remaining_msat)
            } else if c.confirmed {
                // With no recipient budget, only the one-time confirmation
                // can authorize admission, bounded separately from the message.
                max_msat.saturating_mul(2).min(g.remaining_msat)
            } else {
                return Err(readmission_needs_ok());
            };
            limit.max(max_msat)
        }
        _ => max_msat,
    };
    let op = spend_journal::operation(&body);
    let one_to_one = path == "/messages/compose" && body["is_room"].as_bool() != Some(true);
    // One send, one id. A retry of it, or a resend of the same message the node
    // holds no payment for, reuses the saved id; a legacy record has none.
    let operation_id = match &prior {
        _ if !(one_to_one && charge.as_ref().is_some_and(|c| c.operation)) => None,
        Some(p) if retry.is_some() => p.operation_id.clone(),
        Some(p) if p.op.as_deref() == Some(op.as_str()) && p.operation_id.is_some() => p.operation_id.clone(),
        _ => Some(spend_journal::new_operation_id()?),
    };
    // What this send's status vouches for binds to the node it dispatches to, and
    // only to a payment this attempt makes: a reused id may name an older row,
    // unless the node refused that attempt before any dispatch.
    let failure_final_on = charge.as_ref().and_then(|c| c.failure_final_on.clone()).filter(|on| *on == node_id
        && operation_id.is_some() && (prior.as_ref().and_then(|p| p.operation_id.as_ref()) != operation_id.as_ref()
            || prior.as_ref().is_some_and(|p| p.non_dispatch_proven)));
    // Once minted/reused, the id accompanies every failure, including begin,
    // retry snapshot writes, ledger repair and the outcome error handler itself.
    let outcome = async {
    let mut pending = match (&prior, retry) {
        (Some(p), Some(_)) => {
            // Settled when the 502 came back; again here in case that write failed.
            if let (Some(paid), true) = (p.accounting_msat, charge.is_some()) { close_charge(state, p.charge_id(), Some(paid), p.target.as_ref())?; }
            // The same operation, the same record: rewritten in place, never
            // removed before this attempt exists.
            let mut next = p.clone();
            let u = next.undelivered.as_mut().expect("checked above");
            u.in_flight = true;
            u.attempts += 1;
            next.charge_id = Some(format!("{}-retry-{}", p.request_hash, u.attempts));
            next.rollback_charge_id = Some(p.charge_id().to_string());
            next.accounting_msat = None;
            next.paid = None;
            next.max_msat = max_msat;
            next.target = None;
            journal.save(&next)?;
            next
        }
        _ => {
            let mut started = journal.begin_operation(&node_id, path, &body, max_msat, operation_id.clone().map(|id| (id, op.clone())))?;
            // Saved with the dispatch time below, before the POST.
            started.failure_final_on = failure_final_on;
            started
        }
    };
    use spend_journal::OperationState as OpState;
    journal.record_outcome(&pending, OpState::Dispatching, None)?;
    let begun = pending.clone();
    let abandon = |journal: &Journal| -> Result<(), ActionError> {
        // Tests only: this step can be made to fail (`fault_points`).
        #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_abandon")?;
        if retry.is_some() {
            // This attempt paid nothing new; its original payment still exists.
            journal.record_outcome(&begun, OpState::PaidUndelivered, None)?;
        } else {
            journal.record_outcome(&begun, OpState::Unpaid, None)?;
        }
        match &prior {
            Some(p) => journal.save(p),
            None => journal.clear(),
        }
    };
    // Once pending exists, ambiguous failures also update its ledger outcome.
    let result = async {
    // Durable above; only now may the id leave the app.
    if let Some(id) = &operation_id { body["operation_id"] = serde_json::json!(id); }
    if let Some(body) = body.as_object_mut() {
        body.remove("host_hangup_cap_msat");
        body.remove("host_expected_node_id");
        body.remove("host_admission_op");
        body.remove("host_call_snapshot");
    }
    pending.all_in = true;
    let charged = match &charge {
        Some(c) => match reserve(state, auth, c, pending.charge_id(), reserve_msat) {
            Ok(()) => Some(pending.charge_id().to_string()),
            Err(e) => {
                abandon(&journal)?;
                return Err(e);
            }
        },
        None => None,
    };
    if charged.is_some() {
        pending.budgeted = true;
        // A direct payment's request is saved only now, in the same write
        // that records its reservation as held, and before the POST below:
        // recovery repeats exactly this request under exactly this key, and
        // only while that reservation is held.
        if let (true, Some(id)) = (is_direct_payment(path), body["request_id"].as_str()) {
            pending.direct = Some(spend_journal::DirectRequest { request_id: id.to_string(), path: path.to_string(), body: body.clone() });
        }
        journal.save(&pending)?;
    }
    let release = |state: &NodeState| -> Result<(), ActionError> {
        // Tests only: this step can be made to fail (`fault_points`).
        #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_release")?;
        match &charged {
            Some(id) => release_own_reservation(state, id),
            None => Ok(()),
        }
    };
    // Proven unpaid: free the reservation first, then retire the pending
    // record. A failed release returns with that record still saved, so a
    // reservation is never left held with nothing that can reconcile it.
    // The decision is saved first: if the release or the clear fails, the
    // owner's check finishes it without asking the node (`finish_unpaid_release`).
    let unpaid_cleanup = |state: &NodeState, journal: &Journal, pending: &spend_journal::Pending| -> Result<(), ActionError> {
        let mut decided = pending.clone();
        decided.unpaid_release = Some(spend_journal::UnpaidRelease {
            outcome: if retry.is_some() { OpState::PaidUndelivered } else { OpState::Unpaid },
            restore: prior.clone().map(Box::new),
        });
        let save = || -> Result<(), ActionError> {
            // Tests only: this step can be made to fail (`fault_points`).
            #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_decision")?;
            journal.save(&decided)
        };
        save()?;
        release(state)?;
        abandon(journal)
    };
    pending.non_dispatch_proven = false;
    pending.dispatched_at = Some(spend_journal::timestamp_ms());
    journal.save(&pending)?;
    if cfg!(test) { pause_points::at(&state.api_base, "before_dispatch").await; }
    // Journal I/O can take time. Recheck immediately before issuing the
    // request, after every await: no await follows until it is sent.
    if let Err(e) = refuse_if_connection_waiting(state)
        .and_then(|()| refuse_if_paused(state))
        .and_then(|()| check_auth(state, auth)) {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(e);
    }
    if cfg!(test) { pause_points::at(&state.api_base, "before_decision").await; }
    // The last step before a minute's POST: its consent, read once more under
    // the lock that End, teardown and a received hangup take without waiting
    // for the money lock. Revoked first: nothing is sent. Not revoked yet: this
    // one minute goes out, and the money lock this path holds orders End's
    // hangup after it. The consent lock is held only inside the check, not
    // during the cleanup below (which locks the budget and the node identity)
    // or the POST.
    if path == "/messages/compose" && body["kind"].as_u64() == Some(u64::from(act::KIND_CALL_BLOCK)) {
        if let Some(refused) = block_consent_refusal(state, &node_id, &body) {
            unpaid_cleanup(state, &journal, &pending)?;
            return Err(refused);
        }
    }
    if cfg!(test) { pause_points::at(&state.api_base, "after_decision").await; }
    let response = state.http.post(format!("{}{path}", state.api_base))
        .bearer_auth(token).json(&body).timeout(state.spend_timeout).send().await
        .map_err(|_| spend_journal::unknown("The node did not return a complete response."))?;
    let status = response.status();
    // These statuses are rejected by authentication before any handler runs.
    if status == reqwest::StatusCode::FORBIDDEN || status == reqwest::StatusCode::UNAUTHORIZED {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(refuse_spend(state));
    }
    let text = response.text().await.map_err(|_| spend_journal::unknown("The response was interrupted."))?;
    if act::readiness_refusal(status.as_u16(), &text) {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(act::readiness_error(status.as_u16(), &text));
    }
    // A call refusal proves unpaid only for a fresh attempt (new operation id or
    // none). An existing kind-400 operation can return call_id_used after ring
    // expiry while its earlier payment is unresolved; delivery retries also stay
    // held.
    let fresh_operation = operation_id.is_none()
        || prior.as_ref().and_then(|p| p.operation_id.as_ref()) != operation_id.as_ref();
    let fresh_attempt = retry.is_none() && fresh_operation && one_to_one;
    let call_signal = body["kind"].as_u64().is_some_and(|kind| (400..=403).contains(&kind));
    let call_signal_refused = |reason: &'static str| -> Result<ActionError, ActionError> {
        release(state)?;
        // Persist node closure evidence before restoring/clearing the slot.
        journal.record_outcome(&begun, OpState::Unpaid, Some(&serde_json::json!({"reason": reason})))?;
        abandon(&journal)?;
        Ok(ActionError::new(reason, "The node refused this call signal before payment. Nothing was paid."))
    };
    // Proven non-dispatch (#115): nothing left the wallet. Clear the journal
    // and release the app reservation; any other error stays spend_unknown.
    if act::not_dispatched_refusal(status.as_u16(), &text) {
        // Node rc19.2 and later answer a fresh 1:1 call signal this way, with
        // the rule's reason. "No live call" is how End learns the node has ended
        // the call by itself (its minute cap, a failed minute, an unpaid expiry,
        // the ring deadline), and the journal needs that reason to close the
        // admission. A minute keeps the generic answer: rc21 gives it this reason
        // too when it is early or out of order on a call that stays live, and the
        // scheduler retries `not_dispatched` but reads `call_not_live` as over.
        let call_gone = (fresh_attempt && call_signal)
            .then(|| serde_json::from_str::<serde_json::Value>(&text).ok()).flatten()
            .and_then(|v| Some((act::call_gone_reason(&v)?, act::reports_no_payment(&v))));
        match call_gone {
            Some((reason, true)) => return Err(call_signal_refused(reason)?),
            // It also names a state that may hold a payment: this proves nothing.
            Some((_, false)) => {}
            None => {
                unpaid_cleanup(state, &journal, &pending)?;
                return Err(act::call_not_dispatched(&text)
                    .unwrap_or_else(|| ActionError::new("not_dispatched", act::not_dispatched_message(&text))));
            }
        }
    }
    // Node main b21e9a94 / rc18 20c6449e: calls::refused is used only by
    // reserve_outgoing, before compose_locked creates/executes the operation.
    // Nodes since rc19.2 send a fresh call signal the reply above instead, and
    // keep this bare reason for an operation they already know.
    //
    // Node rc21 also checks a block (kind 404) again after its reservation, in
    // block_dispatch_guard, and refuses a late one with this same 400 before
    // the operation pays. Only that refusal proves a block unpaid, and not if
    // the node reports the operation in any state but unpaid.
    let block = body["kind"].as_u64() == Some(u64::from(act::KIND_CALL_BLOCK));
    if fresh_attempt && (block || call_signal) && status == reqwest::StatusCode::BAD_REQUEST {
        if let Some(reason) = serde_json::from_str::<serde_json::Value>(&text).ok()
            .and_then(|v| match v["reason"].as_str()? {
                "call_not_live" => act::reports_no_payment(&v).then_some("call_not_live"),
                _ if block => None,
                "call_id_used" => Some("call_id_used"),
                "call_busy" => Some("call_busy"),
                "call_signal_in_flight" => Some("call_signal_in_flight"),
                "call_signal_invalid" => Some("call_signal_invalid"),
                _ => None,
            }) {
            return Err(call_signal_refused(reason)?);
        }
    }
    // G1: the node refused under its grant before reserving or paying anything.
    if let Some(refusal) = grant::refusal(status.as_u16(), &text) {
        unpaid_cleanup(state, &journal, &pending)?;
        let known = state.node_grant.lock().unwrap().clone();
        if refusal.ends_grant() { drop_grant(state); }
        return Err(refusal.error(known.as_ref()));
    }
    if status == reqwest::StatusCode::CONFLICT && body.get("max_total_msat").is_some()
        && serde_json::from_str::<serde_json::Value>(&text).ok().is_some_and(|v| v["code"] == "price_cap_exceeded") {
        release(state)?;
        // Not a price change: the contact asks for admission again.
        if act::readmission_capped_refusal(status.as_u16(), &text) {
            if operation_id.is_some() && retry.is_none() {
                // The node holds this operation `prepared`, nothing paid: sending
                // this very message again (under the contact's re-admission
                // quote) reuses its id, so it can never be paid twice.
                pending.resumable = true;
                pending.non_dispatch_proven = fresh_operation || prior.as_ref().is_some_and(|p| p.non_dispatch_proven);
                pending.budgeted = false;
                pending.accounting_msat = None;
                pending.paid = None;
                pending.target = None;
                journal.save(&pending)?;
                journal.record_outcome(&pending, OpState::Unpaid, None)?;
            } else {
                abandon(&journal)?;
            }
            return Err(ActionError::new("readmission_capped", act::READMISSION_CAPPED));
        }
        abandon(&journal)?;
        return Err(ActionError::new("price_cap_exceeded", "The node refused the changed price before any payment. Refresh the quote."));
    }
    // The node compared this operation before paying anything in this call.
    if let Some(code) = operation_id.as_ref().and(act::operation_conflict(status.as_u16(), &text)) {
        match code {
            "operation_mismatch" => {
                unpaid_cleanup(state, &journal, &pending)?;
                return Err(ActionError::new("operation_mismatch", act::OPERATION_MISMATCH));
            }
            "failed_paid" => {
                release(state)?;
                journal.record_outcome(&pending, OpState::FailedPaid, serde_json::from_str(&text).ok().as_ref())?;
                journal.clear()?;
                return Err(ActionError::new("failed_paid", act::FAILED_PAID));
            }
            // An earlier attempt's payment is unresolved: keep everything held.
            _ => return Err(ActionError::new("payment_unknown", act::PAYMENT_UNKNOWN).for_pending(&pending.id)),
        }
    }
    let op_error = operation_id.as_deref().and_then(|id| act::operation_error(&text, id));
    let is_room = body["is_room"].as_bool() == Some(true);
    // BUG-PSI: the node paid, the message did not go. Known money, not an
    // unknown outcome, but the fence stays: nothing is paid again on its own.
    if let (false, "/messages/compose", Some(incomplete)) = (is_room, path, act::settled_incomplete(status.as_u16(), &text)) {
        let paid = retry.map_or(0, |u| u.paid_msat).checked_add(incomplete.amount_msat)
            .ok_or_else(|| spend_journal::unknown("The reported total overflows; the reservation stays held."))?;
        pending.over_budget = incomplete.amount_msat > reserve_msat;
        // The node's 502 reports settled principal, without a routing-fee
        // field. Keep the all-in allowance for any positive settlement, as
        // for a legacy success reply. A no-pay probe adds no new allowance.
        let accounted = if incomplete.amount_msat == 0 { 0 } else { reserve_msat.max(incomplete.amount_msat) };
        pending.accounting_msat = Some(accounted);
        pending.paid = Some(budget::Paid { msat: incomplete.amount_msat, fee_unknown: incomplete.amount_msat > 0 });
        // The node holds this operation paid: a retry with its id re-sends, never re-pays.
        let op_retry = op_error.as_ref().is_some_and(|e| e.retry_allowed
            && matches!(spend_journal::outcome(e.state.as_deref().unwrap_or_default()), spend_journal::Outcome::Paid | spend_journal::Outcome::Sent));
        let retry_safe = incomplete.retry_safe || op_retry;
        pending.undelivered = Some(spend_journal::Undelivered {
            peer: body["recipient"].as_str().unwrap_or_default().to_string(),
            paid_msat: paid,
            retry: retry_safe && !pending.over_budget,
            op,
            admission_msat: retry.map_or(incomplete.amount_msat, |u| u.admission_msat),
            in_flight: false,
            attempts: retry.map_or(0, |u| u.attempts + 1),
            payment_hash: op_error.as_ref().and_then(|e| e.payment_hash.clone()).or_else(|| retry.and_then(|u| u.payment_hash.clone())),
        });
        journal.save(&pending)?;
        journal.record_outcome(&pending, OpState::PaidUndelivered, Some(&serde_json::json!({
            "amount_msat": paid, "payment_hash": pending.undelivered.as_ref().and_then(|u| u.payment_hash.clone())
        })))?;
        if pending.over_budget {
            return Err(spend_journal::unknown(format!("The node reports {} msat settled, beyond the reserved total ({reserve_msat}). Funds may already have moved; do not retry.", incomplete.amount_msat)));
        }
        if let Some(id) = &charged { close_charge(state, id, Some(accounted), pending.target.as_ref())?; }
        return Err(ActionError::undelivered(paid, retry_safe).for_pending(&pending.id));
    }
    // A minute only: their node is catching up, and this node's own reply says the
    // attempt holds no payment. A later try is a new operation.
    if fresh_attempt && block
        && operation_id.as_deref().is_some_and(|id| act::peer_not_ready_unpaid(status.as_u16(), &text, id)) {
        // Release first: the record of the reservation goes only once the book
        // no longer holds it.
        release(state)?;
        abandon(&journal)?;
        return Err(ActionError::new("peer_not_ready", act::PEER_NOT_READY_MINUTE));
    }
    // The node answered this attempt with its own proof that nothing was paid
    // (a recipient gone offline, no call price): nothing to wait for, no fence.
    if fresh_attempt && !status.is_success()
        && operation_id.as_deref().is_some_and(|id| act::released_without_payment(&text, id)) {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(ActionError::new("not_dispatched", act::released_refusal_message(&text)));
    }
    if !status.is_success() {
        if op_error.as_ref().is_some_and(|e| spend_journal::outcome(e.state.as_deref().unwrap_or_default()) == spend_journal::Outcome::PaymentUnknown) {
            return Err(ActionError::new("payment_unknown", act::PAYMENT_UNKNOWN).for_pending(&pending.id));
        }
        return Err(spend_journal::unknown(api_error(path, status, &text)));
    }
    let mut value: serde_json::Value = serde_json::from_str(&text).map_err(spend_journal::unknown)?;
    let mut room_refused = false;
    // Admission paid again after a reconnect: outside the message's confirmed
    // cap (the node's grant bounds it), but it counts against the contact.
    let mut readmission = 0;
    let mut payment_failed = false;
    let mut prior_over_budget = false;
    let (amount, complete) = if path == "/payments/pay" {
        let receipt: act::PayReply = serde_json::from_value(value.clone()).map_err(spend_journal::unknown)?;
        (receipt.amount_msat, !receipt.preimage.is_empty())
    } else if path == "/payments/keysend" {
        let receipt: act::KeysendReply = serde_json::from_value(value.clone()).map_err(spend_journal::unknown)?;
        payment_failed = receipt.status.eq_ignore_ascii_case("failed");
        (receipt.amount_msat, matches!(receipt.status.to_ascii_lowercase().as_str(), "settled" | "failed"))
    } else {
        let receipt: act::SendReply = serde_json::from_value(value.clone()).map_err(spend_journal::unknown)?;
        if operation_id.is_some() && receipt.operation_id != operation_id {
            return Err(spend_journal::unknown("The node answered for a different operation. Nothing was dispatched again."));
        }
        journal.record_outcome(&pending, OpState::Paid, Some(&value))?;
        let complete = if is_room {
            let summary = act::room_result(&value, &body, max_msat)?;
            room_refused = summary.1;
            summary.0
        } else { true };
        readmission = receipt.readmission_msat.unwrap_or(0);
        let mut amount = receipt.amount_msat;
        if let (Some(u), Some(_)) = (retry, &operation_id) {
            prior_over_budget = refine_retry_fee(state, &pending, &receipt)?;
            // An operation reply reports the whole operation. The same settled
            // payment means this call paid nothing new; otherwise only the increase.
            amount = if receipt.payment_hash.is_some() && receipt.payment_hash == u.payment_hash { 0 }
                else { amount.saturating_add(readmission).saturating_sub(u.paid_msat) };
            readmission = 0;
            value["amount_msat"] = serde_json::json!(amount);
            value["readmission_msat"] = serde_json::Value::Null;
            if amount == 0 {
                value["max_routing_fee_msat"] = serde_json::json!(0);
                value["fee_paid_msat"] = serde_json::json!(0);
            }
        }
        (amount, complete)
    };
    pending.target = value.get("payment_hash").and_then(|h| h.as_str())
        .filter(|h| h.len() == 64 && h.bytes().all(|c| c.is_ascii_hexdigit()))
        .map(|hash| Target::Payment { hash: hash.to_string() })
        .or_else(|| Some(Target::Message {
            id: control::node_id(value.get("message_id")?.as_str()?).ok()?,
            peer: body.get("recipient")?.as_str()?.to_string(),
        }));
    // A canonical room message proves only one member. It must NEVER reconcile
    // missing/unknown members; current node API has no aggregate lookup.
    if is_room { pending.target = None; }
    // Ceilings enforce limits; only node-reported fees are payment evidence.
    let principal = amount.checked_add(readmission)
        .ok_or_else(|| spend_journal::unknown("The reported principal overflows."))?;
    let reported_fee = value.get("max_routing_fee_msat").and_then(|v| v.as_u64());
    let fee = reported_fee.unwrap_or_else(|| reserve_msat.saturating_sub(principal));
    value["max_routing_fee_msat"] = serde_json::json!(fee);
    let fee_paid = value.get("fee_paid_msat").and_then(|v| v.as_u64());
    let proven = if payment_failed { 0 } else {
        principal.checked_add(fee_paid.unwrap_or(0))
            .ok_or_else(|| spend_journal::unknown("The reported paid total overflows."))?
    };
    pending.paid = Some(budget::Paid { msat: proven, fee_unknown: !payment_failed && fee_paid.is_none() });
    let paid = if payment_failed || fee_paid.is_some() { proven } else {
        principal.checked_add(fee)
            .ok_or_else(|| spend_journal::unknown("The reported total overflows; the reservation stays held."))?
    };
    // A retained legacy allowance is not evidence that those fees were paid.
    let observed = principal.checked_add(reported_fee.unwrap_or(0))
        .ok_or_else(|| spend_journal::unknown("The reported total overflows."))?;
    pending.over_budget = prior_over_budget || amount > max_msat || ((all_in_caps || readmission == 0) && observed > max_msat) || paid > reserve_msat;
    // Save the aggregate before touching the book. A crash or failed book
    // write is recoverable without another payment or message-only history.
    // Delivered: saved with its accounting below, the record is no longer an
    // unresolved delivery, only accounting to finish, so a crash before
    // `clear` reconciles it like any known result.
    if complete && !is_room {
        pending.undelivered = None;
    }
    if let (Some(id), true) = (&charged, complete) {
        pending.accounting_msat = Some(paid);
        journal.save(&pending)?;
        close_charge(state, id, Some(paid), pending.target.as_ref())?;
    }
    if pending.over_budget || !complete {
        journal.save(&pending)?;
        if pending.over_budget {
            return Err(spend_journal::unknown(format!("The node reports {amount} msat for the message and {readmission} msat for admission, beyond the confirmed message cap ({max_msat}) or reserved total ({reserve_msat}). Funds may already have moved; do not retry.")));
        }
    } else {
        journal.record_outcome(&pending, OpState::Settled, None)?;
        journal.clear()?;
    }
    if is_room && !complete {
        return Err(spend_journal::unknown("At least one room payment is unresolved. Do not retry the room send."));
    }
    if room_refused {
        return Err(ActionError::new("room_partial", "Room send incomplete: a member was refused or a paid message could not be stored. Do not resend the whole room message."));
    }
    serde_json::to_string(&value).map_err(spend_journal::unknown)
    }.await;
    result.map_err(|error: ActionError| {
        // Explicit evidence above wins; ambiguous exits must not erase known payment.
        let saved = operation_id.as_deref().map(|id| journal.operation_record(id)).transpose();
        let update = match saved {
            Ok(Some(Some(record))) if record.state == OpState::Dispatching =>
                journal.record_outcome(&pending, OpState::Unknown, None),
            Err(error) => Err(error),
            _ => Ok(()),
        };
        update.err().unwrap_or(error)
    })
    }.await;
    act::with_op(Active(operation_id.as_deref()), outcome).map(|text| MoneyReply { text, operation_id })
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// Read-only H1 projection; the single pending slot remains the spending fence.
async fn do_op_list(state: &NodeState, peer: Option<&str>) -> Result<spend_journal::OpList, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let peer = peer.map(control::node_id).transpose().map_err(ActionError::invalid)?;
    let node_id = state.node_id.lock().unwrap().clone()
        .ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
    let dir = app_files_dir(state).ok_or_else(|| ActionError::new("app_not_ready", "No app storage."))?.join("app-spend");
    // Atomic operation files can be read without the global money/OS journal
    // locks. Keep directory work off the async executor as well.
    tokio::task::spawn_blocking(move || spend_journal::list_operations(&dir, &node_id, peer.as_deref(), spend_journal::OP_LIST_LIMIT))
        .await.map_err(spend_journal::unknown)?
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// Repair metadata only. Money and admission closure still belong to op_end_call.
async fn do_op_repair_call_index(state: &NodeState, index_id: &str) -> Result<Option<String>, ActionError> {
    let _money = state.money.lock().await;
    let node_id = state.node_id.lock().unwrap().clone()
        .ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
    spend_journal(state)?.repair_call_index(&node_id, index_id)
}

/// Waits for any money POST in flight (`NodeState::money`), then reads its record.
async fn do_spend_reconcile(state: &NodeState) -> Result<String, ActionError> {
    let mut existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let _money = state.money.lock().await;
    // A failed refresh cannot erase an ID already observed before the wait.
    existing_operation = pending_operation_id(state).unwrap_or_else(|_| existing_operation.clone());
    let journal = locked_spend_journal(state)?;
    let Some(mut pending) = journal.pending()? else { return Ok("No pending spend.".into()); };
    let operation_id = pending.operation_id.clone();
    let result = async {
    if state.node_id.lock().unwrap().as_deref() != Some(pending.node_id.as_str()) {
        return Err(spend_journal::unknown("The pending action belongs to another identity."));
    }
    if finish_unpaid_release(state, &journal, &pending)? {
        return Ok(UNPAID_RELEASE_FINISHED.into());
    }
    if pending.evidence_reservation_msat.is_some() {
        let id = pending.operation_id.clone().ok_or_else(|| spend_journal::unknown("Payment evidence has no operation identity. Inspect the owner node."))?;
        return reconcile_operation(state, &journal, pending, &id).await;
    }
    if let Some(undelivered) = &pending.undelivered {
        // Paid, not delivered. Accounting it resolves the money, not the
        // message: the record stays until a retry delivers it or the owner
        // stops retrying (`spend_dismiss_undelivered`).
        if pending.over_budget {
            return Err(spend_journal::unknown("The node exceeded its spending bound; inspect the owner node."));
        }
        if undelivered.in_flight {
            if let Some(id) = pending.operation_id.clone() {
                return reconcile_operation(state, &journal, pending, &id).await;
            }
            return Err(spend_journal::unknown("A delivery retry was sent and its result is unknown. Missing history does not prove failure; inspect the owner node. The app will not retry."));
        }
        if let Some(paid) = pending.accounting_msat {
            close_charge(state, pending.charge_id(), Some(paid), pending.target.as_ref())?;
        }
        return Err(ActionError::new("undelivered_pending", format!(
            "Accounted: {} msat paid, and the message is still not delivered. Nothing was dispatched again. Retry delivery from its card, or stop retrying it.",
            undelivered.paid_msat
        )).for_pending(&pending.id));
    }
    if let Some(paid) = pending.accounting_msat {
        if pending.over_budget {
            return Err(spend_journal::unknown("The node exceeded its spending bound; inspect the owner node."));
        }
        close_charge(state, pending.charge_id(), Some(paid), pending.target.as_ref())?;
        // Finishing accounting does not turn a permanent rejection or an
        // undelivered payment into a successfully settled operation.
        let recorded = pending.operation_id.as_deref().map(|id| journal.operation_record(id)).transpose()?.flatten();
        if !recorded.is_some_and(|r| matches!(r.state,
            spend_journal::OperationState::FailedPaid | spend_journal::OperationState::PaidUndelivered)) {
            journal.record_outcome(&pending, spend_journal::OperationState::Settled, None)?;
        }
        journal.clear()?;
        return Ok("Previous action accounted for. Nothing was dispatched again.".into());
    }
    if pending.resumable {
        return Ok(NOTHING_PAID.into());
    }
    if let Some(id) = pending.operation_id.clone() {
        return reconcile_operation(state, &journal, pending, &id).await;
    }
    let replayed = match pending.direct.clone() {
        Some(direct) => replay_direct_payment(state, &journal, &mut pending, &direct).await?,
        None => None,
    };
    let rows: Vec<serde_json::Value> = match replayed {
        Some(receipt) => vec![receipt],
        None => {
            let path = match &pending.target {
                Some(Target::Payment { .. }) => "/payments?limit=100".to_string(),
                Some(Target::Message { peer, .. }) => control::messages_path(peer, None, Some(200))?,
                None => return Err(spend_journal::unknown("No node-issued receipt ID was returned. Automatic reconciliation is unavailable; inspect the owner node. The app will not retry.")),
            };
            get_json(state, &path).await?
        }
    };
    let terminal = rows.iter().find_map(|row| {
        spend_journal::terminal(&pending, std::slice::from_ref(row)).map(|status| (status, row))
    });
    match terminal {
        Some((status, row)) => {
            // Payment history is sufficient for direct principal, but message
            // history may omit admission. Never shrink a message reservation here.
            if pending.budgeted && matches!(pending.target, Some(Target::Payment { .. })) {
                let paid = if status == "failed" { 0 } else {
                    let principal = row["amount_msat"].as_u64().ok_or_else(|| spend_journal::unknown("The payment record has no principal."))?;
                    let fee = row["fee_paid_msat"].as_u64();
                    let proven = principal.checked_add(fee.unwrap_or(0))
                        .ok_or_else(|| spend_journal::unknown("The reported paid total overflows."))?;
                    pending.paid = Some(budget::Paid { msat: proven, fee_unknown: fee.is_none() });
                    if fee.is_some() || !pending.all_in { proven } else { pending.max_msat.max(principal) }
                };
                if status == "failed" { pending.paid = Some(budget::Paid { msat: 0, fee_unknown: false }); }
                pending.over_budget = paid > pending.max_msat;
                pending.accounting_msat = Some(paid);
                journal.save(&pending)?;
                close_charge(state, &pending.request_hash, Some(paid), pending.target.as_ref())?;
                if pending.over_budget {
                    return Err(spend_journal::unknown("The node reports payment beyond the confirmed bound. Funds may already have moved; do not retry."));
                }
            }
            journal.clear()?;
            Ok(format!("Previous action {status}. Nothing was dispatched again."))
        }
        None => Err(spend_journal::unknown("No matching terminal record. Missing history does not prove failure.")),
    }
    }.await;
    act::with_op(Active(operation_id.as_deref()), result)
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

const NOTHING_PAID: &str = "Not sent - nothing was paid: your node reports no payment for this message. Nothing was dispatched again.";
const PAYMENT_FAILED: &str = "Not sent - nothing was paid: your node reports that the payment failed. Nothing was dispatched again. You can send it again.";

/// Ask the node about a direct payment by repeating its request under the
/// same `request_id`. The node answers a key it has seen from its record and
/// never pays it twice (a request it never received is paid now, once, under
/// the reservation still held for it). A settled receipt is returned as a
/// payment row for the caller's accounting; a payment hash it names is saved
/// as the target. In flight stays unknown; a refusal falls back to the
/// payment history when the hash is known.
async fn replay_direct_payment(state: &NodeState, journal: &Journal, pending: &mut spend_journal::Pending, direct: &spend_journal::DirectRequest)
    -> Result<Option<serde_json::Value>, ActionError> {
    if !is_direct_payment(&direct.path) || direct.body["request_id"].as_str() != Some(direct.request_id.as_str()) {
        return Err(spend_journal::unknown("The saved payment request is not readable; inspect the owner node. Nothing was dispatched again."));
    }
    // Repeating may pay a request the node never received: only under the
    // reservation still held for it, and never while paused. Checked again
    // after the token refresh, the last await before the POST (the caller
    // holds the money lock; pausing does not take it).
    if let Some(refused) = replay_refusal(state, journal, pending) { return Err(refused); }
    ensure_fresh_token(state).await;
    if let Some(refused) = replay_refusal(state, journal, pending) { return Err(refused); }
    let token = state.ordinary_token()
        .map_err(|_| spend_journal::unknown("The node's network is not checked yet. Nothing was dispatched again."))?
        .ok_or_else(|| spend_journal::unknown("The node is not authenticated yet. Nothing was dispatched again."))?;
    // One attempt, no re-authentication loop: a refused sign-in sends nothing.
    let response = state.http.post(format!("{}{}", state.api_base, direct.path))
        .bearer_auth(token).json(&direct.body).timeout(state.spend_timeout).send().await
        .map_err(|_| spend_journal::unknown("Your node did not answer about this payment. It is never paid twice under its request ID."))?;
    let status = response.status();
    let text = response.text().await
        .map_err(|_| spend_journal::unknown("Your node's answer about this payment was interrupted. It is never paid twice under its request ID."))?;
    if !status.is_success() {
        if matches!(pending.target, Some(Target::Payment { .. })) { return Ok(None); }
        return Err(spend_journal::unknown(api_error(&direct.path, status, &text)));
    }
    let mut receipt: serde_json::Value = serde_json::from_str(&text).map_err(spend_journal::unknown)?;
    if receipt["request_id"].as_str() != Some(direct.request_id.as_str()) {
        return Err(spend_journal::unknown("The node answered for a different payment request. Nothing was dispatched again."));
    }
    let hash = receipt["payment_hash"].as_str()
        .filter(|h| h.len() == 64 && h.bytes().all(|c| c.is_ascii_hexdigit()))
        .map(str::to_string);
    if let (None, Some(hash)) = (&pending.target, &hash) {
        pending.target = Some(Target::Payment { hash: hash.clone() });
        journal.save(pending)?;
    }
    if receipt["status"].as_str() != Some("settled") || hash.is_none() {
        return Err(spend_journal::unknown("Your node reports this payment still in flight. Check again shortly. It is never paid twice under its request ID."));
    }
    receipt["direction"] = serde_json::json!("outgoing");
    Ok(Some(receipt))
}
/// A saved direct-payment request may be repeated only while this exact
/// pending record is current, unaccounted, and its reservation is held in the
/// budget book at its full bound; and only while payments are not paused.
/// The refusal, if not.
fn replay_refusal(state: &NodeState, journal: &Journal, pending: &spend_journal::Pending) -> Option<ActionError> {
    if let Err(refused) = refuse_if_paused(state).and_then(|()| refuse_if_connection_busy(state)) {
        return Some(refused);
    }
    let current = match journal.pending() { Ok(current) => current, Err(error) => return Some(error) };
    let unchanged = current.as_ref().is_some_and(|c| c.id == pending.id && c.direct == pending.direct
        && c.accounting_msat.is_none() && c.budgeted);
    let held = unchanged && with_book(state, false, |book| Ok(book.ledger.iter().any(|e|
        e.id == pending.charge_id() && !e.settled && e.msat >= pending.max_msat))).unwrap_or(false);
    (!held).then(|| spend_journal::unknown("This payment's budget reservation is not held, so its request was not sent again. Inspect the owner node."))
}

const RECONCILE_WAIT: &str = "Payment unknown: the original send may still reach your node. Another spend is blocked; check again in a few minutes. Nothing was dispatched again.";

fn unpaid_grace_elapsed(dispatched_at: u64, now: u64, timeout: Duration) -> bool {
    Duration::from_millis(now.saturating_sub(dispatched_at)) >= timeout.saturating_add(Duration::from_secs(180))
}

fn operation_reply_outcome(reply: &act::SendReply) -> spend_journal::Outcome {
    use spend_journal::Outcome;
    match reply.state.as_deref().unwrap_or_default() {
        // Admission may have settled even though the message never dispatched.
        "prepared" | "released" | "abandoned" if reply.amount_msat > 0
            || reply.readmission_msat.unwrap_or(0) > 0 || reply.payment_hash.is_some() => Outcome::Paid,
        "abandoned" => Outcome::NothingPaid,
        state => spend_journal::outcome(state),
    }
}

/// The node's answer for a payment its wallet tried and that failed for good:
/// `released`, still naming the payment's hash, with nothing settled or paid
/// again. The node writes it in one place, its `reconcile`, on a failed or
/// expired status for exactly this hash, amount and direction, and treats it as
/// proof: it may pay that operation again (`compose_locked`) and calls it
/// "definitely not paid" (`payloads::call::settlement`). Its abandon refuses
/// this row, because the hash shows a dispatch, so no tombstone can ever follow.
fn reports_failed_payment(reply: &act::SendReply) -> bool {
    reply.state.as_deref() == Some("released") && reply.payment_hash.is_some()
        && reply.amount_msat == 0 && reply.readmission_msat.unwrap_or(0) == 0
        && reply.fee_paid_msat.is_none() && reply.retry_allowed
        && !reply.accepted && !reply.delivered
}

/// Nothing this app already holds contradicts that reply. Only a previous
/// reading of the same failure may be on record: zero paid, the same hash.
fn no_payment_on_record(journal: &Journal, pending: &spend_journal::Pending, id: &str, reply: &act::SendReply) -> Result<bool, ActionError> {
    use spend_journal::OperationState as OpState;
    let clean = pending.undelivered.is_none() && !pending.over_budget
        && pending.accounting_msat.unwrap_or(0) == 0
        && pending.paid.as_ref().is_none_or(|p| p.msat == 0 && !p.fee_unknown);
    Ok(clean && journal.operation_record(id)?.is_some_and(|r| r.paid_msat.unwrap_or(0) == 0
        && r.payment_hash.as_ref().is_none_or(|hash| Some(hash) == reply.payment_hash.as_ref())
        && !matches!(r.state, OpState::Paid | OpState::Settled | OpState::Closed | OpState::FailedPaid)))
}

/// This node's identity, if its status shows that a payment it reports failed is
/// really over. LDK reports a payment failed once none of its HTLCs is left and
/// none will be retried (`Event::PaymentFailed`), and it does not retry after a
/// restart. Node rc14 and older could also mark an outgoing payment failed when an
/// inbound HTLC used its hash, with the payment still in flight; rc15 stopped that
/// and was the first to offer abandon, the capability checked here. Any other
/// wallet's status comes from outside this source, so it does not count.
fn final_failure_node(status: &serde_json::Value) -> Option<String> {
    let offers_abandon = status["api_capabilities"].as_array()
        .is_some_and(|caps| caps.iter().any(|cap| cap.as_str() == Some("message_operation_abandon_v1")));
    if status["lightning_backend"].as_str() != Some("ldk") || !offers_abandon { return None; }
    status["node_id"].as_str().map(str::to_string)
}

/// Today's status alone cannot vouch for that reply: an upgrade carries a row over
/// unchanged, and the node never reads the wallet for it again. So it counts only
/// for a payment dispatched under such a status, recorded then for this identity,
/// and while the node still shows it.
async fn wallet_failure_is_final(state: &NodeState, pending: &spend_journal::Pending) -> Result<bool, ActionError> {
    if pending.failure_final_on.as_deref() != Some(pending.node_id.as_str()) { return Ok(false); }
    let status: serde_json::Value = get_json(state, "/status").await.map_err(spend_journal::unknown)?;
    Ok(final_failure_node(&status).as_deref() == Some(pending.node_id.as_str()))
}

/// Ask the node what became of this send (`GET /messages/operations/{id}`).
/// Never re-sends and never pays: a retry is a separate owner action that
/// reuses the same id. Unknown or unrecognised states keep the fence.
/// What the owner's check answers once it has finished a saved unpaid release.
const UNPAID_RELEASE_FINISHED: &str = "Previous action accounted for. Nothing was dispatched again.";

/// A cleanup proved this attempt unpaid and saved that decision before
/// releasing its reservation, then the release or the clear failed. Carry out
/// exactly that decision, as the cleanup would have: release the reservation
/// (nothing if it is already gone), record the outcome, then put back the
/// earlier record or clear. No node is asked and nothing is decided here.
/// Only for the pending record of this node identity.
fn finish_unpaid_release(state: &NodeState, journal: &Journal, pending: &spend_journal::Pending) -> Result<bool, ActionError> {
    let Some(decided) = &pending.unpaid_release else { return Ok(false) };
    if state.node_id.lock().unwrap().as_deref() != Some(pending.node_id.as_str()) { return Ok(false); }
    release_own_reservation(state, pending.charge_id())?;
    journal.record_outcome(pending, decided.outcome.clone(), None)?;
    match &decided.restore {
        Some(prior) => journal.save(prior)?,
        None => journal.clear()?,
    }
    Ok(true)
}

async fn reconcile_operation(state: &NodeState, journal: &Journal, pending: spend_journal::Pending, id: &str) -> Result<String, ActionError> {
    reconcile_operation_with_reply(state, journal, pending, id, None).await
}

/// A resume POST's answer uses the same evidence/accounting rules as a lookup.
async fn reconcile_operation_with_reply(state: &NodeState, journal: &Journal, mut pending: spend_journal::Pending, id: &str, response: Option<(reqwest::StatusCode, String)>) -> Result<String, ActionError> {
    let result = async {
    use spend_journal::{Outcome, OperationState as OpState};
    if finish_unpaid_release(state, journal, &pending)? {
        return Ok(UNPAID_RELEASE_FINISHED.into());
    }
    // Never retain stale permission after a failed check or a changed state.
    if pending.admission_resume {
        pending.admission_resume = false;
        journal.save(&pending)?;
        journal.record_outcome(&pending, OpState::Unknown, None)?;
    }
    let path = format!("/messages/operations/{id}");
    let lookup_started_at = spend_journal::timestamp_ms();
    let (status, mut text) = match response {
        Some(reply) => reply,
        None => call_api(state, reqwest::Method::GET, &path, None).await
            .map_err(|e| spend_journal::unknown(format!("Your node could not be asked about this send ({e}). Nothing was dispatched again.")))?,
    };
    let decode = |text: &str| -> Result<act::SendReply, ActionError> {
        let reply: act::SendReply = serde_json::from_str(text).map_err(spend_journal::unknown)?;
        if reply.operation_id.as_deref() != Some(id) {
            return Err(spend_journal::unknown("The node answered for a different operation. Nothing was dispatched again."));
        }
        Ok(reply)
    };
    let mut reply = if status == reqwest::StatusCode::NOT_FOUND { None } else {
        if !status.is_success() {
            return Err(spend_journal::unknown(api_error(&path, status, &text)));
        }
        Some(decode(&text)?)
    };
    let mut outcome = reply.as_ref().map_or(Outcome::NothingPaid, operation_reply_outcome);
    let payment_failed = match &reply {
        Some(reply) if reports_failed_payment(reply) && no_payment_on_record(journal, &pending, id, reply)? => wallet_failure_is_final(state, &pending).await?,
        _ => false,
    };
    if payment_failed {
        outcome = Outcome::NothingPaid;
    } else if outcome == Outcome::NothingPaid {
        // History can be ahead of the pending slot after a crash between the
        // evidence write and save below. Its amount/hash survive Unknown
        // transitions, so repeated empty lookups cannot erase that evidence.
        let recorded_evidence = journal.operation_record(id)?.is_some_and(|record|
            record.paid_msat.is_some_and(|paid| paid > 0) || record.payment_hash.is_some());
        if pending.evidence_reservation_msat.is_some() || recorded_evidence {
            outcome = Outcome::PaymentUnknown;
        }
    }
    let retry = pending.undelivered.clone();
    // A durable tombstone also survives a lost abandon reply or a host crash.
    let mut abandoned = outcome == Outcome::NothingPaid
        && reply.as_ref().is_some_and(|r| r.state.as_deref() == Some("abandoned"));
    if outcome == Outcome::NothingPaid && retry.is_none() && !abandoned && !payment_failed {
        let status: serde_json::Value = get_json(state, "/status").await.map_err(spend_journal::unknown)?;
        let offers_abandon = status["api_capabilities"].as_array().is_some_and(|caps|
            caps.iter().any(|cap| cap.as_str() == Some("message_operation_abandon_v1")));
        if offers_abandon {
            let path = format!("{path}/abandon");
            let (status, body) = call_api(state, reqwest::Method::POST, &path, None).await
                .map_err(spend_journal::unknown)?;
            match status {
                reqwest::StatusCode::OK | reqwest::StatusCode::CREATED => abandoned = true,
                reqwest::StatusCode::CONFLICT => {
                    reply = Some(decode(&body)?);
                    text = body;
                    outcome = operation_reply_outcome(reply.as_ref().unwrap());
                    abandoned = outcome == Outcome::NothingPaid
                        && reply.as_ref().unwrap().state.as_deref() == Some("abandoned");
                    // A refusal is not proof of abandonment, even if its view
                    // still looks prepared. Never loop or bypass it via grace.
                    if outcome == Outcome::NothingPaid && !abandoned { outcome = Outcome::PaymentUnknown; }
                }
                reqwest::StatusCode::NOT_FOUND => {} // Older node: bounded fallback below.
                _ => return Err(spend_journal::unknown(api_error(&path, status, &body))),
            }
        }
    }
    // Serialised with every money action; still, never write over a record
    // that another action replaced, or whose retry started or ended, meanwhile.
    let in_flight = |p: &spend_journal::Pending| p.undelivered.as_ref().map(|u| u.in_flight);
    if journal.pending()?.is_none_or(|now| now.id != pending.id || in_flight(&now) != in_flight(&pending)) {
        return Err(spend_journal::unknown("The pending result changed while your node was asked. Nothing was dispatched again; check the pending result again."));
    }
    if outcome == Outcome::NothingPaid && retry.is_none() && !abandoned && !payment_failed {
        let now = spend_journal::timestamp_ms();
        // Old journals have no dispatch time: start a durable, conservative
        // window now rather than assuming an old or missing GET is final.
        let dispatched_at = *pending.dispatched_at.get_or_insert(now);
        journal.save(&pending)?;
        // A lookup begun before the deadline may already be stale by the time
        // /status or the unsupported abandon request finishes.
        // Calls cannot use the legacy elapsed-time fallback: even an old
        // 404/prepared/released snapshot can race the original POST. Only a
        // node tombstone/confirmed abandon excludes future dispatch.
        // Metadata-less legacy journals may also be calls. Their hash alone
        // cannot establish otherwise, so require node abandonment for them too.
        let call_operation = journal.operation_record(id)?.is_none_or(|r| r.kind == "legacy" || r.kind.starts_with("call_"));
        if call_operation || !unpaid_grace_elapsed(dispatched_at, lookup_started_at, state.spend_timeout) {
            journal.record_outcome(&pending, OpState::Unknown, None)?;
            return Err(ActionError::new("payment_unknown", RECONCILE_WAIT).for_pending(&pending.id));
        }
    }
    let reply = match (outcome, reply) {
        (Outcome::PaymentUnknown, _) => {
            journal.record_outcome(&pending, OpState::Unknown, None)?;
            return Err(ActionError::new("payment_unknown", act::PAYMENT_UNKNOWN).for_pending(&pending.id));
        }
        (Outcome::NothingPaid, _) if retry.is_some() => {
            return Err(spend_journal::unknown("Your node holds no payment for a message it reported paid. Inspect the owner node; the app will not retry."));
        }
        (Outcome::NothingPaid, _) => {
            // A crash before the save below repeats this release. An earlier
            // identical send shares the charge id: its row must not go instead.
            if pending.budgeted { release_own_reservation(state, pending.charge_id())?; }
            // Tests only: stop between the release and the save below (`fault_points`).
            #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_reconcile_released")?;
            pending.resumable = true;
            pending.budgeted = false;
            pending.accounting_msat = None;
            pending.evidence_reservation_msat = None;
            pending.paid = None;
            pending.target = None;
            journal.record_outcome(&pending, OpState::Unpaid, None)?;
            // This id is never posted again. A later attempt is a new operation,
            // so no old reading of this row can ever stand for it.
            if abandoned || payment_failed {
                pending.operation_id = None;
                pending.operation_record = None;
            }
            journal.save(&pending)?;
            return Ok(if payment_failed { PAYMENT_FAILED } else { NOTHING_PAID }.into());
        }
        (_, Some(reply)) => reply,
        (_, None) => unreachable!("only NothingPaid lacks a reply"),
    };
    let history = journal.operation_record(id)?;
    // Node operations::response includes admission in amount_msat; a prepared
    // row without a message id/hash has not dispatched the message (§5 of
    // .plan-abandon.md). No other evidence shape authorizes compose again.
    let admission_only = reply.state.as_deref() == Some("prepared") && reply.amount_msat > 0
        && reply.readmission_msat.unwrap_or(0) == 0 && reply.payment_hash.is_none()
        && reply.message_id.is_empty() && !reply.delivered && !reply.accepted && reply.retry_allowed
        && retry.is_none() && pending.op.is_some() && pending.peer.is_some()
        && history.as_ref().is_some_and(|r| r.kind == "message" && r.payment_hash.is_none()
            && r.message_id.is_none() && r.paid_msat.unwrap_or(0) <= reply.amount_msat
            && !matches!(r.state, OpState::Paid | OpState::Settled | OpState::Closed | OpState::FailedPaid));
    let evidence: serde_json::Value = serde_json::from_str(&text).map_err(spend_journal::unknown)?;
    let recorded = match outcome {
        Outcome::Accepted | Outcome::Sent => OpState::Paid,
        Outcome::FailedPaid => OpState::FailedPaid,
        _ => OpState::PaidUndelivered,
    };
    journal.record_outcome(&pending, recorded, Some(&evidence))?;
    let prior_over_budget = refine_retry_fee(state, &pending, &reply)?;
    // The reply covers the whole operation; a retry accounts only what it added.
    let whole = reply.amount_msat.checked_add(reply.readmission_msat.unwrap_or(0))
        .ok_or_else(|| spend_journal::unknown("The reported principal overflows."))?;
    let principal = match &retry {
        Some(u) if reply.payment_hash.is_some() && reply.payment_hash == u.payment_hash => 0,
        Some(u) => whole.saturating_sub(u.paid_msat),
        None => whole,
    };
    let proven = if principal == 0 { 0 } else {
        principal.checked_add(reply.fee_paid_msat.unwrap_or(0))
            .ok_or_else(|| spend_journal::unknown("The reported paid total overflows."))?
    };
    pending.paid = Some(budget::Paid { msat: proven, fee_unknown: principal > 0 && reply.fee_paid_msat.is_none() });
    let reported_ceiling = serde_json::from_str::<serde_json::Value>(&text).ok()
        .and_then(|v| v["max_routing_fee_msat"].as_u64());
    let reserved = match pending.evidence_reservation_msat {
        Some(reserved) => reserved,
        None => with_book(state, false, |book| Ok(book.ledger.iter().rev()
            .find(|e| e.id == pending.charge_id()).map_or(pending.max_msat, |e| e.msat)))?,
    };
    let paid = if principal == 0 || reply.fee_paid_msat.is_some() { proven } else {
        principal.checked_add(reported_ceiling.unwrap_or_else(|| reserved.saturating_sub(principal)))
            .ok_or_else(|| spend_journal::unknown("The reported total overflows."))?
    };
    let message_msat = if retry.is_some() { principal } else { reply.amount_msat };
    pending.over_budget = pending.over_budget || prior_over_budget || message_msat > pending.max_msat || paid > reserved;
    let evidence_only = matches!(reply.state.as_deref(), Some("prepared" | "released" | "abandoned"));
    let paid_msat = retry.as_ref().map_or(whole, |u| u.paid_msat.saturating_add(principal));
    pending.evidence_reservation_msat = evidence_only.then_some(reserved);
    if outcome == Outcome::Paid && !evidence_only {
        pending.undelivered = Some(spend_journal::Undelivered {
            peer: retry.as_ref().map(|u| u.peer.clone()).or_else(|| pending.peer.clone()).unwrap_or_default(),
            paid_msat,
            retry: reply.retry_allowed,
            op: retry.as_ref().map(|u| u.op.clone()).or_else(|| pending.op.clone()).unwrap_or_default(),
            admission_msat: retry.as_ref().map_or(0, |u| u.admission_msat),
            in_flight: false,
            attempts: retry.as_ref().map_or(0, |u| u.attempts),
            payment_hash: reply.payment_hash.clone(),
        });
    }
    pending.accounting_msat = Some(paid);
    pending.admission_resume = admission_only && !pending.over_budget;
    journal.save(&pending)?;
    if pending.budgeted { close_charge(state, pending.charge_id(), Some(paid), pending.target.as_ref())?; }
    if pending.admission_resume {
        journal.record_outcome(&pending, OpState::AdmissionResumable, None)?;
        return Ok(format!("Admission paid ({paid_msat} msat), message not sent. Send the same message with the same cap to resume its existing operation. Nothing was dispatched again."));
    }
    if pending.over_budget {
        return Err(spend_journal::unknown("The node reports payment beyond the confirmed bound. Funds may already have moved; do not retry."));
    }
    match outcome {
        Outcome::Accepted | Outcome::Sent => {
            journal.record_outcome(&pending, OpState::Settled, None)?;
            journal.clear()?;
            Ok(if outcome == Outcome::Accepted {
                format!("Accepted: the recipient's node stored it ({whole} msat paid). Nothing was dispatched again.")
            } else {
                format!("Sent: paid ({whole} msat) and handed to the recipient's node, not yet accepted. Your node keeps delivering it; nothing was dispatched again.")
            })
        }
        Outcome::FailedPaid => {
            journal.clear()?;
            Err(ActionError::new("failed_paid", act::FAILED_PAID))
        }
        _ => {
            if evidence_only {
                return Err(ActionError::new("payment_unknown", format!(
                    "Accounted: {paid_msat} msat of payment evidence, but the operation's final outcome is unknown. Another spend is blocked; check the pending result again in a few minutes. Nothing was dispatched again."
                )).for_pending(&pending.id));
            }
            Err(ActionError::new("undelivered_pending", format!(
                "Accounted: {paid_msat} msat paid, and the message is not delivered yet. Your node keeps resending it; nothing was dispatched again. Retry delivery from its card (it pays nothing new), or stop retrying it."
            )).for_pending(&pending.id))
        }
    }
    }.await;
    act::with_op(Active(Some(id)), result)
}

/// The owner stops retrying a paid, undelivered message. Only a record whose
/// money is fully known (no retry in flight, within its bound) is released,
/// after its accounting is written. Nothing is dispatched.
fn do_spend_dismiss_undelivered(state: &NodeState, pending_id: &str) -> Result<String, ActionError> {
    let mut existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = (|| {
    let Ok(_money) = state.money.try_lock() else {
        return Err(ActionError::new("money_busy", "Another payment action is still running. Nothing was changed; try again in a moment."));
    };
    existing_operation = pending_operation_id(state).unwrap_or_else(|_| existing_operation.clone());
    let journal = locked_spend_journal(state)?;
    // Only the record the owner chose: a stale card never releases another message.
    let pending = journal.pending()?.filter(|p| p.id == pending_id)
        .ok_or_else(|| ActionError::new("retry_unavailable", "That message is no longer waiting for delivery. Nothing was changed."))?;
    let operation_id = pending.operation_id.clone();
    let result = (|| {
    if state.node_id.lock().unwrap().as_deref() != Some(pending.node_id.as_str()) {
        return Err(spend_journal::unknown("The pending action belongs to another identity."));
    }
    if pending.evidence_reservation_msat.is_some() {
        return Err(spend_journal::unknown("Payment evidence is not a final outcome. Check the pending result; the spending fence stays in place."));
    }
    let undelivered = match &pending.undelivered {
        Some(u) if !u.in_flight && !pending.over_budget => u.clone(),
        _ => return Err(spend_journal::unknown("This pending result is not a known paid, undelivered message. Check the pending result.")),
    };
    if let Some(paid) = pending.accounting_msat {
        close_charge(state, pending.charge_id(), Some(paid), pending.target.as_ref())?;
    }
    journal.record_outcome(&pending, spend_journal::OperationState::Settled, None)?;
    journal.clear()?;
    Ok(format!("Stopped retrying. {} msat was paid and the message was not delivered; nothing more will be paid for it.", undelivered.paid_msat))
    })();
    act::with_op(Active(operation_id.as_deref()), result)
    })();
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

// ---- G1 node grants -------------------------------------------------------------
//
// See `grant.rs`. Without `spend_budget_grant_v1` the node keeps the pre-G1
// behaviour. With it, `GET /pair/grant` bounds every approval this app opens.

/// Does the node advertise budget grants? An unreadable `/status` is an error.
async fn node_has_g1(state: &NodeState) -> Result<bool, ActionError> {
    let status: serde_json::Value = get_json(state, "/status").await.map_err(|_| grant::unreadable())?;
    let caps = status["api_capabilities"].as_array().ok_or_else(grant::unreadable)?;
    Ok(caps.iter().any(|v| v.as_str() == Some(grant::CAPABILITY)))
}

async fn read_grant(state: &NodeState) -> Result<Option<NodeGrant>, ActionError> {
    // Read capabilities first so the grant remains the freshest authority
    // check immediately before a paid request.
    let envelope_ids = node_offers(state, grant::RELATION_ENVELOPE_ID_CAPABILITY).await;
    read_grant_with_envelope_ids(state, envelope_ids).await
}

async fn read_grant_with_envelope_ids(state: &NodeState, envelope_ids: bool) -> Result<Option<NodeGrant>, ActionError> {
    let (status, body) = call_api(state, reqwest::Method::GET, "/pair/grant", None).await.map_err(|_| grant::unreadable())?;
    if !status.is_success() {
        return Err(grant::unreadable());
    }
    let mut grant = grant::parse(&body)?;
    if let Some(g) = grant.as_mut() {
        if !envelope_ids {
            g.envelope_id_by_recipient = None;
        }
    }
    Ok(grant)
}

/// Before opening anything on a paired node: `Ok(None)` on a pre-G1 node, the
/// live grant on a G1 node, or an error that opens nothing (`grant_ended` when
/// the node holds no live grant, `grant_unknown` when it could not be read).
async fn grant_for_open(state: &NodeState) -> Result<Option<NodeGrant>, ActionError> {
    if !node_has_g1(state).await? {
        return Ok(None);
    }
    match read_grant(state).await? {
        Some(g) if g.live(now_ms()) => Ok(Some(g)),
        _ => Err(grant::ended()),
    }
}

/// Open what was asked, bounded by the node grant when there is one: never past
/// its expiry, and a budget approval never above its total. The caller holds
/// both approval locks and has checked the fence.
fn arm_want(spend: &mut act::SpendGate, autopay: &mut budget::Autopay, want: Want, basis: act::SpendBasis, node: Option<&NodeGrant>) {
    let until = node.map_or(u64::MAX, NodeGrant::expires_at_ms);
    match want {
        Want::Window => spend.arm_granted_until(now_ms(), until, basis, node.map(|g| g.op_id.as_str())),
        Want::Budget(ceiling) => {
            let ceiling = node.map_or(ceiling, |g| ceiling.min(g.budget_msat));
            autopay.arm_until(now_ms(), until, ceiling, basis)
        }
    }
}

/// The owner's cancellation fence: the window's and the budget approval's
/// generations. Lock, Pause all, expiry and a dropped grant each bump one.
fn approval_fence(state: &NodeState) -> (u64, u64) {
    let spend = state.spend.lock().unwrap().generation();
    let autopay = state.autopay.lock().unwrap().generation();
    (spend, autopay)
}

fn fence_broken() -> ActionError {
    ActionError::new(
        "budget_needed",
        "Spending was paused or locked while your approval was being opened. Nothing was opened; approve it again.",
    )
}

/// Open `want` only if payments are not paused and neither approval changed
/// since `fence` was taken, checked and opened under both locks at once. An
/// answer that arrives after the owner paused or locked opens nothing.
fn open_fenced(state: &NodeState, fence: (u64, u64), want: Want, basis: act::SpendBasis, node: Option<&NodeGrant>) -> Result<(), ActionError> {
    // Pause writes the book after bumping both generations, so a pause that
    // lands after this read is caught by the generation check below.
    if budget_paused(state)? {
        return Err(ActionError::new("budget_paused", "Payments are paused. Resume them first."));
    }
    let mut spend = state.spend.lock().unwrap();
    let mut autopay = state.autopay.lock().unwrap();
    if (spend.generation(), autopay.generation()) != fence {
        return Err(fence_broken());
    }
    arm_want(&mut spend, &mut autopay, want, basis, node);
    *state.node_grant.lock().unwrap() = node.cloned();
    Ok(())
}

/// The node grant is gone: close everything that was opened under it.
fn drop_grant(state: &NodeState) {
    state.autopay.lock().unwrap().lock();
    state.spend.lock().unwrap().lock();
    *state.wants.lock().unwrap() = Wants::default();
    *state.node_grant.lock().unwrap() = None;
}

/// Re-read the node grant immediately before a paid request, and refuse what
/// it would refuse. Only when this run opened its approvals under one.
async fn check_node_grant(state: &NodeState, path: &str, body: &serde_json::Value, max_msat: u64) -> Result<Option<NodeGrant>, ActionError> {
    check_node_grant_with_envelope_ids(state, path, body, max_msat, None, grant::PaymentCap::Grant).await
}

/// `cap` names the per-payment maximum: the 6-sat message cap for messages,
/// files and rooms; the signed limit for an explicit payment; for one call payment, the call's pinned
/// per-block ceiling (enforced by the node) plus the call per-payment limit;
/// none for a whole call's summed payments (`CallTotal`).
async fn check_node_grant_with_envelope_ids(state: &NodeState, path: &str, body: &serde_json::Value, max_msat: u64, envelope_ids: Option<bool>, cap: grant::PaymentCap) -> Result<Option<NodeGrant>, ActionError> {
    if state.node_grant.lock().unwrap().is_none() {
        return Ok(None);
    }
    let now = now_ms();
    let grant = match envelope_ids {
        Some(offered) => read_grant_with_envelope_ids(state, offered).await?,
        None => read_grant(state).await?,
    };
    let Some(g) = grant.filter(|g| g.live(now)) else {
        drop_grant(state);
        return Err(grant::ended());
    };
    // The node keys a peer message or file by node id and a keysend by
    // `dest_pubkey`; rooms and invoices are checked member by member there.
    let recipient = match path {
        "/payments/keysend" => body["dest_pubkey"].as_str(),
        "/payments/pay" => None,
        porch::ROUTE => body["node_id"].as_str(),
        _ if body["is_room"].as_bool() == Some(true) => None,
        _ => body["recipient"].as_str(),
    };
    let checked = g.check_under(cap, max_msat, recipient, now);
    *state.node_grant.lock().unwrap() = Some(g.clone());
    checked.map(|()| Some(g))
}

/// The G1 `budget` proposal for an elevation request. Only a suggestion.
fn budget_proposal(state: &NodeState, want: Want, minimum: Option<u64>) -> Option<serde_json::Value> {
    let book = with_book(state, false, |b| Ok(b.clone())).ok()?;
    Some(match want {
        Want::Budget(ceiling) => grant::proposal(ceiling, grant::MAX_TTL_SECS, &book.contacts),
        // A whole day, as the node allows: the app's own ten-minute lock
        // (`act::SPEND_WINDOW_MS`) still closes payments here by itself.
        Want::Window => grant::proposal(book.ceiling_msat.max(minimum.unwrap_or(0)), grant::MAX_TTL_SECS, &Default::default()),
    })
}

/// Advance the spend window. `ask` is the owner's tap: on rc7 it opens the
/// app's own window; on a paired node it opens a window over an existing grant
/// or asks the node for one. Without `ask`, only polls a pending request.
async fn spend_advance(state: &NodeState, ask: bool) -> Result<act::SpendView, ActionError> {
    Ok(spend_advance_for(state, ask.then_some(Want::Window)).await?.view)
}

/// A call proposal covers the reservation and signals; an explicit replacement
/// still needs the node owner's approval.
async fn do_spend_request(state: &NodeState, budget_msat: Option<u64>, call_peer: Option<&str>) -> Result<act::SpendView, ActionError> {
    if let Some(amount) = budget_msat {
        if amount == 0 || amount > budget::MAX_DAILY_MSAT {
            return Err(ActionError::invalid("the requested budget must be positive and within the app total limit"));
        }
        if !matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(_)) {
            return Err(ActionError::invalid("this node does not support a replacement budget request"));
        }
        return Ok(spend_advance_with_proposal(state, Some(Want::Window), Some(amount), None).await?.view);
    }
    let Some(peer) = call_peer else { return spend_advance(state, true).await };
    refuse_if_paused(state)?;
    let fence = approval_fence(state);
    let quote = read_call_quote_with_blocks(state, peer).await.map_err(ActionError::node)?;
    if approval_fence(state) != fence { return Err(fence_broken()); }
    let minimum = quote.reservation_max_msat.zip(quote.call_total_msat)
        .and_then(|(hold, signals)| hold.checked_add(signals))
        .filter(|total| *total <= control::MAX_SAFE_MSAT)
        .ok_or_else(|| ActionError::new("call_price_unknown", "The call price is unavailable. Read it again before requesting a call budget."))?;
    Ok(spend_advance_with_proposal(state, Some(Want::Window), None, Some(minimum)).await?.view)
}

/// Separate the current view from the window this invocation actually armed.
struct SpendAdvance {
    view: act::SpendView,
    armed_granted_op: Option<String>,
}

/// Open what the owner asked for (`want`): the ten-minute window or the budget
/// approval. On a paired node without `spend`, both go through one elevation
/// request, and a grant opens only what was asked.
async fn spend_advance_for(state: &NodeState, want: Option<Want>) -> Result<SpendAdvance, ActionError> {
    spend_advance_with_proposal(state, want, None, None).await
}

async fn spend_advance_with_proposal(state: &NodeState, want: Option<Want>, budget_msat: Option<u64>, minimum: Option<u64>) -> Result<SpendAdvance, ActionError> {
    // The shell polls spend before budget at startup. Read current authority
    // before a saved request changes the pristine approval generations. The
    // request may already have been granted, with a much longer grant expiry.
    // A failed read leaves restoration retryable and the saved request intact.
    if want.is_none() && !state.approvals_restored.load(Ordering::SeqCst)
        && matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(_)) {
        do_budget_status(state).await?;
    }
    restore_spend_pending(state);
    let out = spend_advance_for_inner(state, want, budget_msat, minimum).await;
    save_spend_pending(state);
    out
}

/// Where this node's pending console approval is saved (step 3).
fn approvals_file(state: &NodeState) -> Option<PathBuf> {
    let (dir, node_id) = budget_dir(state).ok()?;
    Some(device::approvals_path(&dir, &node_id))
}

/// Save the pending request (or its absence) so an app restart resumes it.
fn save_spend_pending(state: &NodeState) {
    let Some(path) = approvals_file(state) else { return };
    let pending = state.spend.lock().unwrap().pending().cloned();
    if let Err(e) = device::save_pending(&path, pending.as_ref()) {
        eprintln!("[spend] could not save the pending approval: {e}");
    }
}

/// Once per run: pick up a request an earlier run was waiting on, if it has
/// not run out. The next poll asks the node where it stands.
fn restore_spend_pending(state: &NodeState) {
    if !matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(_)) {
        return;
    }
    if state.approvals_restored.swap(true, Ordering::SeqCst) {
        return;
    }
    let Some(path) = approvals_file(state) else { return };
    let Some(saved) = device::load_pending(&path, now_ms()) else { return };
    // A grant completes only its own request. A distinct saved replacement
    // still needs polling even while an older grant remains live.
    if state.node_grant.lock().unwrap().as_ref()
        .is_some_and(|g| g.live(now_ms()) && g.op_id == saved.op_id) {
        return;
    }
    let mut gate = state.spend.lock().unwrap();
    if gate.pending().is_none() {
        gate.set_replacement_pending(saved, now_ms());
    }
}

async fn spend_advance_for_inner(state: &NodeState, want: Option<Want>, budget_msat: Option<u64>, minimum: Option<u64>) -> Result<SpendAdvance, ActionError> {
    if want.is_some() && budget_paused(state)? {
        return Err(ActionError::new("budget_paused", "Payments are paused. Resume them first."));
    }
    // Only a verified node request supplies an identity, even when this call
    // completes it. Immediate approvals have no request identity.
    let mut request_id = None;
    let mut armed_granted_op = None;
    // Taken before any await: whatever the node answers later opens nothing
    // if the owner paused or locked in the meantime.
    let fence = approval_fence(state);
    enum Mode {
        Local,
        Paired { spend: bool },
    }
    let mode = match &*state.auth.lock().unwrap() {
        AuthMode::Unauthenticated => {
            return Err(ActionError::new("app_not_ready", "Your node is not signed in yet."))
        }
        AuthMode::Local => Mode::Local,
        AuthMode::Paired(session) => Mode::Paired {
            spend: session.scopes.iter().any(|s| s == "spend"),
        },
    };
    if let Some(amount) = budget_msat {
        if !node_has_g1(state).await? {
            return Err(ActionError::invalid("this node does not support a replacement budget request"));
        }
        // Recheck before posting: a completed grant can arrive before the
        // renderer dismisses the form. Returning the view opens no authority.
        let current = read_grant(state).await?;
        if approval_fence(state) != fence { return Err(fence_broken()); }
        if current.as_ref().is_some_and(|g| g.live(now_ms()) && g.remaining_msat >= amount) {
            return Ok(SpendAdvance { view: state.spend.lock().unwrap().view(now_ms()), armed_granted_op: None });
        }
    }
    // A token that already claims `spend` opens only over a live G1 grant; with
    // none left on the node, ask again as if it had no `spend`.
    let mut held: Option<NodeGrant> = None;
    let pending = state.spend.lock().unwrap().pending()
        .is_some_and(|p| p.expires_at_ms > now_ms());
    let mode = match (mode, want) {
        // Token refresh can add spend before this poll observes the console
        // approval. Finish the pending request, including its original wants,
        // regardless of token scope.
        (Mode::Paired { .. }, _) if pending => Mode::Paired { spend: false },
        (Mode::Paired { .. }, Some(_)) if budget_msat.is_some() => Mode::Paired { spend: false },
        (Mode::Paired { spend: true }, Some(_)) => match grant_for_open(state).await {
            Ok(g) => {
                held = g;
                Mode::Paired { spend: true }
            }
            Err(e) if e.code == "grant_ended" => Mode::Paired { spend: false },
            Err(e) => return Err(e),
        },
        (mode, _) => mode,
    };
    match mode {
        Mode::Local => {
            if let Some(want) = want { open_fenced(state, fence, want, act::SpendBasis::AppLock, None)?; }
        }
        Mode::Paired { spend: true } => {
            if let Some(want) = want {
                open_fenced(state, fence, want, act::SpendBasis::NodeGrant, held.as_ref())?;
                if matches!(want, Want::Window) {
                    armed_granted_op = held.as_ref().map(|g| g.op_id.clone()).filter(|id| !id.is_empty());
                }
            }
        }
        Mode::Paired { spend: false } => {
            let (generation, pending) = {
                let mut gate = state.spend.lock().unwrap();
                gate.view(now_ms());
                (gate.generation(), gate.pending().cloned())
            };
            let budget_generation = state.autopay.lock().unwrap().generation();
            if budget_msat.is_some() && (generation, budget_generation) != fence {
                return Err(fence_broken());
            }
            if let Some(want) = want {
                let mut wants = state.wants.lock().unwrap();
                // A new request carries only this ask; a pending one gathers them.
                if pending.is_none() { *wants = Wants::default(); }
                match want {
                    Want::Window => wants.window = true,
                    Want::Budget(ceiling) => wants.budget = Some(ceiling),
                }
            }
            if let Some(pending) = pending {
                if want.is_some() { request_id = Some(pending.op_id.clone()); }
                let path = act::elevation_status_path(&pending.op_id)?;
                let (status, body) = call_api(state, reqwest::Method::GET, &path, None).await?;
                if !status.is_success() {
                    return Err(ActionError::node(api_error("/pair/elevation", status, &body)));
                }
                let reply: act::ElevationStatusReply = decode_act("/pair/elevation", &body)?;
                if !state.spend.lock().unwrap().matches_poll(generation, &pending, now_ms()) {
                    return Ok(SpendAdvance { view: act::SpendView { request_id, ..state.spend.lock().unwrap().view(now_ms()) }, armed_granted_op });
                }
                match reply.status.as_str() {
                    "granted" => {
                        // The grant reaches a token only on re-issue.
                        refresh_paired(state).await?;
                        let has_spend = matches!(
                            &*state.auth.lock().unwrap(),
                            AuthMode::Paired(s) if s.scopes.iter().any(|x| x == "spend")
                        );
                        // On a G1 node the grant's own terms bound what opens.
                        let node = if has_spend { Some(grant_for_open(state).await) } else { None };
                        let mut gate = state.spend.lock().unwrap();
                        if !gate.matches_poll(generation, &pending, now_ms()) {
                            return Ok(SpendAdvance { view: act::SpendView { request_id, ..gate.view(now_ms()) }, armed_granted_op });
                        }
                        let wants = std::mem::take(&mut *state.wants.lock().unwrap());
                        let node = match node {
                            None => {
                                stop_spending(state);
                                state.autopay.lock().unwrap().lock();
                                return Err(gate.refused());
                            }
                            Some(Err(e)) => {
                                gate.lock();
                                drop(gate);
                                drop_grant(state);
                                return Err(e);
                            }
                            Some(Ok(node)) => node,
                        };
                        // Pause all or a budget lock during the poll: the grant
                        // opens nothing (the window's own generation is checked
                        // above; pause writes the book after bumping both).
                        let mut autopay = state.autopay.lock().unwrap();
                        if autopay.generation() != budget_generation || budget_paused(state)? {
                            gate.lock();
                            autopay.lock();
                            return Err(fence_broken());
                        }
                        // Open only what the owner asked for with this request.
                        if !wants.window { gate.clear_pending(); }
                        if wants.window {
                            gate.arm_pending_granted_until(
                                now_ms(), node.as_ref().map_or(u64::MAX, NodeGrant::expires_at_ms),
                                act::SpendBasis::NodeGrant, node.as_ref().map(|g| g.op_id.as_str()),
                            );
                            armed_granted_op = node.as_ref().map(|g| g.op_id.clone()).filter(|id| !id.is_empty());
                        }
                        if let Some(ceiling) = wants.budget {
                            autopay.arm_pending_until(
                                now_ms(), node.as_ref().map_or(u64::MAX, NodeGrant::expires_at_ms),
                                node.as_ref().map_or(ceiling, |g| ceiling.min(g.budget_msat)),
                                act::SpendBasis::NodeGrant, &pending,
                            );
                        }
                        *state.node_grant.lock().unwrap() = node.clone();
                    }
                    // Over without a grant: expired, or lost to a node restart
                    // (the node's owner code lived in memory). Never wait out a
                    // request nothing can approve; the owner asks again.
                    status => if let Some(lapse) = act::Lapse::from_status(status) {
                        let mut gate = state.spend.lock().unwrap();
                        if gate.matches_poll(generation, &pending, now_ms()) {
                            gate.pending_expired(lapse);
                            *state.wants.lock().unwrap() = Wants::default();
                        }
                    },
                }
            } else if let Some(want) = want {
                request_id = post_elevation_request(state, want, budget_msat, minimum, generation).await?;
            }
        }
    }
    Ok(SpendAdvance {
        view: act::SpendView { request_id, ..state.spend.lock().unwrap().view(now_ms()) },
        armed_granted_op,
    })
}

/// Ask the node for spend (`POST /pair/elevation-request`) and remember the
/// pending request when the window's generation is still `generation`.
/// Returns the node's request id. Never obtains anything by itself.
async fn post_elevation_request(state: &NodeState, want: Want, budget_msat: Option<u64>, minimum: Option<u64>, generation: u64) -> Result<Option<String>, ActionError> {
    // One request at a time, shared with the automatic pairing ask; a request
    // that appeared meanwhile is followed, not repeated (a replacement still asks).
    let _create = state.elevation_create.lock().await;
    if budget_msat.is_none() {
        let live = state.spend.lock().unwrap().pending()
            .filter(|p| p.expires_at_ms > now_ms()).map(|p| p.op_id.clone());
        if let Some(op_id) = live {
            return Ok(Some(op_id));
        }
    }
    let mut ask = serde_json::json!({ "scopes": ["spend"] });
    // A G1 node shows the owner a budget to approve; the owner's
    // flags override it. Older nodes get the pre-G1 body.
    if let Some(amount) = budget_msat {
        ask["budget"] = grant::proposal(amount, grant::MAX_TTL_SECS, &Default::default());
    } else if node_has_g1(state).await.unwrap_or(false) {
        if let Some(budget) = budget_proposal(state, want, minimum) {
            ask["budget"] = budget;
        }
    }
    dispatch_elevation_request(state, ask, budget_msat, generation).await
}

/// POST one prepared elevation request and track it when the window's
/// generation is still `generation`. Callers hold `elevation_create`.
async fn dispatch_elevation_request(state: &NodeState, ask: serde_json::Value, budget_msat: Option<u64>, generation: u64) -> Result<Option<String>, ActionError> {
    let (status, body) = call_api(state, reqwest::Method::POST, "/pair/elevation-request", Some(ask)).await?;
    if !status.is_success() {
        return Err(ActionError::node(api_error("/pair/elevation-request", status, &body)));
    }
    let reply: act::ElevationReply = decode_act("/pair/elevation-request", &body)?;
    let pending = reply.into_elevation()?;
    let request_id = Some(pending.op_id.clone());
    let mut gate = state.spend.lock().unwrap();
    if gate.generation() == generation && pending.expires_at_ms > now_ms() {
        if budget_msat.is_some() {
            gate.set_replacement_pending(pending, now_ms());
        } else {
            gate.set_pending(pending);
        }
    }
    Ok(request_id)
}

/// Read only the policy and backend from the SAME config passed to node start.
/// Missing routing_fees/fields have the node's serde defaults; unreadable or
/// malformed config is not evidence of a default policy. Never expose config
/// parse errors (the rest of this file can contain credentials).
#[cfg(all(desktop, not(feature = "mobile")))]
fn configured_routing_policy(path: &Path) -> Option<(String, act::RoutingFeePolicy)> {
    #[derive(Deserialize)]
    struct Config {
        lightning: Backend,
        #[serde(default)]
        routing_fees: act::RoutingFeePolicy,
    }
    #[derive(Deserialize)]
    struct Backend { backend: String }
    let text = std::fs::read_to_string(path).ok()?;
    let config: Config = toml::from_str(&text).ok()?;
    Some((config.lightning.backend, config.routing_fees))
}

/// The LDK `network` from the SAME config passed to node start, or none for
/// another backend or an unreadable config. Same rules as the policy read.
#[cfg(all(desktop, not(feature = "mobile")))]
fn configured_network(path: &Path) -> Option<String> {
    #[derive(Deserialize)]
    struct Config { lightning: Backend }
    #[derive(Deserialize)]
    struct Backend {
        backend: String,
        // The node's own serde default for LDK.
        #[serde(default = "mainnet")]
        network: String,
    }
    fn mainnet() -> String { "bitcoin".into() }
    let text = std::fs::read_to_string(path).ok()?;
    let config: Config = toml::from_str(&text).ok()?;
    if config.lightning.backend != "ldk" {
        return None;
    }
    control::ldk_network_name(&config.lightning.network).map(str::to_owned)
}

fn room_routing_policy(state: &NodeState, status: &serde_json::Value) -> Result<act::RoutingFeePolicy, String> {
    if state.sidecar_terminated.load(Ordering::SeqCst) {
        return Err("The supervised node stopped. Restart it before quoting a room.".into());
    }
    let backend = status["lightning_backend"].as_str().unwrap_or_default();
    // dac01c8 has no ordinary member fee quote API. Mock providers explicitly
    // use the trait default; LND/LDK load routing_fees from their startup config.
    match backend {
        "mock" | "shared_mock" => Ok(act::RoutingFeePolicy::default()),
        "lnd" | "ldk" => state.room_routing_policy.lock().unwrap().as_ref()
            .filter(|(configured, _)| configured == backend)
            .map(|(_, policy)| *policy)
            .ok_or_else(|| "The node's routing fee policy is unavailable. Restart the supervised node before quoting a room.".into()),
        _ => Err("The node has not reported a supported routing fee policy. Refresh after upgrading the node.".into()),
    }
}

async fn read_room_quote(state: &NodeState, room_id: &str) -> Result<act::RoomQuote, String> {
    read_room_quote_with_status(state, room_id, None).await
}

async fn read_room_quote_with_status(state: &NodeState, room_id: &str, status: Option<&serde_json::Value>) -> Result<act::RoomQuote, String> {
    let room = control::room_id(room_id)?;
    let own_id = state.node_id.lock().unwrap().clone().unwrap_or_default();
    let own_id = if own_id.is_empty() { fetch_node_id(state).await? } else { own_id };
    let members = read_room_members(state, &room).await?;
    let peers: Vec<control::Peer> = get_json(state, "/peers").await?;
    let own: control::KindPrice = get_json(state, &control::price_path(control::KIND_CHAT)).await?;
    let tables: Vec<control::PeerPrice> = get_json(state, "/pricing/peers").await?;
    let fresh;
    let status = match status {
        Some(status) => status,
        None => { fresh = get_json(state, "/status").await?; &fresh }
    };
    let policy = room_routing_policy(state, status)?;
    act::room_quote(&room, &own_id, own.price_msat, &members, &peers, &tables, policy)
        .map_err(|e| e.message)
}

/// Only an explicit versioned node contract authorizes variable-price sends.
/// What a paid send may rely on at this node.
struct SendCaps {
    /// This send's status, also used for room routing policy. Never stored.
    status: serde_json::Value,
    /// Admission may be paid separately from a message cap.
    readmission_possible: bool,
    /// Durable, idempotent 1:1 message operations.
    operations: bool,
    /// A capped 1:1 chat may pay a reconnect's re-admission under the
    /// contact's fresh signed quote (genome #111 revived).
    quoted_readmission: bool,
    envelope_ids: bool,
}

async fn require_price_caps(state: &NodeState, room: bool) -> Result<SendCaps, ActionError> {
    let unavailable = || ActionError::new("price_cap_unavailable", "This node cannot enforce your confirmed spending ceiling. Upgrade the node before sending messages or files.");
    let status: serde_json::Value = get_json(state, "/status").await.map_err(|reason|
        ActionError::new("price_quote_unavailable", format!("Node capabilities unavailable: {reason}")))?;
    let capabilities = status["api_capabilities"].as_array().ok_or_else(unavailable)?;
    let has = |cap: &str| capabilities.iter().any(|v| v.as_str() == Some(cap));
    if !has("paid_send_caps_v1") || (room && !has("room_terminal_outcomes_v1")) {
        return Err(unavailable());
    }
    Ok(SendCaps {
        readmission_possible: has(grant::FIRST_CONTACT_CAPABILITY),
        operations: has(OPERATIONS_CAPABILITY),
        quoted_readmission: has(act::QUOTED_READMISSION_CAPABILITY),
        envelope_ids: has(grant::RELATION_ENVELOPE_ID_CAPABILITY),
        status,
    })
}

/// Genome #113: `operation_id` on 1:1 compose, idempotent POST, `GET /messages/operations/{id}`.
const OPERATIONS_CAPABILITY: &str = "message_operations_v1";

/// Node #442: `POST /payments/pay` and `/payments/keysend` require a client
/// `request_id` (an idempotency key bound to the request), answer `202
/// in_flight` until settled, and answer a repeat from their record.
const DIRECT_PAYMENT_OPERATIONS_CAPABILITY: &str = "direct_payment_operations_v1";

/// An explicit payment: an invoice or a keysend.
fn is_direct_payment(path: &str) -> bool {
    matches!(path, "/payments/pay" | "/payments/keysend")
}

/// A fresh idempotency key for one direct payment when the node takes one
/// (it then requires it); `None` for an older node, which refuses unknown
/// fields. A node whose capabilities cannot be read is not paid at all.
async fn direct_request_id(state: &NodeState) -> Result<Option<String>, ActionError> {
    let status: serde_json::Value = get_json(state, "/status").await.map_err(|reason|
        ActionError::new("price_quote_unavailable", format!("Node capabilities unavailable: {reason}. Nothing was paid.")))?;
    let offered = status["api_capabilities"].as_array().is_some_and(|caps|
        caps.iter().any(|cap| cap.as_str() == Some(DIRECT_PAYMENT_OPERATIONS_CAPABILITY)));
    offered.then(spend_journal::new_operation_id).transpose()
}

/// The visible conversation ceiling includes admission and routing. Older
/// nodes reuse paid_send_caps_v1 but may admit outside it; their quote cannot
/// promise this ceiling. Keep legacy accounting for recovery and other flows.
async fn require_conversation_ceiling(state: &NodeState, peer: &str, caps: &SendCaps) -> Result<(), ActionError> {
    let peer = control::node_id(peer).map_err(ActionError::invalid)?;
    if has_all_in_caps(state) { return Ok(()); }
    // A successful status read without the quote capability proves this is
    // a legacy node. Do not turn that evidence into a failed quote probe.
    if !caps.readmission_possible {
        return control::conversation_ceiling_evidence(false, Ok(()));
    }
    let probe = read_first_contact_quote_with_cap(state, &peer, caps.readmission_possible).await.map(|_| ());
    control::conversation_ceiling_evidence(has_all_in_caps(state), probe)
}

async fn read_conversation_quote(state: &NodeState, peer: Option<&str>) -> Result<control::PriceQuote, String> {
    let mut quote = read_price_quote(state, peer).await?;
    if let Some(peer) = peer {
        let ceiling = match require_price_caps(state, false).await {
            Ok(caps) => require_conversation_ceiling(state, peer, &caps).await,
            Err(error) => Err(error),
        };
        quote.send_unavailable = ceiling.err().map(|e| {
            if e.code == "not_ready" && e.reason.as_deref() == Some("chain_unavailable") {
                "not_ready:chain_unavailable".into()
            } else { e.message }
        });
    }
    Ok(quote)
}

/// Public conversation sends opt into the displayed all-in promise. Room
/// legs keep their existing individual caps and never raise for admission.
async fn do_conversation_send(
    state: &NodeState,
    recipient: &str,
    is_room: bool,
    plaintext: &str,
    max_msat: u64,
    max_recipient_msat: Option<std::collections::HashMap<String, u64>>,
    first_contact_msat: Option<u64>,
) -> Result<act::SendReceipt, ActionError> {
    do_message_send_inner(state, recipient, is_room, plaintext, max_msat, max_recipient_msat, first_contact_msat, true).await
}

/// Slice B's call shape: no first-contact confirmation. Tests only.
#[cfg(all(test, desktop, not(feature = "mobile")))]
async fn do_message_send(
    state: &NodeState,
    recipient: &str,
    is_room: bool,
    plaintext: &str,
    max_msat: u64,
    max_recipient_msat: Option<std::collections::HashMap<String, u64>>,
) -> Result<act::SendReceipt, ActionError> {
    do_message_send_with(state, recipient, is_room, plaintext, max_msat, max_recipient_msat, None).await
}

/// A message pays inside the owner's budget without a prompt, or under the
/// ten-minute window. `first_contact_msat` is the owner's one-time OK for a
/// contact or room not yet in the book, with the budget they chose for it.
#[cfg(all(test, desktop, not(feature = "mobile")))]
async fn do_message_send_with(
    state: &NodeState,
    recipient: &str,
    is_room: bool,
    plaintext: &str,
    max_msat: u64,
    max_recipient_msat: Option<std::collections::HashMap<String, u64>>,
    first_contact_msat: Option<u64>,
) -> Result<act::SendReceipt, ActionError> {
    do_message_send_inner(state, recipient, is_room, plaintext, max_msat, max_recipient_msat, first_contact_msat, false).await
}

/// The only escape from an admission-only fence. Never replaces the slot,
/// changes the request, raises a cap, or enters the delivery-retry path.
async fn resume_admission_send(state: &NodeState, pending_id: &str, peer: &str, is_room: bool, plaintext: &str, max_msat: u64) -> Result<MoneyReply, ActionError> {
    let _money = state.money.lock().await;
    let journal = locked_spend_journal(state)?;
    let mut pending = journal.pending()?.filter(|p| p.id == pending_id && p.admission_resume
        && !p.over_budget && p.evidence_reservation_msat.is_some() && p.undelivered.is_none()
        && p.max_msat == max_msat && p.peer.as_deref() == Some(peer) && !is_room
        && state.node_id.lock().unwrap().as_deref() == Some(p.node_id.as_str()))
        .ok_or_else(|| spend_journal::unknown("Only the same message and cap can resume its paid admission."))?;
    let id = pending.operation_id.clone().ok_or_else(|| spend_journal::unknown("Missing operation identity."))?;
    let mut body = act::compose_body(peer, false, plaintext)?;
    body["max_total_msat"] = serde_json::json!(max_msat);
    if let Some(fee) = pending.compose_fee_msat { body["max_routing_fee_msat"] = serde_json::json!(fee); }
    let matches_request = |body: &serde_json::Value| {
        blake3::hash(format!("/messages/compose\n{body}").as_bytes()).to_hex().as_str() == pending.request_hash
    };
    if !matches_request(&body) && pending.compose_fee_msat.is_none()
        && pending.op.as_deref() == Some(spend_journal::operation(&body).as_str()) {
        // Older journals lack the fee cap. Use today's quote only if it
        // reconstructs the exact original hash; never guess or raise a cap.
        let quote = read_price_quote(state, Some(peer)).await?;
        body["max_routing_fee_msat"] = serde_json::json!(quote.max_routing_fee_msat);
    }
    if !matches_request(&body) {
        return Err(spend_journal::unknown("Only the same message and request can resume its paid admission."));
    }
    refuse_if_connection_busy(state)?;
    refuse_if_paused(state)?;
    ensure_fresh_token(state).await;
    let token = state.ordinary_token().map_err(|e| ActionError::new("app_not_ready", &e))?
        .ok_or_else(|| ActionError::new("app_not_ready", "Not authenticated."))?;
    check_node_grant(state, "/messages/compose", &body, max_msat).await?;
    // Restore the original reservation in place. The whole-operation answer
    // settles this same entry, including its already-paid admission.
    let reserved = pending.evidence_reservation_msat.unwrap();
    let window = approval_generation(state);
    let (ceiling, generation) = {
        let mut approval = state.autopay.lock().unwrap();
        (approval.ceiling(now_ms()), approval.generation())
    };
    let mut accounted = None;
    let auth = with_book(state, true, |book| {
        let index = book.ledger.iter().rposition(|e| e.id == pending.charge_id())
            .ok_or_else(|| spend_journal::unknown("Missing admission budget entry."))?;
        accounted = Some((book.ledger[index].msat, book.ledger[index].settled));
        // This is a replacement, not a second charge. Exclude only its own
        // entry while planning; every other liability still counts.
        let mut projected = book.clone();
        projected.ledger.remove(index);
        let plan = budget::plan(&projected, budget::Ask { target: peer, room: false, max_msat: reserved,
            first_contact_msat: None, autopay: ceiling, window: window.as_ref().map(|_| ()).map_err(Clone::clone), now_ms: now_ms() })?;
        let auth = match plan.route { budget::Route::Budget => Auth::Budget(generation), budget::Route::Window => Auth::Window(window?) };
        book.ledger[index].msat = reserved;
        book.ledger[index].settled = false;
        Ok(auth)
    })?;
    // Consume permission durably before exactly one POST. A lost answer must
    // be checked again; saved accounting is never authority to resume.
    let before = pending.clone();
    pending.admission_resume = false;
    pending.non_dispatch_proven = false;
    pending.dispatched_at = Some(spend_journal::timestamp_ms());
    journal.save(&pending)?;
    journal.record_outcome(&pending, spend_journal::OperationState::Dispatching, None)?;
    if cfg!(test) { pause_points::at(&state.api_base, "before_resume_decision").await; }
    // Refused here, nothing was sent: the resume keeps its permission and its
    // accounting. Saving the permission also puts its history back.
    if let Err(refused) = refuse_if_connection_busy(state)
        .and_then(|()| refuse_if_paused(state))
        .and_then(|()| check_auth(state, auth)) {
        journal.save(&before)?;
        if let Some((msat, settled)) = accounted {
            with_book(state, true, |book| {
                if let Some(entry) = book.ledger.iter_mut().rev().find(|e| e.id == before.charge_id()) {
                    entry.msat = msat;
                    entry.settled = settled;
                }
                Ok(())
            })?;
        }
        return Err(refused);
    }
    body["operation_id"] = serde_json::json!(id);
    let response = state.http.post(format!("{}/messages/compose", state.api_base))
        .bearer_auth(token).json(&body).timeout(state.spend_timeout).send().await
        .map_err(|_| spend_journal::unknown("The resume did not return a complete response. Check pending result."))?;
    let status = response.status();
    let text = response.text().await.map_err(spend_journal::unknown)?;
    if !status.is_success() {
        return Err(spend_journal::unknown("The resume did not complete. Admission remains accounted; check pending result."));
    }
    reconcile_operation_with_reply(state, &journal, pending, &id, Some((status, text.clone()))).await?;
    let reply: act::SendReply = serde_json::from_str(&text).map_err(spend_journal::unknown)?;
    if !matches!(reply.state.as_deref(), Some("acked" | "sent")) {
        return Err(spend_journal::unknown("The message is still pending. Check pending result."));
    }
    Ok(MoneyReply { text, operation_id: Some(id) })
}

#[allow(clippy::too_many_arguments)]
async fn do_message_send_inner(
    state: &NodeState,
    recipient: &str,
    is_room: bool,
    plaintext: &str,
    max_msat: u64,
    max_recipient_msat: Option<std::collections::HashMap<String, u64>>,
    first_contact_msat: Option<u64>,
    conversation: bool,
) -> Result<act::SendReceipt, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let target = if is_room { control::room_id(recipient) } else { control::node_id(recipient) }.map_err(ActionError::invalid)?;
    // A room leg (genome `room_binding_v1`) pays at most the owner's confirmed
    // cap for that member, fee included: no first contact, no raised re-admission cap.
    let room_leg = !is_room && act::is_room_chat(plaintext);
    if room_leg && first_contact_msat.is_some() {
        return Err(ActionError::invalid("A room never pays a first contact."));
    }
    let admission = spend_journal(state)?.pending()?.filter(|p| p.admission_resume);
    if let Some(pending) = admission {
        let text = resume_admission_send(state, &pending.id, &target, is_room, plaintext, max_msat).await?;
        return send_receipt(text, target, is_room);
    }
    let (auth, plan) = plan_message(state, &target, is_room, max_msat, first_contact_msat)?;
    no_pending_spend(state)?;
    let caps = require_price_caps(state, is_room).await?;
    if conversation && !is_room && !room_leg {
        require_conversation_ceiling(state, &target, &caps).await?;
    }
    let readmission_possible = caps.readmission_possible;
    let mut body = act::compose_body(recipient, is_room, plaintext)?;
    body["max_total_msat"] = serde_json::json!(max_msat);
    if is_room {
        let caps = max_recipient_msat.as_ref().ok_or_else(|| ActionError::new("price_changed", "Refresh the room quote before sending."))?;
        body["max_recipient_msat"] = serde_json::json!(caps);
    }
    let node_ok = if is_room { None } else { plan.confirm.or(first_contact_msat) };
    let price = if is_room {
        let quote = read_room_quote_with_status(state, recipient, Some(&caps.status)).await?;
        act::room_sendable(&quote)?;
        let caps = max_recipient_msat.as_ref().expect("room caps checked above");
        if caps.len() != quote.members.len() || quote.members.iter().any(|member|
            caps.get(&member.node_id).is_none_or(|cap| member.msat > *cap)) {
            return Err(ActionError::new("price_changed", "The room all-in price changed. Review the new quote before sending."));
        }
        // Genome takes min(policy, caller) per member, then checks each all-in
        // amount against its recipient cap BEFORE paying. The largest fee lets
        // each member use its displayed policy allowance; caps remain unchanged.
        let caller_fee = quote.members.iter().map(|m| m.max_routing_fee_msat).max().unwrap_or(0);
        body["max_routing_fee_msat"] = serde_json::json!(caller_fee);
        quote.total_msat
    } else if node_ok.is_some() {
        // The owner confirms the fresh node quote, including its configured
        // fees. A stale table or our ordinary fee estimate cannot replace it.
        max_msat
    } else {
        let quote = read_price_quote(state, Some(recipient)).await?;
        body["max_routing_fee_msat"] = serde_json::json!(quote.max_routing_fee_msat);
        (if quote.peer_stale { quote.own_msat } else { quote.peer_msat.unwrap_or(quote.own_msat) })
            .max(act::MIN_PAYMENT_MSAT).checked_add(quote.max_routing_fee_msat)
            .ok_or_else(|| ActionError::invalid("The all-in quote overflows."))?
    };
    ceiling(price, max_msat)?;
    let recipient = body["recipient"].as_str().unwrap_or_default().to_string();
    // A confirmed first paid message to a contact: the node backs that one OK
    // with a single-use grant for exactly this contact and this cap. The same
    // OK re-admits a known contact the node's grant does not budget yet.
    if let Some(contact_budget) = node_ok {
        confirm_first_contact(state, &recipient, max_msat, contact_budget, caps.readmission_possible).await?;
    }
    let quoted_readmission = !is_room && !room_leg && node_ok.is_none() && caps.quoted_readmission;
    // The owner approved the contact's re-admission quote (`readmission_quoted`):
    // that send carries its routing ceilings for both payments, under its total.
    if quoted_readmission {
        if let Some(ask) = take_readmission_ask(state, &recipient, max_msat) {
            body["max_routing_fee_msat"] = serde_json::json!(ask.max_routing_fee_msat);
        }
    }
    let charge = Charge { target: target.clone(), room: is_room, confirm: plan.confirm, readmission_possible, confirmed: node_ok.is_some(), operation: caps.operations && !is_room, envelope_ids: Some(caps.envelope_ids), failure_final_on: final_failure_node(&caps.status), call_window: false };
    let sent = money_post(state, auth, "/messages/compose", body.clone(), max_msat, Some(charge)).await;
    let sent = match sent {
        // After a reconnect or restart the contact asks for admission again,
        // and the node kept its signed quote for this connection.
        Err(e) if e.code == "readmission_capped" && quoted_readmission => {
            let operation_id = e.operation_id.clone();
            act::with_op(Active(operation_id.as_deref()),
                readmit_under_quote(state, &target, body, max_msat, e, caps.readmission_possible).await)
        }
        Err(e) if e.code == "readmission_capped" && room_leg => Err(ActionError::new("readmission_capped", act::ROOM_LEG_READMISSION).for_operation(e.operation_id.as_deref())),
        other => other,
    };
    let text = match sent {
        // After a reconnect the contact asks for admission again. The node pays
        // it from the budget only for a contact its grant budgets; this one it
        // does not, so the owner confirms once, on the door card.
        Err(e) if e.code == "grant_first_contact" && node_ok.is_none() => {
            return Err(readmission_needs_ok().for_operation(e.operation_id.as_deref()));
        }
        other => other?,
    };
    send_receipt(text, recipient, is_room)
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

fn send_receipt(text: MoneyReply, recipient: String, is_room: bool) -> Result<act::SendReceipt, ActionError> {
    let reply: act::SendReply = text.decode("/messages/compose")?;
    let total_msat = act::with_op(Active(text.operation_id.as_deref()), reply.total_msat())?;
    Ok(act::SendReceipt {
        total_msat,
        fee_paid_msat: reply.fee_paid_msat,
        message_id: reply.message_id,
        recipient,
        is_room,
        delivered: reply.delivered,
        amount_msat: reply.amount_msat,
        max_routing_fee_msat: reply.max_routing_fee_msat,
        sent_at_ms: now_ms(),
        operation_id: reply.operation_id,
        state: reply.state,
        accepted: reply.accepted,
        readmission_msat: reply.readmission_msat.filter(|m| *m > 0),
    })
}

/// Genome `quoted_readmission_v1`: the contact asked for admission again and
/// the node refused this send's cap before paying anything, keeping the
/// contact's fresh signed quote for this connection. The quote's total
/// (admission once, this message, both routing ceilings) is the new all-in
/// ceiling. Even inside an approved budget a higher cap requires a fresh
/// press (`readmission_quoted`). Nothing here dispatches another compose;
/// the next send keeps the same operation id. Unexpected replies keep the refusal.
async fn readmit_under_quote(
    state: &NodeState,
    target: &str,
    body: serde_json::Value,
    max_msat: u64,
    refused: ActionError,
    quote_offered: bool,
) -> Result<MoneyReply, ActionError> {
    let operation_id = refused.operation_id.clone();
    let result = async {
    let recipient = body["recipient"].as_str().unwrap_or_default().to_string();
    let Ok(quote) = read_first_contact_quote_with_cap(state, &recipient, quote_offered).await else { return Err(refused) };
    // A cap that already covered this quote was refused: never loop.
    if quote.total_msat <= max_msat { return Err(refused); }
    let view = act::AdmissionView {
        admission_msat: quote.admission_msat,
        message_msat: quote.message_msat,
        max_routing_fee_msat: quote.max_routing_fee_msat,
        total_msat: quote.total_msat,
        quoted: true,
    };
    // Approval and budget limits still win over a price confirmation. Reading
    // a new quote is not permission to reserve or pay it.
    let (auth, _) = plan_message(state, target, false, quote.total_msat, None)?;
    refuse_if_paused(state)?;
    check_auth(state, auth)?;
    check_node_grant(state, "/messages/compose", &body, quote.total_msat).await?;
    remember_readmission_ask(state, &recipient, &quote);
    Err(ActionError::readmission_quoted(view))
    }.await;
    act::with_op(Active(operation_id.as_deref()), result)
}

fn remember_readmission_ask(state: &NodeState, peer: &str, quote: &control::FirstContactQuote) {
    let Some(node_id) = state.node_id.lock().unwrap().clone() else { return };
    *state.readmission_ask.lock().unwrap() = Some(ReadmissionAsk {
        node_id,
        peer: peer.to_string(),
        total_msat: quote.total_msat,
        max_routing_fee_msat: quote.max_routing_fee_msat,
        expires_at_ms: quote.expires_at.saturating_mul(1000),
    });
}

/// The re-admission quote the owner was shown for `peer`, if this send is for
/// exactly its total and it has not expired. Single use.
fn take_readmission_ask(state: &NodeState, peer: &str, max_msat: u64) -> Option<ReadmissionAsk> {
    let node_id = state.node_id.lock().unwrap().clone()?;
    let mut ask = state.readmission_ask.lock().unwrap();
    let matches = ask.as_ref().is_some_and(|a| a.node_id == node_id && a.peer == peer && a.total_msat == max_msat && a.expires_at_ms > now_ms());
    if matches { ask.take() } else { None }
}

fn readmission_needs_ok() -> ActionError {
    ActionError::new(
        "grant_readmission",
        "This contact reconnected and asks to be admitted again. Your node's budget does not cover them yet, so it needs your OK once. Nothing was sent.",
    )
}

/// Retry delivery of a paid, undelivered message: the same operation (this
/// message, this contact), through the journal record it left, never a fresh
/// unjournaled compose.
///
/// - `approved_msat: None` (Retry delivery) never pays anything new. It is a
///   compose with `max_total_msat: 0`: the node checks every payment against
///   that cap before dispatch (the message, a fresh admission, a re-admission),
///   so it can only re-send the proof already paid for. Genome #100: on the
///   connection that holds the proof, or with a proof that never went out, the
///   node re-delivers it; a proof consumed on an earlier connection needs a new
///   admission, which the zero cap refuses. Whatever is still due, the owner
///   gets `retry_needs_admission` with the all-in price and approves it.
/// - `approved_msat: Some(total)`: the owner approved that all-in price under
///   the normal approval, as for any send; the node pays at most that.
async fn do_message_retry(state: &NodeState, recipient: &str, plaintext: &str, approved_msat: Option<u64>) -> Result<act::SendReceipt, ActionError> {
    let mut existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let target = control::node_id(recipient).map_err(ActionError::invalid)?;
    let mut body = act::compose_body(recipient, false, plaintext)?;
    let op = spend_journal::operation(&body);
    let unavailable = || ActionError::new("retry_unavailable", "There is no paid, undelivered message to retry for this contact. Check the pending result; do not send the message again.");
    let pending = spend_journal(state)?.pending()?;
    existing_operation = pending.as_ref().and_then(|p| p.operation_id.clone());
    let undelivered = pending
        .filter(|p| !p.over_budget)
        .and_then(|p| p.undelivered)
        .filter(|u| u.retry && !u.in_flight && u.peer == target && u.op == op)
        .ok_or_else(unavailable)?;
    let caps = require_price_caps(state, false).await?;
    let readmission_possible = caps.readmission_possible;
    // Zero for Retry delivery: the node refuses any payment before dispatch.
    let cap = approved_msat.unwrap_or(0);
    let (auth, plan) = plan_message(state, &target, false, cap, None)?;
    // A contact not yet in the book needs a first-contact budget: the composer's door card.
    if plan.confirm.is_some() { return Err(unavailable()); }
    body["max_total_msat"] = serde_json::json!(cap);
    if approved_msat.is_some() {
        // A paired first-contact authorization is single-use, including when
        // the previous paid send failed. Renew it for this exact peer and cap.
        let contact_budget = retry_contact_budget(state, &target, cap).await?;
        confirm_first_contact(state, &target, cap, contact_budget, caps.readmission_possible).await?;
    }
    // Nothing can be paid under a zero cap, re-admission included.
    let charge = Charge { target: target.clone(), room: false, confirm: None, readmission_possible: readmission_possible && approved_msat.is_some(), confirmed: approved_msat.is_some(), operation: caps.operations, envelope_ids: Some(caps.envelope_ids), failure_final_on: None, call_window: false };
    let text = match money_post_with(state, auth, "/messages/compose", body, cap, Some(charge), Some(&undelivered)).await {
        // The node pays re-admission under a cap that fits the contact's signed
        // quote: Retry delivery (zero cap) asks the owner for that price.
        Err(e) if e.code == "readmission_capped" && caps.quoted_readmission && approved_msat.is_none() => {
            return Err(needs_admission(state, &target, &undelivered).await.for_operation(e.operation_id.as_deref()));
        }
        // Asking the owner to approve a price cannot help: any cap refuses it.
        Err(e) if e.code == "readmission_capped" => {
            return Err(ActionError::new("readmission_capped", act::READMISSION_CAPPED_RETRY).for_operation(e.operation_id.as_deref()));
        }
        // Refused before paying anything: a payment is still due.
        Err(e) if approved_msat.is_none() && matches!(e.code, "price_cap_exceeded" | "grant_first_contact" | "grant_readmission") => {
            return Err(needs_admission(state, &target, &undelivered).await.for_operation(e.operation_id.as_deref()));
        }
        Err(e) if e.code == "price_cap_exceeded" => {
            return Err(ActionError::new("price_cap_exceeded", "Your node refused before paying: delivering it now costs more than the price you approved, or needs an admission the node pays only on a new send. Nothing was paid. Retry delivery for the current price, or stop retrying.").for_operation(e.operation_id.as_deref()));
        }
        other => other?,
    };
    let reply: act::SendReply = text.decode("/messages/compose")?;
    let total_msat = act::with_op(Active(text.operation_id.as_deref()), reply.total_msat())?;
    Ok(act::SendReceipt {
        total_msat,
        fee_paid_msat: reply.fee_paid_msat,
        max_routing_fee_msat: reply.max_routing_fee_msat,
        message_id: reply.message_id,
        recipient: undelivered.peer,
        is_room: false,
        delivered: reply.delivered,
        amount_msat: reply.amount_msat,
        sent_at_ms: now_ms(),
        operation_id: reply.operation_id,
        state: reply.state,
        accepted: reply.accepted,
        readmission_msat: reply.readmission_msat.filter(|m| *m > 0),
    })
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// `retry_needs_admission`, with the contact's own signed quote when the node
/// can give one (it pays and reserves nothing), else an estimate from the
/// admission paid before and the contact's current message price.
async fn needs_admission(state: &NodeState, target: &str, undelivered: &spend_journal::Undelivered) -> ActionError {
    if let Ok(q) = read_first_contact_quote(state, target).await {
        return ActionError::needs_admission(Some(act::AdmissionView {
            admission_msat: q.admission_msat, message_msat: q.message_msat, max_routing_fee_msat: q.max_routing_fee_msat, total_msat: q.total_msat, quoted: true,
        }));
    }
    let message_msat = read_price_quote(state, Some(target)).await.ok()
        .and_then(|q| q.peer_msat.filter(|_| !q.peer_stale))
        .map(|p| p.max(act::MIN_PAYMENT_MSAT));
    let view = message_msat.and_then(|m| {
        let max_routing_fee_msat = act::routing_fee(undelivered.admission_msat).checked_add(act::routing_fee(m))?;
        Some(act::AdmissionView {
            admission_msat: undelivered.admission_msat,
            message_msat: m,
            max_routing_fee_msat,
            total_msat: undelivered.admission_msat.checked_add(m)?.checked_add(max_routing_fee_msat)?,
            quoted: false,
        })
    }).filter(|v| v.admission_msat > 0);
    ActionError::needs_admission(view)
}

async fn do_invoice_create(
    state: &NodeState,
    amount_msat: u64,
    note: &str,
    expiry_secs: u32,
) -> Result<act::InvoiceView, ActionError> {
    let body = act::invoice_body(amount_msat, note, expiry_secs)?;
    let expiry = body["expiry_secs"].as_u64().unwrap_or(3600);
    let (status, text) = call_api(state, reqwest::Method::POST, "/payments/invoice", Some(body)).await?;
    if !status.is_success() {
        return Err(ActionError::node(api_error("/payments/invoice", status, &text)));
    }
    let reply: act::InvoiceReply = decode_act("/payments/invoice", &text)?;
    let note = note.trim();
    Ok(act::InvoiceView {
        bolt11: reply.bolt11,
        amount_msat,
        note: (!note.is_empty()).then(|| note.to_string()),
        expires_at_ms: now_ms() + expiry * 1000,
    })
}

async fn do_payment_pay(state: &NodeState, bolt11: &str, amount_msat: u64, max_msat: u64) -> Result<act::PaymentReceipt, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let generation = approval_generation(state)?;
    no_pending_spend(state)?;
    let mut body = act::pay_body(bolt11, amount_msat)?;
    let quote = act::payment_quote(amount_msat)?;
    ceiling(quote.total_msat, max_msat)?;
    body["max_routing_fee_msat"] = serde_json::json!(quote.max_routing_fee_msat);
    let charge = plan_manual_charge(state, budget::INVOICE_PAYMENTS, max_msat)?;
    // One key per payment intent, saved with the pending spend before the POST.
    if let Some(id) = direct_request_id(state).await? { body["request_id"] = serde_json::json!(id); }
    let text = money_post(state, Auth::Window(generation), "/payments/pay", body, max_msat, Some(charge)).await?;
    Ok(text.decode::<act::PayReply>("/payments/pay")?.receipt(now_ms()))
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

async fn do_payment_keysend(
    state: &NodeState,
    dest_pubkey: &str,
    amount_msat: u64,
    memo: Option<&str>,
    max_msat: u64,
) -> Result<act::PaymentReceipt, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let generation = approval_generation(state)?;
    no_pending_spend(state)?;
    let mut body = act::keysend_body(dest_pubkey, amount_msat, memo)?;
    let quote = act::payment_quote(amount_msat)?;
    ceiling(quote.total_msat, max_msat)?;
    body["max_routing_fee_msat"] = serde_json::json!(quote.max_routing_fee_msat);
    let charge = plan_manual_charge(state, budget::KEYSEND_PAYMENTS, max_msat)?;
    if let Some(id) = direct_request_id(state).await? { body["request_id"] = serde_json::json!(id); }
    let text = money_post(state, Auth::Window(generation), "/payments/keysend", body, max_msat, Some(charge)).await?;
    Ok(text.decode::<act::KeysendReply>("/payments/keysend")?.receipt(now_ms()))
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

async fn do_invite_create(state: &NodeState, invitee: &str, addr: &str, hours: u64) -> Result<act::InviteView, ActionError> {
    state.spend.lock().unwrap().check(now_ms())?;
    let now = now_ms();
    let body = act::invite_body(invitee, addr, hours, now / 1000)?;
    let invitee = body["invitee_pubkey"].as_str().unwrap_or_default().to_string();
    let expires_at_ms = body["expiry_unix"].as_u64().unwrap_or(0) * 1000;
    let text = gated_post(state, "/invites", body).await?;
    let reply: act::InviteReply = decode_act("/invites", &text)?;
    Ok(act::InviteView {
        invite_id: reply.invite_id,
        invite_link: reply.invite_link,
        invitee,
        expires_at_ms,
    })
}

async fn do_invite_redeem(state: &NodeState, invite: &str) -> Result<act::RedeemView, ActionError> {
    state.spend.lock().unwrap().check(now_ms())?;
    let token = act::invite_token(invite)?;
    let text = gated_post(state, "/invites/accept", serde_json::json!({ "token": token })).await?;
    decode_act("/invites/accept", &text)
}

/// GET one stored file with a limit on what is read into memory: stops at
/// [`act::FILE_BODY_MAX`] whatever the response declares, then checks the
/// declared and decoded sizes. Read-only, and separate from [`call_api`], which
/// keeps its behaviour for every other route.
async fn read_file_blob(state: &NodeState, id: &str) -> Result<act::FileBlob, String> {
    let path = format!("/files/{id}");
    ensure_fresh_token(state).await;
    let mut refreshed = false;
    loop {
        let token = state
            .ordinary_token()?
            .ok_or_else(|| "the node is not authenticated yet".to_string())?;
        let mut response = state
            .http
            .get(format!("{}{path}", state.api_base))
            .bearer_auth(token)
            .send()
            .await
            .map_err(|e| format!("{path} request failed: {e}"))?;
        let status = response.status();
        if status == reqwest::StatusCode::UNAUTHORIZED && !refreshed {
            refreshed = true;
            if remint_throttled(state).await.is_ok() {
                continue;
            }
        }
        if response.content_length().is_some_and(|n| n > act::FILE_BODY_MAX as u64) {
            return Err(act::FILE_RESPONSE_TOO_LARGE.into());
        }
        let mut body = Vec::new();
        while let Some(chunk) = response
            .chunk()
            .await
            .map_err(|e| format!("{path} response read failed: {e}"))?
        {
            if body.len() + chunk.len() > act::FILE_BODY_MAX {
                return Err(act::FILE_RESPONSE_TOO_LARGE.into());
            }
            body.extend_from_slice(&chunk);
        }
        let blob: act::FileBlob = decode(&path, status, &String::from_utf8_lossy(&body))?;
        act::blob_within_cap(&blob)?;
        return Ok(blob);
    }
}

/// A received voice note's bytes, for the inline player. Read-only: two GETs,
/// never a payment. Anything that is not an audio file is refused.
async fn do_voice_note_fetch(state: &NodeState, message_id: &str) -> Result<act::FileBlob, String> {
    let message_id = control::node_id(message_id).map_err(|_| "expected a 64-character hex message id".to_string())?;
    let mut found = None;
    for limit in act::FILE_LIST_WINDOWS {
        let rows: Vec<act::FileRow> = get_json(state, &format!("/files?limit={limit}")).await?;
        match act::voice_file_for(&rows, &message_id) {
            act::VoiceLookup::Voice(row) => { found = Some(row.id.clone()); break; }
            act::VoiceLookup::NotVoice => return Err(act::NOT_A_VOICE_NOTE.into()),
            // A short page is the whole list: no wider window can hold it.
            act::VoiceLookup::Missing if rows.len() < limit => break,
            act::VoiceLookup::Missing => {}
        }
    }
    let row = found.ok_or_else(|| act::VOICE_NOT_STORED.to_string())?;
    let id = control::room_id(&row).map_err(|_| "the node returned an unexpected file id".to_string())?;
    let blob = read_file_blob(state, &id).await?;
    if !act::is_voice_file(&blob.filename, &blob.mime_type) {
        return Err(act::NOT_A_VOICE_NOTE.into());
    }
    Ok(blob)
}

/// Any received kind-200 file by message id. Read-only: list + GET /files/:id,
/// never a payment. Over the app size cap → refused (nothing written).
async fn do_file_fetch(state: &NodeState, message_id: &str) -> Result<act::FileBlob, String> {
    let message_id = control::node_id(message_id).map_err(|_| "expected a 64-character hex message id".to_string())?;
    let mut found = None;
    for limit in act::FILE_LIST_WINDOWS {
        let rows: Vec<act::FileRow> = get_json(state, &format!("/files?limit={limit}")).await?;
        match act::stored_file_for(&rows, &message_id) {
            act::StoredLookup::Found(row) => { found = Some(row.id.clone()); break; }
            act::StoredLookup::Missing if rows.len() < limit => break,
            act::StoredLookup::Missing => {}
        }
    }
    let row = found.ok_or_else(|| act::FILE_NOT_STORED.to_string())?;
    let id = control::room_id(&row).map_err(|_| "the node returned an unexpected file id".to_string())?;
    read_file_blob(state, &id).await
}

/// One native save dialog at a time (N6): a second Save click while the first
/// dialog is open gets a clear error instead of stacking dialogs.
#[cfg(all(desktop, not(feature = "mobile")))]
static FILE_SAVE_DIALOG: Mutex<()> = Mutex::new(());

/// Fetch then write only where the owner picks in the native save dialog.
/// Cancel → `saved: false`. Never auto-saves or opens the file.
#[cfg(all(desktop, not(feature = "mobile")))]
async fn do_file_save(state: &NodeState, message_id: &str) -> Result<act::FileSaveResult, String> {
    let blob = do_file_fetch(state, message_id).await?;
    let _guard = FILE_SAVE_DIALOG
        .try_lock()
        .map_err(|_| "save already in progress".to_string())?;
    let name = act::safe_save_name(&blob.filename);
    // Release builds: always the native dialog (`dev_node::save_dir` is `Ok(None)`).
    let path = match dev_node::save_dir()? {
        Some(dir) => {
            let path = dir.join(&name);
            if path.exists() {
                return Err(format!("{} already exists; the test save dir never overwrites", path.display()));
            }
            Some(path)
        }
        None => rfd::FileDialog::new().set_file_name(&name).save_file(),
    };
    let Some(path) = path else {
        return Ok(act::FileSaveResult {
            saved: false,
            filename: blob.filename,
            mime_type: blob.mime_type,
            size_bytes: blob.size_bytes,
        });
    };
    act::write_file_bytes(&path, &blob.data_b64)?;
    Ok(act::FileSaveResult {
        saved: true,
        filename: blob.filename,
        mime_type: blob.mime_type,
        size_bytes: blob.size_bytes,
    })
}

/// Android: fetch, then save into the shared Downloads collection through the
/// app's MediaStore plugin (Android 10+). Nothing is replaced: a taken name is
/// renamed by the system.
#[cfg(target_os = "android")]
async fn do_file_save(state: &NodeState, message_id: &str) -> Result<act::FileSaveResult, String> {
    let blob = do_file_fetch(state, message_id).await?;
    let request = crate::file_save_android::request(&blob.filename, &blob.mime_type, &blob.data_b64)?;
    let returned = crate::file_save_android::save(request).await?;
    Ok(act::FileSaveResult {
        saved: true,
        // The name Downloads gave the file, which may differ from the one sent.
        filename: crate::file_save_android::saved_name(&returned, &blob.filename),
        mime_type: blob.mime_type,
        size_bytes: blob.size_bytes,
    })
}

/// iOS: fetch, then write into the app's own Documents folder, which the Files
/// app shows under BitSov (`UIFileSharingEnabled`). Never replaces a file:
/// a taken name becomes `name (2)`. Nothing else of the app lives there.
#[cfg(target_os = "ios")]
async fn do_file_save(state: &NodeState, message_id: &str) -> Result<act::FileSaveResult, String> {
    let blob = do_file_fetch(state, message_id).await?;
    let home = std::env::var_os("HOME").ok_or_else(|| "could not save: no app folder".to_string())?;
    let dir = std::path::PathBuf::from(home).join("Documents");
    std::fs::create_dir_all(&dir).map_err(|e| format!("could not save: {e}"))?;
    act::save_new_file(&dir, &blob.filename, &blob.data_b64)?;
    Ok(act::FileSaveResult {
        saved: true,
        filename: blob.filename,
        mime_type: blob.mime_type,
        size_bytes: blob.size_bytes,
    })
}

#[cfg(all(any(mobile, feature = "mobile"), not(any(target_os = "ios", target_os = "android"))))]
async fn do_file_save(
    _state: &NodeState,
    _message_id: &str,
) -> Result<act::FileSaveResult, String> {
    Err("Saving received files is not available on mobile yet.".into())
}

async fn read_call_quote(state: &NodeState, peer: &str) -> Result<control::CallQuote, String> {
    let peer = control::node_id(peer)?;
    let own: control::KindPrice = get_json(state, &control::price_path(act::KIND_CALL_OFFER + 1)).await?;
    // Genome asks the callee now; a refusal or an older node means no offer price.
    let live: Option<control::PeerCallPrice> = get_json(state, &format!("/pricing/peers/{peer}/call")).await.ok();
    Ok(control::call_quote(live.as_ref(), own.price_msat))
}

/// `call_quote`: the call price plus, for M6 node-routed calls, the callee's
/// advertised per-minute block price and the most the caller's node will
/// reserve for it. Read-only; the price advert is the node's cached table.
async fn read_call_quote_with_blocks(state: &NodeState, peer: &str) -> Result<control::CallQuote, String> {
    let quote = read_call_quote(state, peer).await?;
    let peer = control::node_id(peer)?;
    let table: Option<control::PeerPrice> = get_json(state, &format!("/pricing/peers/{peer}")).await.ok();
    let mut quote = control::with_call_blocks(quote, table.as_ref());
    quote.minutes_payable = minutes_payable(state);
    Ok(quote)
}

/// Genome N3: the caller's node reserves a call's minutes only for a paired
/// app spending under a grant. An owner session (`/auth/local`) gets no
/// reservation, so the host would pay no minute of its calls.
fn minutes_payable(state: &NodeState) -> bool {
    matches!(*state.auth.lock().unwrap(), AuthMode::Paired(_))
}

/// The agreed minutes for this outgoing call, if this run took any.
fn call_consent(state: &NodeState, peer: &str, call_id: &str) -> Option<CallConsent> {
    let node_id = state.node_id.lock().unwrap().clone()?;
    state.call_consents.lock().unwrap().find(&node_id, peer, call_id).cloned()
}

/// No money action of this app is pending at the host: nothing it sent can
/// still be on its way to the node. A journal that cannot be read is not.
fn spend_settled(state: &NodeState) -> bool {
    app_files_dir(state).is_some_and(|dir| matches!(spend_journal::read_pending(&dir.join("app-spend")), Ok(None)))
}

/// Ask the node whether this call and its hold are closed, and record it
/// (`CallConsents::node_reported`). A failed read proves nothing: the call
/// stays pinned. Returns whether the node shows it closed.
async fn verify_call_closed(state: &NodeState, node_id: &str, peer: &str, call_id: &str) -> bool {
    let Ok(status) = read_call_status_on(state, node_id, peer, call_id).await else { return false };
    let settled = spend_settled(state);
    state.call_consents.lock().unwrap().node_reported(node_id, peer, call_id, status.as_ref(), settled)
}

/// Re-verify every call the node has not yet shown closed (refused, ended or
/// open), so calls that are over stop counting against the limit. Never
/// touches an offer that is with the node right now; a failed read, or a call
/// still open at the node, changes nothing.
async fn sweep_call_consents(state: &NodeState) {
    let Some(node_id) = state.node_id.lock().unwrap().clone() else { return };
    let unverified: Vec<(String, String)> = state.call_consents.lock().unwrap().entries.iter()
        .filter(|c| c.node_id == node_id && !c.node_closed && !c.offering)
        .map(|c| (c.peer.clone(), c.call_id.clone())).collect();
    for (peer, call_id) in unverified {
        verify_call_closed(state, &node_id, &peer, &call_id).await;
    }
}

/// M6 A2: a node-routed offer with the minutes the owner agreed to before
/// Ring. The host keeps that consent for the call (never an amount to pay);
/// every later minute is checked against it. An owner session gets no
/// reservation from its node, so such a call is refused before anything is
/// paid rather than rung and then ended unpaid.
async fn do_call_offer_with_minutes(
    state: &NodeState, peer: &str, plaintext: &str, max_msat: u64, consent: control::MinutesConsent, shown_hangup: Option<u64>,
) -> Result<act::CallReceipt, ActionError> {
    let consent = consent.validated().map_err(ActionError::invalid)?;
    if !minutes_payable(state) {
        return Err(ActionError::new("call_minutes_unpayable",
            "This app is signed in to your node as its owner, not paired with a spending grant. Your node then keeps no reservation for a call's minutes, so the app cannot pay them. Pair the app with a spending grant to make calls. Nothing was paid."));
    }
    offer_within_consent(state, peer, plaintext, max_msat, consent, shown_hangup).await
}

/// The offer's admission, bound to the consent. The node makes the call's
/// hold when it admits the offer, at the callee's live per-minute price:
/// - the offer carries the consent's ceilings (genome N3 `max_block_msat`,
///   `max_hold_msat`): the node refuses, before it holds or pays anything,
///   a live price or a computed hold above them (`call_offer_price_above_consent`,
///   `call_offer_hold_above_consent`);
/// - routing allowance per minute: the offer's routing ceiling, which the
///   node applies to every block of the hold, is at most the agreed one;
/// - per-minute price: their advert is read again just before the offer;
///   above the agreed price (or gone) nothing is sent;
/// - the hold itself is checked again here as soon as the offer returns
///   (defence in depth). Until a check passes the call is `Offering` and no
///   minute is payable; a hold above the consent is `Refused` for good (set
///   before the hangup), so it is never paid, and the call is hung up.
///
/// An offer that did not go through ends the call's consent for good: its
/// terms can never be admitted later, under these or wider ones.
async fn offer_within_consent(
    state: &NodeState, peer: &str, plaintext: &str, max_msat: u64, consent: control::MinutesConsent, shown_hangup: Option<u64>,
) -> Result<act::CallReceipt, ActionError> {
    let consent = consent.validated().map_err(ActionError::invalid)?;
    let target = control::node_id(peer).map_err(ActionError::invalid)?;
    let call_id = serde_json::from_str::<serde_json::Value>(plaintext).ok()
        .and_then(|v| v["call_id"].as_str().map(str::to_string))
        .filter(|id| act::is_call_id(id))
        .ok_or_else(|| ActionError::invalid("invalid call id"))?;
    let node_id = state.node_id.lock().unwrap().clone()
        .ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
    if state.call_consents.lock().unwrap().pinned_count(&node_id) >= CALL_CONSENTS_OPEN {
        sweep_call_consents(state).await;
    }
    {
        let mut kept = state.call_consents.lock().unwrap();
        kept.register(node_id.clone(), &target, &call_id, consent, spend_stops(state))?;
        let entry = kept.find_mut(&node_id, &target, &call_id)
            .ok_or_else(|| ActionError::new("call_no_consent", "Nothing was paid."))?;
        if entry.phase != ConsentPhase::Offering || entry.offering || entry.dispatched {
            return Err(ActionError::new("call_offer_in_flight", "This call's offer was already sent to your node. Nothing more was paid."));
        }
        entry.offering = true;
    }
    let mut sent = true;
    let result = async {
        let table: Option<control::PeerPrice> = get_json(state, &format!("/pricing/peers/{target}")).await.ok();
        if control::advert_block_msat(table.as_ref()).is_none_or(|block| block > consent.block_msat) {
            sent = false;
            return Err(ActionError::new("call_price_changed",
                "Their per-minute price is no longer the one you agreed to. Nothing was sent or paid; check the price and call again."));
        }
        do_call_signal_bounded(state, &target, act::KIND_CALL_OFFER, plaintext, max_msat, None, Some(&consent), shown_hangup).await
    }.await;
    {
        let mut kept = state.call_consents.lock().unwrap();
        if let Some(entry) = kept.find_mut(&node_id, &target, &call_id) {
            entry.offering = false;
            if result.is_ok() { entry.dispatched = true; }
        }
        if result.is_err() { kept.end(&node_id, Some(&target), &call_id); }
        if !sent { kept.node_reported(&node_id, &target, &call_id, None, true); }
    }
    let receipt = match result {
        Ok(receipt) => receipt,
        Err(error) => {
            // Nothing of it is payable now; it stays pinned until the node shows no call or hold for it.
            if sent { verify_call_closed(state, &node_id, &target, &call_id).await; }
            return Err(error);
        }
    };
    // Check the hold the node made with the offer now. A refused one is hung
    // up and stays refused; a failed read leaves the call unpayable until
    // `call_hold` checks it. The paid offer's receipt is returned either way.
    let _ = checked_call_hold(state, &target, &call_id).await;
    Ok(receipt)
}

/// End an outgoing call whose minutes the host will not pay, through the same
/// host-owned hangup as `op_end_call`, then ask the node whether the call and
/// its hold are closed. Says what happened for the refusal. Whatever the
/// outcome, the refusal was recorded first and stays the answer.
async fn hang_up_unpaid_call(state: &NodeState, node_id: &str, peer: &str, call_id: &str) -> &'static str {
    let hung_up = do_op_end_call(state, call_id).await.is_ok();
    let closed = verify_call_closed(state, node_id, peer, call_id).await;
    match (hung_up, closed) {
        (true, true) => "The app hung up the call, and your node has closed its hold.",
        (false, true) => "Your node has closed the call and its hold.",
        (true, false) => "The app hung up the call; your node releases what it held when it closes the call.",
        (false, false) => "Hang up the call; your node releases what it held when it closes the call.",
    }
}

/// A consent that can no longer pay: its refusal, or the call ended.
fn consent_closed(phase: &ConsentPhase) -> Option<ActionError> {
    match phase {
        ConsentPhase::Refused { code, message } => Some(ActionError::new(code, message.clone())),
        ConsentPhase::Ended => Some(ActionError::new("call_not_live", "This call has ended. Nothing more was paid.")),
        ConsentPhase::Offering | ConsentPhase::Admitted => None,
    }
}

const NO_CONSENT: &str = "This app holds no per-minute price you agreed to for this call, so it pays none of its minutes. Nothing was paid.";

/// M6 A2: the node's reservation for this outgoing call, checked against the
/// owner's consent before any minute is paid. Refuses (proven unpaid) when no
/// consent was taken, the node has not accepted the call's offer yet, the
/// call is not an open outgoing call, or the hold is closed. Without a
/// reservation, or with one above the consent (per-minute price, routing
/// allowance or total held), the host refuses the call's consent for good,
/// then hangs up: those minutes are never paid. A hold within the consent
/// admits the call (the only state that can pay). Every node status read here
/// that shows the call closed is recorded (`node_reported`).
async fn checked_call_hold(state: &NodeState, peer: &str, call_id: &str)
    -> Result<(control::CallStatus, control::CallReservation, CallConsent), ActionError> {
    let target = control::node_id(peer).map_err(ActionError::invalid)?;
    if !act::is_call_id(call_id) {
        return Err(ActionError::invalid("invalid call id"));
    }
    let consent = call_consent(state, &target, call_id).ok_or_else(|| ActionError::new("call_no_consent", NO_CONSENT))?;
    if let Some(error) = consent_closed(&consent.phase) { return Err(error); }
    if !consent.dispatched {
        // A hold listed under this call id before the node accepted this very
        // offer is not this offer's hold: it is never checked or admitted.
        return Err(ActionError::new("call_hold_unconfirmed",
            "Your node has not accepted this call's offer yet, so its hold cannot be checked. Nothing was paid."));
    }
    let node_id = consent.node_id.clone();
    let reported = |state: &NodeState, status: Option<&control::CallStatus>| {
        let settled = spend_settled(state);
        let mut kept = state.call_consents.lock().unwrap();
        if !kept.node_reported(&node_id, &target, call_id, status, settled) {
            // Ended at the node but its hold is not closed yet: no further minute, still pinned.
            kept.end(&node_id, Some(&target), call_id);
        }
    };
    let Some(status) = read_call_status_on(state, &node_id, &target, call_id).await? else {
        // The node accepted the offer and lists the call no more: it is over.
        reported(state, None);
        return Err(ActionError::new("call_not_live", "Your node no longer lists this call. Nothing more was paid."));
    };
    if status.direction != "outgoing" || status.state == "ended" {
        if status.state == "ended" { reported(state, Some(&status)); }
        return Err(ActionError::new("call_not_live", "Your node has ended this call. Nothing more was paid."));
    }
    let hold = match status.reservation.clone() {
        Some(hold) if hold.closed => {
            reported(state, Some(&status));
            return Err(ActionError::new("call_reservation_closed", "Your node has closed this call's reservation. Nothing more was paid."));
        }
        Some(hold) => hold,
        None => {
            let message = "Your node keeps no reservation for this call's minutes, so the app pays none of them. No minute was paid.";
            state.call_consents.lock().unwrap().refuse(&node_id, &target, call_id, "call_no_reservation", message);
            let ended = hang_up_unpaid_call(state, &node_id, &target, call_id).await;
            return Err(ActionError::new("call_no_reservation", format!("{message} {ended}")));
        }
    };
    if !consent.consent.covers(&hold) {
        let message = format!(
            "Your node reserved {} for this call ({} a minute plus up to {} routing), more than the {} ({} a minute plus up to {} routing) you agreed to before calling. No minute was paid.",
            bitsov_app::format::amount(hold.reserved_msat), bitsov_app::format::amount(hold.per_block_msat), bitsov_app::format::amount(hold.per_block_fee_msat),
            bitsov_app::format::amount(consent.consent.max_hold_msat), bitsov_app::format::amount(consent.consent.block_msat),
            bitsov_app::format::amount(consent.consent.block_max_routing_fee_msat));
        // Refused before the hangup awaits: a minute raced against it finds the refusal.
        state.call_consents.lock().unwrap().refuse(&node_id, &target, call_id, "call_hold_above_consent", &message);
        let ended = hang_up_unpaid_call(state, &node_id, &target, call_id).await;
        return Err(ActionError::new("call_hold_above_consent", format!("{message} {ended}")));
    }
    let consent = {
        let mut kept = state.call_consents.lock().unwrap();
        kept.admit(&node_id, &target, call_id);
        let current = kept.find(&node_id, &target, call_id).cloned()
            .ok_or_else(|| ActionError::new("call_no_consent", NO_CONSENT))?;
        if let Some(error) = consent_closed(&current.phase) { return Err(error); }
        current
    };
    Ok((status, hold, consent))
}

/// The call's consent is still admitted and its confirmation still names
/// this exact hold: checked again right before a minute is paid.
fn consent_payable(state: &NodeState, consent: &CallConsent, reserved_msat: u64) -> Result<(), ActionError> {
    let kept = state.call_consents.lock().unwrap();
    let current = kept.find(&consent.node_id, &consent.peer, &consent.call_id)
        .ok_or_else(|| ActionError::new("call_no_consent", NO_CONSENT))?;
    if let Some(error) = consent_closed(&current.phase) { return Err(error); }
    if current.phase != ConsentPhase::Admitted || current.consent != consent.consent || current.confirmed_msat != Some(reserved_msat) {
        return Err(ActionError::new("call_hold_unconfirmed",
            "Confirm your node's hold for this call before its first minute is paid. Nothing was paid."));
    }
    Ok(())
}

/// Pause points inside `money_post_with` for the race tests, per fake node
/// (`api_base`): a test arms a point, waits until a request arrives there,
/// acts, then releases it. Reached only under `cfg!(test)`; never armed or
/// awaited in a build.
mod pause_points {
    use std::sync::{Arc, Mutex};
    use tokio::sync::Notify;

    struct Gate { api_base: String, point: &'static str, arrived: Arc<Notify>, release: Arc<Notify> }
    static GATES: Mutex<Vec<Gate>> = Mutex::new(Vec::new());

    /// One pause at `point` for this node: (arrived, release). Tests only.
    #[cfg_attr(any(not(test), feature = "mobile"), allow(dead_code))]
    pub fn arm(api_base: &str, point: &'static str) -> (Arc<Notify>, Arc<Notify>) {
        let (arrived, release) = (Arc::new(Notify::new()), Arc::new(Notify::new()));
        GATES.lock().unwrap().push(Gate { api_base: api_base.into(), point, arrived: arrived.clone(), release: release.clone() });
        (arrived, release)
    }

    pub async fn at(api_base: &str, point: &'static str) {
        let gate = {
            let mut gates = GATES.lock().unwrap();
            gates.iter().position(|g| g.api_base == api_base && g.point == point).map(|i| gates.remove(i))
        };
        if let Some(gate) = gate {
            gate.arrived.notify_one();
            gate.release.notified().await;
        }
    }
}

/// Compiled only for the tests that use it: a one-time failure of a named
/// cleanup step on one node's money path, so a test can show what a failed
/// cleanup leaves behind. Armed per node and point; consumed when it fires.
#[cfg(all(test, desktop, not(feature = "mobile")))]
mod fault_points {
    use std::sync::Mutex;

    static ARMED: Mutex<Vec<(String, &'static str)>> = Mutex::new(Vec::new());

    /// The next pass through `point` on this node fails, once.
    pub fn arm(api_base: &str, point: &'static str) {
        ARMED.lock().unwrap().push((api_base.into(), point));
    }

    /// Fails, once, if `point` is armed for this node.
    pub fn check(api_base: &str, point: &'static str) -> Result<(), super::ActionError> {
        let mut armed = ARMED.lock().unwrap();
        let Some(i) = armed.iter().position(|(base, p)| base == api_base && *p == point) else { return Ok(()) };
        armed.remove(i);
        Err(super::spend_journal::unknown("Synthetic fault for this test only."))
    }
}

/// A call block's peer and wire call id, from its body.
fn block_identity(body: &serde_json::Value) -> (String, String) {
    let peer = body["recipient"].as_str().unwrap_or_default().to_string();
    let call_id = body["plaintext"].as_str().and_then(|p| serde_json::from_str::<serde_json::Value>(p).ok())
        .and_then(|p| p["call_id"].as_str().map(str::to_string)).unwrap_or_default();
    (peer, call_id)
}

/// `money_post_with`, under the money lock, for a call block (kind 404): its
/// call's consent is still admitted and its hold confirmed. The refusal, if
/// not. Called when the minute reaches the lock and again as its last step
/// before the POST.
fn block_consent_refusal(state: &NodeState, node_id: &str, body: &serde_json::Value) -> Option<ActionError> {
    let (peer, call_id) = block_identity(body);
    let kept = state.call_consents.lock().unwrap();
    let Some(current) = kept.find(node_id, &peer, &call_id) else {
        return Some(ActionError::new("call_no_consent", NO_CONSENT));
    };
    if let Some(error) = consent_closed(&current.phase) { return Some(error); }
    (current.phase != ConsentPhase::Admitted || current.confirmed_msat.is_none()).then(|| ActionError::new("call_hold_unconfirmed",
        "Confirm your node's hold for this call before its first minute is paid. Nothing was paid."))
}

const MINUTE_PAST_HOLD: &str = "call_minutes_above_hold";
const MINUTE_PAST_HOLD_WORDS: &str = "The next minute of this call would go past the hold you agreed to. Nothing was paid for it.";

/// `money_post_with`, under the money lock, for a call block: the ceilings of this
/// call's minutes in the journal, plus this one, pass the hold the owner confirmed.
/// An attempt the node proved unpaid uses none of it; one whose outcome is not known
/// yet does. A journal that cannot be read pays nothing.
fn minute_past_journaled_hold(state: &NodeState, journal: &Journal, node_id: &str, body: &serde_json::Value, cap: u64) -> Result<bool, ActionError> {
    let (peer, call_id) = block_identity(body);
    // Ended or refused since `block_consent_refusal` (End takes no money lock):
    // that refusal is the answer, not "past the hold".
    let limit = {
        let kept = state.call_consents.lock().unwrap();
        let Some(c) = kept.find(node_id, &peer, &call_id) else { return Err(ActionError::new("call_no_consent", NO_CONSENT)) };
        if let Some(error) = consent_closed(&c.phase) { return Err(error); }
        c.confirmed_msat.map(|m| m.min(c.consent.max_hold_msat))
    };
    let Some(limit) = limit else { return Ok(true) };
    let records = journal.call_operations_for(node_id, Some(&peer), Some(&call_id))?;
    let journaled = records.iter().filter(|r| r.kind == "call_block" && r.state != spend_journal::OperationState::Unpaid)
        .try_fold(cap, |sum, r| sum.checked_add(r.cap_msat));
    Ok(journaled.is_none_or(|most| most > limit))
}

/// Refuse the call's further minutes for good, then hang up, as for a hold above
/// the consent. Pays no minute.
async fn end_call_past_hold(state: &NodeState, consent: &CallConsent) -> ActionError {
    state.call_consents.lock().unwrap().refuse(&consent.node_id, &consent.peer, &consent.call_id, MINUTE_PAST_HOLD, MINUTE_PAST_HOLD_WORDS);
    let ended = hang_up_unpaid_call(state, &consent.node_id, &consent.peer, &consent.call_id).await;
    ActionError::new(MINUTE_PAST_HOLD, format!("{MINUTE_PAST_HOLD_WORDS} {ended}"))
}

/// M6 A2 `call_hold`: the node's reservation for an outgoing call, checked
/// against the owner's consent (see `checked_call_hold`). With
/// `confirm_reserved_msat` the owner confirms the hold the card showed; it
/// must equal the node's reservation total, and only then may block 0 be
/// paid. Pays nothing itself (a refused hold is hung up).
async fn do_call_hold(state: &NodeState, peer: &str, call_id: &str, confirm_reserved_msat: Option<u64>) -> Result<control::CallStatus, ActionError> {
    let (status, hold, consent) = checked_call_hold(state, peer, call_id).await?;
    *state.call_limit_seen.lock().unwrap() = Some((consent.node_id.clone(), hold.max_call_minutes));
    if let Some(shown) = confirm_reserved_msat {
        if shown != hold.reserved_msat {
            return Err(ActionError::new("call_hold_changed",
                "Your node's hold for this call is not the one you confirmed. Nothing was paid; check the hold and confirm again."));
        }
        let mut kept = state.call_consents.lock().unwrap();
        let entry = kept.find_mut(&consent.node_id, &consent.peer, &consent.call_id)
            .ok_or_else(|| ActionError::new("call_no_consent", NO_CONSENT))?;
        if let Some(error) = consent_closed(&entry.phase) { return Err(error); }
        entry.confirmed_msat = Some(hold.reserved_msat);
        let stops = entry.stops;
        drop(kept);
        state.held_calls.lock().unwrap().keep(&consent.node_id, &consent.peer, &consent.call_id, stops);
    }
    Ok(status)
}

/// M6: one call's paid interval and spend reservation as the node reports
/// them (`GET /calls?peer=`). Read-only: never pays, releases or settles.
/// `None`: the node no longer lists the call (ended with nothing pending).
async fn read_call_status(state: &NodeState, peer: &str, call_id: &str) -> Result<Option<control::CallStatus>, ActionError> {
    read_call_status_from(state, None, peer, call_id).await
}

/// `read_call_status`, asked of `node_id` only: a failed read if another node
/// is active, or becomes active at any point of it, even for a moment.
async fn read_call_status_on(state: &NodeState, node_id: &str, peer: &str, call_id: &str) -> Result<Option<control::CallStatus>, ActionError> {
    let bound = NodeBound::now(state, node_id, None).ok_or_else(|| ActionError::node("/calls: another node is active"))?;
    read_call_status_from(state, Some(&bound), peer, call_id).await
}

async fn read_call_status_from(state: &NodeState, bound: Option<&NodeBound>, peer: &str, call_id: &str) -> Result<Option<control::CallStatus>, ActionError> {
    let peer = control::node_id(peer).map_err(ActionError::invalid)?;
    if !act::is_call_id(call_id) {
        return Err(ActionError::invalid("invalid call id"));
    }
    let calls: Vec<control::CallStatus> = get_json_on(state, bound, &format!("/calls?peer={peer}")).await.map_err(ActionError::node)?;
    Ok(calls.into_iter().find(|c| c.id == call_id))
}

/// M6: pay block `seq` (kind 404) of an outgoing node-routed call. The node
/// draws it from the reservation it made when the offer went out. Paid only
/// with the owner's consent for this call kept by the host, a node
/// reservation within it (`checked_call_hold`, which hangs up otherwise) and
/// the owner's confirmation of exactly that hold; amount and routing ceiling
/// are the reservation's own, never the renderer's. Same authority and
/// exactly-once journal as every other call signal.
async fn do_call_block(state: &NodeState, peer: &str, call_id: &str, seq: u32) -> Result<act::CallReceipt, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
        let target = control::node_id(peer).map_err(ActionError::invalid)?;
        let (status, hold, consent) = checked_call_hold(state, &target, call_id).await?;
        consent_payable(state, &consent, hold.reserved_msat)?;
        if status.next_block_seq != seq {
            return Err(ActionError::new("call_block_not_due", "Your node expects another minute of this call. Nothing was paid for this one."));
        }
        let cap = hold.per_block_msat.checked_add(hold.per_block_fee_msat)
            .ok_or_else(|| ActionError::invalid("the call block amount is out of range"))?;
        let fee = hold.per_block_fee_msat;
        // What the node has spent of this hold leaves room for this whole minute.
        // The journal's own count is checked under the money lock, in `money_post_with`.
        let limit = hold.reserved_msat.min(consent.consent.max_hold_msat);
        if hold.spent_msat.checked_add(cap).is_none_or(|most| most > limit) {
            return Err(end_call_past_hold(state, &consent).await);
        }
        // As paid, a minute is its price plus the routing fee the node pinned
        // on the hold (none on a usable direct channel). That whole payment
        // must fit the grant's call limit, or nothing is sent.
        let known = state.node_grant.lock().unwrap().clone();
        if let Some(g) = known {
            let per_act = if g.recipients_only { g.per_act_max_by_recipient.get(&target).copied().unwrap_or(0) } else { u64::MAX };
            let limit = g.per_payment_max(grant::PaymentCap::CallCeiling).unwrap_or(u64::MAX).min(per_act);
            if cap > limit {
                return Err(grant::per_call(limit));
            }
        }
        let mut body = act::call_block_body(&target, call_id, seq)?;
        let needs_contact = || ActionError::new("call_needs_contact", "Calls go to contacts you have already paid. Send them a message first. Nothing was paid.");
        let caps = require_price_caps(state, false).await?;
        let (auth, plan) = match plan_message(state, &target, false, cap, None) {
            // The approval ran out during this admitted call (by time, or the
            // grant left the node's list): a node that keeps the call draws
            // this minute on its pinned hold, as the owner confirmed it, unless
            // spending was explicitly stopped since the call was offered. The
            // book's limits still apply.
            Err(e) if matches!(e.code, "spend_expired" | "spend_locked")
                && status_lists(&caps.status, CALL_CONTINUITY_CAPABILITY) && spend_stops(state) == consent.stops => {
                let plan = with_book(state, false, |book| budget::plan(book, budget::Ask {
                    target: &target, room: false, max_msat: cap, first_contact_msat: None,
                    autopay: None, window: Ok(()), now_ms: now_ms(),
                }))?;
                (Auth::CallHold(consent.stops), plan)
            }
            planned => planned.map_err(|e| if e.code == "first_contact" { needs_contact() } else { e })?,
        };
        if plan.confirm.is_some() {
            return Err(needs_contact());
        }
        if !caps.operations {
            return Err(ActionError::new("call_needs_node_upgrade",
                "Upgrade your node before making calls: it cannot track call payments and admission safely. Nothing was paid."));
        }
        body["max_total_msat"] = serde_json::json!(cap);
        body["max_routing_fee_msat"] = serde_json::json!(fee);
        let charge = Charge {
            target: target.clone(),
            room: false,
            confirm: None,
            readmission_possible: caps.readmission_possible,
            confirmed: false,
            operation: caps.operations,
            envelope_ids: Some(caps.envelope_ids),
            failure_final_on: final_failure_node(&caps.status),
            call_window: false,
        };
        // Refused or ended while this minute was prepared: nothing is sent.
        consent_payable(state, &consent, hold.reserved_msat)?;
        let text = match money_post(state, auth, "/messages/compose", body, cap, Some(charge)).await {
            Err(error) if error.code == MINUTE_PAST_HOLD => return Err(end_call_past_hold(state, &consent).await),
            sent => sent?,
        };
        let reply: act::SendReply = text.decode("/messages/compose")?;
        Ok(act::CallReceipt {
            operation_id: reply.operation_id.clone(),
            total_msat: act::with_op(Active(text.operation_id.as_deref()), reply.total_msat())?,
            message_id: reply.message_id,
            kind: act::KIND_CALL_BLOCK,
            amount_msat: reply.amount_msat,
            max_routing_fee_msat: reply.max_routing_fee_msat,
            delivered: reply.delivered,
            accepted: reply.accepted,
            sent_at_ms: now_ms(),
        })
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// Spending is open right now: the owner's window, or a budget approval, and
/// payments are not paused. Fails closed on a book that cannot be read.
fn spending_open(state: &NodeState) -> bool {
    let now = now_ms();
    let window = state.spend.lock().unwrap().check(now).is_ok();
    let budget = state.autopay.lock().unwrap().ceiling(now).is_some();
    (window || budget) && budget_paused(state).is_ok_and(|paused| !paused)
}

/// An incoming call whose answer went out: kept for `held_call_plan`.
fn keep_answered_call(state: &NodeState, node_id: &str, peer: &str, plaintext: &str, stops: u64) {
    let call_id = serde_json::from_str::<serde_json::Value>(plaintext).ok()
        .and_then(|v| v["call_id"].as_str().filter(|id| act::is_call_id(id)).map(str::to_string));
    if let (Some(call_id), false) = (call_id, node_id.is_empty()) {
        state.held_calls.lock().unwrap().keep(node_id, peer, &call_id, stops);
    }
}

const HELD_GRANT_ENDED: &str = "call_grant_ended";
const HELD_GRANT_ENDED_WORDS: &str = "Your node's spend budget has ended, so this call signal could not be sent. Your node ends the call when its paid time runs out. Nothing was sent or paid.";

/// `call_continuity_v1`: the owner's approval ran out (by time, or the grant
/// left the node's list) during a call this node keeps. That call may still
/// send its own hangup, so End can always reach the other side, and the
/// reconnect request it needs: kinds 402 and 403 only. An offer or an answer
/// starts or takes a call and still needs an approval. Only for a call kept
/// in `NodeState::held_calls` whose `spend_stops` is still current (no lock,
/// pause, refused token or new connection since it began), at most
/// `HELD_CALL_SIGNALS` per call, each within the book's limits. On a node
/// with grants, only while the node still holds a live grant: a token
/// without `spend` is never asked to send, so a refusal cannot stop the
/// call's minutes. The caller then checks the live price and the message
/// cap as for any signal. `None`: not such a call; the lapse is the answer.
async fn held_call_plan(state: &NodeState, target: &str, kind: u16, plaintext: &str, max_msat: u64) -> Result<Option<(Auth, budget::Plan)>, ActionError> {
    if !matches!(kind, act::KIND_CALL_ICE | act::KIND_CALL_HANGUP) { return Ok(None); }
    let Some(call_id) = serde_json::from_str::<serde_json::Value>(plaintext).ok()
        .and_then(|v| v["call_id"].as_str().filter(|id| act::is_call_id(id)).map(str::to_string)) else { return Ok(None) };
    let node_id = state.node_id.lock().unwrap().clone();
    let Some(node_id) = node_id else { return Ok(None) };
    let stops = spend_stops(state);
    let kept = state.held_calls.lock().unwrap().can_send(&node_id, target, &call_id, stops);
    if !kept { return Ok(None); }
    let caps = require_price_caps(state, false).await?;
    if !status_lists(&caps.status, CALL_CONTINUITY_CAPABILITY) { return Ok(None); }
    let paired = matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(_));
    if paired && status_lists(&caps.status, grant::CAPABILITY) {
        match read_grant(state).await? {
            Some(g) if g.live(now_ms()) => { *state.node_grant.lock().unwrap() = Some(g); }
            _ => return Err(ActionError::new(HELD_GRANT_ENDED, HELD_GRANT_ENDED_WORDS)),
        }
    }
    let plan = with_book(state, false, |book| budget::plan(book, budget::Ask {
        target, room: false, max_msat, first_contact_msat: None,
        autopay: None, window: Ok(()), now_ms: now_ms(),
    }))?;
    let taken = state.held_calls.lock().unwrap().take(&node_id, target, &call_id, stops);
    Ok(taken.then_some((Auth::CallHold(stops), plan)))
}

async fn do_call_signal_for_admission(
    state: &NodeState, peer: &str, kind: u16, plaintext: &str, max_msat: u64,
    admission: Option<&spend_journal::OperationRecord>,
) -> Result<act::CallReceipt, ActionError> {
    do_call_signal_bounded(state, peer, kind, plaintext, max_msat, admission, None, None).await
}

/// `minutes`: an offer under the minutes the owner agreed to. Its routing
/// ceiling is at most the agreed allowance per minute (the caller's node
/// takes the offer's routing ceiling as every block's, never wider), and it
/// carries the consent's ceilings for the node to enforce before it holds
/// anything (genome N3 `max_block_msat`, `max_hold_msat`).
///
/// `shown_hangup`: the most the owner was shown this call's hangup can cost. An
/// offer whose hangup now costs more is refused before anything is sent, so the
/// ceiling saved for End is never above what was shown.
#[allow(clippy::too_many_arguments)]
async fn do_call_signal_bounded(
    state: &NodeState, peer: &str, kind: u16, plaintext: &str, max_msat: u64,
    admission: Option<&spend_journal::OperationRecord>, minutes: Option<&control::MinutesConsent>, shown_hangup: Option<u64>,
) -> Result<act::CallReceipt, ActionError> {
    if (minutes.is_some() || shown_hangup.is_some()) && kind != act::KIND_CALL_OFFER {
        return Err(ActionError::invalid("agreed minutes and a shown hangup ceiling go with an offer only"));
    }
    // An answer keeps its call for `held_call_plan` under the stops it began with.
    let stops = spend_stops(state);
    // A hangup ends the call's minutes as it begins, whatever its outcome.
    if kind == act::KIND_CALL_HANGUP {
        if let Some(call_id) = serde_json::from_str::<serde_json::Value>(plaintext).ok()
            .and_then(|v| v["call_id"].as_str().filter(|id| act::is_call_id(id)).map(str::to_string)) {
            end_minutes(state, &call_id);
        }
    }
    let mut existing_operation = admission.map(|r| r.op_id.clone()).or_else(|| pending_operation_id(state).unwrap_or_default());
    let result = async {
    let target = control::node_id(peer).map_err(ActionError::invalid)?;
    let signal_node_id = state.node_id.lock().unwrap().clone().unwrap_or_default();
    // Bind ordinary renderer hangups too, before any quote/auth await.
    let captured = if kind == act::KIND_CALL_HANGUP && admission.is_none() {
        let payload: serde_json::Value = serde_json::from_str(plaintext).map_err(|_| ActionError::invalid("invalid call signal"))?;
        let dir = app_files_dir(state).ok_or_else(|| spend_journal::unknown("The app data directory is not ready."))?;
        spend_journal::read_call_admission(&dir.join("app-spend"), &signal_node_id, &target,
            payload["call_id"].as_str().unwrap_or_default())?
    } else { None };
    let admission = admission.or(captured.as_ref());
    if let Some(admission) = admission { existing_operation = Some(admission.op_id.clone()); }
    let mut body = act::call_body(&target, kind, plaintext)?;
    if kind == act::KIND_CALL_HANGUP {
        body["host_call_snapshot"] = serde_json::json!(true);
        body["host_expected_node_id"] = serde_json::json!(signal_node_id);
    }
    if let Some(admission) = admission {
        body["host_expected_node_id"] = serde_json::json!(admission.node_id);
        body["host_admission_op"] = serde_json::json!(admission.op_id);
    }
    let needs_contact = || ActionError::new("call_needs_contact", "Calls go to contacts you have already paid. Send them a message first. Nothing was paid.");
    let (auth, plan) = match plan_message(state, &target, false, max_msat, None) {
        // The approval ran out during a call this node keeps: that call's own
        // hangup or reconnect request still goes, on the call's authority.
        Err(e) if matches!(e.code, "spend_expired" | "spend_locked") => match held_call_plan(state, &target, kind, plaintext, max_msat).await? {
            Some(held) => held,
            None => return Err(e),
        },
        planned => planned.map_err(|e| if e.code == "first_contact" { needs_contact() } else { e })?,
    };
    if plan.confirm.is_some() {
        return Err(needs_contact());
    }
    // The locked money path owns call fencing, including a pending receipt.
    let caps = require_price_caps(state, false).await?;
    if (kind == act::KIND_CALL_OFFER || admission.is_some()) && !caps.operations {
        return Err(ActionError::new("call_needs_node_upgrade",
            "Upgrade your node before making calls: it cannot track call payments and admission safely. Nothing was paid."));
    }
    // `call_continuity_v1`: this node keeps an admitted call through its
    // grant's expiry or renewal, so the grant need not outlast the call.
    let continuity = status_lists(&caps.status, CALL_CONTINUITY_CAPABILITY);
    let quote = read_call_quote(state, &target).await.map_err(ActionError::node)?;
    let unsupported = || ActionError::new(
        "call_unsupported", "Their node does not take calls yet (no call price advertised). Nothing was paid.");
    let no_live_price = || ActionError::new("call_price_unknown",
        "Their node gave no live call price, so this was not sent. Nothing was sent or paid.");
    let (principal, fee) = if kind == act::KIND_CALL_OFFER {
        (quote.offer_msat.ok_or_else(unsupported)?, quote.offer_max_routing_fee_msat)
    } else if quote.offer_msat.is_some() {
        (quote.signal_msat, quote.signal_max_routing_fee_msat)
    } else {
        // Without their live answer the quote's signal price is only this node's
        // own tariff, which says nothing about what this signal would cost.
        return Err(no_live_price());
    };
    let cost = principal.checked_add(fee).ok_or_else(no_live_price)?;
    let hangup = quote.signal_msat.checked_add(quote.signal_max_routing_fee_msat).ok_or_else(no_live_price)?;
    ceiling(cost, max_msat)?;
    if let Some(shown) = shown_hangup { ceiling(hangup, shown)?; }
    if kind == act::KIND_CALL_OFFER {
        // Admission plus one hangup: check the ceiling shown for the whole
        // call, not just this offer. money_post still rechecks the paid step.
        let total = quote.call_total_msat.ok_or_else(unsupported)?;
        // The node caps the offer and each minute by the call per-payment
        // limit (a relation envelope's per-act maximum on a relation grant),
        // never by the 6-sat message cap; their sum is checked against the
        // budgets only. A minute is compared at its price: the node pins no
        // routing fee for a usable direct channel and refuses, before any
        // hold or payment, a minute whose ceiling does not fit. The routing
        // allowance stays in the hold and the budget checks.
        let minute = minutes.map_or(0, |m| m.block_msat);
        let per_payment = cost.max(minute);
        let checked = check_node_grant_with_envelope_ids(state, "/messages/compose", &body, total, Some(caps.envelope_ids), grant::PaymentCap::CallTotal).await
            .and_then(|g| match g.as_ref().map(|g| g.check_call(per_payment, Some(&target), now_ms())) {
                Some(Err(error)) => Err(error),
                _ => Ok(g),
            })
            .map_err(|mut error| {
                if matches!(error.code, "grant_exhausted" | "grant_recipient") {
                    error.message = format!(
                        "This call needs up to {}. {} The owner would need to approve enough remaining budget for that ceiling. Nothing was sent or paid.",
                        bitsov_app::format::amount(total), error.message,
                    );
                } else if error.code == "grant_per_call" {
                    error.message = format!(
                        "This call needs up to {} per payment. {} The owner would need to approve at least {} per payment. Nothing was sent or paid.",
                        bitsov_app::format::amount(per_payment), error.message, bitsov_app::format::amount(per_payment),
                    );
                }
                error
            })?;
        // A node-routed call must fit inside the grant the node holds now,
        // unless the node keeps an admitted call past that grant's end.
        if minutes.is_some() && !continuity {
            if let Some(g) = &checked { call_window_fits(state, g.expires_at_ms())?; }
        }
        // A hangup is bounded like a message (the 6-sat cap). A call that
        // could not be ended is never started.
        if let Some(g) = checked {
            let per_act = if g.recipients_only { g.per_act_max_by_recipient.get(&target.to_ascii_lowercase()).copied().unwrap_or(0) } else { u64::MAX };
            let limit = g.per_payment_max(grant::PaymentCap::Grant).unwrap_or(u64::MAX).min(per_act);
            // Above the most any message payment may carry, no approval helps;
            // below it, a lower signed limit (or contact amount) could be raised.
            if hangup > grant::MESSAGING_PER_CALL_MAX_MSAT {
                return Err(ActionError::new("call_hangup_above_message_max", format!(
                    "Hanging up this call can cost up to {}, more than the {} any message payment may carry, so it could not be ended. A larger per-payment limit would not change that. Nothing was sent or paid.",
                    bitsov_app::format::amount(hangup), bitsov_app::format::amount(grant::MESSAGING_PER_CALL_MAX_MSAT))));
            }
            if hangup > limit {
                return Err(ActionError::new("call_hangup_unpayable", format!(
                    "Hanging up this call can cost up to {}, more than the {} per message payment your node allows, so it could not be ended. The owner would need to approve at least {} per payment. Nothing was sent or paid.",
                    bitsov_app::format::amount(hangup), bitsov_app::format::amount(limit), bitsov_app::format::amount(hangup))));
            }
        }
    }
    if kind == act::KIND_CALL_OFFER {
        body["host_hangup_cap_msat"] = serde_json::json!(hangup);
    }
    body["max_total_msat"] = serde_json::json!(max_msat);
    body["max_routing_fee_msat"] = serde_json::json!(minutes.map_or(fee, |m| fee.min(m.block_max_routing_fee_msat)));
    if let Some(minutes) = minutes {
        // The node refuses (`not_dispatched`, nothing held or paid) a live
        // per-minute price or a computed hold above what the owner agreed to.
        body["max_block_msat"] = serde_json::json!(minutes.block_msat);
        body["max_hold_msat"] = serde_json::json!(minutes.max_hold_msat);
    }
    let charge = Charge {
        target: target.clone(),
        room: false,
        confirm: None,
        readmission_possible: caps.readmission_possible,
        confirmed: false,
        operation: caps.operations,
        envelope_ids: Some(caps.envelope_ids),
        failure_final_on: final_failure_node(&caps.status),
        call_window: !continuity && (kind == act::KIND_CALL_ANSWER || (kind == act::KIND_CALL_OFFER && minutes.is_some())),
    };
    let text = money_post(state, auth, "/messages/compose", body, max_msat, Some(charge)).await?;
    let reply: act::SendReply = text.decode("/messages/compose")?;
    if kind == act::KIND_CALL_ANSWER { keep_answered_call(state, &signal_node_id, &target, plaintext, stops); }
    Ok(act::CallReceipt {
        operation_id: reply.operation_id.clone(),
        total_msat: act::with_op(Active(text.operation_id.as_deref()), reply.total_msat())?,
        message_id: reply.message_id,
        kind,
        amount_msat: reply.amount_msat,
        max_routing_fee_msat: reply.max_routing_fee_msat,
        delivered: reply.delivered,
        accepted: reply.accepted,
        sent_at_ms: now_ms(),
    })
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// Local teardown is not evidence that the node has closed its admission.
/// The renderer must name the exact admission, not a reusable wire call id.
async fn do_op_close_call(state: &NodeState, operation_id: &str, peer: &str, call_id: &str) -> Result<(), ActionError> {
    // Local teardown: no new minute of this call is issued. Revoked at once,
    // without the money lock; a minute already issued holds that lock until
    // its outcome is recorded, and teardown is ordered after it.
    if act::is_call_id(call_id) { end_minutes(state, call_id); }
    let _money = state.money.lock().await;
    let journal = locked_spend_journal(state)?;
    let offer = journal.operation_record(operation_id)?
        .ok_or_else(|| ActionError::new("call_not_found", "No outgoing admission is recorded."))?;
    if state.node_id.lock().unwrap().as_deref() != Some(&offer.node_id)
        || offer.peer != peer || offer.call_id.as_deref() != Some(call_id)
        || !matches!(offer.kind.as_str(), "call_offer" | "call_recovery") {
        return Err(ActionError::new("call_not_found", "No outgoing admission is recorded for this identity."));
    }
    // Keep admission and payment fenced until node-confirmed cleanup.
    Ok(())
}

/// End an outgoing admission using host-owned identity and cap. Waiting for the
/// money lock joins any offer/hangup receipt already in flight. Only this call's
/// own unknown send (its offer or one of its minutes) is reconciled; unrelated
/// sends retain their existing fence.
async fn do_op_end_call(state: &NodeState, call_id: &str) -> Result<spend_journal::OpView, ActionError> {
    do_op_end_call_with_limit(state, call_id, None).await
}

/// A priced owner repair can lower, never raise, the admission's saved ceiling.
async fn do_op_end_call_with_limit(state: &NodeState, call_id: &str, max_msat: Option<u64>) -> Result<spend_journal::OpView, ActionError> {
    // The app is ending the call: no new minute is issued for it, whatever
    // becomes of the hangup (a refusal stays the answer). Revoked before the
    // hangup is even prepared, so a minute being prepared finds it ended.
    end_minutes(state, call_id);
    end_call_admission(state, call_id, max_msat).await
}

/// How often, and for how long, End asks the node whether it has ended a call.
/// A live call ends at its paid time plus ten seconds of grace, and a minute buys
/// at most eighty seconds from the moment it is paid.
const END_WAIT_POLL: Duration = if cfg!(test) { Duration::from_millis(10) } else { Duration::from_secs(2) };
const END_WAIT_MAX: Duration = if cfg!(test) { Duration::from_secs(5) } else { Duration::from_secs(100) };

/// The owner's End. A hangup refused before any payment (the callee is offline,
/// say), or one that cannot be sent because a kept call's grant has ended
/// (`HELD_GRANT_ENDED`), cannot reach anyone yet, and no spend is pending for
/// it. The node ends the call by itself when its paid time runs out, so End
/// waits for that, asking
/// the node and holding no lock. The node showing the call ended is the evidence
/// that closes the admission, so End writes that down and asks for nothing more.
/// A further request could only be refused, by the node or by anything that
/// changed meanwhile (a pause, an approval or budget gone), and none of those is a
/// reason to keep a call open that is over. Nothing is sent or paid, and no other
/// pending result is touched. A read that fails, a call still open when the wait
/// runs out (a read in progress included), or another node made active meanwhile
/// (even for a moment) or its connection replaced, leaves the refusal as the
/// answer, and "Try ending it again" stays on the card.
async fn do_op_end_call_when_node_ends(state: &NodeState, call_id: &str, max_msat: Option<u64>) -> Result<spend_journal::OpView, ActionError> {
    let refused = do_op_end_call_with_limit(state, call_id, max_msat).await;
    let Err(error) = &refused else { return refused };
    let offer = match error.code {
        "not_dispatched" => refused_hangup_admission(state, error.operation_id.as_deref()).await,
        // A kept call after its grant ended: its minutes stopped as End began,
        // and the node ends it when its paid time runs out.
        HELD_GRANT_ENDED => refused_end_admission(state, error.operation_id.as_deref()).await,
        _ => None,
    };
    let Some(offer) = offer else { return refused };
    let deadline = tokio::time::Instant::now() + END_WAIT_MAX;
    // Only the call's own node can show it ended, and only over the connection
    // the wait began on. Every read is bound to both and to the deadline: none
    // goes out, is retried or is believed once another node was made active
    // (even if the call's own is active again) or the deadline has come, and the
    // wait ends with the refusal.
    let Some(bound) = NodeBound::now(state, &offer.node_id, Some(deadline)) else { return refused };
    loop {
        match tokio::time::timeout_at(deadline, read_call_status_from(state, Some(&bound), &offer.peer, call_id)).await {
            Ok(Ok(Some(status))) if status.state != "ended" => {}
            Ok(Ok(_)) => break,
            Ok(Err(_)) | Err(_) => return refused,
        }
        if cfg!(test) { pause_points::at(&state.api_base, "end_wait_read").await; }
        tokio::time::sleep_until(deadline.min(tokio::time::Instant::now() + END_WAIT_POLL)).await;
    }
    {
        let _money = state.money.lock().await;
        // Still the node and connection that read the call: another node's word closes nothing.
        if !(NodeBound { until: None, ..bound }).holds(state) { return refused; }
        locked_spend_journal(state)?.observe_call(&offer, true)?;
    }
    do_op_end_call_with_limit(state, call_id, max_msat).await
}

/// The admission End named in its refusal, when no hangup could be sent for it.
async fn refused_end_admission(state: &NodeState, operation_id: Option<&str>) -> Option<spend_journal::OperationRecord> {
    let _money = state.money.lock().await;
    let journal = locked_spend_journal(state).ok()?;
    let offer = journal.operation_record(operation_id?).ok()??;
    matches!(offer.kind.as_str(), "call_offer" | "call_recovery").then_some(offer)
}

/// The admission End's refused hangup belonged to, from the host's own record.
async fn refused_hangup_admission(state: &NodeState, operation_id: Option<&str>) -> Option<spend_journal::OperationRecord> {
    let _money = state.money.lock().await;
    let journal = locked_spend_journal(state).ok()?;
    let hangup = journal.operation_record(operation_id?).ok()??;
    if hangup.kind != "call_hangup" { return None; }
    journal.operation_record(hangup.parent_op.as_deref()?).ok()?
}

/// No new minute of this call is issued, for this node identity. Takes no
/// money lock and waits for nothing, so End, teardown and a hangup can call it
/// the moment they begin. At most one minute already issued may still settle:
/// it holds the money lock until its outcome is recorded, so a hangup goes out
/// after it, as soon as that lock is free. Anything that reaches the node later
/// is refused there, by the call's own state and clock.
fn end_minutes(state: &NodeState, call_id: &str) {
    let node_id = state.node_id.lock().unwrap().clone();
    let Some(node_id) = node_id else { return };
    state.call_consents.lock().unwrap().end(&node_id, None, call_id);
}

async fn end_call_admission(state: &NodeState, call_id: &str, max_msat: Option<u64>) -> Result<spend_journal::OpView, ActionError> {
    let mut operation_id = pending_operation_id(state).unwrap_or_default();
    let result = async {
        if call_id.len() != 32 || !call_id.bytes().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()) {
            return Err(ActionError::invalid("invalid call id"));
        }
        let offer = {
            let _money = state.money.lock().await;
            let journal = locked_spend_journal(state)?;
            let pending = journal.pending()?;
            let node_id = state.node_id.lock().unwrap().clone()
                .ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
            let records = journal.call_operations_for(&node_id, None, Some(call_id))?;
            let calls: Vec<_> = records.iter().filter(|r| r.call_id.as_deref() == Some(call_id)).collect();
            let offer = calls.iter().filter(|r| matches!(r.kind.as_str(), "call_offer" | "call_recovery"))
                .max_by_key(|r| (r.created_ms, &r.op_id)).copied()
                .ok_or_else(|| ActionError::new("call_not_found", "No outgoing admission is recorded for this call."))?;
            operation_id = Some(offer.op_id.clone());
            if calls.iter().any(|r| r.peer != offer.peer) {
                return Err(spend_journal::unknown("This call id names more than one peer."));
            }
            if let Some(hangup) = calls.iter().find(|r| spend_journal::hangup_for(r, offer) && spend_journal::hangup_blocks(r)) {
                return Ok((**hangup).clone().into());
            }
            if !spend_journal::admission_open(offer, &records) { return Ok(offer.clone().into()); }
            // This call's own send whose receipt was lost: its offer, or one of
            // its minutes, which would otherwise fence the hangup.
            let own = pending.filter(|p| !p.resumable).and_then(|p| {
                let id = p.operation_id.clone()?;
                (id == offer.op_id || calls.iter().any(|r| r.op_id == id && r.kind == "call_block")).then_some((p, id))
            });
            if let Some((p, id)) = own {
                // Checked by exact operation id, never replaced or guessed
                // unpaid just because a request timed out.
                match reconcile_operation(state, &journal, p, &id).await {
                    Ok(_) => {}
                    Err(error) if error.code == "failed_paid" => {
                        // Reconciliation accounted this terminal payment and
                        // cleared its slot; the admission still needs cleanup.
                        if journal.pending()?.is_some() || journal.operation_record(&id)?
                            .is_none_or(|r| r.state != spend_journal::OperationState::FailedPaid) {
                            return Err(error);
                        }
                    }
                    Err(error) if error.code == "undelivered_pending" => {
                        let p = journal.pending()?.ok_or_else(|| spend_journal::unknown("Missing paid call operation."))?;
                        if p.operation_id.as_deref() != Some(&id) || p.over_budget
                            || p.evidence_reservation_msat.is_some() || p.accounting_msat.is_none()
                            || p.undelivered.as_ref().is_none_or(|u| u.in_flight) {
                            return Err(error);
                        }
                        // End cancels further app delivery retries of this
                        // send. Preserve its paid evidence and admission fence;
                        // only retire the fully accounted dispatch slot so the
                        // single, parent-bound hangup can be sent.
                        close_charge(state, p.charge_id(), p.accounting_msat, p.target.as_ref())?;
                        journal.record_outcome(&p, spend_journal::OperationState::PaidUndelivered, None)?;
                        journal.clear()?;
                    }
                    Err(error) => return Err(error),
                }
            }
            let offer = journal.operation_record(&offer.op_id)?.ok_or_else(|| spend_journal::unknown("Missing call offer."))?;
            if !spend_journal::admission_open(&offer, &records) { return Ok(offer.into()); }
            offer
        };
        let cap = match offer.hangup_cap_msat {
            Some(cap) => cap,
            // H1 predates the saved signal cap. Its explicit offer cap remains
            // an upper bound; the normal call path checks today's signal quote.
            None => offer.cap_msat,
        };
        let cap = max_msat.map_or(cap, |limit| cap.min(limit));
        let payload = serde_json::json!({"v": 1, "call_id": call_id, "reason": "hangup"}).to_string();
        let id = match do_call_signal_for_admission(state, &offer.peer, act::KIND_CALL_HANGUP, &payload, cap, Some(&offer)).await {
            Ok(receipt) => receipt.operation_id.ok_or_else(|| spend_journal::unknown("The node did not identify the hangup operation."))?,
            Err(error) if matches!(error.code, "hangup_in_flight" | "call_not_live" | "call_not_found") => {
                error.operation_id.ok_or_else(|| spend_journal::unknown("The hangup operation has no identity."))?
            }
            // No hangup can be priced, so this never reached the node, which is how
            // End learns a call is over. Ask it: a call it has ended needs no hangup.
            Err(error) if error.code == "call_price_unknown" => {
                let Some(bound) = NodeBound::now(state, &offer.node_id, None) else { return Err(error) };
                let over = read_call_status_from(state, Some(&bound), &offer.peer, call_id).await.is_ok_and(|status| status.is_none_or(|s| s.state == "ended"));
                let _money = state.money.lock().await;
                // The call's own node, and the same one throughout since the read.
                if !over || !bound.holds(state) { return Err(error); }
                let journal = locked_spend_journal(state)?;
                journal.observe_call(&offer, true)?;
                return journal.operation_record(&offer.op_id)?.map(Into::into)
                    .ok_or_else(|| spend_journal::unknown("Missing call offer."));
            }
            Err(error) => return Err(error),
        };
        operation_id = Some(id.clone());
        let _money = state.money.lock().await;
        locked_spend_journal(state)?.operation_record(&id)?.map(Into::into)
            .ok_or_else(|| spend_journal::unknown("Missing hangup operation."))
    }.await;
    act::with_op(Fallback(operation_id.as_deref()), result)
}

// ---- porch reads (genome BROWSE.md, `porch_read_v1`) ------------------------------
//
// One paid read of a contact's card or a page, through the node's
// `/browse/fetch`. Same authority as a 1:1 message (the budget or the window),
// one journaled spend at a time, and never a retry: reading again pays again.

/// Free availability and recipient price for this path. Only nodes without
/// `porch_quote_v1` use the legacy read-capability and price-table checks.
async fn read_porch_quote(state: &NodeState, peer: &str, path: &str) -> Result<act::PaymentQuote, ActionError> {
    let peer = control::node_id(peer).map_err(ActionError::invalid)?;
    let path = porch::porch_path(path)?;
    // Only the dedicated quote capability selects the new protocol. A failed
    // quote never falls back to cached/own prices or a legacy paid read.
    let status: serde_json::Value = get_json(state, "/status").await.map_err(ActionError::node)?;
    let offers = |cap: &str| status["api_capabilities"].as_array()
        .is_some_and(|caps| caps.iter().any(|v| v.as_str() == Some(cap)));
    if offers(porch::QUOTE_CAPABILITY) {
        let (status, text) = call_api(state, reqwest::Method::POST, porch::QUOTE_ROUTE,
            Some(serde_json::json!({"node_id": peer, "path": path}))).await.map_err(ActionError::node)?;
        if !status.is_success() {
            if matches!(status.as_u16(), 403 | 409)
                && serde_json::from_str::<serde_json::Value>(&text).ok()
                    .is_some_and(|v| v["reason"] == "admission_required") {
                return Err(porch::refused("porch_knock_first"));
            }
            if act::readmission_capped_refusal(status.as_u16(), &text) {
                return Err(porch::refused("porch_readmission"));
            }
            if let Some(porch::Answer::Refused(error)) = porch::answer(status.as_u16(), &text) {
                return Err(error);
            }
            return Err(ActionError::node(api_error(porch::QUOTE_ROUTE, status, &text)));
        }
        return porch::quote(&text, &peer, &path);
    }
    if !offers(porch::CAPABILITY) {
        return Err(ActionError::new("porch_unavailable",
            "Your node cannot read porches yet. Update it to read contacts’ cards and pages. Nothing was paid."));
    }
    let peers: Vec<control::Peer> = get_json(state, "/peers").await.map_err(ActionError::node)?;
    match control::with_porch_support(peers).into_iter().find(|p| p.node_id.eq_ignore_ascii_case(&peer)) {
        Some(p) if p.porch => {}
        Some(p) if p.connected => return Err(porch::refused("porch_unsupported")),
        _ => return Err(porch::refused("porch_unreachable")),
    }
    let own: control::KindPrice = get_json(state, &control::price_path(porch::KIND_PAGE_REQUEST)).await.map_err(ActionError::node)?;
    let tables: Vec<control::PeerPrice> = get_json(state, "/pricing/peers").await.map_err(ActionError::node)?;
    let table = tables.iter().find(|t| t.peer_id.eq_ignore_ascii_case(&peer));
    act::payment_quote(porch::read_price(table, own.price_msat))
}

async fn do_porch_read(state: &NodeState, peer: &str, path: &str, max_msat: u64) -> Result<porch::PorchRead, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let target = control::node_id(peer).map_err(ActionError::invalid)?;
    let path = porch::porch_path(path)?;
    let (auth, plan) = plan_message(state, &target, false, max_msat, None)
        .map_err(|e| if e.code == "first_contact" { porch::refused("porch_needs_contact") } else { e })?;
    if plan.confirm.is_some() {
        return Err(porch::refused("porch_needs_contact"));
    }
    no_pending_spend(state)?;
    let quote = read_porch_quote(state, &target, &path).await?;
    ceiling(quote.total_msat, max_msat)?;
    let body = porch::fetch_body(&target, &path, max_msat, quote.max_routing_fee_msat);
    let charge = Charge {
        target: target.clone(),
        room: false,
        confirm: None,
        readmission_possible: false,
        confirmed: false,
        operation: false,
        envelope_ids: None,
        failure_final_on: None,
        call_window: false,
    };
    let (text, accounted) = porch_post(state, auth, body, max_msat, charge).await?;
    porch::project(&text, &target, &path, accounted, now_unix().max(0) as u64).map_err(|e| {
        ActionError::new("porch_reply_invalid", format!("Paid {}, but the answer could not be shown: {e}.", porch::amount(accounted)))
    })
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// `money_post` for a read: its reply is a page, not a send receipt. A refusal
/// the node proves came before paying releases everything; a paid read with
/// no usable reply is known money, accounted and not retried; any other
/// failure keeps the journal fenced as an unknown outcome. Returns the reply
/// and what it counts against the budget (the all-in ceiling: the node
/// reports no routing fee for a read).
async fn porch_post(state: &NodeState, auth: Auth, body: serde_json::Value, max_msat: u64, charge: Charge) -> Result<(String, u64), ActionError> {
    let mut existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let _money = state.money.lock().await;
    // The quote and lock wait may have let another command publish a pending ID.
    existing_operation = pending_operation_id(state).unwrap_or_else(|_| existing_operation.clone());
    refuse_if_connection_waiting(state)?;
    let journal = locked_spend_journal(state)?;
    let prior = journal.pending()?;
    existing_operation = prior.as_ref().and_then(|p| p.operation_id.clone());
    ensure_fresh_token(state).await;
    let token = state.ordinary_token().map_err(|e| ActionError::new("app_not_ready", &e))?
        .ok_or_else(|| ActionError::new("app_not_ready", "Not authenticated."))?;
    let node_id = state.node_id.lock().unwrap().clone().ok_or_else(|| ActionError::new("app_not_ready", "No node identity."))?;
    match &prior {
        None => {}
        Some(p) if p.resumable && p.node_id == node_id => {}
        _ => return Err(spend_journal::unknown("Check the pending result before sending again.")),
    }
    let abandon = |journal: &Journal| -> Result<(), ActionError> {
        // Tests only: this step can be made to fail (`fault_points`).
        #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_abandon")?;
        match &prior {
            Some(p) => journal.save(p),
            None => journal.clear(),
        }
    };
    refuse_if_paused(state)?;
    check_auth(state, auth)?;
    check_node_grant(state, porch::ROUTE, &body, max_msat).await?;
    let mut pending = journal.begin(&node_id, porch::ROUTE, &body, max_msat)?;
    pending.all_in = true;
    let charge_id = pending.charge_id().to_string();
    if let Err(e) = reserve(state, auth, &charge, &charge_id, max_msat) {
        abandon(&journal)?;
        return Err(e);
    }
    pending.budgeted = true;
    journal.save(&pending)?;
    let release = |state: &NodeState| -> Result<(), ActionError> {
        // Tests only: this step can be made to fail (`fault_points`).
        #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_release")?;
        release_own_reservation(state, &charge_id)
    };
    // Proven unpaid: save the decision, release, then clear (see `money_post_with`).
    let unpaid_cleanup = |state: &NodeState, journal: &Journal, pending: &spend_journal::Pending| -> Result<(), ActionError> {
        let mut decided = pending.clone();
        decided.unpaid_release = Some(spend_journal::UnpaidRelease {
            outcome: spend_journal::OperationState::Unpaid,
            restore: prior.clone().map(Box::new),
        });
        let save = || -> Result<(), ActionError> {
            // Tests only: this step can be made to fail (`fault_points`).
            #[cfg(all(test, desktop, not(feature = "mobile")))] fault_points::check(&state.api_base, "unpaid_decision")?;
            journal.save(&decided)
        };
        save()?;
        release(state)?;
        abandon(journal)
    };
    if let Err(e) = refuse_if_connection_waiting(state)
        .and_then(|()| refuse_if_paused(state))
        .and_then(|()| check_auth(state, auth)) {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(e);
    }
    let response = state.http.post(format!("{}{}", state.api_base, porch::ROUTE))
        .bearer_auth(token).json(&body).timeout(state.spend_timeout).send().await
        .map_err(|_| spend_journal::unknown("The node did not return a complete response."))?;
    let status = response.status();
    if status == reqwest::StatusCode::FORBIDDEN || status == reqwest::StatusCode::UNAUTHORIZED {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(refuse_spend(state));
    }
    let text = response.text().await.map_err(|_| spend_journal::unknown("The response was interrupted."))?;
    let code = status.as_u16();
    let nothing_paid = if act::readiness_refusal(code, &text) {
        Some(act::readiness_error(code, &text))
    } else if act::not_dispatched_refusal(code, &text) {
        Some(ActionError::new("not_dispatched", act::not_dispatched_message(&text)))
    } else if let Some(refusal) = grant::refusal(code, &text) {
        let known = state.node_grant.lock().unwrap().clone();
        if refusal.ends_grant() { drop_grant(state); }
        Some(refusal.error(known.as_ref()))
    } else if act::readmission_capped_refusal(code, &text) {
        Some(porch::refused("porch_readmission"))
    } else if status == reqwest::StatusCode::CONFLICT
        && serde_json::from_str::<serde_json::Value>(&text).ok().is_some_and(|v| v["code"] == "price_cap_exceeded") {
        Some(ActionError::new("price_cap_exceeded", "The node refused the changed price before any payment. Refresh the quote."))
    } else {
        match porch::answer(code, &text) {
            Some(porch::Answer::Refused(e)) => Some(e),
            Some(porch::Answer::Paid { paid_msat, error }) => {
                if paid_msat > max_msat {
                    pending.over_budget = true;
                    journal.save(&pending)?;
                    return Err(spend_journal::unknown(format!("The node reports {paid_msat} msat paid, beyond the confirmed ceiling ({max_msat}). Funds may already have moved; do not retry.")));
                }
                pending.accounting_msat = Some(max_msat);
                pending.paid = Some(budget::Paid { msat: paid_msat, fee_unknown: true });
                journal.save(&pending)?;
                close_charge(state, &charge_id, Some(max_msat), None)?;
                journal.clear()?;
                return Err(error);
            }
            None => None,
        }
    };
    if let Some(e) = nothing_paid {
        unpaid_cleanup(state, &journal, &pending)?;
        return Err(e);
    }
    if !status.is_success() {
        return Err(spend_journal::unknown(api_error(porch::ROUTE, status, &text)));
    }
    let principal = porch::principal(&text).ok_or_else(|| spend_journal::unknown(format!("{} decode failed.", porch::ROUTE)))?;
    if principal > max_msat {
        pending.over_budget = true;
        journal.save(&pending)?;
        return Err(spend_journal::unknown(format!("The node reports {principal} msat for this read, beyond the confirmed ceiling ({max_msat}). Funds may already have moved; do not retry.")));
    }
    pending.accounting_msat = Some(max_msat);
    pending.paid = Some(budget::Paid { msat: principal, fee_unknown: true });
    journal.save(&pending)?;
    close_charge(state, &charge_id, Some(max_msat), None)?;
    journal.clear()?;
    Ok((text, max_msat))
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

async fn read_porch_cards(state: &NodeState) -> Result<Vec<porch::PorchCard>, String> {
    let status: serde_json::Value = get_json(state, "/status").await?;
    if !status["api_capabilities"].as_array().is_some_and(|caps| caps.iter()
        .any(|v| v.as_str() == Some(porch::QUOTE_CAPABILITY) || v.as_str() == Some(porch::CAPABILITY))) {
        return Ok(Vec::new());
    }
    let (status, text) = call_api(state, reqwest::Method::GET, porch::CARDS_ROUTE, None).await?;
    if !status.is_success() {
        return Err(api_error(porch::CARDS_ROUTE, status, &text));
    }
    porch::cached_cards(&text, now_unix().max(0) as u64)
}

async fn do_file_send(
    state: &NodeState,
    recipient: &str,
    filename: &str,
    mime_type: &str,
    data_b64: &str,
    max_msat: u64,
    first_contact_msat: Option<u64>,
) -> Result<act::FileReceipt, ActionError> {
    let existing_operation = pending_operation_id(state).unwrap_or_default();
    let result = async {
    let recipient = control::node_id(recipient).map_err(ActionError::invalid)?;
    // Same budget / ten-minute window rules as a 1:1 message. Genome's file
    // send has no `operation_id` field (`deny_unknown_fields`), so we keep
    // `operation: false`; the spend journal still fences concurrent money posts.
    let (auth, plan) = plan_message(state, &recipient, false, max_msat, first_contact_msat)?;
    no_pending_spend(state)?;
    let caps = require_price_caps(state, false).await?;
    // The button promises "up to" this total. An older node may pay admission on
    // top of a cap, so no file goes through one, as for a conversation's message.
    require_conversation_ceiling(state, &recipient, &caps).await?;
    let body = act::file_upload_body(filename, mime_type, data_b64)?;
    let filename = body["filename"].as_str().unwrap_or_default().to_string();
    let quote: control::KindPrice = get_json(state, &control::price_path(act::KIND_FILE_REF)).await?;
    ceiling(act::payment_quote(quote.price_msat.max(act::MIN_PAYMENT_MSAT))?.total_msat, max_msat)?;
    let text = gated_post_auth(state, auth, "/files", body).await?;
    let upload: act::UploadReply = decode_act("/files", &text)?;
    let path = act::file_send_path(&upload.file_id)?;
    // Upload can take time; quote again immediately before the money request.
    let quote: control::KindPrice = get_json(state, &control::price_path(act::KIND_FILE_REF)).await?;
    let principal = quote.price_msat.max(act::MIN_PAYMENT_MSAT);
    ceiling(act::payment_quote(principal)?.total_msat, max_msat)?;
    let node_ok = plan.confirm.or(first_contact_msat);
    if let Some(contact_budget) = node_ok {
        confirm_first_contact(state, &recipient, max_msat, contact_budget, caps.readmission_possible).await?;
    }
    let charge = Charge {
        target: recipient.clone(),
        room: false,
        confirm: plan.confirm,
        readmission_possible: caps.readmission_possible,
        confirmed: node_ok.is_some(),
        operation: false,
        envelope_ids: Some(caps.envelope_ids),
        failure_final_on: None,
        call_window: false,
    };
    let text = money_post(
        state,
        auth,
        &path,
        serde_json::json!({
            "recipient": recipient,
            "max_total_msat": max_msat,
            "max_routing_fee_msat": act::routing_fee(principal),
        }),
        max_msat,
        Some(charge),
    )
    .await?;
    let reply: act::SendReply = text.decode("/files/send")?;
    let total_msat = act::with_op(Active(text.operation_id.as_deref()), reply.total_msat())?;
    Ok(act::FileReceipt {
        readmission_msat: reply.readmission_msat,
        fee_paid_msat: reply.fee_paid_msat,
        total_msat,
        message_id: reply.message_id,
        recipient,
        filename,
        size_bytes: upload.size_bytes,
        delivered: reply.delivered,
        amount_msat: reply.amount_msat,
        max_routing_fee_msat: reply.max_routing_fee_msat,
        sent_at_ms: now_ms(),
        operation_id: reply.operation_id,
        state: reply.state,
        accepted: reply.accepted,
    })
    }.await;
    act::with_op(Fallback(existing_operation.as_deref()), result)
}

/// A pairing link was just imported: the next signed-in spend poll asks the
/// node once for the day's budget (`ask_budget_after_pairing`).
fn pairing_imported(state: &NodeState) {
    state.budget_after_pairing.store(true, Ordering::SeqCst);
}

const BUDGET_ASK_FILE: &str = "budget-ask-after-pairing";

fn budget_ask_path(app_data_dir: &Path) -> PathBuf {
    app_data_dir.join(BUDGET_ASK_FILE)
}

/// A link was imported and is used now: the ask is due in this run and, until
/// it is sent, in every later start too (the app may quit first).
fn pairing_imported_at(state: &NodeState, app_data_dir: &Path) {
    save_budget_ask(app_data_dir);
    *state.budget_ask_marker.lock().unwrap() = Some(budget_ask_path(app_data_dir));
    pairing_imported(state);
}

/// The ask waits in a file until it is sent. It holds no secret, only that
/// the ask is due. Desktop Import writes it for the next start.
fn save_budget_ask(app_data_dir: &Path) {
    if let Err(error) = std::fs::write(budget_ask_path(app_data_dir), b"1\n") {
        eprintln!("[spend] could not keep the budget ask for the next start: {error}");
    }
}

/// Startup with a saved link: an ask the import left for this start is due.
fn restore_budget_ask(state: &NodeState, app_data_dir: &Path) {
    let path = budget_ask_path(app_data_dir);
    if path.is_file() {
        *state.budget_ask_marker.lock().unwrap() = Some(path);
        pairing_imported(state);
    }
}

fn remove_budget_ask(path: &Path) -> std::io::Result<()> {
    match std::fs::remove_file(path) {
        Err(error) if error.kind() != std::io::ErrorKind::NotFound => Err(error),
        _ => Ok(()),
    }
}

/// The ask is sent now, or not needed: never again for this link. Its file
/// goes first: if it cannot be removed, nothing is sent and the ask stays, so
/// a later start can never repeat a request whose result was unclear.
fn budget_ask_done(state: &NodeState) -> Result<(), ActionError> {
    let path = state.budget_ask_marker.lock().unwrap().clone();
    if let Some(path) = path {
        remove_budget_ask(&path).map_err(|error| {
            eprintln!("[spend] could not clear the budget ask: {error}");
            ActionError::new("app_not_ready", "The app could not update its own files. Nothing was sent.")
        })?;
        *state.budget_ask_marker.lock().unwrap() = None;
    }
    state.budget_after_pairing.store(false, Ordering::SeqCst);
    Ok(())
}

/// One owner step up front: right after pairing, ask the node for the day's
/// budget so its owner can say yes before the first call, not at Accept or
/// Ring. Only asks (never obtains), only once per imported link, and only for
/// a signed-in pairing without spending and without a request already waiting.
/// It records no wants: a yes at the box opens nothing in the app until the
/// owner taps here. Waits, without losing the ask, while not signed in yet and
/// after any read that fails before the request: the next poll tries again.
/// The ask is spent just before its POST, so an unclear POST is never repeated.
async fn ask_budget_after_pairing(state: &NodeState) -> Result<(), ActionError> {
    if !state.budget_after_pairing.load(Ordering::SeqCst) {
        return Ok(());
    }
    if !matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(_)) {
        return Ok(());
    }
    if budget_paused(state)? {
        return budget_ask_done(state);
    }
    // A saved request from an earlier run is followed, not repeated. This read
    // may also refresh the session, so its scopes are read only after it.
    if !state.approvals_restored.load(Ordering::SeqCst) {
        do_budget_status(state).await?;
    }
    let has_spend = match &*state.auth.lock().unwrap() {
        AuthMode::Paired(session) => session.scopes.iter().any(|s| s == "spend"),
        _ => return Ok(()),
    };
    if has_spend {
        return budget_ask_done(state);
    }
    restore_spend_pending(state);
    // One request at a time, shared with every explicit ask. Busy: the next poll tries again.
    let Ok(_create) = state.elevation_create.try_lock() else { return Ok(()) };
    if !state.budget_after_pairing.load(Ordering::SeqCst) {
        return Ok(());
    }
    let generation = {
        let gate = state.spend.lock().unwrap();
        if gate.pending().is_some_and(|p| p.expires_at_ms > now_ms()) {
            drop(gate);
            return budget_ask_done(state);
        }
        gate.generation()
    };
    // Pre-G1 nodes keep their old ask-at-use path.
    if !node_has_g1(state).await? {
        return budget_ask_done(state);
    }
    // The whole request is ready before the ask is spent: a failed read keeps it.
    let budget = budget_proposal(state, Want::Window, None)
        .ok_or_else(|| ActionError::new("app_not_ready", "The day’s budget could not be read yet. Nothing was sent."))?;
    let ask = serde_json::json!({ "scopes": ["spend"], "budget": budget });
    // Spent just before the POST: an unclear POST is never repeated.
    budget_ask_done(state)?;
    dispatch_elevation_request(state, ask, None, generation).await?;
    save_spend_pending(state);
    Ok(())
}

/// `spend_status`: the pairing's first budget ask, then the usual poll.
async fn spend_status_now(state: &NodeState) -> Result<act::SpendView, ActionError> {
    if let Err(error) = ask_budget_after_pairing(state).await {
        eprintln!("[spend] could not ask for the budget after pairing: {}", error.message);
    }
    spend_advance(state, false).await
}

/// The owner's spend window as it stands; polls a pending elevation request.
#[tauri::command(rename_all = "snake_case")]
async fn spend_status(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
) -> Result<act::SpendView, ActionError> {
    reject_sealed_window(&window)?;
    drop(window);
    spend_status_now(state.inner()).await
}

/// The owner's one tap: open a short spend window, or ask the node for spend.
#[tauri::command(rename_all = "snake_case")]
async fn spend_request(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    budget_msat: Option<u64>,
    call_peer: Option<String>,
) -> Result<act::SpendView, ActionError> {
    reject_sealed_window(&window)?;
    drop(window);
    do_spend_request(state.inner(), budget_msat, call_peer.as_deref()).await
}

/// Close the spend window now.
#[tauri::command(rename_all = "snake_case")]
async fn spend_lock(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
) -> Result<act::SpendView, ActionError> {
    reject_sealed_window(&window)?;
    drop(window);
    Ok(do_spend_lock(state.inner()))
}

fn do_spend_lock(state: &NodeState) -> act::SpendView {
    // The owner's lock also stops a live call's held minutes.
    stop_spending(state);
    let view = {
        let mut gate = state.spend.lock().unwrap();
        gate.lock();
        // The lock also ends a pending request, and with it anything it would have opened.
        *state.wants.lock().unwrap() = Wants::default();
        gate.view(now_ms())
    };
    save_spend_pending(state);
    view
}

/// Withdraw the pending request at the node, then forget it here.
#[tauri::command(rename_all = "snake_case")]
async fn spend_cancel(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
) -> Result<act::SpendView, ActionError> {
    reject_sealed_window(&window)?;
    drop(window);
    do_spend_cancel(state.inner()).await
}

async fn do_spend_cancel(state: &NodeState) -> Result<act::SpendView, ActionError> {
    let (pending, generation) = {
        let gate = state.spend.lock().unwrap();
        (gate.pending().cloned(), gate.generation())
    };
    if let Some(p) = &pending {
        if let Ok(path) = act::elevation_status_path(&p.op_id) {
            withdraw_at_node(state, &path).await?;
        }
    }
    let view = {
        let mut gate = state.spend.lock().unwrap();
        if pending.is_some() && gate.generation() == generation && gate.pending() == pending.as_ref() {
            gate.clear_pending();
        } else {
            stop_spending(state);
            gate.lock();
        }
        *state.wants.lock().unwrap() = Wants::default();
        gate.view(now_ms())
    };
    save_spend_pending(state);
    Ok(view)
}

/// DELETE a pending request at the node. Gone already (404) is withdrawn; any
/// other failure is reported, and the request is kept, never claimed cancelled.
async fn withdraw_at_node(state: &NodeState, path: &str) -> Result<(), ActionError> {
    let (status, body) = call_api(state, reqwest::Method::DELETE, path, None)
        .await
        .map_err(|e| ActionError::node(format!("Could not reach your node to cancel the request; it may still be approved there. {e}")))?;
    if status.is_success() || status == reqwest::StatusCode::NOT_FOUND {
        return Ok(());
    }
    Err(ActionError::node(format!(
        "Your node did not cancel the request; it may still be approved there. {}",
        api_error(path, status, &body)
    )))
}

// ---- this Mac as a paired device (relation ladder steps 1–2) -------------------

fn device_store(state: &NodeState) -> Result<PathBuf, ActionError> {
    state
        .pairing
        .lock()
        .unwrap()
        .as_ref()
        .map(|ctx| ctx.store.clone())
        .ok_or_else(|| ActionError::new("app_not_ready", "This app is not paired with a node."))
}

/// Whether this Mac can approve with a device key. Test keys need no Touch
/// ID, so tests only need the enclave.
fn device_available(state: &NodeState) -> bool {
    match *state.device_policy.lock().unwrap() {
        device_key::Policy::NoPromptForTests => device_key::enclave_available(),
        device_key::Policy::Biometry => device_key::available(),
    }
}

#[cfg(target_os = "android")]
fn device_error(e: device_key::DeviceKeyError) -> ActionError {
    match e {
        device_key::DeviceKeyError::Cancelled => ActionError::new("device_cancelled", "Biometric approval was cancelled. Nothing was approved."),
        device_key::DeviceKeyError::Unavailable => ActionError::new("device_unavailable", "This phone has no hardware-backed Android Keystore key the app can use. Approve on your box instead."),
        device_key::DeviceKeyError::BiometryUnavailable => ActionError::new("device_biometry", "Strong biometric approval is not available on this phone right now (none enrolled, unavailable, or locked out). Nothing was approved. Ask the person who set up your box to approve it there instead."),
        device_key::DeviceKeyError::Invalid => ActionError::new("device_invalid", "This phone's approval key no longer works (for example, biometric enrollment changed). Set up biometric approvals again."),
        device_key::DeviceKeyError::Other(code) => ActionError::new("device_key", format!("Android Keystore refused ({code}). Nothing was approved.")),
    }
}

#[cfg(not(target_os = "android"))]
fn device_error(e: device_key::DeviceKeyError) -> ActionError {
    match e {
        device_key::DeviceKeyError::Cancelled => ActionError::new("device_cancelled", "Biometric approval (Touch ID or Face ID) was cancelled. Nothing was approved."),
        device_key::DeviceKeyError::Unavailable => ActionError::new("device_unavailable", "This device has no Secure Enclave the app can use. Approve on your box instead."),
        device_key::DeviceKeyError::BiometryUnavailable => ActionError::new("device_biometry", "Touch ID or Face ID is not available on this device right now (not enrolled, or locked out after failed tries). Nothing was approved. Ask the person who set up your box to approve it there instead."),
        device_key::DeviceKeyError::Invalid => ActionError::new("device_invalid", "This device's approval key no longer works (for example, the enrolled fingerprints or face changed). Set up biometric approvals again."),
        device_key::DeviceKeyError::Other(code) => ActionError::new("device_key", format!("The Secure Enclave refused ({code}). Nothing was approved.")),
    }
}

/// Only explicit key invalidation permits deleting the stored approval key.
/// Bridge/transport failures leave the key and its enrollment available to retry.
fn forget_invalid_signing_key(store: &std::path::Path, error: &ActionError) -> bool {
    if error.code != "device_invalid" { return false; }
    device::forget(store);
    true
}

#[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
#[derive(Clone)]
struct DeviceSigningKey {
    directory: PathBuf,
    public: [u8; device_key::PUBLIC_KEY_LEN],
}
#[cfg(not(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile"))))))]
type DeviceSigningKey = Vec<u8>;

fn device_signing_key(store: &Path, record: &device::Record, blob: Vec<u8>) -> Result<DeviceSigningKey, ActionError> {
    #[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
    {
        let _ = blob;
        let public = hex::decode(&record.public_key).ok().and_then(|v| v.try_into().ok())
            .ok_or_else(|| ActionError::new("device_key", "Invalid device public key record."))?;
        Ok(DeviceSigningKey { directory: store.to_path_buf(), public })
    }
    #[cfg(not(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile"))))))]
    { let _ = (store, record); Ok(blob) }
}

// Apple password storage has its own wrapping key and uses no device blob.
fn password_device_blob(key: DeviceSigningKey) -> Vec<u8> {
    #[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
    { let _ = key; Vec::new() }
    #[cfg(not(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile"))))))]
    { key }
}

/// Protected storage reads and the enclave signature share one operation on
/// the blocking pool. Polls hold only public metadata, never this context.
async fn device_sign(blob: DeviceSigningKey, message: String, reason: String) -> Result<String, ActionError> {
    tokio::task::spawn_blocking(move || {
        #[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
        { sign_stored(&blob, message.as_bytes(), &reason) }
        #[cfg(not(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile"))))))]
        { device_key::sign(&blob, message.as_bytes(), &reason).map_err(device_error) }
    })
        .await
        .map_err(|_| ActionError::new("device_key", "The biometric request stopped unexpectedly."))?
        .map(hex::encode)
}

#[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
fn sign_stored(key: &DeviceSigningKey, message: &[u8], reason: &str) -> Result<Vec<u8>, ActionError> {
    sign_stored_with(key, message, reason, None)
}

#[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
fn sign_stored_with(key: &DeviceSigningKey, message: &[u8], reason: &str, setup: Option<bool>) -> Result<Vec<u8>, ActionError> {
    let context = bitsov_ffi::client_keychain::AuthenticationContext::new_for_operation(reason, setup == Some(true))
        .map_err(|e| ActionError::new("device_key", e))?;
    stored_signing_operation(&key.directory,
        || crate::apple_key_material::read_for_signing(&key.directory, &context),
        |blob| context.sign(blob, &key.public, message, reason, setup))
}

#[cfg(any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")), all(test, unix)))]
fn stored_signing_operation(
    directory: &Path,
    read: impl FnOnce() -> Result<Option<zeroize::Zeroizing<Vec<u8>>>, crate::apple_key_material::ReadError>,
    sign: impl FnOnce(&[u8]) -> Result<Vec<u8>, device_key::DeviceKeyError>,
) -> Result<Vec<u8>, ActionError> {
    let result = (|| {
        let blob = read().map_err(|error| match error {
            crate::apple_key_material::ReadError::Cancelled => device_error(device_key::DeviceKeyError::Cancelled),
            crate::apple_key_material::ReadError::Storage(message) => ActionError::new("device_key", message),
        })?
            .ok_or_else(|| device_error(device_key::DeviceKeyError::Invalid))?;
        sign(&blob).map_err(device_error)
    })();
    if let Err(error) = &result { forget_invalid_signing_key(directory, error); }
    result
}

/// The node identity and pairing a device signs into every message, as the
/// node itself states them (`GET /pair/device-keys`).
#[derive(Deserialize)]
struct DeviceBinding {
    #[serde(default)]
    owner_device_count: Option<u64>,
    node: String,
    client_id: String,
    #[serde(default)]
    device_keys: Vec<RegisteredKey>,
    /// "enabled", or why the node has device approvals off. Absent on nodes
    /// before the node-wide gate.
    #[serde(default)]
    device_approvals: Option<String>,
}

#[derive(Deserialize)]
struct RegisteredKey {
    key_id: String,
}

async fn device_binding(state: &NodeState) -> Result<DeviceBinding, ActionError> {
    let (status, body) = call_api(state, reqwest::Method::GET, "/pair/device-keys", None).await.map_err(ActionError::node)?;
    if status == reqwest::StatusCode::NOT_FOUND {
        return Err(ActionError::new("device_unsupported", "This box version does not take device approvals. Approve on your box instead."));
    }
    if !status.is_success() {
        return Err(ActionError::node(api_error("/pair/device-keys", status, &body)));
    }
    decode_act("/pair/device-keys", &body)
}

fn device_view(state: &NodeState, record: Option<&device::Record>) -> device::DeviceView {
    device::DeviceView::of(device_available(state), record, state.device_lapsed.load(Ordering::SeqCst), now_ms())
}

#[derive(Deserialize)]
struct DeviceKeyReply {
    #[serde(default)]
    delegation_message: Option<String>,
    op_id: String,
    key_id: String,
    fingerprint: String,
    expires_at: i64,
    owner_action: String,
}

/// Read the local key only when its public key agrees with the registration.
/// A bridge/transport failure is retryable, not evidence of invalidation.
fn local_key(state: &NodeState, store: &Path) -> Result<Option<(DeviceSigningKey, device::Record)>, ActionError> {
    device::retry_forget(store)?;
    #[cfg(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile")))))]
    {
        local_device_record(state, store)?.map(|record| {
            device_signing_key(store, &record, Vec::new()).map(|key| (key, record))
        }).transpose()
    }
    #[cfg(not(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile"))))))]
    { local_key_with(state, store, device_key::public_key) }
}

/// All status views use this prompt-free path, including the locked home view.
fn local_device_record(state: &NodeState, store: &Path) -> Result<Option<device::Record>, ActionError> {
    let _guard = state.device_lifecycle.lock().unwrap();
    if !device::material_present(store).map_err(|e| ActionError::new("device_key", e.to_string()))? {
        let _ = std::fs::remove_file(store.join(device::RECORD_FILE));
        return Ok(None);
    }
    match device::load_record(store) {
        Some(record) => Ok(Some(record)),
        None => device::recover_record(store).map(Some),
    }
}

#[cfg(not(all(not(test), any(target_os = "ios", all(target_os = "macos", not(feature = "mobile"))))))]
fn local_key_with(
    state: &NodeState,
    store: &Path,
    public_key: impl FnOnce(&[u8]) -> Result<[u8; device_key::PUBLIC_KEY_LEN], device_key::DeviceKeyError>,
) -> Result<Option<(Vec<u8>, device::Record)>, ActionError> {
    // Keep cleanup in the same critical section as the read, so registration
    // cannot publish a new record between observing absence and removing it.
    let _guard = state.device_lifecycle.lock().unwrap();
    let record = device::load_record(store);
    let blob = match device::read_blob(store) {
        Ok(Some(blob)) => blob,
        Ok(None) => {
            // Only a confirmed missing blob makes the record stale. Never
            // remove a blob here, including one created after the read.
            let _ = std::fs::remove_file(store.join(device::RECORD_FILE));
            return Ok(None);
        }
        Err(error) => return Err(ActionError::new("device_key", format!("Could not access the protected device key: {error}"))),
    };
    match public_key(&blob) {
        Ok(public) if record.as_ref().is_none_or(|record| hex::encode(public) == record.public_key) => {
            let record = match record {
                Some(record) => record,
                None => {
                    // Resume a key published before cancellation or a crash interrupted enrollment.
                    let record = device::Record { public_key: hex::encode(public), ..Default::default() };
                    device::save_record(store, &record)?;
                    record
                }
            };
            Ok(Some((blob, record)))
        },
        Ok(_) | Err(device_key::DeviceKeyError::Invalid) => {
            device::forget(store);
            Ok(None)
        }
        // Propagate transient failures so registration cannot overwrite the key
        // by treating a failed read as a missing enrollment.
        Err(error) => Err(device_error(error)),
    }
}

async fn do_device_key_status(state: &NodeState) -> Result<device::DeviceView, ActionError> {
    let mut view = do_device_key_status_local(state).await?;
    if view.state == device::DeviceState::Registered && add_device::second_completion_pending(state) {
        let _connection = state.remote_recovery.lock().await;
        add_device::complete_second_join(state).await?;
    }
    view.second_device = view.state != device::DeviceState::Registered && add_device::has_second_ticket(state);
    view.delegation_supported = view.second_device || add_device::supported(state).await.unwrap_or(false);
    // Whether the node takes device approvals at all (e.g. not while its
    // recovery phrase is unencrypted). Unreadable → leave the view as is.
    let binding = if view.second_device { None } else { device_binding(state).await.ok() };
    view.owner_device_count = binding.as_ref().and_then(|b| b.owner_device_count);
    Ok(view.with_node_approvals(binding.as_ref().and_then(|b| b.device_approvals.as_deref())))
}

async fn do_device_key_status_local(state: &NodeState) -> Result<device::DeviceView, ActionError> {
    let store = device_store(state)?;
    let Some(record) = local_device_record(state, &store)? else { return Ok(device_view(state, None)) };
    // What this poll found, applied only if the record is still the one polled.
    let before = record.clone();
    let mut updated = record;
    let mut lapsed = None;
    if let Some(p) = updated.pending.clone() {
        let path = format!("/pair/device-key/{}", p.op_id);
        if act::elevation_status_path(&p.op_id).is_err() {
            updated.pending = None;
        } else if let Ok((code, body)) = call_api(state, reqwest::Method::GET, &path, None).await {
            if code.is_success() {
                let reply: act::ElevationStatusReply = decode_act("/pair/device-key", &body)?;
                if let Some(pending) = updated.pending.as_mut() {
                    if reply.delegation_message.is_some() {
                        pending.delegation_message = reply.delegation_message;
                    }
                }
                lapsed = apply_device_status(&mut updated, &reply.status);
            }
        }
    } else if updated.registered {
        // The owner may have revoked it at the node.
        if let (Ok(binding), Some(key_id)) = (device_binding(state).await, updated.key_id.clone()) {
            if !binding.device_keys.iter().any(|k| k.key_id == key_id) {
                updated.registered = false;
            }
        }
    }
    if updated == before {
        return Ok(device_view(state, Some(&updated)));
    }
    match save_device_record_if(state, &store, &before, &updated, lapsed)? {
        None => Ok(device_view(state, Some(&updated))),
        // A Cancel or a new Set up landed while this poll waited: its reply is
        // about a request that is no longer this Mac's. Drop it.
        Some(current) => Ok(device_view(state, current.as_ref())),
    }
}

/// A registration's node status applied to the record; returns the new
/// "lapsed" flag when the status changes it.
fn apply_device_status(record: &mut device::Record, status: &str) -> Option<bool> {
    match status {
        "registered" => {
            record.registered = true;
            record.pending = None;
            Some(false)
        }
        "expired" | "lost" | "absent" => {
            record.pending = None;
            Some(true)
        }
        _ => None,
    }
}

/// Save `updated` only if the record on disk is still `before`, with the
/// compare and the save under the device-lifecycle lock that register and
/// cancel also hold. `None` when saved, else the record now on disk.
fn save_device_record_if(
    state: &NodeState,
    store: &Path,
    before: &device::Record,
    updated: &device::Record,
    lapsed: Option<bool>,
) -> Result<Option<Option<device::Record>>, ActionError> {
    let _guard = state.device_lifecycle.lock().unwrap();
    let current = device::load_record(store);
    if current.as_ref() != Some(before) {
        return Ok(Some(current));
    }
    device::save_record(store, updated)?;
    if let Some(lapsed) = lapsed {
        state.device_lapsed.store(lapsed, Ordering::SeqCst);
    }
    Ok(None)
}

fn allow_device_change(state: &NodeState) -> Result<(), ActionError> {
    #[cfg(all(desktop, not(feature = "mobile")))]
    {
        local_owner::allow_legacy_device_change(state)
    }
    #[cfg(any(mobile, feature = "mobile"))]
    {
        let _ = state;
        Ok(())
    }
}

/// Set up Touch ID approvals: create the enclave key (once), prove it to the
/// node with one Touch ID signature, and wait for the owner's one-time
/// approval at the node. This app cannot approve it.
async fn do_device_key_register(state: &NodeState) -> Result<device::DeviceView, ActionError> {
    allow_device_change(state)?;
    if !device_available(state) {
        return Err(device_error(device_key::DeviceKeyError::BiometryUnavailable));
    }
    let store = device_store(state)?;
    let existing = local_key(state, &store)?;
    if let Some((_, r)) = existing.as_ref().filter(|(_, r)| r.registered) {
        return Ok(device_view(state, Some(r)));
    }
    let (blob, mut record) = match existing {
        Some((blob, record)) => (blob, record),
        None => {
            let policy = *state.device_policy.lock().unwrap();
            let (blob, public) = tokio::task::spawn_blocking(move || device_key::create(policy))
                .await
                .map_err(|_| ActionError::new("device_key", "Creating the key stopped unexpectedly."))?
                .map_err(device_error)?;
            let record = device::Record { public_key: hex::encode(public), ..Default::default() };
            {
                let _guard = state.device_lifecycle.lock().unwrap();
                device::save_blob(&store, &blob)?;
                device::save_record(&store, &record)?;
            }
            (device_signing_key(&store, &record, blob)?, record)
        }
    };
    let binding = device_binding(state).await?;
    if let Some(reason) = binding.device_approvals.as_deref().filter(|r| *r != "enabled") {
        // Before any Touch ID prompt: the node would refuse it anyway.
        return Err(device::node_off_error(reason));
    }
    let message = device::registration_message(&binding.node, &binding.client_id, &record.public_key);
    let name = device::registration_name(std::env::consts::OS);
    let reason = if cfg!(target_os = "macos") {
        "register this Mac with your BitSov node, so it can approve payments with Touch ID"
    } else {
        "register this device with your BitSov node, so it can approve payments with biometrics"
    };
    let proof = device_sign(blob, message, reason.into()).await?;
    let body = serde_json::json!({"public_key": record.public_key, "name": name, "proof": proof});
    let (status, text) = call_api(state, reqwest::Method::POST, "/pair/device-key", Some(body)).await.map_err(ActionError::node)?;
    if !status.is_success() {
        if let Some(reason) = device::node_off_reason(&text) {
            return Err(device::node_off_error(reason));
        }
        return Err(ActionError::node(api_error("/pair/device-key", status, &text)));
    }
    let reply: DeviceKeyReply = decode_act("/pair/device-key", &text)?;
    if act::elevation_status_path(&reply.op_id).is_err() {
        return Err(ActionError::node("the node returned an unexpected operation id"));
    }
    record.key_id = Some(reply.key_id);
    record.fingerprint = Some(reply.fingerprint.chars().filter(|c| c.is_ascii_alphanumeric() || *c == '-').take(24).collect());
    record.pending = Some(device::PendingRegistration {
        delegation_message: reply.delegation_message,
        op_id: reply.op_id,
        owner_action: reply.owner_action.chars().take(600).collect(),
        expires_at_ms: (reply.expires_at.max(0) as u64).saturating_mul(1000),
    });
    {
        let _guard = state.device_lifecycle.lock().unwrap();
        device::save_record(&store, &record)?;
        state.device_lapsed.store(false, Ordering::SeqCst);
    }
    Ok(device_view(state, Some(&record)))
}

/// Withdraw a registration still waiting for the owner.
async fn do_device_key_cancel(state: &NodeState) -> Result<device::DeviceView, ActionError> {
    allow_device_change(state)?;
    let store = device_store(state)?;
    let Some(mut record) = device::load_record(&store) else { return Ok(device_view(state, None)) };
    if let Some(p) = record.pending.clone() {
        if act::elevation_status_path(&p.op_id).is_ok() {
            withdraw_at_node(state, &format!("/pair/device-key/{}", p.op_id)).await?;
        }
        let _guard = state.device_lifecycle.lock().unwrap();
        // Clear only the request that was withdrawn at the node.
        let mut current = device::load_record(&store).unwrap_or_default();
        if current.pending.as_ref().map(|c| &c.op_id) == Some(&p.op_id) {
            current.pending = None;
            device::save_record(&store, &current)?;
        }
        record = current;
    }
    state.device_lapsed.store(false, Ordering::SeqCst);
    Ok(device_view(state, Some(&record)))
}

/// Open (or renew) one contact's spend envelope: the owner signs the exact
/// terms with Touch ID, the node verifies and enforces them, and the app's
/// spend window then opens over that grant as for any node grant.
async fn do_relation_approve(
    state: &NodeState,
    peer: &str,
    budget_msat: Option<u64>,
    per_act_max_msat: Option<u64>,
) -> Result<act::SpendView, ActionError> {
    // Contact defaults (research doc): 200 sats in total for up to 24 hours,
    // the quoted price per act.
    let budget_msat = budget_msat.unwrap_or(device::DEFAULT_BUDGET_MSAT);
    let per_act_max_msat = device::default_per_act(per_act_max_msat, budget_msat);
    if budget_paused(state)? {
        return Err(ActionError::new("budget_paused", "Payments are paused. Resume them first."));
    }
    // Taken before the Touch ID prompt: a Lock or Pause while the owner is
    // at the dialog, or while the node answers, opens nothing.
    let fence = approval_fence(state);
    let store = device_store(state)?;
    let Some((blob, record)) = local_key(state, &store)?.filter(|(_, r)| r.registered) else {
        return Err(ActionError::new("device_not_registered", if cfg!(target_os = "android") {
            "Set up biometric approvals first."
        } else {
            "Set up Touch ID approvals first."
        }));
    };
    let key_id = record.key_id.clone().ok_or_else(|| ActionError::new(
        "device_not_registered",
        if cfg!(target_os = "android") {
            "Set up biometric approvals first."
        } else {
            "Set up Touch ID approvals first."
        },
    ))?;
    let intent = device::Intent::contact(&key_id, peer, budget_msat, per_act_max_msat, now_unix())?;
    let binding = device_binding(state).await?;
    if let Some(reason) = binding.device_approvals.as_deref().filter(|r| *r != "enabled") {
        // Before any Touch ID prompt: the node would refuse the signature.
        return Err(device::node_off_error(reason));
    }
    let message = device::intent_message(&binding.node, &binding.client_id, &intent);
    // The dialog names the contact by the key it signs, never by a name: the
    // node's /peers label may be the peer's own claim (PR #92 keeps those
    // apart from local petnames), and petnames never leave this Mac.
    let reason = device::contact_intent_reason(&intent);
    let signature = match device_sign(blob, message, reason).await {
        Ok(signature) => signature,
        Err(e) => {
            forget_invalid_signing_key(&store, &e);
            return Err(e);
        }
    };
    let body = serde_json::json!({"intent": intent, "signature": signature});
    let (status, text) = call_api(state, reqwest::Method::POST, "/pair/relation-intent", Some(body)).await.map_err(ActionError::node)?;
    if !status.is_success() {
        // A semantic refusal can also be a 404 (for example a revoked client).
        // Only a route miss, without the node's error code, means unsupported.
        let has_code = serde_json::from_str::<serde_json::Value>(&text).ok()
            .is_some_and(|reply| reply.get("code").is_some_and(|code| !code.is_null()));
        let error = if matches!(status, reqwest::StatusCode::NOT_FOUND | reqwest::StatusCode::METHOD_NOT_ALLOWED) && !has_code {
            ActionError::new("device_remote_unsupported", "Your node can't take device approvals over remote access yet. Nothing was approved. Update your node, or approve at the node.")
        } else if let Some(reason) = device::node_off_reason(&text) {
            device::node_off_error(reason)
        } else {
            ActionError::node(api_error("/pair/relation-intent", status, &text))
        };
        // Never log the response body or the signed request.
        eprintln!("path=/pair/relation-intent status={} code={}", status.as_u16(), error.code);
        return Err(error);
    }
    // This approval's ID comes only from its response, never from the later
    // grant read (another device may already have replaced the envelope).
    let envelope_id = if node_offers(state, grant::RELATION_ENVELOPE_ID_CAPABILITY).await {
        serde_json::from_str::<serde_json::Value>(&text).ok()
            .and_then(|reply| reply["envelope_id"].as_str().map(str::to_owned))
    } else {
        None
    };
    // The grant reaches a token only on re-issue. Open the window over the
    // relation grant and nothing else: never a console elevation request.
    refresh_paired(state).await.map_err(ActionError::node)?;
    let has_spend = matches!(&*state.auth.lock().unwrap(), AuthMode::Paired(s) if s.scopes.iter().any(|x| x == "spend"));
    let grant = read_grant(state).await?.filter(|g| g.recipients_only && g.has_envelope(&intent.peer, now_ms()));
    let (true, Some(grant)) = (has_spend, grant) else {
        return Err(ActionError::new(
            "grant_no_envelope",
            "Your node accepted the approval, but its spend grant for this contact could not be confirmed. Nothing was opened; try again.",
        ));
    };
    open_fenced(state, fence, Want::Window, act::SpendBasis::NodeGrant, Some(&grant))?;
    save_spend_pending(state);
    Ok(act::SpendView { envelope_id, ..state.spend.lock().unwrap().view(now_ms()) })
}

