#[cfg(test)]
mod mcp_command_tests {
    //! The MCP commands: main window only, short codes, one list everywhere.

    fn source(path: &str) -> String {
        std::fs::read_to_string(format!("{}/{path}", env!("CARGO_MANIFEST_DIR"))).unwrap()
    }

    fn section() -> String {
        let app = source("src/app.rs");
        let start = app.find("// ---- MCP: AI apps on this computer").expect("MCP section");
        let end = app[start..].find("// ---- end MCP").expect("MCP section end");
        app[start..start + end].to_owned()
    }

    fn quoted(text: &str, marker: &str) -> Vec<String> {
        let start = text.find(marker).unwrap_or_else(|| panic!("missing {marker}")) + marker.len();
        let end = start + text[start..].find(']').expect("list end");
        text[start..end].split('"').skip(1).step_by(2).map(str::to_owned).collect()
    }

    fn commands() -> Vec<String> {
        quoted(&section(), "const MCP_COMMANDS: [&str; 13] = [")
    }

    #[test]
    fn every_mcp_command_checks_the_main_window_first() {
        let section = section();
        assert!(section.contains("reject_sealed_window(window).map_err(|_| bitsov_app::mcp::runtime::code::MAIN_WINDOW_ONLY"));
        for command in commands() {
            let start = section.find(&format!("async fn {command}(")).unwrap_or_else(|| panic!("missing async fn {command}"));
            let body = &section[start..];
            let open = body.find(") -> Result<").expect("returns a Result");
            let first = body[open..].lines().nth(1).unwrap_or_default().trim();
            assert_eq!(first, "mcp_main_window(&window)?;", "{command} must check the window first");
        }
        assert!(super::window_may_run_privileged_command(super::MAIN_WINDOW_LABEL));
        assert!(!super::window_may_run_privileged_command("assistant"));
    }

    #[test]
    fn the_command_lists_agree_and_the_grant_is_the_main_window_only() {
        let listed = commands();
        assert_eq!(listed.len(), 13);
        assert_eq!(quoted(&source("build.rs"), "const MCP_COMMANDS: &[&str] = &["), listed, "build.rs");
        let section = section();
        let handler = &section[section.find("generate_handler![").expect("handler")..];
        let handler = &handler[..handler.find(']').unwrap()];
        for command in &listed {
            assert!(handler.contains(command.as_str()), "{command} is not in the MCP handler");
        }
        assert!(section.contains("CapabilityBuilder::new(\"mcp\").window(MAIN_WINDOW_LABEL)"));
        assert!(!section.contains(".windows("), "granted to one window only");
        // No capability file grants them: only the runtime grant above does.
        for entry in std::fs::read_dir(format!("{}/capabilities", env!("CARGO_MANIFEST_DIR"))).unwrap() {
            let text = std::fs::read_to_string(entry.unwrap().path()).unwrap();
            assert!(!text.contains("allow-mcp-"), "a capability file names an MCP permission");
        }
    }

    #[test]
    fn errors_are_short_codes() {
        use bitsov_app::mcp::runtime::code;
        for value in [code::MAIN_WINDOW_ONLY, code::UNAVAILABLE, code::BLOCKED, code::START_FAILED, code::UNKNOWN,
            code::NO_TOPICS, code::PRESET_TOO_WIDE, code::NOT_SAVED, code::PAIRING_CLOSED, code::TOPIC_NOT_ALLOWED] {
            assert!(value.chars().all(|c| c.is_ascii_lowercase() || c == '_'), "{value}");
        }
    }
}

#[cfg(test)]
mod media_send_session_tests {
    use super::*;

    struct NoActivity;
    impl control::call_activity::ActivityDriver for NoActivity {
        fn begin(&self) {}
        fn end(&self) {}
    }

    fn open(state: &NodeState, send_base: Option<u64>) -> Arc<control::media::FrameQueue> {
        let activity = control::call_activity::CallActivity::new(Box::new(NoActivity));
        install_media_session(state, "call-1", false, send_base, Arc::new(activity.hold("call-1"))).0
    }

    fn drain(queue: &control::media::FrameQueue) -> Vec<u8> {
        std::iter::from_fn(|| queue.try_pop()).map(|frame| frame[0]).collect()
    }

    /// A send from the old socket that only runs after close and a new open
    /// looks up the new session; its lower count keeps it out of that uplink.
    #[test]
    fn a_stale_send_after_close_and_reopen_never_reaches_the_new_session() {
        let state = NodeState::for_api("http://127.0.0.1:1/api/v1");
        let old = open(&state, Some(0));
        for count in 0..5u64 {
            admit_media_send(&state, Some(count), Ok(vec![count as u8])).unwrap();
        }
        assert_eq!(drain(&old), [0, 1, 2, 3, 4]);
        // Counts 5 and 6 were handed over for the old socket but have not run yet.
        stop_media_session(&state);
        let new = open(&state, Some(7));
        admit_media_send(&state, Some(6), Ok(vec![6])).unwrap();
        admit_media_send(&state, Some(5), Ok(vec![5])).unwrap();
        assert!(drain(&new).is_empty(), "the old call's frames must not go to the new peer");
        admit_media_send(&state, Some(7), Ok(vec![7])).unwrap();
        admit_media_send(&state, Some(8), Ok(vec![8])).unwrap();
        assert_eq!(drain(&new), [7, 8]);
        assert!(drain(&old).is_empty());
        stop_media_session(&state);
    }

    #[test]
    fn the_queue_stats_need_an_open_session_and_count_what_each_queue_dropped() {
        let state = NodeState::for_api("http://127.0.0.1:1/api/v1");
        assert_eq!(media_queue_stats(&state).unwrap_err(), "no media session is open");
        let activity = control::call_activity::CallActivity::new(Box::new(NoActivity));
        let (uplink, downlink, _, _) = install_media_session(&state, "call-1", false, None, Arc::new(activity.hold("call-1")));
        assert_eq!(media_queue_stats(&state).unwrap(), serde_json::json!({ "uplink_dropped": 0, "downlink_dropped": 0 }));
        // Each queue holds QUEUE_FRAMES and drops the oldest beyond that.
        for frame in 0..control::media::QUEUE_FRAMES + 2 {
            uplink.push(vec![frame as u8]);
        }
        for frame in 0..control::media::QUEUE_FRAMES + 5 {
            downlink.push(vec![frame as u8]);
        }
        assert_eq!(media_queue_stats(&state).unwrap(), serde_json::json!({ "uplink_dropped": 2, "downlink_dropped": 5 }));
        stop_media_session(&state);
        assert!(media_queue_stats(&state).is_err(), "closed again");
    }

    #[test]
    fn a_send_without_a_session_or_count_keeps_todays_answers() {
        let state = NodeState::for_api("http://127.0.0.1:1/api/v1");
        assert!(admit_media_send(&state, Some(0), Ok(vec![0])).is_err());
        let queue = open(&state, None);
        admit_media_send(&state, None, Ok(vec![3])).unwrap();
        assert!(admit_media_send(&state, Some(1), Err("bad".into())).is_err());
        assert_eq!(drain(&queue), [3]);
        stop_media_session(&state);
    }
}

#[cfg(all(test, not(feature = "call-seal")))]
mod no_call_seal_tests {
    /// Without the feature, the generated permission and capability sets know
    /// nothing of the seal: there is no command to grant or to call.
    #[test]
    fn a_build_without_call_seal_has_no_seal_command_permission_or_capability() {
        // This build's own output, not the shared gen/schemas a later build may overwrite.
        let acl = include_str!(concat!(env!("OUT_DIR"), "/acl-manifests.json"));
        let capabilities = include_str!(concat!(env!("OUT_DIR"), "/capabilities.json"));
        for text in [acl, capabilities] {
            assert!(!text.contains("call_seal") && !text.contains("call-seal"));
        }
        assert!(acl.contains("call_media_open"), "the ACL file is the app's");
    }
}

#[cfg(all(test, feature = "call-seal"))]
mod call_seal_open_tests {
    use super::*;
    use control::call_seal::{CallerOffer, Parties, SealError};

    const CALL: &str = "0123456789abcdef0123456789abcdef";
    const OTHER: &str = "fedcba9876543210fedcba9876543210";

    fn offered(call: &str) -> PreparedSeal {
        let parties = Parties::new(call, &"a1".repeat(32), &"b2".repeat(32)).unwrap();
        PreparedSeal::Offered { call_id: call.to_string(), offer: Box::new(CallerOffer::new(parties).unwrap().0) }
    }

    fn ready(call: &str) -> PreparedSeal {
        let parties = Parties::new(call, &"a1".repeat(32), &"b2".repeat(32)).unwrap();
        let (offer, line) = CallerOffer::new(parties.clone()).unwrap();
        let control::call_seal::AnswerDecision::Seal { attribute, .. } = control::call_seal::answer_offer(parties, &line).unwrap() else { panic!("no seal") };
        PreparedSeal::Ready { call_id: call.to_string(), media: Box::new(offer.accept_answer(&attribute).unwrap().unwrap()) }
    }

    #[test]
    fn a_media_session_starts_sealed_only_with_this_calls_finished_exchange() {
        assert!(seal_for_media(Some(ready(CALL)), CALL, true).unwrap().is_some());
        // A finished exchange is used even if the renderer did not ask: the host decides.
        assert!(seal_for_media(Some(ready(CALL)), CALL, false).unwrap().is_some());
    }

    #[test]
    fn asking_for_a_seal_with_nothing_to_open_refuses_the_socket() {
        for prepared in [None, Some(offered(CALL)), Some(offered(OTHER)), Some(ready(OTHER))] {
            assert_eq!(seal_for_media(prepared, CALL, true).err(), Some(SealError::NotReady));
        }
    }

    #[test]
    fn this_calls_unanswered_offer_never_opens_in_the_clear() {
        assert_eq!(seal_for_media(Some(offered(CALL)), CALL, false).err(), Some(SealError::NotReady));
    }

    #[test]
    fn with_no_exchange_a_session_is_todays() {
        assert!(seal_for_media(None, CALL, false).unwrap().is_none());
        // Another call's leftovers are dropped, not used.
        assert!(seal_for_media(Some(ready(OTHER)), CALL, false).unwrap().is_none());
        assert!(seal_for_media(Some(offered(OTHER)), CALL, false).unwrap().is_none());
    }

}

#[cfg(test)]
mod trust_tests {
    use super::*;

    #[test]
    fn trust_is_bound_to_the_ready_authenticated_node_and_survives_reopening() {
        let dir = tempfile::tempdir().unwrap();
        let state = NodeState::for_api("http://127.0.0.1:1/api/v1");
        *state.app_dir.lock().unwrap() = Some(dir.path().to_path_buf());
        *state.node_id.lock().unwrap() = Some("abcd".into());
        state.remote_mode.store(true, Ordering::SeqCst);
        assert!(state.acknowledge_trust("abcd", true, false).is_err());
        *state.ready.lock().unwrap() = true;
        state.pairing_view.lock().unwrap().state = "paired";
        assert!(state.pairing_snapshot().trust_acknowledged_node_id.is_none());
        assert!(state.acknowledge_trust("cdef", true, false).is_err());
        assert!(state.acknowledge_trust("abcd", false, false).is_err());
        state.pairing_view.lock().unwrap().bootstrap = Some("bootstrap".into());
        assert!(state.acknowledge_trust("abcd", true, false).is_err());
        state.pairing_view.lock().unwrap().bootstrap = None;
        assert!(state.acknowledge_trust("ABCD", true, false).unwrap());
        drop(state);

        let reopened = NodeState::for_api("http://127.0.0.1:1/api/v1");
        *reopened.app_dir.lock().unwrap() = Some(dir.path().to_path_buf());
        *reopened.node_id.lock().unwrap() = Some("abcd".into());
        reopened.remote_mode.store(true, Ordering::SeqCst);
        assert_eq!(reopened.pairing_snapshot().trust_acknowledged_node_id.as_deref(), Some("abcd"));
        *reopened.node_id.lock().unwrap() = Some("cdef".into());
        assert!(reopened.pairing_snapshot().trust_acknowledged_node_id.is_none());
    }
}

