    #[tokio::test]
    async fn remote_reauthentication_waits_then_recovers_paired_state_and_clears_stale_error() {
        let f = fixture(PairRoutes::Live);
        authenticate(&f.state, f.data_dir.path()).await.unwrap();
        f.state.remote_mode.store(true, Ordering::SeqCst);
        *f.state.expected_remote_node_id.lock().unwrap() = Some(mock_node::NODE_ID.into());
        *f.state.error.lock().unwrap() = Some(remote_access::HANDSHAKE_UNAVAILABLE.into());
        let ctx = f.state.pairing.lock().unwrap().clone().unwrap();
        let key_before = std::fs::read(ctx.store.join(pairing::KEY_FILE)).unwrap();
        let record_before = std::fs::read(ctx.store.join(pairing::RECORD_FILE)).unwrap();
        let before = f.node.calls("/api/v1/pair/challenge");
        f.state
            .remote_retry
            .failed(&remote_access::RemoteError::RateLimited(1));
        assert!(tokio::time::timeout(
            Duration::from_millis(100),
            finish_remote_auth(&f.state, f.data_dir.path())
        )
        .await
        .is_err());
        assert_eq!(f.node.calls("/api/v1/pair/challenge"), before);
        // An existing authenticated HTTP connection can recover without a new
        // handshake. Its success must still complete this recovery exactly once.
        tokio::time::sleep(Duration::from_secs(
            f.state.remote_retry.remaining().unwrap(),
        ))
        .await;
        tokio::time::timeout(
            Duration::from_secs(3),
            finish_remote_auth(&f.state, f.data_dir.path()),
        )
        .await
        .unwrap();
        assert_eq!(f.node.calls("/api/v1/pair/challenge"), before + 1);
        assert!(f.state.status_snapshot().ready);
        assert_eq!(f.state.status_snapshot().error, None);
        assert_eq!(f.state.status_snapshot().retry_after_secs, None);
        assert_eq!(f.state.pairing_snapshot().state, "paired");
        assert_eq!(
            std::fs::read(ctx.store.join(pairing::KEY_FILE)).unwrap(),
            key_before
        );
        assert_eq!(
            std::fs::read(ctx.store.join(pairing::RECORD_FILE)).unwrap(),
            record_before
        );
        assert_eq!(f.node.calls("/api/v1/auth/local"), 0);
    }

    #[tokio::test]
    async fn successful_remote_reauthentication_clears_structured_connection_failure() {
        let f = fixture(PairRoutes::Live);
        finish_auth(&f.state, f.data_dir.path()).await;
        f.state.remote_mode.store(true, Ordering::SeqCst);
        f.state.remote_retry.failed(&remote_access::RemoteError::LocalNetwork);
        set_error(&f.state, "previous network unavailable");
        finish_remote_auth(&f.state, f.data_dir.path()).await;
        let status = f.state.status_snapshot();
        assert!(status.ready);
        assert!(status.error.is_none());
        assert!(status.connection_error.is_none());
        assert_eq!(status.node_id.as_deref(), Some(mock_node::NODE_ID));
        assert_eq!(f.node.calls("/api/v1/auth/local"), 0);
    }

    #[tokio::test]
    async fn warm_remote_reauthentication_distinguishes_upstream_outage_from_pin_refusal() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        for (code, stays_ready) in [("remote_retry_wait", true), ("remote_transport_refused", false)] {
            let f = fixture(PairRoutes::Live);
            finish_auth(&f.state, f.data_dir.path()).await;
            f.state.remote_mode.store(true, Ordering::SeqCst);
            let ctx = f.state.pairing.lock().unwrap().clone().unwrap();
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let base = format!("http://127.0.0.1:{}/api/v1", listener.local_addr().unwrap().port());
            let server = tokio::spawn(async move {
                let (mut stream, _) = listener.accept().await.unwrap();
                let mut request = vec![0; 4096];
                let read = stream.read(&mut request).await.unwrap();
                assert_ne!(read, 0, "the client sent a request");
                let body = format!(r#"{{"code":"{code}","message":"remote unavailable"}}"#);
                stream.write_all(format!("HTTP/1.1 502 Bad Gateway\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len()).as_bytes()).await.unwrap();
            });
            *f.state.pairing.lock().unwrap() = Some(Arc::new(PairingCtx {
                client: PairingClient::new(f.state.http.clone(), base),
                key: ctx.key.clone(), store: ctx.store.clone(), data_dir: ctx.data_dir.clone(),
            }));
            finish_remote_auth(&f.state, f.data_dir.path()).await;
            server.await.unwrap();
            assert_eq!(f.state.status_snapshot().ready, stays_ready, "{code}");
            assert_eq!(f.state.pairing_snapshot().state, if stays_ready { "paired" } else { "failed" });
            assert_eq!(f.state.token.lock().unwrap().is_some(), stays_ready);
        }
    }

    #[tokio::test]
    async fn warm_remote_reauthentication_keeps_readiness_and_session_during_transport_loss() {
        let f = fixture(PairRoutes::Live);
        finish_auth(&f.state, f.data_dir.path()).await;
        f.state.remote_mode.store(true, Ordering::SeqCst);
        let token = f.state.token.lock().unwrap().clone();
        let ctx = f.state.pairing.lock().unwrap().clone().unwrap();
        // An unreachable endpoint is a transient transport failure, not revocation.
        let dead = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://127.0.0.1:{}/api/v1", dead.local_addr().unwrap().port());
        drop(dead);
        *f.state.pairing.lock().unwrap() = Some(Arc::new(PairingCtx {
            client: PairingClient::new(f.state.http.clone(), base),
            key: ctx.key.clone(), store: ctx.store.clone(), data_dir: ctx.data_dir.clone(),
        }));
        finish_remote_auth(&f.state, f.data_dir.path()).await;
        assert!(f.state.status_snapshot().ready);
        assert_eq!(f.state.pairing_snapshot().state, "paired");
        assert_eq!(*f.state.token.lock().unwrap(), token);
        assert!(matches!(*f.state.auth.lock().unwrap(), AuthMode::Paired(_)));
        assert!(f.state.status_snapshot().error.is_some());
    }

    #[tokio::test]
    async fn remote_reauthentication_stops_on_refusal_even_with_old_retry_debt() {
        let f = fixture(PairRoutes::Live);
        authenticate(&f.state, f.data_dir.path()).await.unwrap();
        f.state.remote_mode.store(true, Ordering::SeqCst);
        let ctx = f.state.pairing.lock().unwrap().clone().unwrap();
        let record_before = std::fs::read(ctx.store.join(pairing::RECORD_FILE)).unwrap();
        *f.state.ready.lock().unwrap() = true;
        f.node.revoke_all();
        let before = f.node.calls("/api/v1/pair/challenge");
        f.state
            .remote_retry
            .failed(&remote_access::RemoteError::HandshakeUnavailable);
        tokio::time::sleep(Duration::from_secs(
            f.state.remote_retry.remaining().unwrap(),
        ))
        .await;
        tokio::time::timeout(
            Duration::from_secs(3),
            finish_remote_auth(&f.state, f.data_dir.path()),
        )
        .await
        .unwrap();
        assert_eq!(f.node.calls("/api/v1/pair/challenge"), before + 1);
        assert!(!f.state.status_snapshot().ready);
        assert_eq!(f.state.pairing_snapshot().state, "failed");
        assert!(!f.state.remote_retry.is_retrying());
        assert_eq!(
            std::fs::read(ctx.store.join(pairing::RECORD_FILE)).unwrap(),
            record_before
        );
        assert_eq!(f.node.calls("/api/v1/auth/local"), 0);
    }

    #[tokio::test]
    async fn forgotten_remote_restarts_on_rc7_without_reusing_remote_pairing() {
        let f = fixture(PairRoutes::Absent);
        let store = f.data_dir.path().join(PAIRING_STORE_DIR);
        let key = ClientKey::load_or_create(&store).unwrap();
        let original_key = std::fs::read(store.join(pairing::KEY_FILE)).unwrap();
        pairing::save_remote_record(&store, &key,
            "0123456789abcdef0123456789abcdef".into(), vec!["read".into(), "receive".into()]).unwrap();
        let remote_dir = f.data_dir.path().join(remote_access::REMOTE_CONFIG_DIR);
        std::fs::create_dir(&remote_dir).unwrap();
        std::fs::write(remote_dir.join(remote_access::REMOTE_CONFIG_FILE), "saved remote descriptor").unwrap();
        remote_access::forget_persisted(f.data_dir.path()).unwrap();
        // Forgetting leaves the live remote session's record available.
        assert!(store.join(pairing::RECORD_FILE).exists());
        remote_access::prepare_local_pairing(f.data_dir.path(), &store).unwrap();
        authenticate(&f.state, f.data_dir.path()).await.expect("local fallback after restart");
        assert_eq!(f.state.pairing_view.lock().unwrap().state, "fallback");
        assert_eq!(f.node.calls("/api/v1/pair/challenge"), 0);
        assert_eq!(f.node.calls("/api/v1/auth/local"), 1);
        assert_eq!(std::fs::read(store.join(pairing::KEY_FILE)).unwrap(), original_key);
    }

