    /// End with their price unavailable: the hangup is refused, and no new minute of
    /// the call is dispatched after it, even though the node still shows the call live.
    #[tokio::test]
    async fn end_with_the_price_unavailable_dispatches_no_new_minute_after_it() {
        use std::sync::atomic::{AtomicBool, Ordering::SeqCst};
        let (inner, _, reserved) = PacedHold { per_block: 8_000, fee: 2_000, minutes: 5, closing: 0, direct: false, spent: SPENT_AT_CEILING }.routes();
        let unreadable = Arc::new(AtomicBool::new(false));
        let u = unreadable.clone();
        let node = paced_call(Arc::new(move |m, p, b| {
            if p == format!("/pricing/peers/{A}/call") && u.load(SeqCst) {
                return (400, r#"{"error":"their node did not answer with a call price; nothing was paid","code":400,"reason":"call_price_unknown"}"#.into());
            }
            inner(m, p, b)
        }), reserved).await;
        do_call_block(&node.state, A, CALL_ID, 0).await.unwrap();
        unreadable.store(true, SeqCst);
        assert_eq!(do_op_end_call(&node.state, CALL_ID).await.unwrap_err().code, "call_price_unknown");
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 1).await.unwrap_err().code, "call_not_live");
        assert_eq!(compose_kinds(&node), [400, 404], "one minute before End, none after, and no hangup");
    }

    /// Node routes that issue a new token on each exchange and count them.
    fn minting_routes(minted: Arc<std::sync::atomic::AtomicUsize>) -> Routes {
        Arc::new(move |_, p, _| {
            if p.starts_with("/pair/challenge") { return (200, serde_json::json!({"challenge": "bitsov-pair-token-v1:00ff"}).to_string()); }
            if p == "/pair/token" {
                let n = minted.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
                return (200, serde_json::json!({"token": format!("tok.media{n}"), "expires_at": now_unix() + 600, "scopes": ["read", "receive", "spend"]}).to_string());
            }
            (404, r#"{"error":"route","code":404}"#.into())
        })
    }

    /// Each media open gets a token of its own, whatever the shared token's age. The
    /// shared token and session stay as they were, so the live feed and every
    /// request keep their renewal.
    #[tokio::test]
    async fn a_media_socket_gets_its_own_token_and_the_shared_one_stays() {
        use std::sync::atomic::{AtomicUsize, Ordering::SeqCst};
        for left in [300, 590, 599] {
            let minted = Arc::new(AtomicUsize::new(0));
            let (node, _dir) = paired_fake(minting_routes(minted.clone()));
            let expires_at = now_unix() + left;
            if let AuthMode::Paired(session) = &mut *node.state.auth.lock().unwrap() { session.expires_at = expires_at; }
            *node.state.token.lock().unwrap() = Some("tok.1".into());
            assert_eq!(media_token(&node.state).await.as_deref(), Some("tok.media1"), "{left} s left");
            assert_eq!(media_token(&node.state).await.as_deref(), Some("tok.media2"), "{left} s left, a re-open");
            assert_eq!(minted.load(SeqCst), 2, "{left} s left");
            assert_eq!(node.state.token.lock().unwrap().as_deref(), Some("tok.1"), "{left} s left");
            let auth = node.state.auth.lock().unwrap();
            let AuthMode::Paired(session) = &*auth else { panic!("still paired") };
            assert_eq!((session.token.as_str(), session.expires_at), ("tok.1", expires_at), "{left} s left");
        }
    }

    /// No token of its own: the socket opens on the shared one, as before.
    #[tokio::test]
    async fn a_media_socket_falls_back_to_the_shared_token() {
        // The node does not answer the exchange.
        let (node, _dir) = paired_fake(Arc::new(|_, _, _| (500, r#"{"error":"down","code":500}"#.into())));
        *node.state.token.lock().unwrap() = Some("tok.1".into());
        assert_eq!(media_token(&node.state).await.as_deref(), Some("tok.1"));
        // An owner session has no pairing to ask.
        let minted = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let node = fake(AuthMode::Local, minting_routes(minted.clone()));
        *node.state.token.lock().unwrap() = Some("tok.local".into());
        assert_eq!(media_token(&node.state).await.as_deref(), Some("tok.local"));
        assert_eq!(minted.load(std::sync::atomic::Ordering::SeqCst), 0);
        // A shared token inside its renewal margin is renewed by the usual route.
        let minted = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let inner = minting_routes(minted.clone());
        let first = Arc::new(std::sync::atomic::AtomicBool::new(true));
        let (node, _dir) = paired_fake(Arc::new(move |m, p, b| {
            if p == "/pair/token" && first.swap(false, std::sync::atomic::Ordering::SeqCst) { return (500, r#"{"error":"down","code":500}"#.into()); }
            inner(m, p, b)
        }));
        if let AuthMode::Paired(session) = &mut *node.state.auth.lock().unwrap() { session.expires_at = now_unix() + 60; }
        assert_eq!(media_token(&node.state).await.as_deref(), Some("tok.media1"));
        assert_eq!(node.state.token.lock().unwrap().as_deref(), Some("tok.media1"), "that renewal is the shared token's");
    }

    /// A token issued across a change of connection is not used.
    #[tokio::test]
    async fn a_media_token_from_a_replaced_connection_is_not_used() {
        let (arrived, proceed) = (Arc::new(tokio::sync::Notify::new()), Arc::new(std::sync::Barrier::new(2)));
        let (a, p) = (arrived.clone(), proceed.clone());
        let (node, _dir) = paired_fake(Arc::new(move |_, path, _| {
            if path.starts_with("/pair/challenge") { return (200, serde_json::json!({"challenge": "bitsov-pair-token-v1:00ff"}).to_string()); }
            if path == "/pair/token" {
                a.notify_one();
                p.wait();
                return (200, serde_json::json!({"token": "tok.stale", "expires_at": now_unix() + 600, "scopes": ["read"]}).to_string());
            }
            (404, r#"{"error":"route","code":404}"#.into())
        }));
        *node.state.token.lock().unwrap() = Some("tok.1".into());
        let (token, ()) = tokio::join!(media_token(&node.state), async {
            arrived.notified().await;
            node.state.remote_connect_generation.send_modify(|g| *g += 1);
            proceed.wait();
        });
        assert_eq!(token.as_deref(), Some("tok.1"));
    }

    /// A hangup signal refused while it is prepared, before the money lock and
    /// with nothing sent, has still revoked the call's minutes.
    #[tokio::test]
    async fn a2_a_hangup_refused_while_prepared_still_revokes_the_minutes() {
        use std::sync::atomic::{AtomicBool, Ordering::SeqCst};
        let (inner, _) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let unreadable = Arc::new(AtomicBool::new(false));
        let u = unreadable.clone();
        let node = minute_ready(Arc::new(move |m, p, b| {
            if p == "/payments/price/401" && u.load(SeqCst) { return (500, "{}".into()); }
            inner(m, p, b)
        })).await;
        unreadable.store(true, SeqCst);
        let plaintext = format!(r#"{{"v":1,"call_id":"{CALL_ID}","reason":"hangup"}}"#);
        do_call_signal(&node.state, A, 403, &plaintext, 15_000).await.unwrap_err();
        assert_eq!(consent_phase(&node), ConsentPhase::Ended);
        assert_eq!(compose_kinds(&node), [400], "nothing was sent");
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_not_live");
        assert_eq!(minutes_sent(&node), 0);
    }

    /// End or local teardown on the runtime's worker threads against a minute's
    /// last step. Either one revokes at once, while the minute still holds the
    /// money lock. Revoked first: no kind 404 goes out and the minute is charged
    /// nothing, its reservation released. Decided first: exactly one kind 404
    /// goes out and is accounted, and End's hangup is ordered after it.
    /// Teardown never claims the node closed the call. Every wait is bounded.
    #[test]
    fn a2_a_minute_revoked_first_is_never_sent_and_one_decided_first_goes_before_the_hangup() {
        let rt = race_runtime();
        for ender in ["end", "close"] {
            for revoke_first in [true, false] {
                let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
                let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
                let state = &node.state;
                let spent = budget_now(state).spent_msat;
                let op = offer_op(node);
                let point = if revoke_first { "before_decision" } else { "after_decision" };
                let case = format!("{ender} {point}");
                let before = minute_snapshot(node, &paid);
                assert_admitted_and_idle(node, &case);
                let (arrived, release) = pause_points::arm(&state.api_base, point);
                let minute = rt.spawn(do_call_block(state, A, CALL_ID, 0));
                reach(&rt, &arrived, &release, &case);
                let stop = {
                    let op = op.clone();
                    rt.spawn(async move {
                        if ender == "end" { do_op_end_call(&node.state, CALL_ID).await.map(|_| ()) }
                        else { do_op_close_call(&node.state, &op, A, CALL_ID).await }
                    })
                };
                let phase = phase_once_ended(node);
                let sent_while_paused = compose_kinds(node);
                let posts_while_paused = node.posts();
                let stop_waiting = !stop.is_finished();
                // Every assertion below runs after the minute is released, so a
                // failure ends the test instead of leaving it paused.
                release.notify_one();
                assert_eq!(phase, ConsentPhase::Ended, "{case}: revoked at once, without the money lock");
                assert_eq!(sent_while_paused, [400], "{case}: nothing goes out while the minute holds the lock");
                assert_eq!(posts_while_paused, before.posts, "{case}: no POST of any kind while paused");
                assert!(stop_waiting, "{case}: the ender waits for the minute's money lock");
                let minute = joined(&rt, minute, &case);
                if revoke_first {
                    assert_eq!(minute.unwrap_err().code, "call_not_live", "{case}");
                } else {
                    minute.unwrap();
                }
                joined(&rt, stop, &case).unwrap();
                let hangups = u64::from(ender == "end");
                let minutes = u64::from(!revoke_first);
                let mut order = vec![400];
                if !revoke_first { order.push(404); }
                if ender == "end" { order.push(403); }
                assert_eq!(compose_kinds(node), order, "{case}: the minute, if any, then the hangup");
                assert_eq!(budget_now(state).spent_msat, spent + (minutes + hangups) * PAID_SIGNAL_MSAT, "{case}: charged exactly what was sent");
                assert_eq!(paid.lock().unwrap().pays as u64, 1 + minutes + hangups, "{case}");
                let records = minute_records(node);
                assert_eq!(records.len(), 1, "{case}");
                assert_eq!(records[0].state, if revoke_first { spend_journal::OperationState::Unpaid } else { spend_journal::OperationState::Settled }, "{case}");
                assert_eq!(records[0].paid_msat.unwrap_or(0), minutes * PAID_SIGNAL_MSAT, "{case}");
                assert!(pending(node).is_none(), "{case}");
                assert_eq!(consent_phase(node), ConsentPhase::Ended, "{case}");
                // Every POST: the earlier ones unchanged, then exactly the expected
                // signals for this peer and call, and nothing else.
                let after = minute_snapshot(node, &paid);
                assert_eq!(after.posts[..before.posts.len()], before.posts[..], "{case}");
                let added: Vec<_> = after.posts[before.posts.len()..].iter().map(compose_signal).collect();
                let expected: Vec<_> = order[1..].iter().map(|kind| ("/messages/compose".to_string(), *kind, A.to_string(), CALL_ID.to_string())).collect();
                assert_eq!(added, expected, "{case}: no other POST");
                // One reservation per paid signal; a refused minute's is released.
                assert_eq!(after.book[..before.book.len()], before.book[..], "{case}");
                assert_eq!(after.book.len(), before.book.len() + (minutes + hangups) as usize, "{case}: no reservation left held");
                assert!(after.book.iter().all(|(_, _, settled)| *settled), "{case}: no reservation left held");
                assert_eq!(records[0].peer, A, "{case}");
                assert_eq!(records[0].call_id.as_deref(), Some(CALL_ID), "{case}");
                assert_ne!(records[0].op_id, op, "{case}");
                let hangup_ops = hangup_records(node);
                assert_eq!(hangup_ops.len() as u64, hangups, "{case}");
                if let Some(hangup) = hangup_ops.first() {
                    assert_eq!(hangup.parent_op.as_deref(), Some(op.as_str()), "{case}: the hangup is bound to the offer");
                    assert_eq!(hangup.state, spend_journal::OperationState::Settled, "{case}");
                    assert_ne!(hangup.op_id, records[0].op_id, "{case}");
                } else {
                    let offer = spend_journal(state).unwrap().operation_record(&op).unwrap().expect("the offer stays recorded");
                    assert!(!offer.call_closed, "{case}: local teardown is not the node closing the call");
                    assert!(!call_consent(state, A, CALL_ID).expect("consent kept").node_closed, "{case}");
                }
                // Revoked: no later minute passes, and nothing more is sent or paid.
                let settled = minute_snapshot(node, &paid);
                assert_eq!(rt.block_on(do_call_block(state, A, CALL_ID, 1)).unwrap_err().code, "call_not_live", "{case}");
                assert_eq!(minutes_sent(node), minutes as usize, "{case}");
                assert_eq!(minute_snapshot(node, &paid), settled, "{case}");
            }
        }
    }

    /// End lands while a minute sits between its two checks under the money
    /// lock (consent still admitted, then the hold). The minute is refused as
    /// a call that ended, not as one past its hold, and nothing is sent: no
    /// POST of any kind, no charge, no reservation, no minute operation.
    #[test]
    fn a2_end_between_the_minute_checks_reports_the_call_ended() {
        let rt = race_runtime();
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
        let before = minute_snapshot(node, &paid);
        assert_admitted_and_idle(node, "end between checks");
        let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, "end between checks");
        end_minutes(&node.state, CALL_ID);
        release.notify_one();
        let code = joined(&rt, minute, "end between checks").unwrap_err().code;
        assert_eq!(code, "call_not_live", "End came first: the call ended, not past its hold");
        assert_eq!(consent_phase(node), ConsentPhase::Ended);
        assert_eq!(minutes_sent(node), 0);
        assert_eq!(minute_snapshot(node, &paid), before, "no POST, charge, reservation or payment");
        assert!(!compose_kinds(node).contains(&403), "the ended minute hangs up nothing itself");
        assert!(minute_records(node).is_empty(), "no minute operation was begun");
        assert!(pending(node).is_none());
    }

    /// Every POST, the budget's spend and book, and the node's paid dispatches:
    /// all a minute could change.
    #[derive(Debug, PartialEq)]
    struct MinuteSnapshot { posts: Vec<(String, serde_json::Value)>, spent: u64, book: Vec<(String, u64, bool)>, pays: usize }

    fn minute_snapshot(node: &Fake, paid: &Mutex<OpsNode>) -> MinuteSnapshot {
        let pays = paid.lock().unwrap().pays;
        MinuteSnapshot { posts: node.posts(), spent: budget_now(&node.state).spent_msat, book: book(node), pays }
    }

    /// `minute_ready`'s starting point: the offer alone sent, the call admitted,
    /// no minute begun and nothing pending.
    fn assert_admitted_and_idle(node: &Fake, case: &str) {
        assert_eq!(compose_kinds(node), [400], "{case}");
        assert_eq!(consent_phase(node), ConsentPhase::Admitted, "{case}");
        assert!(minute_records(node).is_empty(), "{case}");
        assert!(pending(node).is_none(), "{case}");
    }

    /// Waits, bounded, for a minute to reach its armed pause point. If it never
    /// does, the gate is released so nothing stays paused, and the test fails.
    fn reach(rt: &tokio::runtime::Runtime, arrived: &tokio::sync::Notify, release: &tokio::sync::Notify, case: &str) {
        reach_within(rt, arrived, release, case, Duration::from_secs(5));
    }

    fn reach_within(rt: &tokio::runtime::Runtime, arrived: &tokio::sync::Notify, release: &tokio::sync::Notify, case: &str, bound: Duration) {
        if rt.block_on(async { tokio::time::timeout(bound, arrived.notified()).await }).is_err() {
            release.notify_one();
            panic!("{case}: the minute never reached its pause point");
        }
    }

    /// A spawned task's result, bounded: a task still running after 20 seconds
    /// is aborted and fails the test instead of hanging it.
    fn joined<T>(rt: &tokio::runtime::Runtime, task: tokio::task::JoinHandle<T>, case: &str) -> T {
        joined_within(rt, task, case, Duration::from_secs(20))
    }

    fn joined_within<T>(rt: &tokio::runtime::Runtime, task: tokio::task::JoinHandle<T>, case: &str, bound: Duration) -> T {
        let abort = task.abort_handle();
        match rt.block_on(async { tokio::time::timeout(bound, task).await }) {
            Ok(done) => done.unwrap(),
            Err(_) => {
                abort.abort();
                panic!("{case}: did not finish in time");
            }
        }
    }

    /// The call's consent phase once it reads Ended, or after two seconds.
    fn phase_once_ended(node: &Fake) -> ConsentPhase {
        let deadline = Instant::now() + Duration::from_secs(2);
        while consent_phase(node) != ConsentPhase::Ended && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(2));
        }
        consent_phase(node)
    }

    /// The call's hangup operations.
    fn hangup_records(node: &Fake) -> Vec<spend_journal::OperationRecord> {
        spend_journal(&node.state).unwrap().call_operations_for(OWN, None, Some(CALL_ID)).unwrap()
            .into_iter().filter(|r| r.kind == "call_hangup").collect()
    }

    /// The kind and call id of a compose POST, and its recipient.
    fn compose_signal(post: &(String, serde_json::Value)) -> (String, u64, String, String) {
        let (path, body) = post;
        let call_id = body["plaintext"].as_str().and_then(|p| serde_json::from_str::<serde_json::Value>(p).ok())
            .and_then(|p| p["call_id"].as_str().map(str::to_string)).unwrap_or_default();
        (path.clone(), body["kind"].as_u64().unwrap_or(0), body["recipient"].as_str().unwrap_or_default().to_string(), call_id)
    }

    /// The owner's End, or local teardown, begins while a minute sits between
    /// its two checks under the money lock. Either revokes at once; the minute
    /// is refused as a call that ended and sends nothing. End's own hangup goes
    /// out after it, alone and paid once; teardown sends and charges nothing.
    #[test]
    fn a2_full_end_or_teardown_between_minute_checks_preserves_accounting() {
        let rt = race_runtime();
        for ender in ["end", "close"] {
            let case = format!("{ender} between checks");
            let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
            let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
            let op = offer_op(node);
            let before = minute_snapshot(node, &paid);
            assert_admitted_and_idle(node, &case);
            let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
            let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
            reach(&rt, &arrived, &release, &case);
            let stop = {
                let op = op.clone();
                rt.spawn(async move {
                    if ender == "end" { do_op_end_call(&node.state, CALL_ID).await.map(|_| ()) }
                    else { do_op_close_call(&node.state, &op, A, CALL_ID).await }
                })
            };
            let phase = phase_once_ended(node);
            let while_paused = node.posts();
            let stop_waiting = !stop.is_finished();
            release.notify_one();
            assert_eq!(phase, ConsentPhase::Ended, "{case}: revoked at once, without the money lock");
            assert_eq!(while_paused, before.posts, "{case}: nothing goes out while the minute holds the lock");
            assert!(stop_waiting, "{case}: the ender waits for the minute's money lock");
            let minute = joined(&rt, minute, &case);
            let stop = joined(&rt, stop, &case);
            assert_eq!(minute.unwrap_err().code, "call_not_live", "{case}: the call ended, not past its hold");
            stop.unwrap();
            let after = minute_snapshot(node, &paid);
            assert_eq!(after.posts[..before.posts.len()], before.posts[..], "{case}: earlier POSTs unchanged");
            let added: Vec<_> = after.posts[before.posts.len()..].iter().map(compose_signal).collect();
            assert!(minute_records(node).is_empty(), "{case}: no minute operation was begun");
            assert!(pending(node).is_none(), "{case}");
            assert_eq!(consent_phase(node), ConsentPhase::Ended, "{case}");
            assert_eq!(minutes_sent(node), 0, "{case}");
            if ender == "end" {
                assert_eq!(added, [("/messages/compose".to_string(), 403, A.to_string(), CALL_ID.to_string())], "{case}: only End's hangup goes out");
                assert_eq!(after.spent, before.spent + PAID_SIGNAL_MSAT, "{case}: the hangup alone is charged");
                assert_eq!(after.pays, before.pays + 1, "{case}");
                assert_eq!(after.book.len(), before.book.len() + 1, "{case}: one reservation, for the hangup");
                assert_eq!(after.book[..before.book.len()], before.book[..], "{case}");
                let hangups = hangup_records(node);
                assert_eq!(hangups.len(), 1, "{case}");
                assert_eq!(hangups[0].parent_op.as_deref(), Some(op.as_str()), "{case}: the hangup is bound to the offer");
                assert_eq!(hangups[0].peer, A, "{case}");
                assert_eq!(hangups[0].state, spend_journal::OperationState::Settled, "{case}");
                assert_ne!(hangups[0].op_id, op, "{case}");
            } else {
                assert_eq!(after, before, "{case}: teardown sends, charges and reserves nothing");
                assert!(hangup_records(node).is_empty(), "{case}");
                let offer = spend_journal(&node.state).unwrap().operation_record(&op).unwrap().expect("the offer stays recorded");
                assert!(!offer.call_closed, "{case}: local teardown is not the node closing the call");
                assert!(!call_consent(&node.state, A, CALL_ID).expect("consent kept").node_closed, "{case}");
            }
            // Revoked: no later minute is sent.
            let posts = node.posts();
            assert_eq!(rt.block_on(do_call_block(&node.state, A, CALL_ID, 0)).unwrap_err().code, "call_not_live", "{case}");
            assert_eq!(node.posts(), posts, "{case}");
        }
    }

    /// End begins after a minute's last consent check passed and before its POST.
    /// The call reads Ended at once, yet that one minute goes out, paid and
    /// settled, and only then End's hangup; no later minute is sent.
    #[test]
    fn a2_end_after_the_last_minute_check_sends_that_minute_then_the_hangup() {
        let rt = race_runtime();
        let case = "end after decision";
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
        let op = offer_op(node);
        let before = minute_snapshot(node, &paid);
        assert_admitted_and_idle(node, case);
        let (arrived, release) = pause_points::arm(&node.state.api_base, "after_decision");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, case);
        let stop = rt.spawn(async move { do_op_end_call(&node.state, CALL_ID).await.map(|_| ()) });
        let phase = phase_once_ended(node);
        let while_paused = node.posts();
        let stop_waiting = !stop.is_finished();
        release.notify_one();
        assert_eq!(phase, ConsentPhase::Ended, "{case}: revoked at once");
        assert_eq!(while_paused, before.posts, "{case}: nothing goes out while the minute holds the lock");
        assert!(stop_waiting, "{case}: End's hangup waits for the minute's money lock");
        let minute = joined(&rt, minute, case);
        let stop = joined(&rt, stop, case);
        minute.expect("decided before End: the minute goes out");
        stop.unwrap();
        let after = minute_snapshot(node, &paid);
        assert_eq!(after.posts[..before.posts.len()], before.posts[..], "{case}");
        let added: Vec<_> = after.posts[before.posts.len()..].iter().map(compose_signal).collect();
        let signal = |kind| ("/messages/compose".to_string(), kind, A.to_string(), CALL_ID.to_string());
        assert_eq!(added, [signal(404), signal(403)], "{case}: the minute, then the hangup");
        assert_eq!(after.spent, before.spent + 2 * PAID_SIGNAL_MSAT, "{case}: charged exactly what was sent");
        assert_eq!(after.pays, before.pays + 2, "{case}");
        assert_eq!(after.book[..before.book.len()], before.book[..], "{case}");
        let records = minute_records(node);
        assert_eq!(records.len(), 1, "{case}");
        assert_eq!(records[0].state, spend_journal::OperationState::Settled, "{case}");
        assert_eq!(records[0].paid_msat, Some(PAID_SIGNAL_MSAT), "{case}");
        assert_eq!(records[0].peer, A, "{case}");
        let hangups = hangup_records(node);
        assert_eq!(hangups.len(), 1, "{case}");
        assert_eq!(hangups[0].parent_op.as_deref(), Some(op.as_str()), "{case}: the hangup is bound to the offer");
        assert_ne!(hangups[0].op_id, records[0].op_id, "{case}");
        assert!(pending(node).is_none(), "{case}");
        assert_eq!(consent_phase(node), ConsentPhase::Ended, "{case}");
        // Revoked: the next minute is refused and nothing more is sent or paid.
        let settled = minute_snapshot(node, &paid);
        assert_eq!(rt.block_on(do_call_block(&node.state, A, CALL_ID, 1)).unwrap_err().code, "call_not_live", "{case}");
        assert_eq!(minute_snapshot(node, &paid), settled, "{case}");
        assert_eq!(minutes_sent(node), 1, "{case}");
    }

    /// A refusal that lands while a minute sits between its two checks stays
    /// the answer, with its own code and words: not "ended", not "past the
    /// hold". Nothing is sent, charged or begun.
    #[test]
    fn a2_a_refusal_between_the_minute_checks_keeps_its_own_reason() {
        const CODE: &str = "test_refused_between_checks";
        const WORDS: &str = "Synthetic refusal text for this test only.";
        let rt = race_runtime();
        let case = "refused between checks";
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
        let before = minute_snapshot(node, &paid);
        assert_admitted_and_idle(node, case);
        let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, case);
        node.state.call_consents.lock().unwrap().refuse(OWN, A, CALL_ID, CODE, WORDS);
        release.notify_one();
        let error = joined(&rt, minute, case).unwrap_err();
        assert_eq!((error.code, error.message.as_str()), (CODE, WORDS), "{case}: the refusal is the answer");
        assert_eq!(consent_phase(node), ConsentPhase::Refused { code: CODE, message: WORDS.into() }, "{case}");
        assert_eq!(minute_snapshot(node, &paid), before, "{case}: no POST, charge, reservation or payment");
        assert!(minute_records(node).is_empty(), "{case}");
        assert!(pending(node).is_none(), "{case}");
    }

    /// Synthetic: the call's consent disappears while a minute sits between its
    /// two checks (no product path removes a kept consent). The second check
    /// finds none and the minute is refused as having no consent: nothing is
    /// sent, charged, reserved or begun, and nothing is hung up.
    #[test]
    fn a2_a_consent_gone_between_the_minute_checks_pays_nothing() {
        let rt = race_runtime();
        let case = "consent gone between checks";
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
        let before = minute_snapshot(node, &paid);
        assert_admitted_and_idle(node, case);
        let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, case);
        node.state.call_consents.lock().unwrap().entries.retain(|c| !(c.node_id == OWN && c.peer == A && c.call_id == CALL_ID));
        release.notify_one();
        let error = joined(&rt, minute, case).unwrap_err();
        assert_eq!((error.code, error.message.as_str()), ("call_no_consent", NO_CONSENT), "{case}");
        assert_eq!(minute_snapshot(node, &paid), before, "{case}: no POST, charge, reservation or payment");
        assert!(minute_records(node).is_empty(), "{case}");
        assert!(pending(node).is_none(), "{case}");
    }

    /// Synthetic: a minute of this call already settled in the journal with
    /// ceiling `cap_msat`, as if paid earlier.
    fn seed_settled_minute(node: &Fake, seq: u32, cap_msat: u64) {
        let journal = spend_journal(&node.state).unwrap();
        let body = act::call_block_body(A, CALL_ID, seq).unwrap();
        let operation = (spend_journal::new_operation_id().unwrap(), spend_journal::operation(&body));
        let begun = journal.begin_operation(OWN, "/messages/compose", &body, cap_msat, Some(operation)).unwrap();
        journal.record_outcome(&begun, spend_journal::OperationState::Settled, None).unwrap();
        journal.clear().unwrap();
    }

    /// A minute whose ceiling would pass the hold the owner confirmed, as the
    /// journal counts it under the money lock: refused as past the hold, the
    /// call's consent refused for good, and the call hung up. No kind 404 goes
    /// out and no minute operation is begun; the hangup is the only POST and is
    /// paid like any hangup. Three ways there: (synthetic) the confirmed hold
    /// cleared while the minute sits between its checks, the confirmed hold
    /// used up by minutes already journaled, and a journaled ceiling so large
    /// the sum overflows.
    #[test]
    fn a2_a_minute_past_its_journaled_hold_is_refused_and_the_call_hung_up() {
        let rt = race_runtime();
        for variant in ["hold cleared between checks", "hold used up", "sum overflows"] {
            let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
            let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
            assert_admitted_and_idle(node, variant);
            match variant {
                "hold used up" => seed_settled_minute(node, 59, 600_000),
                "sum overflows" => seed_settled_minute(node, 59, u64::MAX),
                _ => {}
            }
            let seeded: Vec<_> = minute_records(node).into_iter().map(|r| (r.op_id, r.state, r.cap_msat)).collect();
            let before = minute_snapshot(node, &paid);
            let error = if variant == "hold cleared between checks" {
                let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
                let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
                reach(&rt, &arrived, &release, variant);
                node.state.call_consents.lock().unwrap().find_mut(OWN, A, CALL_ID).expect("consent kept").confirmed_msat = None;
                release.notify_one();
                joined(&rt, minute, variant).unwrap_err()
            } else {
                let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
                joined(&rt, minute, variant).unwrap_err()
            };
            assert_eq!(error.code, MINUTE_PAST_HOLD, "{variant}: {}", error.message);
            assert!(error.message.starts_with(MINUTE_PAST_HOLD_WORDS), "{variant}");
            assert_eq!(consent_phase(node), ConsentPhase::Refused { code: MINUTE_PAST_HOLD, message: MINUTE_PAST_HOLD_WORDS.into() }, "{variant}: refused for good");
            let after = minute_snapshot(node, &paid);
            assert_eq!(after.posts[..before.posts.len()], before.posts[..], "{variant}");
            let added: Vec<_> = after.posts[before.posts.len()..].iter().map(compose_signal).collect();
            assert_eq!(added, [("/messages/compose".to_string(), 403, A.to_string(), CALL_ID.to_string())], "{variant}: the hangup alone goes out");
            assert_eq!(after.spent, before.spent + PAID_SIGNAL_MSAT, "{variant}: the hangup alone is charged");
            assert_eq!(after.pays, before.pays + 1, "{variant}");
            assert_eq!(after.book[..before.book.len()], before.book[..], "{variant}");
            assert_eq!(after.book.len(), before.book.len() + 1, "{variant}: one reservation, for the hangup");
            let minutes: Vec<_> = minute_records(node).into_iter().map(|r| (r.op_id, r.state, r.cap_msat)).collect();
            assert_eq!(minutes, seeded, "{variant}: no minute operation begun");
            assert!(pending(node).is_none(), "{variant}");
            let hangups = hangup_records(node);
            assert_eq!(hangups.len(), 1, "{variant}");
            assert_eq!(hangups[0].parent_op.as_deref(), Some(offer_op(node).as_str()), "{variant}: the hangup is bound to the offer");
        }
    }

    /// The text of a caught panic.
    fn panic_text(caught: Box<dyn std::any::Any + Send>) -> String {
        caught.downcast_ref::<String>().cloned().or_else(|| caught.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default()
    }

    /// The pause helpers these tests use fail, and clean up, within bounds
    /// when the orchestration goes wrong, instead of hanging: a pause point that
    /// does not exist or is never reached, an ender that never revokes or fails,
    /// a task that never finishes, and two nodes paused at the same point.
    #[test]
    fn a2_paused_minute_orchestration_fails_within_bounds() {
        let rt = race_runtime();
        let short = Duration::from_millis(500);
        let ready = || -> (&'static Fake, Arc<Mutex<OpsNode>>) {
            let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
            (Box::leak(Box::new(rt.block_on(minute_ready(routes)))), paid)
        };

        // A pause point no step names: the wait for it fails, and the minute,
        // never paused, goes out.
        let case = "missing point";
        let (node, _) = ready();
        let (arrived, release) = pause_points::arm(&node.state.api_base, "no_such_point");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| reach_within(&rt, &arrived, &release, case, short)));
        assert!(panic_text(failed.expect_err("the wait must fail")).contains("never reached its pause point"), "{case}");
        joined(&rt, minute, case).expect("not paused: the minute goes out");
        assert_eq!(minutes_sent(node), 1, "{case}");

        // A minute that fails before its pause point: the wait fails and releases
        // the gate it left armed, so a later minute is not paused there.
        let case = "unreached point";
        let (node, _) = ready();
        let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 1));
        let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| reach_within(&rt, &arrived, &release, case, short)));
        assert!(panic_text(failed.expect_err("the wait must fail")).contains("never reached its pause point"), "{case}");
        assert_eq!(joined(&rt, minute, case).unwrap_err().code, "call_block_not_due", "{case}");
        let later = rt.block_on(async { tokio::time::timeout(Duration::from_secs(5), do_call_block(&node.state, A, CALL_ID, 0)).await });
        assert!(later.is_ok(), "{case}: the unreached gate was released; a later minute is not left paused");
        later.unwrap().expect("the later minute goes out");
        assert_eq!(minutes_sent(node), 1, "{case}");

        // An ender that never revokes (End for another call): the wait for Ended
        // gives up within its bound; released, the minute goes out and the ender
        // reports its own error.
        let case = "ender never revokes";
        let (node, _) = ready();
        let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, case);
        let stop = rt.spawn(do_op_end_call(&node.state, "fedcba9876543210fedcba9876543210"));
        let waited = Instant::now();
        let phase = phase_once_ended(node);
        let waited = waited.elapsed();
        release.notify_one();
        assert_eq!(phase, ConsentPhase::Admitted, "{case}");
        assert!(waited < Duration::from_secs(5), "{case}: the wait for Ended is bounded");
        joined(&rt, minute, case).expect("not revoked: the minute goes out");
        assert_eq!(joined(&rt, stop, case).unwrap_err().code, "call_not_found", "{case}");
        assert_eq!(compose_kinds(node), [400, 404], "{case}");

        // An ender that revokes and then fails (teardown naming no recorded
        // admission): the minute is still refused, and the ender's error is
        // returned, not lost.
        let case = "ender error";
        let (node, paid) = ready();
        let before = minute_snapshot(node, &paid);
        let (arrived, release) = pause_points::arm(&node.state.api_base, "between_block_checks");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, case);
        let stop = rt.spawn(do_op_close_call(&node.state, "00000000-0000-4000-8000-000000000000", A, CALL_ID));
        let phase = phase_once_ended(node);
        release.notify_one();
        assert_eq!(phase, ConsentPhase::Ended, "{case}");
        assert_eq!(joined(&rt, minute, case).unwrap_err().code, "call_not_live", "{case}");
        assert_eq!(joined(&rt, stop, case).unwrap_err().code, "call_not_found", "{case}");
        assert_eq!(minute_snapshot(node, &paid), before, "{case}");

        // A task that never finishes: the bounded join fails and aborts it.
        let case = "task never finishes";
        let alive = Arc::new(());
        let held = alive.clone();
        let stuck = rt.spawn(async move {
            let _held = held;
            std::future::pending::<()>().await
        });
        let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| joined_within(&rt, stuck, case, short)));
        assert!(panic_text(failed.expect_err("the join must fail")).contains("did not finish in time"), "{case}");
        let deadline = Instant::now() + Duration::from_secs(2);
        while Arc::strong_count(&alive) > 1 && Instant::now() < deadline { std::thread::sleep(Duration::from_millis(2)); }
        assert_eq!(Arc::strong_count(&alive), 1, "{case}: the stuck task was aborted");

        // Two nodes paused at the same point: each gate is its own node's.
        // Ending and releasing one leaves the other paused and admitted.
        let case = "two nodes";
        let (first, _) = ready();
        let (second, _) = ready();
        let (arrived_1, release_1) = pause_points::arm(&first.state.api_base, "between_block_checks");
        let (arrived_2, release_2) = pause_points::arm(&second.state.api_base, "between_block_checks");
        let minute_1 = rt.spawn(do_call_block(&first.state, A, CALL_ID, 0));
        let minute_2 = rt.spawn(do_call_block(&second.state, A, CALL_ID, 0));
        reach(&rt, &arrived_1, &release_1, case);
        reach(&rt, &arrived_2, &release_2, case);
        end_minutes(&first.state, CALL_ID);
        release_1.notify_one();
        let first_minute = joined(&rt, minute_1, case);
        let second_still_paused = !minute_2.is_finished();
        let second_phase = consent_phase(second);
        release_2.notify_one();
        assert_eq!(first_minute.unwrap_err().code, "call_not_live", "{case}");
        assert!(second_still_paused, "{case}: the other node's minute stays paused");
        assert_eq!(second_phase, ConsentPhase::Admitted, "{case}: the other node's call is not ended");
        joined(&rt, minute_2, case).expect("the other node's minute goes out");
        assert_eq!((minutes_sent(first), minutes_sent(second)), (0, 1), "{case}");
    }

    /// The call ends while a minute sits just before its last consent check, and
    /// the cleanup of that refused minute then fails (`fault_points`). Cleanup
    /// saves its decision (proven unpaid: release), releases the reservation,
    /// then retires the record. A failure at either step leaves the record
    /// with that decision in place. The cleanup error is the answer, not the
    /// refusal and not a success. No kind 404 goes out and nothing more is paid.
    /// - Release fails: the reservation is still held, next to its record.
    /// - Abandon fails: the reservation is already released.
    ///
    /// Recovery carries out the saved decision without asking the node: the
    /// minute is recorded unpaid and nothing stays reserved. Nothing is released
    /// twice and no minute is paid. It runs through End (which then pays its
    /// hangup once) or through the owner's check (which sends nothing at all).
    #[test]
    fn a2_a_final_refusal_whose_cleanup_fails_reports_it_and_pays_nothing_more() {
        const MINUTE_MSAT: u64 = 8_000 + 2_000;
        let rt = race_runtime();
        for (step, recovery) in [("release", "end"), ("abandon", "end"), ("release", "check")] {
            let case = format!("{step} fails, recovered by {recovery}");
            let (routes, paid) = minutes_routes_with_abandon();
            let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
            let before = minute_snapshot(node, &paid);
            assert_admitted_and_idle(node, &case);
            assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}");
            fault_points::arm(&node.state.api_base, if step == "abandon" { "unpaid_abandon" } else { "unpaid_release" });
            let (arrived, release) = pause_points::arm(&node.state.api_base, "before_decision");
            let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
            reach(&rt, &arrived, &release, &case);
            end_minutes(&node.state, CALL_ID);
            release.notify_one();
            let error = joined(&rt, minute, &case).unwrap_err();
            assert_eq!(error.code, "spend_unknown", "{case}: the cleanup error is the answer: {}", error.message);
            assert!(error.message.ends_with("Synthetic fault for this test only."), "{case}: {}", error.message);

            // Nothing sent or paid. The record stays, with the decision saved.
            let after = minute_snapshot(node, &paid);
            assert_eq!(after.posts, before.posts, "{case}: no kind 404, no other POST");
            assert_eq!((after.spent, after.pays), (before.spent, before.pays), "{case}: nothing paid");
            let records = minute_records(node);
            assert_eq!(records.len(), 1, "{case}");
            let id = records[0].op_id.clone();
            assert_eq!((&records[0].state, records[0].paid_msat), (&spend_journal::OperationState::Unknown, None), "{case}");
            let kept = pending(node).expect("the record stays");
            assert_eq!(kept.operation_id.as_deref(), Some(id.as_str()), "{case}");
            assert!(kept.unpaid_release.as_ref().is_some_and(|d| d.outcome == spend_journal::OperationState::Unpaid && d.restore.is_none()), "{case}: the decision is saved");
            assert_eq!(no_pending_spend(&node.state).unwrap_err().code, "spend_unknown", "{case}: the fence holds");
            assert_eq!(after.book[..before.book.len()], before.book[..], "{case}");
            if step == "release" {
                assert_eq!(after.book.len(), before.book.len() + 1, "{case}");
                let held = after.book.last().unwrap();
                assert_eq!((held.1, held.2), (MINUTE_MSAT, false), "{case}: the reservation stays held, next to its record");
                assert_eq!(budget_now(&node.state).unsettled_msat, MINUTE_MSAT, "{case}");
            } else {
                assert_eq!(after.book, before.book, "{case}: released before the abandon failed");
                assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}");
            }

            // No second try: the next minute is refused and nothing moves.
            assert_eq!(rt.block_on(do_call_block(&node.state, A, CALL_ID, 0)).unwrap_err().code, "call_not_live", "{case}");
            assert_eq!(minute_snapshot(node, &paid), after, "{case}: no automatic second spend");

            let requests = node.targets().len();
            if recovery == "check" {
                assert_eq!(rt.block_on(do_spend_reconcile(&node.state)).unwrap(), UNPAID_RELEASE_FINISHED, "{case}");
                assert_eq!(node.targets().len(), requests, "{case}: the check asks the node nothing");
                assert_eq!(minute_snapshot(node, &paid), MinuteSnapshot { book: before.book.clone(), ..after }, "{case}: the reservation alone is freed");
                assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}");
                assert!(pending(node).is_none(), "{case}");
                assert!(no_pending_spend(&node.state).is_ok(), "{case}: the fence lifts");
                assert_eq!(ledger_record(node, &id)["state"], "unpaid", "{case}");
            }
            // End finishes what is left without asking about the minute, then pays the hangup once.
            let end = rt.block_on(do_op_end_call(&node.state, CALL_ID)).unwrap();
            assert_eq!((end.kind.as_str(), &end.state, end.paid_msat),
                ("call_hangup", &spend_journal::OperationState::Settled, Some(PAID_SIGNAL_MSAT)), "{case}: a paid hangup");
            assert_eq!(compose_kinds(node), [400, 403], "{case}: no minute, one hangup");
            assert_eq!(budget_now(&node.state).spent_msat, before.spent + PAID_SIGNAL_MSAT, "{case}: only the hangup is charged");
            assert_eq!(paid.lock().unwrap().pays, before.pays + 1, "{case}");
            assert!(pending(node).is_none(), "{case}");
            assert_eq!(ledger_record(node, &id)["state"], "unpaid", "{case}");
            assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}: nothing left reserved");
            let ended = book(node);
            assert_eq!(ended[..before.book.len()], before.book[..], "{case}");
            assert_eq!(ended.len(), before.book.len() + 1, "{case}: the hangup's row alone");
            assert_eq!((ended.last().unwrap().1, ended.last().unwrap().2), (PAID_SIGNAL_MSAT, true), "{case}");
            let lookups: Vec<_> = node.targets().into_iter().filter(|t| t.contains("/messages/operations/")).collect();
            assert!(lookups.is_empty(), "{case}: the saved decision needs no lookup: {lookups:?}");
        }
    }

    /// A minute refused at the recheck just before its POST (a connection
    /// cooldown began meanwhile) whose reservation then fails to release: the
    /// same as at the final consent check. The record stays with its decision
    /// and the reservation held, and End finishes both before its hangup.
    #[test]
    fn a2_a_minute_refused_at_its_dispatch_recheck_keeps_its_record_when_the_release_fails() {
        const MINUTE_MSAT: u64 = 8_000 + 2_000;
        let rt = race_runtime();
        let case = "dispatch recheck";
        let (routes, paid) = minutes_routes_with_abandon();
        let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
        let before = minute_snapshot(node, &paid);
        assert_admitted_and_idle(node, case);
        fault_points::arm(&node.state.api_base, "unpaid_release");
        let (arrived, release) = pause_points::arm(&node.state.api_base, "before_dispatch");
        let minute = rt.spawn(do_call_block(&node.state, A, CALL_ID, 0));
        reach(&rt, &arrived, &release, case);
        node.state.remote_retry.failed(&remote_access::RemoteError::RateLimited(60));
        release.notify_one();
        let error = joined(&rt, minute, case).unwrap_err();
        assert_eq!(error.code, "spend_unknown", "{case}: {}", error.message);
        assert!(error.message.ends_with("Synthetic fault for this test only."), "{case}: {}", error.message);
        let after = minute_snapshot(node, &paid);
        assert_eq!(after.posts, before.posts, "{case}: no kind 404");
        assert_eq!((after.spent, after.pays), (before.spent, before.pays), "{case}");
        assert_eq!(after.book.len(), before.book.len() + 1, "{case}");
        assert_eq!((after.book.last().unwrap().1, after.book.last().unwrap().2), (MINUTE_MSAT, false), "{case}: still held");
        let records = minute_records(node);
        assert_eq!(records.len(), 1, "{case}");
        let id = records[0].op_id.clone();
        let kept = pending(node).expect("the record stays");
        assert_eq!(kept.operation_id.as_deref(), Some(id.as_str()), "{case}");
        assert!(kept.unpaid_release.is_some(), "{case}: the decision is saved");

        node.state.remote_retry.reset_for_replacement();
        end_minutes(&node.state, CALL_ID);
        let end = rt.block_on(do_op_end_call(&node.state, CALL_ID)).unwrap();
        assert_eq!(end.kind, "call_hangup", "{case}");
        assert_eq!(compose_kinds(node), [400, 403], "{case}");
        assert_eq!(paid.lock().unwrap().pays, before.pays + 1, "{case}: the hangup alone is paid");
        assert!(pending(node).is_none(), "{case}");
        assert_eq!(ledger_record(node, &id)["state"], "unpaid", "{case}");
        assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}: nothing left reserved");
        assert!(!node.targets().iter().any(|t| t.contains("/messages/operations/")), "{case}: no lookup");
    }

    /// A paid read the node refuses before paying, whose reservation then fails
    /// to release. The read's record stays, with the cleanup's decision saved,
    /// and its reservation is still held; nothing is paid or fetched again. A
    /// read has no operation id, yet the owner's check needs none: it carries
    /// out the saved decision without a single request to the node, and new
    /// sends are no longer fenced.
    #[tokio::test]
    async fn a_read_refused_before_paying_keeps_its_record_when_the_release_fails() {
        let body = serde_json::json!({"error": "porch_knock_first: detail", "code": 409, "reason": "porch_knock_first"}).to_string();
        let (node, peer, _) = porch_node(Arc::new(move |_, _, _| (409, body.clone())));
        porch_budget(&node, &peer).await;
        fault_points::arm(&node.state.api_base, "unpaid_release");
        let error = do_porch_read(&node.state, &peer, "/index.md", 6_000).await.unwrap_err();
        assert_eq!(error.code, "spend_unknown", "{}", error.message);
        assert!(error.message.ends_with("Synthetic fault for this test only."), "{}", error.message);
        assert_eq!(fetches(&node).len(), 1);
        assert_eq!((budget_now(&node.state).spent_msat, budget_now(&node.state).unsettled_msat), (0, 6_000), "held, never paid");
        let held = pending(&node).expect("the record stays");
        assert!(held.unpaid_release.as_ref().is_some_and(|d| d.restore.is_none()), "the decision is saved");
        assert_eq!(book(&node), [(held.charge_id().to_string(), 6_000, false)]);
        assert_eq!(no_pending_spend(&node.state).unwrap_err().code, "spend_unknown", "the fence holds");

        let requests = node.targets().len();
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap(), UNPAID_RELEASE_FINISHED);
        assert_eq!(node.targets().len(), requests, "no request to the node at all");
        assert_eq!(fetches(&node).len(), 1, "nothing fetched or paid again");
        assert_eq!((budget_now(&node.state).spent_msat, budget_now(&node.state).unsettled_msat), (0, 0), "the reservation is freed");
        assert!(book(&node).is_empty());
        assert!(pending(&node).is_none());
        assert!(no_pending_spend(&node.state).is_ok(), "new sends are no longer fenced");
    }

    /// The decision cannot be saved (`fault_points`, before the save): that
    /// error is the answer and nothing is released. The record and the
    /// reservation stay exactly as before the cleanup began, and the owner's
    /// check, which has no saved decision to carry out, frees nothing.
    #[tokio::test]
    async fn a_read_whose_unpaid_decision_cannot_be_saved_releases_nothing() {
        let body = serde_json::json!({"error": "porch_knock_first: detail", "code": 409, "reason": "porch_knock_first"}).to_string();
        let (node, peer, _) = porch_node(Arc::new(move |_, _, _| (409, body.clone())));
        porch_budget(&node, &peer).await;
        fault_points::arm(&node.state.api_base, "unpaid_decision");
        let error = do_porch_read(&node.state, &peer, "/index.md", 6_000).await.unwrap_err();
        assert_eq!(error.code, "spend_unknown", "{}", error.message);
        assert!(error.message.ends_with("Synthetic fault for this test only."), "{}", error.message);
        let held = pending(&node).expect("the record stays");
        assert!(held.unpaid_release.is_none(), "no decision was saved");
        assert_eq!(book(&node), [(held.charge_id().to_string(), 6_000, false)], "nothing released");
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap_err().code, "spend_unknown");
        assert_eq!(budget_now(&node.state).unsettled_msat, 6_000, "still held");
        assert_eq!(pending(&node).unwrap().id, held.id);
        assert_eq!(fetches(&node).len(), 1);
    }

    /// A delivery retry (its message paid, not delivered) refused just before its
    /// POST, whose retry reservation then fails to release. The retry's record
    /// stays, in flight, with the decision saved and the retry's reservation
    /// held. The owner's check carries out the decision without asking the node:
    /// the retry's reservation alone is released and the paid, undelivered
    /// record is put back exactly. The original paid row is never touched, and
    /// nothing is sent or paid again. With and without operation ids.
    #[test]
    fn a_delivery_retry_refused_before_its_post_keeps_its_record_when_the_release_fails() {
        let rt = race_runtime();
        for operations in [true, false] {
            let case = if operations { "operation ids" } else { "no operation ids" };
            let (fake_node, ops) = if operations {
                let (node, ops) = ops_fake(|n| { n.script = vec![("paid", false)]; n.settled_incomplete = true; });
                (node, Some(ops))
            } else {
                (fake(AuthMode::Local, compose_watch(vec![psi_502(2000, 0, 2000, PSI_TIMEOUT)]).0), None)
            };
            let node: &'static Fake = Box::leak(Box::new(fake_node));
            let pays = || ops.as_ref().map(|o| o.lock().unwrap().pays);
            let record = rt.block_on(psi_first(node));
            assert_eq!(record.operation_id.is_some(), operations, "{case}");
            let original = (record.request_hash.clone(), 14_000, true);
            let retry_row = format!("{}-retry-1", record.request_hash);
            assert_eq!(book(node), [original.clone()], "{case}");
            let (composes, paid_before) = (compose_bodies(node).len(), pays());
            fault_points::arm(&node.state.api_base, "unpaid_release");
            let (arrived, release) = pause_points::arm(&node.state.api_base, "before_dispatch");
            let retry = rt.spawn(async move { do_message_retry(&node.state, A, "gm", Some(14_000)).await });
            reach(&rt, &arrived, &release, case);
            node.state.remote_retry.failed(&remote_access::RemoteError::RateLimited(60));
            release.notify_one();
            let error = joined(&rt, retry, case).unwrap_err();
            assert_eq!(error.code, "spend_unknown", "{case}: {}", error.message);
            assert!(error.message.ends_with("Synthetic fault for this test only."), "{case}: {}", error.message);
            assert_eq!(compose_bodies(node).len(), composes, "{case}: the retry was not sent");
            assert_eq!(book(node), [original.clone(), (retry_row.clone(), 14_000, false)], "{case}: the retry's reservation stays held");
            let kept = pending(node).expect("the retry's record stays");
            assert_eq!(kept.charge_id.as_deref(), Some(retry_row.as_str()), "{case}");
            assert_eq!(kept.rollback_charge_id.as_deref(), Some(record.request_hash.as_str()), "{case}");
            assert_eq!(kept.operation_id, record.operation_id, "{case}");
            assert_eq!(kept.undelivered.as_ref().map(|u| (u.in_flight, u.attempts)), Some((true, 1)), "{case}");
            let decided = kept.unpaid_release.as_ref().expect("the decision is saved");
            assert_eq!(decided.outcome, spend_journal::OperationState::PaidUndelivered, "{case}: the original payment still exists");
            assert_eq!(serde_json::to_value(decided.restore.as_deref().expect("the paid record")).unwrap(), serde_json::to_value(&record).unwrap(), "{case}");

            node.state.remote_retry.reset_for_replacement();
            let requests = node.targets().len();
            assert_eq!(rt.block_on(do_spend_reconcile(&node.state)).unwrap(), UNPAID_RELEASE_FINISHED, "{case}");
            assert_eq!(node.targets().len(), requests, "{case}: no request to the node");
            assert_eq!(book(node), [original], "{case}: the retry's reservation alone is released");
            assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}");
            assert_eq!(serde_json::to_value(pending(node).expect("the paid, undelivered record is back")).unwrap(),
                serde_json::to_value(&record).unwrap(), "{case}: put back exactly");
            assert_eq!((compose_bodies(node).len(), pays()), (composes, paid_before), "{case}: nothing sent or paid again");
        }
    }

    /// `ops_node` on a node that also confirms an operation's abandon.
    fn ops_fake_with_abandon() -> (Fake, Arc<Mutex<OpsNode>>) {
        let (inner, ops) = ops_node();
        (fake(AuthMode::Local, with_abandon(inner)), ops)
    }

    /// `inner` on a node that also confirms an operation's abandon.
    fn with_abandon(inner: Routes) -> Routes {
        Arc::new(move |m, p, b| {
            if p == "/status" {
                return (200, serde_json::json!({"api_capabilities": ["paid_send_caps_v1", "room_terminal_outcomes_v1",
                    "message_operations_v1", "message_operation_abandon_v1"]}).to_string());
            }
            if let Some(id) = p.strip_prefix("/messages/operations/").and_then(|id| id.strip_suffix("/abandon")) {
                return (200, op_reply(id, "abandoned"));
            }
            inner(m, p, b)
        })
    }

    /// A message is paid; an identical one (same charge id) is refused just
    /// before its POST, its reservation is released, and retiring its record
    /// then fails. The owner's check, in this process or after a restart,
    /// finishes it: the earlier payment's settled row, the spend and the
    /// contact's usage stay exactly as they were, and nothing is sent or paid
    /// again.
    #[test]
    fn an_identical_send_whose_clear_fails_after_its_release_keeps_the_earlier_payment() {
        let rt = race_runtime();
        for restarted in [false, true] {
            let case = if restarted { "after a restart" } else { "in this process" };
            let (fake_node, ops) = ops_fake_with_abandon();
            let node: &'static Fake = Box::leak(Box::new(fake_node));
            rt.block_on(spend_advance(&node.state, true)).unwrap();
            rt.block_on(do_message_send(&node.state, A, false, "gm", 14000, None)).expect("the first message goes");
            let paid = book(node);
            assert!(paid.len() == 1 && paid[0].2 && paid[0].1 > 0, "{case}: {paid:?}");
            let usage = |node: &Fake| budget_now(&node.state).rows.into_iter().find(|r| r.target == A).map(|r| (r.spent_msat, r.accounted_msat, r.unsettled_msat));
            let (spent, contact) = (budget_now(&node.state).spent_msat, usage(node));

            fault_points::arm(&node.state.api_base, "unpaid_abandon");
            let (arrived, release) = pause_points::arm(&node.state.api_base, "before_dispatch");
            let second = rt.spawn(async move { do_message_send(&node.state, A, false, "gm", 14000, None).await });
            reach(&rt, &arrived, &release, case);
            node.state.remote_retry.failed(&remote_access::RemoteError::RateLimited(60));
            release.notify_one();
            let error = joined(&rt, second, case).unwrap_err();
            assert_eq!(error.code, "spend_unknown", "{case}: {}", error.message);
            assert!(error.message.ends_with("Synthetic fault for this test only."), "{case}: {}", error.message);
            node.state.remote_retry.reset_for_replacement();
            let kept = pending(node).expect("the second send's record stays");
            assert_eq!(kept.charge_id(), paid[0].0, "{case}: the same charge id");
            assert_eq!(book(node), paid, "{case}: the second send's reservation alone is released");

            let check = |node: &'static Fake| if restarted { rt.block_on(do_spend_reconcile(&reopen(node))) } else { rt.block_on(do_spend_reconcile(&node.state)) };
            check(node).expect("the owner's check finishes the cleanup");
            for round in ["checked", "checked again"] {
                assert_eq!(book(node), paid, "{case}, {round}: the earlier payment's row stays, settled");
                assert_eq!(budget_now(&node.state).spent_msat, spent, "{case}, {round}: the spend is unchanged");
                assert_eq!(usage(node), contact, "{case}, {round}: the contact's usage is unchanged");
                if round == "checked" { check(node).expect("a second check changes nothing"); }
            }
            assert!(no_pending_spend(&node.state).is_ok(), "{case}");
            assert_eq!(compose_bodies(node).len(), 1, "{case}: the second message was never sent");
            assert_eq!(ops.lock().unwrap().pays, 1, "{case}: paid once");
        }
    }

    /// As above, but the earlier identical message cost nothing: its row
    /// settled at zero. The second send's reservation is released and retiring
    /// its record fails. The owner's check, in this process or after a restart,
    /// and checked again, releases nothing more: the zero row stays exactly as
    /// it was, with its evidence, and so does the contact's usage. Nothing is
    /// looked up, sent or paid again.
    #[test]
    fn an_identical_send_whose_clear_fails_after_its_release_keeps_an_earlier_send_settled_at_zero() {
        let rt = race_runtime();
        for restarted in [false, true] {
            let case = if restarted { "after a restart" } else { "in this process" };
            let (inner, ops) = ops_node();
            let node: &'static Fake = Box::leak(Box::new(fake(AuthMode::Local, with_abandon(first_send_free(inner)))));
            rt.block_on(spend_advance(&node.state, true)).unwrap();
            rt.block_on(do_message_send(&node.state, A, false, "gm", 14000, None)).expect("the first message goes");
            let first = book(node);
            assert!(first.len() == 1 && first[0].2 && first[0].1 == 0, "{case}: settled at zero: {first:?}");
            let usage = |node: &Fake| budget_now(&node.state).rows.into_iter().find(|r| r.target == A).map(|r| (r.spent_msat, r.accounted_msat, r.unsettled_msat));
            let (before, spent, contact) = (whole_book(node), budget_now(&node.state).spent_msat, usage(node));

            fault_points::arm(&node.state.api_base, "unpaid_abandon");
            let (arrived, release) = pause_points::arm(&node.state.api_base, "before_dispatch");
            let second = rt.spawn(async move { do_message_send(&node.state, A, false, "gm", 14000, None).await });
            reach(&rt, &arrived, &release, case);
            node.state.remote_retry.failed(&remote_access::RemoteError::RateLimited(60));
            release.notify_one();
            let error = joined(&rt, second, case).unwrap_err();
            assert_eq!(error.code, "spend_unknown", "{case}: {}", error.message);
            assert!(error.message.ends_with("Synthetic fault for this test only."), "{case}: {}", error.message);
            node.state.remote_retry.reset_for_replacement();
            let kept = pending(node).expect("the second send's record stays");
            assert_eq!(kept.charge_id(), first[0].0, "{case}: the same charge id");
            assert!(kept.unpaid_release.is_some(), "{case}: its unpaid decision is saved");
            assert_eq!(whole_book(node), before, "{case}: the second send's reservation alone is released");
            let lookups = gets(node).len();

            let check = |node: &'static Fake| if restarted { rt.block_on(do_spend_reconcile(&reopen(node))) } else { rt.block_on(do_spend_reconcile(&node.state)) };
            check(node).expect("the owner's check finishes the cleanup");
            for round in ["checked", "checked again"] {
                assert_eq!(whole_book(node), before, "{case}, {round}: the earlier zero row stays, as it was");
                assert_eq!(usage(node), contact, "{case}, {round}: the contact's usage is unchanged");
                assert_eq!(budget_now(&node.state).spent_msat, spent, "{case}, {round}: the spend is unchanged");
                assert!(pending(node).is_none(), "{case}, {round}: no decision is left pending");
                if round == "checked" { check(node).expect("a second check changes nothing"); }
            }
            assert!(no_pending_spend(&node.state).is_ok(), "{case}");
            assert_eq!(gets(node).len(), lookups, "{case}: nothing was looked up");
            assert_eq!(compose_bodies(node).len(), 1, "{case}: the second message was never sent");
            assert_eq!(ops.lock().unwrap().pays, 1, "{case}: nothing paid again");
        }
    }

    /// The release helper on its own, against a book that holds an earlier
    /// identical send settled at zero next to this attempt's held reservation
    /// (itself zero), and settled zero rows of other kinds: one without payment
    /// evidence and one a duplicate canonical payment. Only the held row goes.
    /// Replayed, it releases nothing more, and a settled zero row with no held
    /// row after it is never released.
    #[tokio::test]
    async fn releasing_an_attempt_takes_only_its_held_row_never_a_settled_zero_row() {
        let node = fake(AuthMode::Local, happy());
        spend_advance(&node.state, true).await.unwrap();
        let now = now_ms();
        let row = |id: &str, msat: u64, settled: bool, paid: Option<budget::Paid>| budget::Entry {
            id: id.into(), at_ms: now, target: A.into(), room: false, msat, settled, paid,
        };
        let zero = Some(budget::Paid { msat: 0, fee_unknown: false });
        let settled = vec![
            row("same", 0, true, zero),
            row("no-evidence", 0, true, None),
            row("duplicate-payment", 0, true, zero),
        ];
        with_book(&node.state, true, |b| {
            b.ledger.extend(settled.iter().cloned());
            b.ledger.push(row("same", 0, false, None));
            Ok(())
        }).unwrap();
        let ledger = |node: &Fake| with_book(&node.state, false, |b| Ok(b.ledger.clone())).unwrap();

        release_own_reservation(&node.state, "same").unwrap();
        assert_eq!(ledger(&node), settled, "only this attempt's held zero row is released");
        for id in ["same", "same", "no-evidence", "duplicate-payment", "absent"] {
            release_own_reservation(&node.state, id).unwrap();
            assert_eq!(ledger(&node), settled, "{id}: a settled row is never released");
        }
    }

    /// A paid, undelivered message's delivery retry is refused just before its
    /// POST; the retry's reservation is released and retiring its record then
    /// fails. The owner's check, in this process or after a restart, puts the
    /// paid, undelivered record back: the next check reports it as known and
    /// undelivered, and the original payment's accounting is intact. From
    /// there, stopping the retries works, and so does a later retry.
    #[test]
    fn a_delivery_retry_whose_clear_fails_after_its_release_recovers_to_the_undelivered_record() {
        let rt = race_runtime();
        for restarted in [false, true] {
            for then in ["dismiss", "retry"] {
                let case = format!("{} then {then}", if restarted { "after a restart" } else { "in this process" });
                let (fake_node, ops) = ops_fake(|n| { n.script = vec![("paid", false)]; n.settled_incomplete = true; });
                let node: &'static Fake = Box::leak(Box::new(fake_node));
                let record = rt.block_on(psi_first(node));
                let original = book(node);
                assert_eq!(original, [(record.request_hash.clone(), 14_000, true)], "{case}");
                let (composes, pays) = (compose_bodies(node).len(), ops.lock().unwrap().pays);

                fault_points::arm(&node.state.api_base, "unpaid_abandon");
                let (arrived, release) = pause_points::arm(&node.state.api_base, "before_dispatch");
                let retry = rt.spawn(async move { do_message_retry(&node.state, A, "gm", Some(14_000)).await });
                reach(&rt, &arrived, &release, &case);
                node.state.remote_retry.failed(&remote_access::RemoteError::RateLimited(60));
                release.notify_one();
                let error = joined(&rt, retry, &case).unwrap_err();
                assert_eq!(error.code, "spend_unknown", "{case}: {}", error.message);
                assert!(error.message.ends_with("Synthetic fault for this test only."), "{case}: {}", error.message);
                node.state.remote_retry.reset_for_replacement();
                assert_eq!(book(node), original, "{case}: the retry's reservation is released");
                assert_eq!(pending(node).expect("the retry's record stays").undelivered.map(|u| u.in_flight), Some(true), "{case}");

                let check = |node: &'static Fake| if restarted { rt.block_on(do_spend_reconcile(&reopen(node))) } else { rt.block_on(do_spend_reconcile(&node.state)) };
                check(node).expect("the owner's check finishes the cleanup");
                assert_eq!(serde_json::to_value(pending(node).expect("the paid, undelivered record is back")).unwrap(),
                    serde_json::to_value(&record).unwrap(), "{case}");
                assert_eq!(check(node).unwrap_err().code, "undelivered_pending", "{case}: known, paid, undelivered");
                assert_eq!(book(node), original, "{case}: the original payment's accounting is intact");
                assert_eq!((compose_bodies(node).len(), ops.lock().unwrap().pays), (composes, pays), "{case}: nothing sent or paid");

                if then == "dismiss" {
                    do_spend_dismiss_undelivered(&node.state, &record.id).expect("stopping the retries works");
                    assert!(pending(node).is_none(), "{case}");
                    assert!(no_pending_spend(&node.state).is_ok(), "{case}");
                } else {
                    ops.lock().unwrap().settled_incomplete = false;
                    rt.block_on(do_message_retry(&node.state, A, "gm", Some(14_000))).expect("a later retry works");
                    assert!(pending(node).is_none(), "{case}: delivered");
                    assert_eq!(ops.lock().unwrap().pays, pays, "{case}: the retry pays nothing new");
                }
                let books = book(node);
                assert_eq!(books[0], original[0], "{case}: the original paid row is untouched");
                assert_eq!(budget_now(&node.state).unsettled_msat, 0, "{case}");
            }
        }
    }

    /// Records saved before the cleanup decision existed (no such field) still
    /// load, with no decision; a record without a decision never writes one.
    #[tokio::test]
    async fn a_record_from_before_the_saved_unpaid_decision_still_loads() {
        let node = fake(AuthMode::Local, happy());
        let journal = spend_journal(&node.state).unwrap();
        let body = act::compose_body(A, false, "gm").unwrap();
        let begun = journal.begin(OWN, "/messages/compose", &body, 7000).unwrap();
        drop(journal);
        let saved: serde_json::Value = serde_json::from_slice(&std::fs::read(journal_file(&node)).unwrap()).unwrap();
        assert!(saved.get("unpaid_release").is_none(), "not written without a decision");
        let mut older = saved.clone();
        older.as_object_mut().unwrap().remove("unpaid_release");
        std::fs::write(journal_file(&node), serde_json::to_vec(&older).unwrap()).unwrap();
        let loaded = pending(&node).expect("an older record loads");
        assert_eq!(loaded.id, begun.id);
        assert!(loaded.unpaid_release.is_none());
    }

    /// A minute and End or local teardown, racing freely on OS threads (the
    /// ender started at staggered delays). The outcome is one of the two the
    /// guarantee allows: no kind 404 and nothing charged for it, or exactly one,
    /// accounted, with End's hangup after it. Bounded: a deadlock fails the round
    /// after a timeout instead of hanging.
    #[test]
    fn a2_a_minute_racing_end_or_teardown_goes_before_the_hangup_or_not_at_all() {
        let rt = race_runtime();
        let mut outcomes = [0usize; 2];
        for round in 0..24u64 {
            let end = round % 2 == 0;
            let (routes, _) = minutes_routes("live", hold_json(8_000, 2_000, 60));
            // Leaked so the racing tasks can outlive a failed round.
            let node: &'static Fake = Box::leak(Box::new(rt.block_on(minute_ready(routes))));
            let op = offer_op(node);
            let spent = budget_now(&node.state).spent_msat;
            let delay = Duration::from_micros(round / 2 * 250);
            let race = async move {
                let minute = tokio::spawn(do_call_block(&node.state, A, CALL_ID, 0));
                let stop = tokio::spawn(async move {
                    tokio::time::sleep(delay).await;
                    if end { do_op_end_call(&node.state, CALL_ID).await.map(|_| ()) }
                    else { do_op_close_call(&node.state, &op, A, CALL_ID).await }
                });
                (minute.await.unwrap(), stop.await.unwrap())
            };
            let Ok((minute, stop)) = rt.block_on(async { tokio::time::timeout(Duration::from_secs(20), race).await }) else {
                rt.shutdown_background();
                panic!("round {round}: a minute and its ender did not finish (deadlock)");
            };
            stop.unwrap();
            let minutes = minutes_sent(node);
            assert!(minutes <= 1, "round {round}");
            let mut order = vec![400];
            if minutes == 1 { order.push(404); }
            if end { order.push(403); }
            assert_eq!(compose_kinds(node), order, "round {round}: the minute, if any, then the hangup");
            let charged = (minutes as u64 + u64::from(end)) * PAID_SIGNAL_MSAT;
            assert_eq!(budget_now(&node.state).spent_msat, spent + charged, "round {round}: charged exactly what was sent");
            if minutes == 0 {
                assert_eq!(minute.unwrap_err().code, "call_not_live", "round {round}");
            } else {
                minute.unwrap();
            }
            assert!(pending(node).is_none(), "round {round}");
            assert_eq!(consent_phase(node), ConsentPhase::Ended, "round {round}");
            outcomes[minutes] += 1;
        }
        eprintln!("revoked first: {}, decided first: {}", outcomes[0], outcomes[1]);
    }

    /// `minute_ready`'s routes on a node that offers the operation abandon and
    /// confirms it, as genome `message_operation_abandon_v1` does.
    fn minutes_routes_with_abandon() -> (Routes, Arc<Mutex<OpsNode>>) {
        let (inner, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        (Arc::new(move |m, p, b| {
            if p == "/status" {
                return (200, serde_json::json!({"api_capabilities": ["paid_send_caps_v1", "room_terminal_outcomes_v1",
                    "message_operations_v1", "message_operation_abandon_v1"]}).to_string());
            }
            if let Some(id) = p.strip_prefix("/messages/operations/").and_then(|id| id.strip_suffix("/abandon")) {
                return (200, op_reply(id, "abandoned"));
            }
            inner(m, p, b)
        }), paid)
    }

    /// Pay block 0 under a 60 ms request timeout, so its reply is lost. `state`:
    /// what the node made of it; `None`, it never saw it. Returns once the node
    /// has done so, with the request timeout back for what follows.
    async fn lose_minute_reply(node: &mut Fake, paid: &Arc<Mutex<OpsNode>>, state: Option<&'static str>) {
        let before = {
            let mut ops = paid.lock().unwrap();
            match state {
                Some(state) => ops.script = vec![(state, true)],
                None => ops.drop_next = true,
            }
            ops.ops.len()
        };
        node.state.spend_timeout = Duration::from_millis(60);
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "spend_unknown");
        node.state.spend_timeout = Duration::from_secs(30);
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let reached = {
                let ops = paid.lock().unwrap();
                if state.is_some() { ops.ops.len() > before } else { !ops.drop_next }
            };
            if reached { return; }
            assert!(Instant::now() < deadline, "the node never took the minute");
            tokio::time::sleep(Duration::from_millis(2)).await;
        }
    }

    /// A node that swallowed the minute: no answer within `spend_timeout`, no
    /// record of it, and the abandon confirmed. End asks by operation id, the
    /// abandon fences the minute, and End pays the hangup.
    #[tokio::test]
    async fn a2_end_reconciles_a_minute_the_node_swallowed_then_pays_the_hangup() {
        let (routes, paid) = minutes_routes_with_abandon();
        let mut node = minute_ready(routes).await;
        let spent = budget_now(&node.state).spent_msat;
        lose_minute_reply(&mut node, &paid, None).await;
        let id = pending(&node).unwrap().operation_id.unwrap();
        let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!((end.kind.as_str(), &end.state, end.paid_msat),
            ("call_hangup", &spend_journal::OperationState::Settled, Some(PAID_SIGNAL_MSAT)), "a paid hangup");
        assert_eq!(compose_kinds(&node), [400, 404, 403], "exactly one minute, then one hangup");
        assert!(pending(&node).is_none());
        assert_eq!(ledger_record(&node, &id)["state"], "unpaid");
        assert_eq!(budget_now(&node.state).spent_msat, spent + PAID_SIGNAL_MSAT, "only the hangup is charged");
        let targets = node.targets();
        let at = |what: String| targets.iter().position(|t| *t == what).unwrap_or_else(|| panic!("{what}: {targets:?}"));
        let last_compose = targets.iter().rposition(|t| t == "POST /messages/compose").unwrap();
        assert!(at(format!("GET /messages/operations/{id}")) < at(format!("POST /messages/operations/{id}/abandon")));
        assert!(at(format!("POST /messages/operations/{id}/abandon")) < last_compose, "abandoned before the hangup");
    }

    /// Their hangup closes the admission, so no End comes for a minute lost to it.
    /// The check the ended card runs by itself settles it, through the owner's
    /// path: by operation id, nothing sent, and the fence is gone.
    #[tokio::test]
    async fn a2_the_check_settles_a_minute_lost_to_their_hangup_and_sends_nothing() {
        let (routes, paid) = minutes_routes_with_abandon();
        let mut node = minute_ready(routes).await;
        lose_minute_reply(&mut node, &paid, None).await;
        let id = pending(&node).unwrap().operation_id.unwrap();
        observe_call_event(&node.state, &inbound_call_event(403, "hangup")).await;
        assert_eq!(no_pending_spend(&node.state).unwrap_err().code, "spend_unknown", "the fence holds until checked");
        let (composed, pays) = (compose_kinds(&node), paid.lock().unwrap().pays);

        assert_eq!(do_spend_reconcile(&node.state).await.unwrap(), NOTHING_PAID);

        assert_eq!(compose_kinds(&node), composed, "the check sends nothing");
        assert_eq!(ledger_record(&node, &id)["state"], "unpaid");
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        assert!(no_pending_spend(&node.state).is_ok());
        do_message_send(&node.state, A, false, "hi", 7000, None).await.expect("a message goes");
        assert_eq!(paid.lock().unwrap().pays, pays + 1, "only the message was paid");
    }

    /// The node reports the minute still paying: End says the outcome is
    /// unknown, names the pending result and sends no hangup. Once the node
    /// knows the outcome, End accounts the minute and pays the hangup.
    #[tokio::test]
    async fn a2_end_with_its_minute_still_paying_reports_unknown_and_sends_no_hangup() {
        let (routes, paid) = minutes_routes_with_abandon();
        let mut node = minute_ready(routes).await;
        let spent = budget_now(&node.state).spent_msat;
        lose_minute_reply(&mut node, &paid, Some("paying")).await;
        let held = pending(&node).unwrap();
        let id = held.operation_id.clone().unwrap();
        let error = do_op_end_call(&node.state, CALL_ID).await.unwrap_err();
        assert_eq!(error.code, "payment_unknown");
        assert_eq!(error.pending_id.as_deref(), Some(held.id.as_str()), "names the pending result");
        assert_eq!(compose_kinds(&node), [400, 404], "no hangup");
        assert_eq!(pending(&node).unwrap().id, held.id, "the fence stays");
        assert!(!node.targets().contains(&format!("POST /messages/operations/{id}/abandon")), "a paying minute is not abandoned");
        assert_eq!(consent_phase(&node), ConsentPhase::Ended);
        paid.lock().unwrap().ops.get_mut(&id).unwrap().1 = "acked";
        let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!(end.kind, "call_hangup");
        assert_eq!(compose_kinds(&node), [400, 404, 403]);
        assert!(pending(&node).is_none());
        assert_eq!(budget_now(&node.state).spent_msat, spent + 2 * PAID_SIGNAL_MSAT, "the minute and the hangup");
    }

    /// The node knows what became of the minute: End accounts it as that
    /// result, retires its slot and pays the hangup once.
    #[tokio::test]
    async fn a2_end_accounts_a_minute_with_a_known_result_then_pays_the_hangup() {
        for (outcome, recorded) in [("acked", "settled"), ("sent", "settled"), ("paid", "paid_undelivered"), ("failed_paid", "failed_paid")] {
            let (routes, paid) = minutes_routes_with_abandon();
            let mut node = minute_ready(routes).await;
            let spent = budget_now(&node.state).spent_msat;
            lose_minute_reply(&mut node, &paid, Some(outcome)).await;
            let id = pending(&node).unwrap().operation_id.unwrap();
            let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
            assert_eq!(end.kind, "call_hangup", "{outcome}");
            assert_eq!(compose_kinds(&node), [400, 404, 403], "{outcome}");
            assert_eq!(ledger_record(&node, &id)["state"], recorded, "{outcome}");
            assert!(pending(&node).is_none(), "{outcome}");
            assert_eq!(budget_now(&node.state).spent_msat, spent + 2 * PAID_SIGNAL_MSAT, "{outcome}: the minute and the hangup");
            // Ending it again changes nothing and pays nothing.
            assert_eq!(do_op_end_call(&node.state, CALL_ID).await.unwrap().op_id, end.op_id, "{outcome}");
            assert_eq!(compose_kinds(&node), [400, 404, 403], "{outcome}");
        }
    }

    /// A node with no abandon: its empty lookup cannot exclude the minute still
    /// arriving, so End stays unknown and sends no hangup.
    #[tokio::test]
    async fn a2_end_needs_the_node_to_confirm_it_abandoned_a_swallowed_minute() {
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let mut node = minute_ready(routes).await;
        lose_minute_reply(&mut node, &paid, None).await;
        let held = pending(&node).unwrap();
        let error = do_op_end_call(&node.state, CALL_ID).await.unwrap_err();
        assert_eq!(error.code, "payment_unknown");
        assert_eq!(error.pending_id.as_deref(), Some(held.id.as_str()));
        assert_eq!(compose_kinds(&node), [400, 404], "no hangup");
        assert!(!pending(&node).unwrap().resumable, "the fence stays");
    }

    // ---- A payment the wallet tried and failed ------------------------------------
    //
    // Node rc21's replies, captured from its own handlers with the wallet reporting
    // the payment failed. The POST gets 502 and `payment_unknown`, and so does a
    // lookup until the node's sweep, which runs every 15 s and moves the row to
    // `released` with its hash kept. Abandon refuses that row with the same view.

    const FAILED_HASH: &str = "6a6857524cdc4e20c9c4f8469d7e8ce0cb268ba77e7e58511925c0b9237e87b6";

    /// A minute's routing ceiling reads 0 there, a message's 5000.
    fn failed_ceiling(kind: u16) -> u64 {
        if kind == act::KIND_CALL_BLOCK { 0 } else { 5000 }
    }

    fn failed_post_reply(id: &str, kind: u16) -> String {
        serde_json::json!({"accepted": false, "code": 502, "error": "invoice payment payment failed", "max_routing_fee_msat": failed_ceiling(kind),
            "operation_id": id, "payment_hash": FAILED_HASH, "retry_allowed": false, "state": "payment_unknown"}).to_string()
    }

    fn failed_view(id: &str, kind: u16, swept: bool) -> serde_json::Value {
        serde_json::json!({"accepted": false, "amount_msat": 0, "delivered": false, "max_routing_fee_msat": failed_ceiling(kind),
            "message_id": "87837f113ee4b408a1080a73286ca9edfa2bf32fd144c8ff5261fbf6a7cf48c6", "operation_id": id,
            "payment_hash": FAILED_HASH, "retry_allowed": swept, "state": if swept { "released" } else { "payment_unknown" }})
    }

    fn ldk_status() -> serde_json::Value {
        serde_json::json!({"node_id": OWN, "lightning_backend": "ldk", "api_capabilities": ["paid_send_caps_v1", "room_terminal_outcomes_v1",
            "message_operations_v1", "message_operation_abandon_v1"]})
    }

    /// Node rc14, as far as this rule reads it: LDK, and no abandon yet.
    fn rc14_status() -> serde_json::Value {
        serde_json::json!({"node_id": OWN, "lightning_backend": "ldk", "api_capabilities": ["paid_send_caps_v1", "room_terminal_outcomes_v1", "message_operations_v1"]})
    }

    /// One failed payment on the node, and what the test may change about it.
    #[derive(Clone)]
    struct FailedPayment {
        /// The next payment of the node's failing kind fails.
        armed: Arc<std::sync::atomic::AtomicBool>,
        /// The node's sweep has run.
        swept: Arc<std::sync::atomic::AtomicBool>,
        /// `/status`. `None`: it cannot be read.
        status: Arc<Mutex<Option<serde_json::Value>>>,
        /// Fields that differ from rc21's view, for replies that must stay fenced.
        changes: Arc<Mutex<serde_json::Value>>,
        ids: Arc<Mutex<Vec<String>>>,
    }

    impl FailedPayment {
        fn sweep(&self) { self.swept.store(true, std::sync::atomic::Ordering::SeqCst); }
        fn arm(&self) { self.armed.store(true, std::sync::atomic::Ordering::SeqCst); }
        fn change(&self, changes: serde_json::Value) { *self.changes.lock().unwrap() = changes; }
        fn report(&self, status: Option<serde_json::Value>) { *self.status.lock().unwrap() = status; }
    }

    /// A node on LDK whose wallet fails the next payment of `kind`, when armed.
    fn node_failing(kind: u16, inner: Routes) -> (Routes, FailedPayment) {
        let wallet = FailedPayment {
            armed: Arc::new(std::sync::atomic::AtomicBool::new(true)),
            swept: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            status: Arc::new(Mutex::new(Some(ldk_status()))),
            changes: Arc::new(Mutex::new(serde_json::json!({}))),
            ids: Arc::new(Mutex::new(Vec::new())),
        };
        let node = wallet.clone();
        (Arc::new(move |m, p, b| {
            use std::sync::atomic::Ordering::SeqCst;
            if p == "/status" {
                return match node.status.lock().unwrap().as_ref() {
                    Some(status) => (200, status.to_string()),
                    None => (500, "{}".into()),
                };
            }
            if let Some(rest) = p.strip_prefix("/messages/operations/") {
                let (id, abandon) = rest.strip_suffix("/abandon").map_or((rest, false), |id| (id, true));
                if node.ids.lock().unwrap().iter().any(|known| known == id) {
                    let mut view = failed_view(id, kind, node.swept.load(SeqCst));
                    for (field, value) in node.changes.lock().unwrap().as_object().unwrap() {
                        view[field] = value.clone();
                    }
                    return (if abandon { 409 } else { 200 }, view.to_string());
                }
            }
            if p == "/messages/compose" {
                let body: serde_json::Value = serde_json::from_str(b).unwrap();
                if body["kind"] == kind && node.armed.swap(false, SeqCst) {
                    let id = body["operation_id"].as_str().unwrap().to_string();
                    node.ids.lock().unwrap().push(id.clone());
                    return (502, failed_post_reply(&id, kind));
                }
            }
            inner(m, p, b)
        }), wallet)
    }

    fn abandons(node: &Fake) -> usize {
        node.targets().iter().filter(|t| t.ends_with("/abandon")).count()
    }

    async fn failed_message(routes: Routes) -> (Fake, String) {
        let node = fake(AuthMode::Local, routes);
        spend_advance(&node.state, true).await.unwrap();
        let error = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err();
        assert_eq!(error.code, "payment_unknown", "{}", error.message);
        (node, error.operation_id.unwrap())
    }

    /// A message's payment failed: the fence holds until the sweep, then one check
    /// proves it unpaid. Nothing is charged, the node is not asked to abandon a row
    /// it would refuse, and sending again is a new operation.
    #[tokio::test]
    async fn a_failed_message_clears_after_the_sweep_and_goes_again_as_a_new_operation() {
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let (node, id) = failed_message(routes).await;
        let reserved = budget_now(&node.state).unsettled_msat;
        assert!(reserved > 0, "the reservation is held");
        let held = pending(&node).unwrap();
        assert_eq!(held.failure_final_on.as_deref(), Some(OWN), "this send's status vouched for the node");
        assert_eq!(do_message_send(&node.state, A, false, "another", 14000, None).await.unwrap_err().code, "spend_unknown");
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap_err().code, "payment_unknown");
        assert_eq!(pending(&node).unwrap().id, held.id, "the fence holds before the sweep");
        assert_eq!(budget_now(&node.state).unsettled_msat, reserved);
        wallet.sweep();
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap(), PAYMENT_FAILED);
        let cleared = pending(&node).unwrap();
        assert!(cleared.resumable && !cleared.budgeted, "the next send replaces it");
        assert_eq!(cleared.operation_id, None, "this id is never posted again");
        assert_eq!((cleared.accounting_msat, cleared.evidence_reservation_msat), (None, None));
        let record = ledger_record(&node, &id);
        assert_eq!((record["state"].as_str(), record["paid_msat"].as_u64()), (Some("unpaid"), Some(0)));
        assert!(book(&node).is_empty(), "the reservation is released and nothing is charged");
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        assert_eq!(abandons(&node), 0);
        assert_eq!(compose_bodies(&node).len(), 1, "nothing was sent again");
        let receipt = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap();
        let resent = receipt.operation_id.unwrap();
        assert_ne!(resent, id);
        assert_eq!(op_ids(&node), [Some(id), Some(resent)]);
        assert_eq!(settled(&node), [2000], "only the second attempt is paid");
        assert!(pending(&node).is_none());
    }

    /// The reply to the POST may be lost as well: the same check of the same row.
    #[tokio::test]
    async fn a_failed_payment_whose_reply_was_lost_clears_the_same_way() {
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let lost: Routes = Arc::new(move |m, p, b| {
            let (status, text) = routes(m, p, b);
            if p == "/messages/compose" && status == 502 { (500, "{}".into()) } else { (status, text) }
        });
        let node = fake(AuthMode::Local, lost);
        spend_advance(&node.state, true).await.unwrap();
        assert_eq!(do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err().code, "spend_unknown");
        wallet.sweep();
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap(), PAYMENT_FAILED);
        assert!(book(&node).is_empty());
        assert_eq!(abandons(&node), 0);
    }

    /// A minute's payment failed on a call the node keeps: before the sweep End
    /// stays unknown and sends no hangup; after it, End resolves the minute as
    /// unpaid and pays the hangup. Only the hangup is charged, and the next send goes.
    #[tokio::test]
    async fn a_failed_minute_clears_after_the_sweep_and_end_pays_the_hangup() {
        let (inner, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let (routes, wallet) = node_failing(act::KIND_CALL_BLOCK, inner);
        let node = minute_ready(routes).await;
        let spent = budget_now(&node.state).spent_msat;
        let minute = do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err();
        assert_eq!(minute.code, "payment_unknown");
        let id = minute.operation_id.unwrap();
        assert!(budget_now(&node.state).unsettled_msat > 0, "its reservation is held");
        let early = do_op_end_call(&node.state, CALL_ID).await.unwrap_err();
        assert_eq!(early.code, "payment_unknown");
        assert_eq!(compose_kinds(&node), [400, 404], "no hangup before the sweep");
        wallet.sweep();
        let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!((end.kind.as_str(), &end.state, end.paid_msat),
            ("call_hangup", &spend_journal::OperationState::Settled, Some(PAID_SIGNAL_MSAT)));
        assert_eq!(compose_kinds(&node), [400, 404, 403]);
        assert!(pending(&node).is_none());
        let record = ledger_record(&node, &id);
        assert_eq!((record["state"].as_str(), record["paid_msat"].as_u64()), (Some("unpaid"), Some(0)));
        assert_eq!(budget_now(&node.state).spent_msat, spent + PAID_SIGNAL_MSAT, "the hangup, not the minute");
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        assert_eq!(abandons(&node), 0);
        assert_eq!(do_op_end_call(&node.state, CALL_ID).await.unwrap().op_id, end.op_id, "ended once");
        let pays = paid.lock().unwrap().pays;
        spend_advance(&node.state, true).await.unwrap();
        do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap();
        assert_eq!(paid.lock().unwrap().pays, pays + 1, "the next send goes");
    }

    /// rc21 ends a paired caller's call when its minute fails, so it refuses the
    /// hangup before paying. End closes the admission on that refusal. No fence is
    /// left, nothing is held or charged, and both the next send and the next call go.
    #[tokio::test]
    async fn a_failed_minute_on_a_call_the_node_ended_leaves_no_fence_and_end_closes_it() {
        let (inner, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let (routes, wallet) = node_failing(act::KIND_CALL_BLOCK, inner);
        let node = minute_ready(Arc::new(move |m, p, b| {
            if p == "/messages/compose" && serde_json::from_str::<serde_json::Value>(b).unwrap()["kind"] == 403 {
                return (400, NODE_ENDED_HANGUP.into());
            }
            routes(m, p, b)
        })).await;
        let offer = offer_op(&node);
        let spent = budget_now(&node.state).spent_msat;
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "payment_unknown");
        wallet.sweep();
        let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!((end.kind.as_str(), &end.state, end.paid_msat), ("call_hangup", &spend_journal::OperationState::Unpaid, Some(0)));
        assert_eq!(compose_kinds(&node), [400, 404, 403], "the minute no longer fences the hangup");
        assert!(!admission_is_open(&node, &offer));
        assert!(pending(&node).is_none_or(|p| p.resumable && p.operation_id.is_none()));
        assert_eq!(budget_now(&node.state).spent_msat, spent);
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        let pays = paid.lock().unwrap().pays;
        spend_advance(&node.state, true).await.unwrap();
        do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap();
        do_call_signal(&node.state, A, 400, &OFFER.replace(CALL_ID, REDIAL_ID), 15000).await.expect("the contact can be called again");
        assert_eq!(paid.lock().unwrap().pays, pays + 2, "the next send and the next call go");
    }

    /// A failed offer closes its admission with nothing paid, so End sends no
    /// hangup and the contact can be called again. A failed hangup is unpaid too,
    /// closes nothing, and End sends another under a new operation.
    #[tokio::test]
    async fn a_failed_offer_or_hangup_clears_the_same_way() {
        let (inner, _) = ledger_call_routes();
        let (routes, wallet) = node_failing(act::KIND_CALL_OFFER, inner);
        let node = fake(AuthMode::Local, routes);
        approve_calls(&node).await;
        let offer = do_call_signal(&node.state, A, 400, OFFER, 15000).await.unwrap_err();
        assert_eq!(offer.code, "payment_unknown");
        wallet.sweep();
        let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!((end.kind.as_str(), &end.state, end.paid_msat), ("call_offer", &spend_journal::OperationState::Unpaid, Some(0)));
        assert_eq!(compose_kinds(&node), [400], "nothing to hang up");
        let redial = OFFER.replace(CALL_ID, "1123456789abcdef0123456789abcdef");
        do_call_signal(&node.state, A, 400, &redial, 15000).await.expect("the contact can be called again");

        let (inner, _) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let (routes, wallet) = node_failing(act::KIND_CALL_HANGUP, inner);
        let node = minute_ready(routes).await;
        let first = do_op_end_call(&node.state, CALL_ID).await.unwrap_err();
        assert_eq!(first.code, "payment_unknown");
        wallet.sweep();
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap(), PAYMENT_FAILED);
        let end = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_ne!(Some(end.op_id.clone()), first.operation_id);
        assert_eq!((end.kind.as_str(), &end.state), ("call_hangup", &spend_journal::OperationState::Settled));
        assert_eq!(compose_kinds(&node), [400, 403, 403]);
    }

    /// Only that exact reply. Anything else this node can say keeps the fence and
    /// its usual accounting: a payment still open, one on record, any money or
    /// delivery reported with it, or a release with no hash and an abandon refused.
    #[tokio::test]
    async fn every_other_reply_stays_fenced() {
        for (changes, code, accounted) in [
            (serde_json::json!({"state": "paying", "retry_allowed": false}), "payment_unknown", None),
            (serde_json::json!({"state": "payment_unknown", "retry_allowed": false}), "payment_unknown", None),
            // The state alone decides, even with every other field as in that reply.
            (serde_json::json!({"state": "paying"}), "payment_unknown", None),
            (serde_json::json!({"state": "payment_unknown"}), "payment_unknown", None),
            (serde_json::json!({"state": "something_new"}), "payment_unknown", None),
            (serde_json::json!({"state": "prepared"}), "payment_unknown", Some(0)),
            (serde_json::json!({"payment_hash": null}), "payment_unknown", None),
            // Accounted with the node's 5000 msat routing ceiling: the fee is not known.
            (serde_json::json!({"state": "paid", "amount_msat": 2000}), "undelivered_pending", Some(7000)),
            (serde_json::json!({"amount_msat": 2000}), "payment_unknown", Some(7000)),
            (serde_json::json!({"readmission_msat": 1000}), "payment_unknown", Some(6000)),
            (serde_json::json!({"fee_paid_msat": 0}), "payment_unknown", Some(0)),
            (serde_json::json!({"delivered": true}), "payment_unknown", Some(0)),
            (serde_json::json!({"accepted": true}), "payment_unknown", Some(0)),
            (serde_json::json!({"retry_allowed": false}), "payment_unknown", Some(0)),
        ] {
            let (ops, _) = ops_node();
            let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
            let (node, id) = failed_message(routes).await;
            wallet.sweep();
            wallet.change(changes.clone());
            let error = do_spend_reconcile(&reopen(&node)).await.unwrap_err();
            assert_eq!(error.code, code, "{changes}: {}", error.message);
            let held = pending(&node).unwrap();
            assert!(!held.resumable, "{changes}");
            assert_eq!(held.operation_id.as_deref(), Some(id.as_str()), "{changes}");
            assert_eq!(held.accounting_msat, accounted, "{changes}");
            assert_eq!(do_message_send(&node.state, A, false, "another", 14000, None).await.unwrap_err().code, "spend_unknown", "{changes}");
            assert_eq!(compose_bodies(&node).len(), 1, "{changes}: never sent again");
            // The rc21 reply, read after any of those, does not undo what they showed.
            wallet.change(serde_json::json!({}));
            let again = do_spend_reconcile(&reopen(&node)).await;
            if accounted.is_some_and(|paid| paid > 0) {
                assert!(again.is_err(), "{changes}: an amount on record is never erased");
                assert!(!pending(&node).unwrap().resumable, "{changes}");
            }
        }
    }

    /// Dispatched under a status that vouched for it, then read when the node no
    /// longer shows that status: another wallet, a node older than rc15, or another
    /// identity. So nothing changes for them; an unreadable status keeps it all.
    #[tokio::test]
    async fn the_same_reply_from_another_wallet_or_an_older_node_stays_fenced() {
        let caps = ldk_status()["api_capabilities"].clone();
        for status in [
            serde_json::json!({"node_id": OWN, "lightning_backend": "lnd", "api_capabilities": caps}),
            serde_json::json!({"node_id": OWN, "lightning_backend": "lnbits", "api_capabilities": caps}),
            serde_json::json!({"node_id": OWN, "lightning_backend": "cln", "api_capabilities": caps}),
            serde_json::json!({"node_id": OWN, "lightning_backend": "mock", "api_capabilities": caps}),
            serde_json::json!({"node_id": OWN, "api_capabilities": caps}),
            rc14_status(),
            serde_json::json!({"node_id": OWN, "lightning_backend": "ldk"}),
            serde_json::json!({"node_id": A, "lightning_backend": "ldk", "api_capabilities": caps}),
            serde_json::json!({"lightning_backend": "ldk", "api_capabilities": caps}),
        ] {
            let (ops, _) = ops_node();
            let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
            let (node, id) = failed_message(routes).await;
            wallet.sweep();
            wallet.report(Some(status.clone()));
            let error = do_spend_reconcile(&reopen(&node)).await.unwrap_err();
            assert_eq!(error.code, "payment_unknown", "{status}: {}", error.message);
            let held = pending(&node).unwrap();
            assert!(!held.resumable && held.evidence_reservation_msat.is_some(), "{status}");
            assert_eq!(held.operation_id.as_deref(), Some(id.as_str()), "{status}");
            assert_eq!(do_message_send(&node.state, A, false, "another", 14000, None).await.unwrap_err().code, "spend_unknown", "{status}");
            assert_eq!(abandons(&node), 0, "{status}");
        }
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let (node, _) = failed_message(routes).await;
        wallet.sweep();
        wallet.report(None);
        let before = book(&node);
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap_err().code, "spend_unknown");
        assert!(!pending(&node).unwrap().resumable);
        assert_eq!(book(&node), before, "nothing was released or accounted");
    }

    /// The app itself holds evidence of money for this operation, whatever put it
    /// there: the reply does not outweigh it. The slot and the ledger each count.
    #[tokio::test]
    async fn a_failure_read_against_a_payment_on_record_stays_fenced() {
        for (in_slot, on_record) in [
            (serde_json::json!({"undelivered": {"peer": A, "paid_msat": 2000, "retry": true, "in_flight": true}}), serde_json::json!({})),
            (serde_json::json!({"over_budget": true}), serde_json::json!({})),
            (serde_json::json!({"accounting_msat": 2000, "evidence_reservation_msat": 14000}), serde_json::json!({})),
            (serde_json::json!({"paid": {"msat": 2000, "fee_unknown": false}}), serde_json::json!({})),
            (serde_json::json!({"paid": {"msat": 0, "fee_unknown": true}}), serde_json::json!({})),
            (serde_json::json!({}), serde_json::json!({"paid_msat": 2000})),
            (serde_json::json!({}), serde_json::json!({"state": "paid"})),
            (serde_json::json!({}), serde_json::json!({"state": "settled"})),
            (serde_json::json!({}), serde_json::json!({"state": "closed"})),
            (serde_json::json!({}), serde_json::json!({"state": "failed_paid"})),
        ] {
            let (ops, _) = ops_node();
            let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
            let (node, id) = failed_message(routes).await;
            wallet.sweep();
            let patch = |path: &std::path::Path, changes: &serde_json::Value| {
                let mut value: serde_json::Value = serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
                for (field, changed) in changes.as_object().unwrap() { value[field] = changed.clone(); }
                std::fs::write(path, value.to_string()).unwrap();
            };
            patch(&journal_file(&node), &in_slot);
            patch(&node._dir.path().join("app-spend").join("ops").join(format!("{id}.json")), &on_record);
            let result = do_spend_reconcile(&reopen(&node)).await;
            let case = format!("{in_slot} {on_record}");
            assert!(result.is_err(), "{case}: {result:?}");
            let held = pending(&node).unwrap();
            assert!(!held.resumable, "{case}");
            assert_eq!(held.operation_id.as_deref(), Some(id.as_str()), "{case}");
            assert_eq!(compose_bodies(&node).len(), 1, "{case}: never sent again");
        }
    }

    /// A hash this app already read for the operation that differs from the
    /// reply's: not the same failure, so it proves nothing.
    #[tokio::test]
    async fn a_failure_of_another_hash_than_the_one_on_record_stays_fenced() {
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let (node, _) = failed_message(routes).await;
        wallet.sweep();
        wallet.change(serde_json::json!({"payment_hash": OP_HASH}));
        wallet.report(Some(serde_json::json!({"lightning_backend": "lnd"})));
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap_err().code, "payment_unknown");
        wallet.change(serde_json::json!({}));
        wallet.report(Some(ldk_status()));
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap_err().code, "payment_unknown");
        assert!(!pending(&node).unwrap().resumable);
    }

    /// Checked twice, nothing is released or accounted twice. A crash before the
    /// slot's save repeats the release, and an earlier identical send, which
    /// shares the charge id, keeps its paid row.
    #[tokio::test]
    async fn checking_a_failed_payment_again_releases_and_accounts_nothing_more() {
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        wallet.armed.store(false, std::sync::atomic::Ordering::SeqCst);
        let node = fake(AuthMode::Local, routes);
        spend_advance(&node.state, true).await.unwrap();
        do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap();
        let paid = book(&node);
        assert_eq!(paid.iter().map(|e| (e.1, e.2)).collect::<Vec<_>>(), [(2000, true)]);
        wallet.arm();
        assert_eq!(do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err().code, "payment_unknown");
        assert_eq!(book(&node).len(), 2, "same charge id, its own reservation");
        assert_eq!(book(&node)[1].0, paid[0].0);
        let before_the_check = std::fs::read(journal_file(&node)).unwrap();
        wallet.sweep();
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap(), PAYMENT_FAILED);
        assert_eq!(book(&node), paid);
        let spent = budget_now(&node.state).spent_msat;
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap(), NOTHING_PAID, "already resolved");
        assert_eq!(book(&node), paid);
        std::fs::write(journal_file(&node), before_the_check).unwrap();
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap(), PAYMENT_FAILED);
        assert_eq!(book(&node), paid, "the earlier send keeps its row");
        assert_eq!(budget_now(&node.state).spent_msat, spent);
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        assert_eq!(compose_bodies(&node).len(), 2, "no check sends anything");
    }

    /// The same for a minute, whose unpaid record a restart would otherwise fence.
    #[tokio::test]
    async fn checking_a_failed_minute_again_after_a_crash_changes_nothing() {
        let (inner, _) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let (routes, wallet) = node_failing(act::KIND_CALL_BLOCK, inner);
        let node = minute_ready(routes).await;
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "payment_unknown");
        let before_the_check = std::fs::read(journal_file(&node)).unwrap();
        wallet.sweep();
        let spent = budget_now(&node.state).spent_msat;
        let rows = book(&node).len();
        assert_eq!(do_spend_reconcile(&node.state).await.unwrap(), PAYMENT_FAILED);
        assert_eq!(book(&node).len(), rows - 1, "its reservation is released once");
        std::fs::write(journal_file(&node), before_the_check).unwrap();
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap(), PAYMENT_FAILED);
        assert_eq!(book(&node).len(), rows - 1, "and not a second row");
        assert_eq!(budget_now(&node.state).spent_msat, spent);
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        assert_eq!(pending(&node).unwrap().operation_id, None);
        assert_eq!(compose_kinds(&node), [400, 404]);
    }

    /// The row rc14 writes when an inbound HTLC reuses an outgoing payment's hash:
    /// `released`, the hash, nothing settled, with the payment still in flight. An
    /// upgrade carries it over unchanged and the node never reads the wallet for it
    /// again, so its reply is the same while that payment is pending and after it
    /// settled. Today's status passes. Only what was recorded at dispatch can tell,
    /// and it says no: the fence stays, and nothing is paid a second time.
    #[tokio::test]
    async fn a_row_carried_across_an_upgrade_stays_fenced_pending_or_settled() {
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        wallet.report(Some(rc14_status()));
        let (node, id) = failed_message(routes).await;
        assert_eq!(pending(&node).unwrap().failure_final_on, None);
        wallet.sweep();
        wallet.report(Some(ldk_status()));
        for phase in ["still pending", "settled since"] {
            let error = do_spend_reconcile(&reopen(&node)).await.unwrap_err();
            assert_eq!(error.code, "payment_unknown", "{phase}: {}", error.message);
            let held = pending(&node).unwrap();
            assert!(!held.resumable && held.evidence_reservation_msat.is_some(), "{phase}");
            assert_eq!(held.operation_id.as_deref(), Some(id.as_str()), "{phase}");
            assert_eq!(ledger_record(&node, &id)["state"], "paid_undelivered", "{phase}");
            assert_eq!(do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err().code, "spend_unknown", "{phase}");
            assert_eq!(compose_bodies(&node).len(), 1, "{phase}: no second payment");
            assert_eq!(abandons(&node), 0, "{phase}");
        }
    }

    /// A status that does not show all of it, for this node, when the send is made,
    /// leaves that send unproven for good, whatever the node shows later. A status
    /// that cannot be read at all stops the send: nothing goes out to fence.
    #[tokio::test]
    async fn a_status_that_cannot_vouch_at_dispatch_leaves_the_send_fenced() {
        let caps = ldk_status()["api_capabilities"].clone();
        for at_dispatch in [
            serde_json::json!({"node_id": OWN, "lightning_backend": "lnd", "api_capabilities": caps}),
            serde_json::json!({"node_id": OWN, "lightning_backend": "mock", "api_capabilities": caps}),
            serde_json::json!({"node_id": OWN, "api_capabilities": caps}),
            serde_json::json!({"lightning_backend": "ldk", "api_capabilities": caps}),
            serde_json::json!({"node_id": A, "lightning_backend": "ldk", "api_capabilities": caps}),
            rc14_status(),
        ] {
            let (ops, _) = ops_node();
            let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
            wallet.report(Some(at_dispatch.clone()));
            let (node, id) = failed_message(routes).await;
            assert_eq!(pending(&node).unwrap().failure_final_on, None, "{at_dispatch}");
            wallet.sweep();
            wallet.report(Some(ldk_status()));
            assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap_err().code, "payment_unknown", "{at_dispatch}");
            let held = pending(&node).unwrap();
            assert!(!held.resumable, "{at_dispatch}");
            assert_eq!(held.operation_id.as_deref(), Some(id.as_str()), "{at_dispatch}");
        }
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let node = fake(AuthMode::Local, routes);
        spend_advance(&node.state, true).await.unwrap();
        wallet.report(None);
        assert_eq!(do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err().code, "price_quote_unavailable");
        assert!(compose_bodies(&node).is_empty(), "nothing goes out");
        assert!(pending(&node).is_none());
    }

    /// What was recorded names one node. A record for any other does not count.
    #[tokio::test]
    async fn a_record_for_another_node_identity_does_not_count() {
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let (node, id) = failed_message(routes).await;
        wallet.sweep();
        let mut held: serde_json::Value = serde_json::from_slice(&std::fs::read(journal_file(&node)).unwrap()).unwrap();
        assert_eq!(held["failure_final_on"], OWN);
        held["failure_final_on"] = serde_json::json!(A);
        std::fs::write(journal_file(&node), held.to_string()).unwrap();
        assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap_err().code, "payment_unknown");
        let still = pending(&node).unwrap();
        assert!(!still.resumable);
        assert_eq!(still.operation_id.as_deref(), Some(id.as_str()));
    }

    /// A resend reuses its id only after the node refused the first attempt. If
    /// that refusal is on record, no earlier payment can be on the row, so this
    /// attempt's failure is what the reply shows. Without it the row may be older.
    #[tokio::test]
    async fn a_resend_under_the_same_id_counts_only_over_a_proven_unsent_attempt() {
        for proven in [true, false] {
            let (ops, state) = ops_node();
            state.lock().unwrap().readmission_capped = true;
            let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
            wallet.armed.store(false, std::sync::atomic::Ordering::SeqCst);
            let node = fake(AuthMode::Local, routes);
            spend_advance(&node.state, true).await.unwrap();
            assert_eq!(do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err().code, "readmission_capped");
            let first = pending(&node).unwrap();
            assert!(first.resumable && first.non_dispatch_proven, "the node refused it before dispatch");
            if !proven {
                let mut held: serde_json::Value = serde_json::from_slice(&std::fs::read(journal_file(&node)).unwrap()).unwrap();
                held["non_dispatch_proven"] = serde_json::json!(false);
                std::fs::write(journal_file(&node), held.to_string()).unwrap();
            }
            state.lock().unwrap().readmission_capped = false;
            wallet.arm();
            let error = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err();
            assert_eq!(error.code, "payment_unknown", "{proven}: {}", error.message);
            assert_eq!(error.operation_id, first.operation_id, "the same id");
            wallet.sweep();
            if proven {
                assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap(), PAYMENT_FAILED);
                assert_eq!(pending(&node).unwrap().operation_id, None);
            } else {
                assert_eq!(pending(&node).unwrap().failure_final_on, None);
                assert_eq!(do_spend_reconcile(&reopen(&node)).await.unwrap_err().code, "payment_unknown");
                assert!(!pending(&node).unwrap().resumable);
            }
        }
    }

    /// A slot written by an earlier build has no record of what the node was at
    /// dispatch. Its next check, End and a restart all keep the fence, as before:
    /// it cannot be told from a row carried across an upgrade.
    #[tokio::test]
    async fn a_failed_payment_stuck_by_an_earlier_build_stays_fenced() {
        fn as_an_earlier_build_wrote_it(node: &Fake) {
            let mut held: serde_json::Value = serde_json::from_slice(&std::fs::read(journal_file(node)).unwrap()).unwrap();
            held.as_object_mut().unwrap().remove("failure_final_on").expect("this build writes it");
            std::fs::write(journal_file(node), held.to_string()).unwrap();
        }
        let (ops, _) = ops_node();
        let (routes, wallet) = node_failing(control::KIND_CHAT, ops);
        let (node, id) = failed_message(routes).await;
        as_an_earlier_build_wrote_it(&node);
        wallet.sweep();
        for _ in 0..2 {
            let stuck = do_spend_reconcile(&reopen(&node)).await.unwrap_err();
            assert!(stuck.message.starts_with("Accounted: 0 msat of payment evidence"), "{}", stuck.message);
        }
        let held = pending(&node).unwrap();
        assert_eq!((held.accounting_msat, held.evidence_reservation_msat.is_some(), held.budgeted, held.resumable), (Some(0), true, true, false));
        assert_eq!(settled(&node), [0]);
        assert_eq!(ledger_record(&node, &id)["state"], "paid_undelivered");
        assert_eq!(do_spend_dismiss_undelivered(&node.state, &held.id).unwrap_err().code, "spend_unknown");
        assert_eq!(do_message_send(&node.state, A, false, "another", 14000, None).await.unwrap_err().code, "spend_unknown");
        assert_eq!(abandons(&node), 0);
        assert_eq!(compose_bodies(&node).len(), 1);

        let (inner, _) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let (routes, wallet) = node_failing(act::KIND_CALL_BLOCK, inner);
        let node = minute_ready(routes).await;
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "payment_unknown");
        as_an_earlier_build_wrote_it(&node);
        wallet.sweep();
        assert_eq!(do_op_end_call(&node.state, CALL_ID).await.unwrap_err().code, "payment_unknown");
        assert_eq!(compose_kinds(&node), [400, 404], "no hangup");
        assert!(!pending(&node).unwrap().resumable);
    }

    /// Only this call's own minute is reconciled: another call's pending minute
    /// keeps its fence, and End of this call never asks about it.
    #[tokio::test]
    async fn a2_end_leaves_another_calls_pending_minute_fenced() {
        const OTHER_CALL: &str = "1123456789abcdef0123456789abcdef";
        let (inner, paid) = minutes_routes_with_abandon();
        let other = format!("/pricing/peers/{C}/call");
        let mut node = minute_ready(Arc::new(move |m, p, b| {
            if p == other {
                return (200, serde_json::json!({"peer_id": C, "offer_msat": 10_000, "signal_msat": 50}).to_string());
            }
            inner(m, p, b)
        })).await;
        with_book(&node.state, true, |b| b.set_limit(C, false, 50_000)).unwrap();
        do_call_signal(&node.state, C, 400, &OFFER.replace(CALL_ID, OTHER_CALL), 15_000).await.unwrap();
        lose_minute_reply(&mut node, &paid, None).await;
        let held = pending(&node).unwrap();
        let minute = held.operation_id.clone().unwrap();
        let error = do_op_end_call(&node.state, OTHER_CALL).await.unwrap_err();
        assert_eq!(error.code, "spend_unknown", "the generic fence");
        assert_eq!(compose_kinds(&node), [400, 400, 404], "no hangup");
        assert!(!node.targets().iter().any(|t| t.contains(&minute) && t.contains("/messages/operations/")), "never asked about");
        assert_eq!(pending(&node).unwrap().id, held.id);
        // Ending the minute's own call resolves it, and then the other can end too.
        assert_eq!(do_op_end_call(&node.state, CALL_ID).await.unwrap().kind, "call_hangup");
        assert_eq!(do_op_end_call(&node.state, OTHER_CALL).await.unwrap().kind, "call_hangup");
        assert_eq!(compose_kinds(&node), [400, 400, 404, 403, 403]);
    }

    /// Lock order: a minute refused at its decision cleans up (journal, budget,
    /// node identity) without the consent lock. A thread that holds the node
    /// identity and then takes the consent lock, as End once did, is not
    /// blocked by that cleanup. Bounded: fails after 3 s instead of hanging.
    #[test]
    fn a2_a_refused_minutes_cleanup_holds_no_consent_lock_against_end() {
        let rt = race_runtime();
        let (routes, _) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node = rt.block_on(minute_ready(routes));
        let state = &node.state;
        let spent = budget_now(state).spent_msat;
        let (arrived, release) = pause_points::arm(&state.api_base, "before_decision");
        std::thread::scope(|s| {
            let minute = s.spawn(|| rt.block_on(do_call_block(state, A, CALL_ID, 0)));
            rt.block_on(arrived.notified());
            // Their hangup ends the call: the paused minute is refused at its decision.
            let node_id = state.node_id.lock().unwrap().clone().unwrap();
            state.call_consents.lock().unwrap().end(&node_id, None, CALL_ID);
            let identity = state.node_id.lock().unwrap();
            release.notify_one();
            // The refusal's cleanup now waits for the node identity.
            std::thread::sleep(Duration::from_millis(100));
            let deadline = Instant::now() + Duration::from_secs(3);
            let took = loop {
                match state.call_consents.try_lock() {
                    Ok(kept) => break kept.find(&node_id, A, CALL_ID).is_some(),
                    Err(_) if Instant::now() < deadline => std::thread::sleep(Duration::from_millis(2)),
                    Err(_) => break false,
                }
            };
            drop(identity);
            assert!(took, "the refused minute's cleanup held the consent lock while it waited for the node identity");
            assert_eq!(minute.join().unwrap().unwrap_err().code, "call_not_live");
        });
        assert_eq!(minutes_sent(&node), 0);
        assert_eq!(budget_now(state).spent_msat, spent, "nothing charged");
        assert!(pending(&node).is_none(), "the refused minute's slot is released");
    }

    #[tokio::test]
    async fn a2_a_hold_above_the_consent_is_hung_up_before_block_zero() {
        // Agreed: at most 60 minutes' worth. The node reserved 240 minutes at the agreed price.
        let (routes, paid) = minutes_routes("ringing", hold_json(10_000, 5_000, 240));
        let node = fake(AuthMode::Local, routes);
        approve_calls(&node).await;
        do_call_signal(&node.state, A, 400, OFFER, 15000).await.unwrap();
        remember_call_consent(&node.state, A, CALL_ID, control::MinutesConsent { max_hold_msat: 60 * 15_000, ..MINUTES }).unwrap();
        let err = do_call_hold(&node.state, A, CALL_ID, None).await.unwrap_err();
        assert_eq!(err.code, "call_hold_above_consent");
        assert!(err.message.contains("No minute was paid") && err.message.contains("hung up"), "{}", err.message);
        assert_eq!(compose_kinds(&node), [400, 403], "hung up at once; block 0 is never sent");
        // Confirming or paying it later is refused the same way; the hangup is not repeated.
        assert_eq!(do_call_hold(&node.state, A, CALL_ID, Some(240 * 15_000)).await.unwrap_err().code, "call_hold_above_consent");
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_hold_above_consent");
        assert_eq!(compose_kinds(&node), [400, 403]);
        assert_eq!(paid.lock().unwrap().pays, 2, "the offer and the hangup; zero minutes");
        // A higher per-minute price is above the consent as well.
        let (routes, _) = minutes_routes("ringing", hold_json(10_001, 5_000, 60));
        let node = fake(AuthMode::Local, routes);
        approve_calls(&node).await;
        do_call_signal(&node.state, A, 400, OFFER, 15000).await.unwrap();
        remember_call_consent(&node.state, A, CALL_ID, MINUTES).unwrap();
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_hold_above_consent");
        assert_eq!(compose_kinds(&node), [400, 403]);
    }

    /// The caller's node as above, plus the callee's cached advert (`kind:404`).
    fn offer_routes(advert_block: u64, reservation: serde_json::Value) -> (Routes, Arc<Mutex<OpsNode>>) {
        let (routes, paid) = minutes_routes("ringing", reservation);
        (Arc::new(move |m, p, b| {
            if p == format!("/pricing/peers/{A}") {
                return (200, serde_json::json!({"peer_id": A, "prices": {"kind:404": advert_block}, "age_secs": 1, "stale": false}).to_string());
            }
            routes(m, p, b)
        }), paid)
    }

    fn consent_phase(node: &Fake) -> ConsentPhase {
        call_consent(&node.state, A, CALL_ID).expect("consent kept").phase
    }

    #[tokio::test]
    async fn a2_a_price_change_between_quote_and_offer_pays_no_minute() {
        // Agreed at 10,000 a minute; their node answers its own node's live ask with 12,000,
        // so the hold made with the offer is above the consent.
        let (routes, paid) = offer_routes(10_000, hold_json(12_000, 5_000, 60));
        let node = fake(AuthMode::Local, routes);
        approve_calls(&node).await;
        offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await.unwrap();
        assert_eq!(compose_kinds(&node), [400, 403], "refused and hung up within the offer's admission, before any minute");
        assert!(matches!(consent_phase(&node), ConsentPhase::Refused { code: "call_hold_above_consent", .. }));
        assert!(call_consent(&node.state, A, CALL_ID).unwrap().pinned(), "its node still lists the hold open: kept, never evicted");
        // The refusal is final: confirming the exact hold, paying, or checking again never pays it.
        let reserved = 17_000 * 60;
        assert_eq!(do_call_hold(&node.state, A, CALL_ID, Some(reserved)).await.unwrap_err().code, "call_hold_above_consent");
        for seq in [0, 0, 1] {
            assert_eq!(do_call_block(&node.state, A, CALL_ID, seq).await.unwrap_err().code, "call_hold_above_consent");
        }
        assert_eq!(compose_kinds(&node), [400, 403], "zero minutes, one hangup");
        assert_eq!(paid.lock().unwrap().pays, 2);
        // The same call id cannot be given new, wider terms afterwards.
        let wider = control::MinutesConsent { block_msat: 12_000, max_hold_msat: 240 * 17_000, ..MINUTES };
        assert_eq!(offer_within_consent(&node.state, A, OFFER, 15000, wider, Some(SHOWN_HANGUP)).await.unwrap_err().code, "invalid");
        assert_eq!(compose_kinds(&node), [400, 403]);
    }

    #[tokio::test]
    async fn a2_an_advert_above_the_consent_sends_no_offer() {
        // Their advert rose between the quote and Ring: nothing is sent, nothing held or paid.
        let (routes, paid) = offer_routes(10_001, hold_json(10_001, 5_000, 60));
        let node = fake(AuthMode::Local, routes);
        approve_calls(&node).await;
        assert_eq!(offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await.unwrap_err().code, "call_price_changed");
        assert!(compose_kinds(&node).is_empty());
        assert_eq!(paid.lock().unwrap().pays, 0);
        assert_eq!(consent_phase(&node), ConsentPhase::Ended);
        assert!(!call_consent(&node.state, A, CALL_ID).unwrap().pinned(), "nothing was sent: no call or hold at the node");
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_not_live");
        assert!(compose_kinds(&node).is_empty());
    }

    #[tokio::test]
    async fn a2_the_offer_binds_the_agreed_routing_allowance_and_admits_a_hold_within_it() {
        // Agreed: up to 4,000 routing a minute. The offer's routing ceiling (which the node
        // applies to every block of the hold) is never wider than that.
        let agreed = control::MinutesConsent { block_msat: 10_000, block_max_routing_fee_msat: 4_000, max_hold_msat: 240 * 14_000 };
        let (routes, _) = offer_routes(10_000, hold_json(10_000, 4_000, 60));
        let node = fake(AuthMode::Local, routes);
        approve_calls(&node).await;
        offer_within_consent(&node.state, A, OFFER, 15000, agreed, Some(SHOWN_HANGUP)).await.unwrap();
        let offer = &compose_bodies(&node)[0];
        assert_eq!((offer["kind"].as_u64(), offer["max_routing_fee_msat"].as_u64()), (Some(400), Some(4_000)));
        // Genome N3: the node enforces the consent itself before it holds anything.
        assert_eq!((offer["max_block_msat"].as_u64(), offer["max_hold_msat"].as_u64()), (Some(10_000), Some(240 * 14_000)));
        assert_eq!(consent_phase(&node), ConsentPhase::Admitted, "checked within the offer's admission");
        // Admitted is not confirmed: still no minute before the owner confirms this exact hold.
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_hold_unconfirmed");
        do_call_hold(&node.state, A, CALL_ID, Some(14_000 * 60)).await.unwrap();
        assert_eq!(call_consent(&node.state, A, CALL_ID).unwrap().confirmed_msat, Some(14_000 * 60));
        // The app hangs up: no further minute, whatever the node still lists.
        do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!(consent_phase(&node), ConsentPhase::Ended);
        assert!(call_consent(&node.state, A, CALL_ID).unwrap().pinned(), "a hangup alone is not the node's closure");
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_not_live");
        assert_eq!(compose_kinds(&node), [400, 403], "the offer and the hangup; no minute after the end");
    }

    #[tokio::test]
    async fn a2_a_minute_raced_against_the_offers_admission_is_never_paid() {
        for above in [true, false] {
            let hold = if above { hold_json(12_000, 5_000, 60) } else { hold_json(10_000, 5_000, 60) };
            let (routes, paid) = offer_routes(10_000, hold);
            let (routes, gate) = hold_compose(routes, 0, None, false);
            let node = fake(AuthMode::Local, routes);
            approve_calls(&node).await;
            let wider = control::MinutesConsent { block_msat: 12_000, max_hold_msat: 240 * 17_000, ..MINUTES };
            // While the offer is with the node: a minute, a confirmation, and a second offer
            // for the same call (same terms, or wider) all race its admission. Before the node
            // accepted this very offer, no hold listed under its call id is checked or admitted.
            let (offer, (block, confirm, again, rebind)) = tokio::join!(
                offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)),
                during_call(&gate, async {
                    let again = offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await;
                    let rebind = offer_within_consent(&node.state, A, OFFER, 15000, wider, Some(SHOWN_HANGUP)).await;
                    let block = do_call_block(&node.state, A, CALL_ID, 0).await;
                    let confirm = do_call_hold(&node.state, A, CALL_ID, Some(15_000 * 60)).await;
                    (block, confirm, again, rebind)
                }),
            );
            offer.unwrap();
            assert_eq!(again.unwrap_err().code, "call_offer_in_flight");
            assert_eq!(rebind.unwrap_err().code, "invalid");
            assert_eq!(block.unwrap_err().code, "call_hold_unconfirmed");
            assert_eq!(confirm.unwrap_err().code, "call_hold_unconfirmed");
            if above {
                assert!(matches!(consent_phase(&node), ConsentPhase::Refused { code: "call_hold_above_consent", .. }));
                assert_eq!(do_call_hold(&node.state, A, CALL_ID, Some(17_000 * 60)).await.unwrap_err().code, "call_hold_above_consent");
                assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_hold_above_consent");
                assert_eq!(compose_kinds(&node), [400, 403], "one offer, one hangup, no minute");
                assert_eq!(paid.lock().unwrap().pays, 2);
            } else {
                assert_eq!(consent_phase(&node), ConsentPhase::Admitted, "the offer's own check admitted it once accepted");
                assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_hold_unconfirmed",
                    "a hold within the consent still waits for the owner");
                do_call_hold(&node.state, A, CALL_ID, Some(15_000 * 60)).await.unwrap();
                assert_eq!(compose_kinds(&node), [400], "one offer, no minute");
            }
        }
    }

    /// One side of the app's remote tunnel, as the box runs it: the pinned
    /// handshake, an accepted client, then the decrypted stream is relayed to
    /// the fake node at `node`. Each record holds one ciphertext.
    async fn box_behind_tunnel(listener: tokio::net::TcpListener, secret: [u8; 32], node: std::net::SocketAddr) {
        use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
        async fn read_frame(stream: &mut (impl AsyncRead + Unpin)) -> std::io::Result<Vec<u8>> {
            let length = stream.read_u32().await? as usize;
            let mut frame = vec![0u8; length];
            stream.read_exact(&mut frame).await?;
            Ok(frame)
        }
        async fn write_frame(stream: &mut (impl AsyncWrite + Unpin), frame: &[u8]) -> std::io::Result<()> {
            stream.write_u32(frame.len() as u32).await?;
            stream.write_all(frame).await
        }
        fn seal(noise: &mut snow::TransportState, plain: &[u8]) -> Vec<u8> {
            let mut sealed = vec![0u8; plain.len() + 18];
            let length = noise.write_message(plain, &mut sealed[2..]).unwrap();
            sealed[..2].copy_from_slice(&(length as u16).to_be_bytes());
            sealed.truncate(length + 2);
            sealed
        }
        fn open(noise: &mut snow::TransportState, record: &[u8]) -> Vec<u8> {
            let mut plain = vec![0u8; record.len()];
            let length = noise.read_message(&record[2..], &mut plain).unwrap();
            plain.truncate(length);
            plain
        }
        async fn serve(stream: tokio::net::TcpStream, secret: [u8; 32], node: std::net::SocketAddr) -> std::io::Result<()> {
            let (mut from_app, mut to_app) = stream.into_split();
            let mut noise = snow::Builder::new(remote_access::NOISE_PROTOCOL.parse().unwrap())
                .local_private_key(&secret).and_then(|b| b.build_responder()).unwrap();
            let mut scratch = vec![0u8; 65_535];
            let message = read_frame(&mut from_app).await?;
            noise.read_message(&message, &mut scratch).unwrap();
            let length = noise.write_message(&[], &mut scratch).unwrap();
            write_frame(&mut to_app, &scratch[..length]).await?;
            let message = read_frame(&mut from_app).await?;
            noise.read_message(&message, &mut scratch).unwrap();
            let mut noise = noise.into_transport_mode().unwrap();
            let auth = read_frame(&mut from_app).await?;
            let _ = open(&mut noise, &auth);
            let accepted = serde_json::to_vec(&remote_access::RemoteAuthResponse::Ok {
                v: 1, client_id: "0123456789abcdef0123456789abcdef".into(), scopes: vec!["read".into()],
                box_transport_pubkey: None, box_transport_signature: None,
                transport_pubkey: None, transport_signature: None,
            }).unwrap();
            write_frame(&mut to_app, &seal(&mut noise, &accepted)).await?;
            let (mut node_read, mut node_write) = tokio::net::TcpStream::connect(node).await?.into_split();
            let (frames, mut frames_rx) = tokio::sync::mpsc::unbounded_channel();
            let reader = tokio::spawn(async move {
                while let Ok(frame) = read_frame(&mut from_app).await {
                    if frames.send(frame).is_err() { break; }
                }
            });
            let mut buffer = vec![0u8; 16 * 1024];
            loop {
                tokio::select! {
                    frame = frames_rx.recv() => {
                        let Some(frame) = frame else { break };
                        node_write.write_all(&open(&mut noise, &frame)).await?;
                    }
                    read = node_read.read(&mut buffer) => {
                        let read = read?;
                        if read == 0 { break; }
                        write_frame(&mut to_app, &seal(&mut noise, &buffer[..read])).await?;
                    }
                }
            }
            reader.abort();
            Ok(())
        }
        loop {
            let (stream, _) = listener.accept().await.unwrap();
            tokio::spawn(serve(stream, secret, node));
        }
    }

    /// The real loopback proxy in front of `node`, reaching it through a real
    /// tunnel. Requests made after this go proxy, tunnel, box, fake node.
    async fn proxied(node: &mut Fake) -> (remote_access::RemoteProxy, tempfile::TempDir, tempfile::TempDir, tokio::task::JoinHandle<()>) {
        use base64::Engine;
        use ed25519_dalek::Signer;
        let upstream = remote_access::loopback_addr(&node.state.api_base).unwrap();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let secret = [91u8; 32];
        let signing = ed25519_dalek::SigningKey::from_bytes(&[92u8; 32]);
        let node_id = hex::encode(signing.verifying_key().as_bytes());
        let transport_pubkey = hex::encode(x25519_dalek::PublicKey::from(&x25519_dalek::StaticSecret::from(secret)).to_bytes());
        let signature = signing.sign(remote_access::descriptor_signature_message(&node_id, &transport_pubkey).as_bytes());
        let b64 = base64::engine::general_purpose::URL_SAFE_NO_PAD;
        let link = serde_json::to_vec(&remote_access::PairingLinkV1 {
            v: 1, endpoint: listener.local_addr().unwrap().to_string(), node_id, transport_pubkey,
            transport_signature: b64.encode(signature.to_bytes()), code: b64.encode([93u8; 32]),
            ..Default::default()
        }).unwrap();
        let link = format!("bitsov://pair/{}", b64.encode(link));
        let descriptor = remote_access::parse_pairing_link(&link).unwrap();
        let server = tokio::spawn(box_behind_tunnel(listener, secret, upstream));
        let (app_dir, store) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
        remote_access::import_pairing_link(app_dir.path(), &link).unwrap();
        let key = Arc::new(bitsov_app::pairing::ClientKey::load_or_create(store.path()).unwrap());
        let free = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = free.local_addr().unwrap().port();
        drop(free);
        let base = format!("http://127.0.0.1:{port}/api/v1");
        let proxy = remote_access::start_proxy(&base, app_dir.path(), descriptor, key, "BitSov test",
            store.path().to_path_buf(), node.state.remote_proxy_auth.clone(), node.state.remote_retry.clone()).await.unwrap();
        node.state.api_base = base;
        (proxy, app_dir, store, server)
    }

    // A minute on a fresh remote tunnel that never connects. The proxy answers
    // at its deadline, before the app's own payment timeout, so the outcome is
    // known: nothing went out, nothing stays pending, and End is not fenced.
    #[tokio::test]
    async fn a_minute_past_the_tunnel_deadline_is_not_dispatched_and_end_pays_the_hangup() {
        let (routes, paid) = minutes_routes("live", hold_json(10_000, 5_000, 60));
        // The tunnel stalls just as the node answers the minute's last read.
        let stall = Arc::new(Mutex::new(None::<Arc<bitsov_app::connection_retry::RemoteRetry>>));
        let (entered, stalled_at) = tokio::sync::oneshot::channel::<()>();
        let (release, held) = tokio::sync::oneshot::channel::<()>();
        let (entered, held) = (Mutex::new(Some(entered)), Mutex::new(Some(held)));
        let runtime = tokio::runtime::Handle::current();
        let wrapped: Routes = {
            let stall = stall.clone();
            Arc::new(move |m, p, b| {
                if m == "GET" && p == "/status" {
                    if let Some(retry) = stall.lock().unwrap().take() {
                        let held = held.lock().unwrap().take().unwrap();
                        let entered = entered.lock().unwrap().take().unwrap();
                        runtime.spawn(async move {
                            retry.run(|| async { let _ = entered.send(()); let _ = held.await; Ok(()) }).await
                        });
                        // A dial younger than a second makes the money path
                        // refuse by itself. This one has been stuck for longer.
                        std::thread::sleep(Duration::from_millis(1100));
                    }
                }
                routes(m, p, b)
            })
        };
        let mut node = fake(AuthMode::Local, wrapped);
        approve_calls(&node).await;
        do_call_signal(&node.state, A, 400, OFFER, 15000).await.unwrap();
        remember_call_consent(&node.state, A, CALL_ID, MINUTES).unwrap();
        do_call_hold(&node.state, A, CALL_ID, Some(900_000)).await.unwrap();
        let (proxy, _app, _store, server) = proxied(&mut node).await;
        *stall.lock().unwrap() = Some(node.state.remote_retry.clone());
        let minute = do_call_block(&node.state, A, CALL_ID, 0);
        tokio::pin!(minute);
        let code = tokio::select! {
            result = &mut minute => panic!("answered before the deadline: {:?}", result.map(|r| r.kind).map_err(|e| e.code)),
            _ = async {
                stalled_at.await.unwrap();
                // The money lock is taken only for the POST.
                while node.state.money.try_lock().is_ok() {
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
                tokio::time::sleep(Duration::from_millis(300)).await;
            } => {
                // Twice at most: a POST queued only after the first step still
                // has its whole payment timeout, so this cannot fake an answer.
                let mut answer = None;
                for _ in 0..2 {
                    tokio::time::pause();
                    tokio::time::advance(Duration::from_secs(61)).await;
                    tokio::time::resume();
                    if let Ok(result) = tokio::time::timeout(Duration::from_secs(3), &mut minute).await {
                        answer = Some(result);
                        break;
                    }
                }
                answer.expect("the proxy answers at its deadline").unwrap_err().code
            }
        };
        assert_eq!(code, "not_dispatched");
        assert!(pending(&node).is_none(), "nothing stays pending behind a proven non-dispatch");
        release.send(()).unwrap();
        tokio::time::sleep(Duration::from_millis(200)).await;
        assert_eq!(compose_kinds(&node), [400], "the held minute never reached the node");
        assert_eq!(paid.lock().unwrap().pays, 1);

        let ended = do_op_end_call(&node.state, CALL_ID).await.unwrap();
        assert_eq!(ended.kind, "call_hangup");
        assert_eq!(compose_kinds(&node), [400, 403], "End paid one hangup through the same proxy, and no minute");
        assert_eq!(paid.lock().unwrap().pays, 2);
        assert!(pending(&node).is_none());
        drop(proxy);
        server.abort();
    }

    // Node rc21 checks a block again after its reservation, and answers a late
    // one with a plain 400 before anything is paid. That must not fence End.
    #[tokio::test]
    async fn a2_a_minute_refused_after_its_reservation_is_proven_unpaid_and_end_is_free() {
        for reply in [
            r#"{"error":"call not live","code":400,"reason":"call_not_live"}"#,
            r#"{"error":"call not live","code":400,"reason":"call_not_live","operation_id":"x","state":"prepared","payment_hash":null,"accepted":false,"retry_allowed":true}"#,
            r#"{"error":"call not live","code":400,"reason":"call_not_live","operation_id":"x","state":"released","payment_hash":null,"accepted":false,"retry_allowed":true}"#,
        ] {
            let (routes, paid) = minutes_routes("live", hold_json(10_000, 5_000, 60));
            let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                if p == "/messages/compose" && serde_json::from_str::<serde_json::Value>(b).unwrap()["kind"] == 404 {
                    return (400, reply.into());
                }
                routes(m, p, b)
            }));
            approve_calls(&node).await;
            do_call_signal(&node.state, A, 400, OFFER, 15000).await.unwrap();
            remember_call_consent(&node.state, A, CALL_ID, MINUTES).unwrap();
            do_call_hold(&node.state, A, CALL_ID, Some(900_000)).await.unwrap();
            let spent = budget_now(&node.state).spent_msat;
            // Each attempt of the scheduler (`MAX_ATTEMPTS` in callMinutes.ts) gets the same
            // answer, which is what it reads as "the node no longer runs the call".
            for attempt in 1..=4 {
                let err = do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err();
                assert_eq!(err.code, "call_not_live", "attempt {attempt}: {reply}");
                assert!(err.message.contains("Nothing was paid"), "{}", err.message);
                assert!(pending(&node).is_none(), "attempt {attempt} leaves no pending: {reply}");
                assert_eq!(budget_now(&node.state).unsettled_msat, 0);
                assert_eq!(budget_now(&node.state).spent_msat, spent, "nothing was charged");
                let record = ledger_record(&node, err.operation_id.as_deref().unwrap());
                assert_eq!((record["kind"].as_str(), record["state"].as_str()), (Some("call_block"), Some("unpaid")));
                assert_eq!(record["paid_msat"], 0);
            }
            assert_eq!(compose_kinds(&node), [400, 404, 404, 404, 404]);
            assert_eq!(paid.lock().unwrap().pays, 1, "only the offer was paid");

            let ended = do_op_end_call(&node.state, CALL_ID).await.unwrap();
            assert_eq!(ended.kind, "call_hangup");
            assert_eq!(compose_kinds(&node), [400, 404, 404, 404, 404, 403], "End paid its hangup with no reconcile first");
            assert_eq!(paid.lock().unwrap().pays, 2);
            assert!(pending(&node).is_none());
        }
    }

    /// Node rc21's reply when the callee's node refuses a minute's invoice because it
    /// is catching up, captured from its own handlers: nothing left the wallet.
    fn callee_catching_up_reply(id: &serde_json::Value) -> serde_json::Value {
        serde_json::json!({"accepted": false, "code": "peer_not_ready", "error": "recipient is not ready to receive payments: not_synced",
            "max_routing_fee_msat": 5000, "operation_id": id, "payment_hash": null, "reason": "not_synced", "retry_allowed": true, "state": "released"})
    }

    /// A passing refusal, proven by the node's own reply: no fence, so the scheduler
    /// tries again, and that try is a new operation, paid once.
    #[tokio::test]
    async fn a2_a_minute_refused_by_a_callee_catching_up_is_proven_unpaid_and_tried_again() {
        let refusing = Arc::new(AtomicBool::new(true));
        let refuse = refusing.clone();
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node = minute_ready(Arc::new(move |m, p, b| {
            let body: serde_json::Value = serde_json::from_str(b).unwrap_or_default();
            if p == "/messages/compose" && body["kind"] == 404 && refuse.load(Ordering::SeqCst) {
                return (503, callee_catching_up_reply(&body["operation_id"]).to_string());
            }
            routes(m, p, b)
        })).await;
        let (spent, pays) = (budget_now(&node.state).spent_msat, paid.lock().unwrap().pays);

        let error = do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err();
        assert_eq!(error.code, "peer_not_ready", "{}", error.message);
        assert!(error.message.contains("Nothing was paid"), "{}", error.message);
        assert!(pending(&node).is_none(), "no fence");
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        assert_eq!(budget_now(&node.state).spent_msat, spent, "nothing was charged");
        let first = error.operation_id.clone().unwrap();
        let record = ledger_record(&node, &first);
        assert_eq!((record["kind"].as_str(), record["state"].as_str()), (Some("call_block"), Some("unpaid")));
        assert!(!node.targets().iter().any(|t| t.starts_with("GET /messages/operations/")), "no check was needed");

        refusing.store(false, Ordering::SeqCst);
        let receipt = do_call_block(&node.state, A, CALL_ID, 0).await.unwrap();
        assert_ne!(receipt.operation_id.as_deref(), Some(first.as_str()), "a new operation");
        assert_eq!(paid.lock().unwrap().pays, pays + 1, "paid once");
    }

    /// The book write that releases the minute's reservation fails. The record of
    /// that reservation stays, so it can still be settled; it is never left held
    /// in the book with nothing pointing at it.
    #[tokio::test]
    async fn a2_a_failed_release_on_a_callee_catching_up_keeps_the_record() {
        let armed = Arc::new(Mutex::new(None::<PathBuf>));
        let hook = armed.clone();
        let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
        let node = minute_ready(Arc::new(move |m, p, b| {
            let body: serde_json::Value = serde_json::from_str(b).unwrap_or_default();
            if p == "/messages/compose" && body["kind"] == 404 {
                if let Some(dir) = hook.lock().unwrap().take() {
                    // A directory in the way of the book's atomic replacement.
                    let p = spend_journal::read_pending(&dir).unwrap().unwrap();
                    std::fs::create_dir(budget::book_path(&dir, &p.node_id).with_extension("json.tmp")).unwrap();
                }
                return (503, callee_catching_up_reply(&body["operation_id"]).to_string());
            }
            routes(m, p, b)
        })).await;
        let dir = journal_file(&node).parent().unwrap().to_path_buf();
        *armed.lock().unwrap() = Some(dir.clone());
        let pays = paid.lock().unwrap().pays;

        let error = do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err();
        assert!(armed.lock().unwrap().is_none(), "the fault was reached");
        assert_ne!(error.code, "peer_not_ready", "{}", error.message);
        assert!(budget_now(&node.state).unsettled_msat > 0, "the book still holds the reservation");
        let held = pending(&node).expect("the reservation keeps its record");
        assert!(held.budgeted);
        assert!(book(&node).iter().any(|(id, _, settled)| id == held.charge_id() && !settled),
            "the record names the held reservation");
        assert_eq!(paid.lock().unwrap().pays, pays);
        let book_tmp = budget::book_path(&dir, &held.node_id).with_extension("json.tmp");
        std::fs::remove_dir(book_tmp).unwrap();
    }

    /// The whole of the reply must prove it. Short of that, the same refusal stays
    /// unknown and the fence holds. `prepared` is what rc21 answers while an earlier
    /// admission is in its journal, and it can hide a paid admission from this reply.
    #[tokio::test]
    async fn a2_a_catching_up_reply_short_of_the_proof_stays_unknown() {
        type Change = fn(&mut serde_json::Value);
        // The whole proof under another status is the general released reading
        // (not dispatched, no fence), not this one; it is not listed here.
        let changes: [(&str, u16, Change); 9] = [
            ("prepared", 503, |v| v["state"] = "prepared".into()),
            ("paying", 503, |v| v["state"] = "paying".into()),
            ("payment_unknown", 503, |v| v["state"] = "payment_unknown".into()),
            ("no state", 503, |v| { v.as_object_mut().unwrap().remove("state"); }),
            ("hash", 503, |v| v["payment_hash"] = OP_HASH.into()),
            ("no hash field", 503, |v| { v.as_object_mut().unwrap().remove("payment_hash"); }),
            ("another operation", 503, |v| v["operation_id"] = "00000000-0000-4000-8000-000000000000".into()),
            ("no retry", 503, |v| v["retry_allowed"] = false.into()),
            ("amount", 503, |v| v["amount_msat"] = 1000.into()),
        ];
        for (name, status, change) in changes {
            let (routes, paid) = minutes_routes("live", hold_json(8_000, 2_000, 60));
            let node = minute_ready(Arc::new(move |m, p, b| {
                let body: serde_json::Value = serde_json::from_str(b).unwrap_or_default();
                if p == "/messages/compose" && body["kind"] == 404 {
                    let mut reply = callee_catching_up_reply(&body["operation_id"]);
                    change(&mut reply);
                    return (status, reply.to_string());
                }
                routes(m, p, b)
            })).await;
            let pays = paid.lock().unwrap().pays;
            let error = do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err();
            assert!(matches!(error.code, "spend_unknown" | "payment_unknown"), "{name}: {}", error.code);
            assert!(pending(&node).is_some(), "{name}: the fence holds");
            assert!(budget_now(&node.state).unsettled_msat > 0, "{name}: the reservation stays held");
            assert_eq!(paid.lock().unwrap().pays, pays, "{name}");
        }
    }

    /// This reading is for a minute. Other sends keep what they had: the node's
    /// released proof reads as not dispatched, with no fence, never as a minute
    /// to try again.
    #[tokio::test]
    async fn a_catching_up_reply_to_another_send_is_unchanged() {
        let (routes, _) = ops_node();
        let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
            if p == "/messages/compose" {
                let body: serde_json::Value = serde_json::from_str(b).unwrap();
                return (503, callee_catching_up_reply(&body["operation_id"]).to_string());
            }
            routes(m, p, b)
        }));
        approve_calls(&node).await;
        let error = do_message_send(&node.state, A, false, "hi", 7000, None).await.unwrap_err();
        assert_eq!(error.code, "not_dispatched");
        assert!(pending(&node).is_none());
    }

    #[tokio::test]
    async fn a2_a_failed_offer_is_final_and_cannot_be_rebound_wider() {
        let (routes, _) = offer_routes(10_000, hold_json(10_000, 5_000, 60));
        let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
            if p == "/messages/compose" {
                return (400, r#"{"error":"call reservation does not fit the grant","code":"not_dispatched","reason":"grant_per_call"}"#.into());
            }
            routes(m, p, b)
        }));
        approve_calls(&node).await;
        assert!(offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await.is_err());
        let sent = compose_kinds(&node);
        assert!(!sent.is_empty() && sent.iter().all(|k| *k == 400));
        // The offer did not go through: its consent can never admit a hold, under these terms
        // or wider ones. This node still lists a hold under the call id, so it stays pinned.
        assert_eq!(consent_phase(&node), ConsentPhase::Ended);
        assert!(call_consent(&node.state, A, CALL_ID).unwrap().pinned());
        let wider = control::MinutesConsent { block_msat: 20_000, max_hold_msat: 240 * 25_000, ..MINUTES };
        assert_eq!(offer_within_consent(&node.state, A, OFFER, 15000, wider, Some(SHOWN_HANGUP)).await.unwrap_err().code, "invalid");
        assert_eq!(offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await.unwrap_err().code, "invalid");
        assert_eq!(remember_call_consent(&node.state, A, CALL_ID, wider).unwrap_err().code, "invalid");
        assert_eq!(do_call_hold(&node.state, A, CALL_ID, Some(15_000 * 60)).await.unwrap_err().code, "call_not_live");
        assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_not_live");
        assert_eq!(compose_kinds(&node), sent, "the rebinds sent nothing; no minute");
        assert_eq!(call_consent(&node.state, A, CALL_ID).unwrap().consent, MINUTES);
    }

    #[tokio::test]
    async fn a2_the_node_refuses_an_offer_above_the_consent_and_nothing_is_held_or_paid() {
        // Genome N3 (#460): the offer carries the consent's ceilings; the node checks its live
        // per-minute price and computed hold against them before it holds, pays or sends anything.
        for (reason, code) in [("call_price_above_consent", "call_offer_price_above_consent"), ("call_hold_above_consent", "call_offer_hold_above_consent")] {
            let (routes, paid) = offer_routes(10_000, hold_json(10_000, 5_000, 60));
            let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                if p == "/messages/compose" {
                    return (400, serde_json::json!({"error": "above consent", "code": "not_dispatched", "reason": reason}).to_string());
                }
                // A refused offer creates no call at the node.
                if p.starts_with("/calls?") { return (200, "[]".into()); }
                routes(m, p, b)
            }));
            approve_calls(&node).await;
            let err = offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await.unwrap_err();
            assert_eq!(err.code, code);
            assert!(err.message.contains("Nothing was sent, held or paid"), "{}", err.message);
            let offer = &compose_bodies(&node)[0];
            assert_eq!((offer["max_block_msat"].as_u64(), offer["max_hold_msat"].as_u64()), (Some(MINUTES.block_msat), Some(MINUTES.max_hold_msat)));
            assert_eq!(paid.lock().unwrap().pays, 0);
            assert!(pending(&node).is_none(), "proven unpaid: the journal holds nothing");
            assert_eq!(consent_phase(&node), ConsentPhase::Ended);
            assert!(!call_consent(&node.state, A, CALL_ID).unwrap().pinned(), "the node lists no call: closed");
            assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_not_live");
            assert!(compose_kinds(&node).iter().all(|k| *k == 400), "no hangup and no minute for an offer never sent");
        }
    }

    #[tokio::test]
    async fn a2_a_refused_call_whose_hold_is_still_open_stays_refused_under_table_pressure() {
        // The hold is above the consent: refused, then the hangup either fails or goes out but the
        // node still lists the call and its hold open. Hundreds of later calls press the table.
        for hangup_fails in [false, true] {
            let closed = Arc::new(AtomicBool::new(false));
            let node_closed = closed.clone();
            let (routes, _) = offer_routes(10_000, hold_json(12_000, 5_000, 60));
            let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                if hangup_fails && p == "/messages/compose"
                    && serde_json::from_str::<serde_json::Value>(b).is_ok_and(|v| v["kind"] == 403) {
                    return (500, r#"{"error":"hangup failed"}"#.into());
                }
                if p.starts_with("/calls?") && node_closed.load(Ordering::SeqCst) {
                    let mut hold = hold_json(12_000, 5_000, 60);
                    hold["closed"] = serde_json::json!(true);
                    return (200, serde_json::json!([{"id": CALL_ID, "state": "ended", "direction": "outgoing", "next_block_seq": 0,
                        "next_block_due_ms": null, "paid_until_ms": null, "reservation": hold}]).to_string());
                }
                routes(m, p, b)
            }));
            approve_calls(&node).await;
            offer_within_consent(&node.state, A, OFFER, 15000, MINUTES, Some(SHOWN_HANGUP)).await.unwrap();
            assert!(matches!(consent_phase(&node), ConsentPhase::Refused { code: "call_hold_above_consent", .. }), "{hangup_fails}");
            let sent = compose_kinds(&node);
            assert_eq!(sent, [400, 403], "the offer and one hangup attempt");
            let node_id = node.state.node_id.lock().unwrap().clone().unwrap();
            let id = |n: usize| format!("{n:032x}");
            {
                let mut kept = node.state.call_consents.lock().unwrap();
                for n in 0..3 * CALL_CONSENTS_KEPT {
                    kept.register(node_id.clone(), A, &id(n), MINUTES, 0).unwrap();
                    assert!(kept.node_reported(&node_id, A, &id(n), None, true), "a short call its node closed");
                }
                assert!(kept.entries.len() <= CALL_CONSENTS_KEPT);
                let refused = kept.find(&node_id, A, CALL_ID).expect("never evicted while its hold may be open");
                assert!(refused.pinned() && matches!(refused.phase, ConsentPhase::Refused { .. }));
                assert_eq!(kept.pinned_count(&node_id), 1, "it counts against the open-call limit");
                // With it pinned, only 15 more calls fit at once.
                for n in 5000..5000 + CALL_CONSENTS_OPEN - 1 { kept.register(node_id.clone(), A, &id(n), MINUTES, 0).unwrap(); }
                assert_eq!(kept.register(node_id.clone(), A, &id(6000), MINUTES, 0).unwrap_err().code, "call_consents_full");
                for n in 5000..5000 + CALL_CONSENTS_OPEN - 1 { kept.node_reported(&node_id, A, &id(n), None, true); }
            }
            // Wider rebinding, confirming the hold and paying a minute all stay refused.
            let wider = control::MinutesConsent { block_msat: 12_000, max_hold_msat: 240 * 17_000, ..MINUTES };
            assert_eq!(offer_within_consent(&node.state, A, OFFER, 15000, wider, Some(SHOWN_HANGUP)).await.unwrap_err().code, "invalid");
            assert_eq!(remember_call_consent(&node.state, A, CALL_ID, wider).unwrap_err().code, "invalid");
            assert_eq!(do_call_hold(&node.state, A, CALL_ID, Some(17_000 * 60)).await.unwrap_err().code, "call_hold_above_consent");
            for seq in [0, 1] {
                assert_eq!(do_call_block(&node.state, A, CALL_ID, seq).await.unwrap_err().code, "call_hold_above_consent");
            }
            // A sweep while the node still lists the hold open changes nothing.
            sweep_call_consents(&node.state).await;
            assert!(call_consent(&node.state, A, CALL_ID).unwrap().pinned());
            // The node closes the call and its hold: no longer pinned, and the refusal is still the answer.
            closed.store(true, Ordering::SeqCst);
            sweep_call_consents(&node.state).await;
            let after = call_consent(&node.state, A, CALL_ID).unwrap();
            assert!(!after.pinned() && matches!(after.phase, ConsentPhase::Refused { code: "call_hold_above_consent", .. }));
            assert_eq!(do_call_block(&node.state, A, CALL_ID, 0).await.unwrap_err().code, "call_hold_above_consent");
            assert_eq!(compose_kinds(&node), sent, "nothing more was sent: no rebind, no minute");
        }
    }

    #[test]
    fn a2_consents_are_write_once_and_only_a_call_its_node_closed_is_evicted() {
        let id = |n: usize| format!("{n:032x}");
        let wider = control::MinutesConsent { block_msat: 20_000, max_hold_msat: 240 * 25_000, ..MINUTES };
        let gone = |kept: &mut CallConsents, n: &str| assert!(kept.node_reported("node", A, n, None, true));
        let mut kept = CallConsents::default();
        // A full table of open calls (offering or admitted): a new call is refused, none is evicted.
        for n in 0..CALL_CONSENTS_OPEN {
            kept.register("node".into(), A, &id(n), MINUTES, 0).unwrap();
            if n % 2 == 0 { kept.admit("node", A, &id(n)); }
        }
        assert_eq!(kept.register("node".into(), A, &id(1000), MINUTES, 0).unwrap_err().code, "call_consents_full");
        assert_eq!(kept.pinned_count("node"), CALL_CONSENTS_OPEN);
        // Another node identity's calls neither count here nor are evicted for it.
        kept.register("other".into(), A, &id(1000), MINUTES, 0).unwrap();
        assert_eq!(kept.pinned_count("other"), 1);
        // Ending one at the app frees nothing: only its node showing it closed does.
        kept.end("node", Some(A), &id(CALL_CONSENTS_OPEN - 1));
        assert_eq!(kept.register("node".into(), A, &id(1000), MINUTES, 0).unwrap_err().code, "call_consents_full");
        gone(&mut kept, &id(CALL_CONSENTS_OPEN - 1));
        // A refused call whose hold is not closed takes that slot and stays pinned.
        let refused = id(1500);
        kept.register("node".into(), A, &refused, MINUTES, 0).unwrap();
        kept.refuse("node", A, &refused, "call_hold_above_consent", "refused");
        assert_eq!(kept.register("node".into(), A, &id(1000), MINUTES, 0).unwrap_err().code, "call_consents_full",
            "a refused call with an open hold counts against the limit");
        kept.end("node", Some(A), &id(CALL_CONSENTS_OPEN - 2));
        gone(&mut kept, &id(CALL_CONSENTS_OPEN - 2));
        // Then many short calls, refused or ended and closed at their node, press the table far past its size.
        for n in 2000..2000 + 3 * CALL_CONSENTS_KEPT {
            kept.register("node".into(), A, &id(n), MINUTES, 0).unwrap();
            if n % 3 == 0 { kept.refuse("node", A, &id(n), "call_hold_above_consent", "refused"); } else { kept.end("node", Some(A), &id(n)); }
            gone(&mut kept, &id(n));
        }
        assert!(kept.entries.len() <= CALL_CONSENTS_KEPT);
        // Every open call kept its own terms, and none can be rebound wider.
        for n in 0..CALL_CONSENTS_OPEN - 2 {
            let c = kept.find("node", A, &id(n)).expect("an open call is never evicted");
            assert_eq!((c.consent, c.phase.open()), (MINUTES, true));
            assert_eq!(kept.register("node".into(), A, &id(n), wider, 0).unwrap_err().code, "invalid");
            assert!(kept.register("node".into(), A, &id(n), MINUTES, 0).is_ok(), "the same offer again is a no-op");
        }
        // The refused call is still kept: it refuses any terms, and never becomes ended or admitted again.
        let c = kept.find("node", A, &refused).expect("a refused call is never evicted before its node closes it");
        assert!(c.pinned() && matches!(c.phase, ConsentPhase::Refused { .. }));
        for terms in [MINUTES, wider] {
            assert_eq!(kept.register("node".into(), A, &refused, terms, 0).unwrap_err().code, "invalid");
        }
        kept.end("node", Some(A), &refused);
        kept.admit("node", A, &refused);
        assert!(matches!(kept.find("node", A, &refused).unwrap().phase, ConsentPhase::Refused { .. }));
        // Only the node's own status closes it: an open hold, an ended call whose hold is still
        // held, an incoming call of that id, an offer in flight, or an unlisted call while a
        // payment may still be on its way to the node all leave it pinned.
        let status = |state: &str, direction: &str, closed: Option<bool>| control::CallStatus {
            id: refused.clone(), state: state.into(), direction: direction.into(), paid_until_ms: None, next_block_seq: 0, next_block_due_ms: None,
            reservation: closed.map(|closed| control::CallReservation { reserved_msat: 1, spent_msat: 0, remaining_msat: 1, per_block_msat: 1,
                per_block_fee_msat: 0, max_call_minutes: 1, released_msat: 0, closed }),
        };
        for open in [status("live", "outgoing", Some(false)), status("ended", "outgoing", Some(false)), status("live", "outgoing", None),
                     status("ended", "incoming", Some(true))] {
            assert!(!kept.node_reported("node", A, &refused, Some(&open), true), "{open:?}");
        }
        assert!(!kept.node_reported("node", A, &refused, None, false), "not listed, but its offer's outcome is unresolved");
        kept.find_mut("node", A, &refused).unwrap().offering = true;
        assert!(!kept.node_reported("node", A, &refused, None, true), "never while an offer is in flight");
        kept.find_mut("node", A, &refused).unwrap().offering = false;
        assert!(kept.find("node", A, &refused).unwrap().pinned());
        // Closed at the node: no longer pinned, and the refusal is still the answer.
        assert!(kept.node_reported("node", A, &refused, Some(&status("ended", "outgoing", Some(true))), false));
        let c = kept.find("node", A, &refused).unwrap();
        assert!(!c.pinned() && matches!(c.phase, ConsentPhase::Refused { .. }));
        assert_eq!(kept.register("node".into(), A, &refused, wider, 0).unwrap_err().code, "invalid");
        // An accepted offer the node no longer lists is over, whatever is pending elsewhere.
        let accepted = id(1000);
        kept.register("node".into(), A, &accepted, MINUTES, 0).unwrap();
        kept.find_mut("node", A, &accepted).unwrap().dispatched = true;
        assert!(kept.node_reported("node", A, &accepted, None, false));
        assert_eq!(kept.find("node", A, &accepted).unwrap().phase, ConsentPhase::Ended);
    }

    #[tokio::test]
